def _orb_executable_entry_premium_per_share(contract) -> float:
    """BTO sizing premium (ask-first) for true-to-live contract counts."""
    try:
        from modules.option_executable_pricing import contract_executable_entry_premium

        return float(contract_executable_entry_premium(contract))
    except Exception:
        return float(getattr(contract, "ask", 0.0) or getattr(contract, "mid_price", 0.0) or 0.01)


def _orb_slot_affordable_quantity(*, budget: float, unit_cost: float) -> int:
    """Slot-budget qty for ORB opens — parity with Trendline (never force 1 over budget)."""
    try:
        from easyTrendline.trendline_capital_allocation import slot_affordable_quantity

        return int(slot_affordable_quantity(budget=float(budget), unit_cost=float(unit_cost)))
    except Exception:
        b = max(0.0, float(budget or 0.0))
        c = max(0.0, float(unit_cost or 0.0))
        if b <= 0.0 or c <= 0.0:
            return 0
        return int(b // c)


