def _option_chain_latency_status(avg_ms: float) -> str:
    """Map rolling average chain latency to telemetry status (good | warning | critical)."""
    if avg_ms <= _orb_0dte_chain_latency_good_ms():
        return "good"
    if avg_ms <= _orb_0dte_chain_latency_critical_ms():
        return "warning"
    return "critical"


def build_orb_0dte_debit_width_ladder(
    signal_spread_width: float,
    width_options_csv: Optional[str] = None,
) -> List[float]:
    """
    Ordered debit-spread width attempts for ORB1 Breakout execution (Jun 2 2026: full 1/2/3/5 ladder).
    Signal width is tried first when positive; standard ladder always included.
    """
    raw = width_options_csv
    if raw is None:
        raw = str(get_config_value("0DTE_DEBIT_SPREAD_WIDTH_OPTIONS", "1,2,3,5"))
    width_tokens: List[float] = []
    for tok in str(raw or "").split(","):
        try:
            wv = float(tok.strip())
            if wv > 0:
                width_tokens.append(wv)
        except Exception:
            continue
    if not width_tokens:
        width_tokens = [1.0, 2.0, 3.0, 5.0]
    ordered: List[float] = []
    for w in [float(signal_spread_width or 0.0)] + width_tokens:
        if w <= 0:
            continue
        if any(abs(w - u) < 1e-6 for u in ordered):
            continue
        ordered.append(float(w))
    return ordered


def _safe_canonical_exit_reason(legacy_reason: Optional[str]) -> str:
    """Resolve exit reason to catalog id; never raises (Cloud Run / path variance safe)."""
    lr = str(legacy_reason or "").strip() or "unknown"
    try:
        from easy0DTE.modules.options_exit_reason_catalog import canonical_exit_reason

        return str(canonical_exit_reason(lr))
    except Exception:
        pass
    try:
        import importlib

        m = importlib.import_module("easy0DTE.modules.options_exit_reason_catalog")
        fn = getattr(m, "canonical_exit_reason", None)
        if callable(fn):
            return str(fn(lr))
    except Exception:
        pass
    return lr


