    def _resolve_adv_refresh_symbols(self) -> list:
        """Watchlist symbols for ADV refresh (0DTE Liquidity / ADV Guard)."""
        symbols = []
        if hasattr(self, "symbol_list") and self.symbol_list:
            symbols = list(self.symbol_list)
        if not symbols:
            try:
                symbols = self._resolve_unified_watchlist_symbols() or []
            except Exception:
                symbols = []
        # Always include liquid benchmarks used by Gate 3b / desk diagnostics.
        for extra in ("SPY", "QQQ", "IWM", "NVDA", "HOOD", "META", "TSLA", "AMD"):
            if extra not in {str(s).strip().upper() for s in symbols}:
                symbols.append(extra)
        return [str(s).strip().upper() for s in symbols if str(s).strip()]

    async def _ensure_liquidity_guard_adv_ready(self, *, force: bool = False) -> None:
        """
        Ensure ADV$ cache is loaded for the 0DTE Liquidity / ADV Guard.

        Broker-token-first: batch equity quotes (E*TRADE ``averageVolume`` × last)
        → durable cache/floors → optional yfinance only if
        ``LIQUIDITY_GUARD_ALLOW_YFINANCE_ADV=true``.
        """
        try:
            from .adv_data_manager import get_adv_manager

            adv_manager = get_adv_manager()
            symbols = self._resolve_adv_refresh_symbols()
            if not symbols:
                log.error("LIQUIDITY_GUARD_ADV | ensure_ready_aborted | reason=no_symbols")
                return

            broker_quotes: dict = {}
            try:
                dm = getattr(self, "data_manager", None)
                if dm is not None and hasattr(dm, "get_batch_quotes"):
                    broker_quotes = await dm.get_batch_quotes(symbols) or {}
                    log.info(
                        "LIQUIDITY_GUARD_ADV | broker_quotes | fetched=%d/%d",
                        len(broker_quotes),
                        len(symbols),
                    )
                    # Same E*TRADE totalVolume deltas TL/BO watch write into the
                    # session-tech hub — warm volume_ratio before 7:30 PP/Convex.
                    self._ingest_broker_quotes_into_session_tech(broker_quotes)
                else:
                    log.warning(
                        "LIQUIDITY_GUARD_ADV | broker_quotes_unavailable | "
                        "reason=no_data_manager_batch_quotes"
                    )
            except Exception as quote_exc:
                log.warning(
                    "LIQUIDITY_GUARD_ADV | broker_quotes_failed | error=%s",
                    quote_exc,
                )
                broker_quotes = {}

            log.info(
                "LIQUIDITY_GUARD_ADV | ensure_ready_start | symbols=%d | force=%s | "
                "cache_symbols=%d | stale=%s | broker_quotes=%d",
                len(symbols),
                force,
                len(adv_manager.adv_cache),
                adv_manager.is_data_stale(),
                len(broker_quotes),
            )

            stats = await asyncio.get_event_loop().run_in_executor(
                None,
                lambda: adv_manager.ensure_ready(
                    symbols, force=force, broker_quotes=broker_quotes
                ),
            )
            log.info(
                "LIQUIDITY_GUARD_ADV | ensure_ready_complete | symbols_loaded=%s | "
                "age_hours=%s | stale=%s | allow_yfinance=%s | gcs_path=%s",
                stats.get("symbols_loaded"),
                stats.get("data_age_hours"),
                stats.get("is_stale"),
                stats.get("allow_yfinance"),
                stats.get("gcs_path"),
            )
            for probe in ("NVDA", "SPY", "HOOD", "META", "INTC"):
                adv_dollars = float(adv_manager.get_adv(probe) or 0.0)
                if adv_dollars <= 0:
                    log.warning(
                        "LIQUIDITY_GUARD_ADV | probe_missing | symbol=%s | "
                        "hint=broker_averageVolume_or_default_floor",
                        probe,
                    )
                else:
                    log.info(
                        "LIQUIDITY_GUARD_ADV | probe_ok | symbol=%s | adv_dollars=%.0f",
                        probe,
                        adv_dollars,
                    )
        except Exception as e:
            log.error("LIQUIDITY_GUARD_ADV | ensure_ready_failed | error=%s", e)
            log.warning(
                "LIQUIDITY_GUARD_ADV | continuing_with_cache | "
                "note=missing_adv_fail_closes_0dte_entries"
            )

