    async def _update_stealth_for_symbol(self, symbol: str) -> Optional[Dict[str, Any]]:
        """Update SO equity stealth from session-tech hub + broker quote (no Yahoo hist)."""
        try:
            if not self.stealth_trailing:
                return None
            sym = str(symbol or "").strip().upper()
            if not sym:
                return None

            # Only update symbols that are actually in equity stealth (avoid 0DTE/OCC spam).
            try:
                active = self.stealth_trailing.get_active_positions() or {}
                if sym not in active and sym not in {str(k).strip().upper() for k in active.keys()}:
                    return None
            except Exception:
                pass

            hub_md: Dict[str, Any] = {}
            try:
                from modules.session_tech_indicators import get_session_tech

                tech = get_session_tech(self, sym) or {}
                if tech:
                    hub_md["rsi"] = tech.get("rsi") if not tech.get("rsi_missing") else None
                    hub_md["rsi_missing"] = bool(tech.get("rsi_missing"))
                    hub_md["volume_ratio"] = (
                        float(tech["volume_ratio"])
                        if not tech.get("volume_ratio_missing") and tech.get("volume_ratio") is not None
                        else None
                    )
                    hub_md["volume_ratio_missing"] = bool(tech.get("volume_ratio_missing"))
                    hub_md["macd_histogram"] = (
                        tech.get("macd_histogram") if not tech.get("macd_missing") else None
                    )
                    hub_md["macd_missing"] = bool(tech.get("macd_missing"))
                    if tech.get("atr") is not None:
                        hub_md["atr"] = float(tech["atr"])
                    if tech.get("price") is not None:
                        hub_md["price"] = float(tech["price"])
            except Exception:
                pass

            # Broker quote for live price — never Yahoo daily hist (yf_provider removed).
            price = hub_md.get("price")
            try:
                if self.data_manager:
                    quotes = await self.data_manager.get_batch_quotes([sym]) or {}
                    if isinstance(quotes, dict) and quotes:
                        try:
                            self._ingest_broker_quotes_into_session_tech(quotes)
                        except Exception:
                            pass
                        q = quotes.get(sym) or {}
                        if isinstance(q, dict):
                            raw = q.get("last", q.get("price", q.get("lastPrice")))
                            if raw is not None:
                                price = float(raw)
            except Exception:
                pass

            if price is None or float(price) <= 0:
                log.debug(
                    "SO_STEALTH_UPDATE | symbol=%s | reason=no_hub_or_broker_price | skip_yahoo=true",
                    sym,
                )
                return None

            price_f = float(price)
            market_data = {
                "price": price_f,
                "rsi": hub_md.get("rsi"),
                "rsi_missing": bool(hub_md.get("rsi_missing", hub_md.get("rsi") is None)),
                "atr": float(hub_md.get("atr") or (price_f * 0.02)),
                "volume_ratio": hub_md.get("volume_ratio"),
                "volume_ratio_missing": bool(
                    hub_md.get("volume_ratio_missing", hub_md.get("volume_ratio") is None)
                ),
                "macd_histogram": hub_md.get("macd_histogram"),
                "macd_missing": bool(hub_md.get("macd_missing", True)),
                "momentum": 0.0,
                "volatility": 0.02,
            }
            return await self.stealth_trailing.update_position(sym, market_data)

        except Exception as e:
            log.error(f"Error updating stealth for {symbol}: {e}")
            return None
    
    def _calculate_rsi(self, prices: List[float], period: int = 14) -> float:
        """Calculate RSI indicator"""
        if len(prices) < period + 1:
            return 50.0
        
        deltas = [prices[i] - prices[i-1] for i in range(1, len(prices))]
        gains = [delta if delta > 0 else 0 for delta in deltas]
        losses = [-delta if delta < 0 else 0 for delta in deltas]
        
        avg_gain = np.mean(gains[-period:])
        avg_loss = np.mean(losses[-period:])
        
        if avg_loss == 0:
            return 100.0
        
        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi
    
    def _calculate_atr(self, historical_data: List[Dict], period: int = 14) -> float:
        """Calculate Average True Range"""
        if len(historical_data) < 2:
            return 0.0
        
        true_ranges = []
        for i in range(1, len(historical_data)):
            high = historical_data[i]['high']
            low = historical_data[i]['low']
            prev_close = historical_data[i-1]['close']
            
            tr1 = high - low
            tr2 = abs(high - prev_close)
            tr3 = abs(low - prev_close)
            
            true_range = max(tr1, tr2, tr3)
            true_ranges.append(true_range)
        
        if not true_ranges:
            return 0.0
        
        return np.mean(true_ranges[-period:]) if len(true_ranges) >= period else np.mean(true_ranges)
    
