    def _trendline_normalize_bar_timestamp(self, ts_raw: Any) -> Optional[datetime]:
        """Normalize any broker/payload timestamp to timezone-aware UTC."""
        try:
            if isinstance(ts_raw, datetime):
                ts = ts_raw
            else:
                ts_text = str(ts_raw)
                if "Z" in ts_text:
                    ts_text = ts_text.replace("Z", "+00:00")
                ts = datetime.fromisoformat(ts_text)
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
            return ts.astimezone(timezone.utc)
        except Exception:
            return None

    def _trendline_parse_intraday_row_to_bar(self, item: Dict[str, Any]) -> Optional[Any]:
        """Parse one dict row into OHLCVBar (UTC ts) or None."""
        from easyTrendline import OHLCVBar

        ts_raw = item.get("timestamp") or item.get("datetime") or item.get("time")
        ts = self._trendline_normalize_bar_timestamp(ts_raw)
        if ts is None:
            return None
        try:
            return OHLCVBar(
                ts=ts,
                open=float(item.get("open", 0.0) or 0.0),
                high=float(item.get("high", 0.0) or 0.0),
                low=float(item.get("low", 0.0) or 0.0),
                close=float(item.get("close", 0.0) or 0.0),
                volume=float(item.get("volume", 0.0) or 0.0),
                atr=float(item.get("atr", 0.0) or 0.0) if item.get("atr") is not None else None,
            )
        except Exception:
            return None

    def _trendline_count_window_bars_pt(self, bars: List[Any], tz_pt: Any) -> int:
        """Count bars with local time in [06:30, 07:30] PT same calendar day as first bar."""
        from easyTrendline import OHLCVBar as _TB

        if not bars or not isinstance(bars[0], _TB):
            return 0
        day = bars[0].ts.astimezone(tz_pt).date()
        start_t = time_class(6, 30)
        end_t = time_class(7, 30)
        n = 0
        for b in bars:
            if not isinstance(b, _TB):
                continue
            loc = b.ts.astimezone(tz_pt)
            if loc.date() != day:
                continue
            tt = loc.time()
            if start_t <= tt <= end_t:
                n += 1
        return n

    def _trendline_merge_structure_bars(
        self,
        symbol: str,
        parsed_intraday: List[Any],
        prefetch_map: Any,
        open_700_map: Any,
        quote: Dict[str, Any],
        ts_700_pt: datetime,
        ts_730_pt: datetime,
    ) -> Tuple[List[Any], int]:
        """
        Merge broker quote + validation/prefetch + optional ORB-timed intraday bar.
        Dedupes by (PT date, hour, minute). Returns (sorted bars, synthetic_points_added).
        """
        from easyTrendline import OHLCVBar

        by_minute: Dict[Tuple[Any, int, int], Any] = {}

        def _add_bar(b: Any) -> None:
            if not isinstance(b, OHLCVBar) or b.ts is None:
                return
            loc = b.ts.astimezone(ts_700_pt.tzinfo)
            key = (loc.date(), loc.hour, loc.minute)
            by_minute[key] = b

        for b in parsed_intraday:
            _add_bar(b)

        pref = (prefetch_map or {}).get(symbol, []) if isinstance(prefetch_map, dict) else []
        if pref and isinstance(pref, list):
            p0 = pref[0] if pref else {}
            if isinstance(p0, dict):
                b = self._trendline_parse_intraday_row_to_bar(p0)
                if b:
                    _add_bar(b)

        key700 = (ts_700_pt.date(), 7, 0)
        key730 = (ts_730_pt.date(), 7, 30)
        if isinstance(open_700_map, dict) and symbol in open_700_map and key700 not in by_minute:
            try:
                o700 = float(open_700_map.get(symbol) or 0.0)
                if o700 > 0:
                    t7 = ts_700_pt.astimezone(timezone.utc)
                    _add_bar(
                        OHLCVBar(
                            ts=t7,
                            open=o700,
                            high=o700,
                            low=o700,
                            close=o700,
                            volume=0.0,
                            atr=None,
                        )
                    )
            except Exception:
                pass

        synth = 0
        q = quote if isinstance(quote, dict) else {}
        try:
            last = float(q.get("last", 0.0) or q.get("close", 0.0) or q.get("price", 0.0) or 0.0)
        except (TypeError, ValueError):
            last = 0.0
        if last > 0:
            o = float(q.get("open", last) or last)
            h = float(q.get("high", max(o, last)) or max(o, last))
            l = float(q.get("low", min(o, last)) or min(o, last))
            v = float(q.get("volume", 0.0) or 0.0)
            t700_utc = ts_700_pt.astimezone(timezone.utc)
            t730_utc = ts_730_pt.astimezone(timezone.utc)
            if key700 not in by_minute and o > 0:
                _add_bar(
                    OHLCVBar(
                        ts=t700_utc,
                        open=o,
                        high=o,
                        low=o,
                        close=o,
                        volume=0.0,
                        atr=None,
                    )
                )
                synth += 1
            # Keep broker intraday 7:30 bar when present — late draw must not rewrite cutoff_close.
            if key730 not in by_minute:
                _add_bar(
                    OHLCVBar(
                        ts=t730_utc,
                        open=o,
                        high=max(h, o, last),
                        low=min(l, o, last),
                        close=last,
                        volume=v,
                        atr=abs(last - o),
                    )
                )
                synth += 1

        merged = sorted(by_minute.values(), key=lambda x: x.ts)
        return merged, synth

    async def _build_trendline_candidates_at_730(
        self,
        pending_so_signals: List[Dict[str, Any]],
        pending_dte_signals: List[Dict[str, Any]],
    ) -> None:
        """Initialize TL1 candidates after ORB2 capture from full 0DTE universe (ORB2 box)."""
        from zoneinfo import ZoneInfo

        if not self._enable_trendline_strategy:
            return
        if not getattr(self, "trendline_signal_engine", None):
            log.warning("TRENDLINE_PIPELINE | stage=build | action=skip | reason=engine_not_initialized")
            return
        # Day-freeze: if TL1 A1/A2/slope already persisted, restore — do not rebuild Yahoo hull.
        # Engine count includes TL0; only skip Yahoo when trendline1 is actually present.
        try:
            if self._trendline_geometry_freeze_has_tl1():
                n_hyd = int(self._hydrate_trendline_geometry_from_daily_markers() or 0)
                if self._trendline_engine_has_tl1_candidates():
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=build | action=skip_rebuild_use_day_freeze | "
                        "hydrated=%d | engine=%d | has_tl1=true",
                        n_hyd,
                        self._trendline_existing_engine_candidate_count(),
                    )
                    self._apply_trendline_open_caps_from_config()
                    self._note_trendline_build_attempt_finished()
                    return
                log.warning(
                    "TRENDLINE_PIPELINE | stage=build | action=freeze_tl1_missing_after_hydrate | "
                    "hydrated=%d | engine=%d | note=fall_through_yahoo_dual_envelope",
                    n_hyd,
                    self._trendline_existing_engine_candidate_count(),
                )
        except Exception as freeze_skip_err:
            log.debug("TRENDLINE_PIPELINE | stage=build | freeze_skip_check_failed=%s", freeze_skip_err)
        try:
            from easyTrendline import OHLCVBar, TrendlineCandidate, TrendlineCandidateState
            from easyTrendline.trendline_setup_selector import select_pre730_structure_setup
        except Exception as import_error:
            log.error(f"TRENDLINE_PIPELINE | stage=build | action=error | reason=import_failed:{import_error}")
            return

        use_full_list = str(get_config_value("TRENDLINE_USE_FULL_0DTE_LIST", "true")).lower() == "true"
        self._apply_trendline_open_caps_from_config()

        source_symbols: List[str] = []
        if use_full_list:
            if hasattr(self, "dte0_manager") and self.dte0_manager and getattr(self.dte0_manager, "target_symbols", None):
                source_symbols = [str(s).strip().upper() for s in (self.dte0_manager.target_symbols or []) if s]
            if not source_symbols:
                # Align with easy0DTE `load_0dte_symbols()` (extra env paths + /app/data/watchlist for Cloud Run).
                try:
                    from easy0DTE.modules.prime_0dte_strategy_manager import load_0dte_symbols

                    loaded = load_0dte_symbols()
                    source_symbols = [str(s).strip().upper() for s in (loaded or []) if s]
                except Exception as e:
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=build_failed | reason=load_0dte_symbols_failed | detail=%s",
                        e,
                    )
                if not source_symbols:
                    try:
                        import pandas as pd

                        for dte_list_path in (
                            "/app/data/watchlist/0dte_list.csv",
                            "data/watchlist/0dte_list.csv",
                        ):
                            if os.path.exists(dte_list_path):
                                df = pd.read_csv(dte_list_path, comment="#")
                                col = "symbol" if "symbol" in df.columns else df.columns[0]
                                source_symbols = [
                                    str(s).strip().upper() for s in df[col].tolist() if s
                                ]
                                break
                    except Exception as e2:
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=build_failed | reason=full_0dte_list_load_failed | detail=%s",
                            e2,
                        )
        else:
            source_candidates = list(pending_dte_signals or pending_so_signals or [])
            source_symbols = [str((r or {}).get("symbol", "")).strip().upper() for r in source_candidates if isinstance(r, dict)]

        source_symbols = list(dict.fromkeys([s for s in source_symbols if s]))
        self._trendline_candidate_universe_size = len(source_symbols)
        if not source_symbols:
            self._trendline_finalize_empty_tl1_build(reason="no_candidates")
            log.warning(
                "TRENDLINE_PIPELINE | stage=build_summary | symbols=0 | initial_failures=0 | fallback_attempts=0 | "
                "fallback_successes=0 | qualified_candidates=0 | no_structure=0 | missing_orb=0 | insufficient_bars_final=0 | "
                "pre730_filter_zero_bars=0 | insufficient_window_bars=0 | ambiguous_structure=0 | outcome=no_source_universe"
            )
            return

        now_utc = datetime.now(timezone.utc)
        PT_TZ = ZoneInfo("America/Los_Angeles")
        now_pt = datetime.now(PT_TZ)
        session_date_pt = now_pt.date()
        ts_630_pt = datetime.combine(session_date_pt, time_class(6, 30), PT_TZ)
        ts_700_pt = datetime.combine(session_date_pt, time_class(7, 0), PT_TZ)
        ts_730_pt = datetime.combine(session_date_pt, time_class(7, 30), PT_TZ)
        cutoff_display_utc = ts_730_pt.astimezone(timezone.utc).isoformat()

        symbols: List[str] = []
        missing_orb = 0
        for symbol in source_symbols:
            if not symbol or symbol in symbols:
                continue
            orb_obj = self._orb2_obj_for_symbol(symbol)
            if not orb_obj or getattr(orb_obj, "orb_high", None) is None or getattr(orb_obj, "orb_low", None) is None:
                missing_orb += 1
                log.debug(
                    "TRENDLINE_PIPELINE | stage=build_reject | symbol=%s | reason=missing_orb2_context",
                    symbol,
                )
                continue
            symbols.append(symbol)

        if not symbols:
            self._trendline_finalize_empty_tl1_build(reason="no_symbols_with_orb2_context")
            log.warning(
                "TRENDLINE_PIPELINE | stage=build_summary | symbols=%d | initial_failures=0 | fallback_attempts=0 | "
                "fallback_successes=0 | qualified_candidates=0 | no_structure=0 | missing_orb=%d | insufficient_bars_final=0 | "
                "pre730_filter_zero_bars=0 | insufficient_window_bars=0 | ambiguous_structure=0 | "
                "session_pt_date=%s | cutoff_7_30_pt=%s | cutoff_utc=%s | outcome=all_missing_orb2",
                len(source_symbols),
                missing_orb,
                session_date_pt.isoformat(),
                ts_730_pt.isoformat(),
                cutoff_display_utc,
            )
            return

        build_t0 = time.perf_counter()
        build_wall_start = datetime.now(timezone.utc)

        # TL1 DATA POLICY (Aug 4 corrected)
        # ------------------------------------------------------------------
        # ORB2 high/low (TL1 A1 *price*) come from E*TRADE *session quote* H/L
        # frozen at ~7:30 (`capture_orb2_breakout_ranges` → etrade_session_ohlc).
        # That session H/L *is* the 6:30–7:30 box — E*TRADE does not give a
        # candle timeline for those levels.
        #
        # Envelope A2 still needs intra-window path highs/lows (desk charts).
        # Broker get_batch_intraday_data(bars=1 or bars>1) returns ONE quote OHLC
        # — not history. Keep bars=1 only as an ORB-timed merge *fallback* seed;
        # primary structure series = Yahoo RTH 1m [06:30, 07:30] below.
        symbols_post_orb_requested = list(symbols)
        chunk_sz = max(1, int(float(get_config_value("TRENDLINE_DATA_CHUNK_SIZE", 25))))
        max_intraday_calls = max(1, int(float(get_config_value("TRENDLINE_MAX_INTRADAY_BATCH_CALLS_PER_BUILD", 8))))
        max_quote_calls = max(1, int(float(get_config_value("TRENDLINE_MAX_QUOTE_BATCH_CALLS_PER_BUILD", 8))))
        max_symbols_build = max(1, int(float(get_config_value("TRENDLINE_MAX_SYMBOLS_PER_BUILD", 200))))
        enable_degrade = str(get_config_value("TRENDLINE_ENABLE_BUILD_DEGRADATION", "true")).lower() == "true"
        max_build_ms = max(0, int(float(get_config_value("TRENDLINE_MAX_BUILD_DURATION_MS", 0))))

        # Open-quote latency does not requeue this build. A slow exit batch
        # must not postpone the lines the 10s watch is waiting to break.
        #
        # First post-ORB2 primary TL1 (before any finished attempt today) stays
        # full-universe — while-open 25-cap must not shrink the morning geometry
        # handoff when ORB1 already has opens.
        primary_tl1 = not self._trendline_build_attempted_today()
        try:
            from modules.open_position_quote_orchestration import (
                open_quote_priority_active,
            )

            if open_quote_priority_active(self) and primary_tl1:
                log.info(
                    "TRENDLINE_PIPELINE | stage=build | action=primary_tl1_full_universe | "
                    "reason=exempt_while_open_cap | symbols_post_orb=%d | max_symbols=%d",
                    len(symbols_post_orb_requested),
                    max_symbols_build,
                )
            elif open_quote_priority_active(self):
                build_cap = max(1, int(float(get_config_value("TRENDLINE_BUILD_SYMBOLS_WHILE_OPEN", 25))))
                max_symbols_build = min(max_symbols_build, build_cap)
                max_intraday_calls = min(max_intraday_calls, 1)
                max_quote_calls = min(max_quote_calls, 1)
                if max_build_ms <= 0:
                    max_build_ms = max(500, int(float(get_config_value("TRENDLINE_BUILD_MAX_MS_WHILE_OPEN", 1200))))
                log.info(
                    "TRENDLINE_PIPELINE | stage=build | action=budgeted_universe_poll | "
                    "reason=open_exact_healthy | symbol_cap=%d | max_intraday_calls=%d | max_quote_calls=%d",
                    max_symbols_build,
                    max_intraday_calls,
                    max_quote_calls,
                )
        except Exception:
            pass

        deferred_cap = symbols_post_orb_requested[max_symbols_build:]
        symbols_capped = symbols_post_orb_requested[:max_symbols_build]
        chunks_all = [symbols_capped[i : i + chunk_sz] for i in range(0, len(symbols_capped), chunk_sz)]
        needed_chunks = len(chunks_all)
        max_chunks_allowed = min(max_intraday_calls, max_quote_calls)

        if needed_chunks > max_chunks_allowed and not enable_degrade:
            self._trendline_finalize_empty_tl1_build(reason="trendline_build_budget_strict")
            log.warning(
                "TRENDLINE_PIPELINE | stage=build | detail=budget_strict | "
                "needed_chunks=%d | max_chunks_allowed=%d | chunk_size=%d | symbols_post_orb=%d | "
                "set TRENDLINE_ENABLE_BUILD_DEGRADATION=true for partial build | watch_active=%s",
                needed_chunks,
                max_chunks_allowed,
                chunk_sz,
                len(symbols_post_orb_requested),
                bool(getattr(self, "_trendline_watch_active", False)),
            )
            log.warning(
                "TRENDLINE_PIPELINE | stage=build_summary | symbols=%d | initial_failures=0 | fallback_attempts=0 | "
                "fallback_successes=0 | qualified_candidates=0 | no_structure=0 | missing_orb=%d | insufficient_bars_final=0 | "
                "pre730_filter_zero_bars=0 | insufficient_window_bars=0 | ambiguous_structure=0 | "
                "outcome=budget_strict_abort | build_start_utc=%s | build_end_utc=%s | total_build_duration_ms=0 | "
                "avg_symbol_processing_ms=0 | batch_quote_duration_ms=0 | intraday_fetch_duration_ms=0 | "
                "skipped_budget=%d",
                len(symbols_post_orb_requested),
                missing_orb,
                build_wall_start.isoformat(),
                datetime.now(timezone.utc).isoformat(),
                len(symbols_post_orb_requested),
            )
            log.warning(
                "TRENDLINE_PIPELINE | stage=request_summary | symbols_requested=%d | intraday_calls=0 | quote_calls=0 | "
                "batch_quote_calls=0 | merged_success=0 | skipped_budget=%d | trendline_intraday_requests=0 | "
                "trendline_quote_requests=0 | symbols_with_intraday_row=0 | symbols_with_quotes=0 | "
                "total_build_duration_ms=%.1f | avg_symbol_processing_ms=%.2f | batch_quote_duration_ms=0 | "
                "intraday_fetch_duration_ms=0 | reason=budget_strict_abort",
                len(symbols_post_orb_requested),
                len(symbols_post_orb_requested),
                (time.perf_counter() - build_t0) * 1000.0,
                ((time.perf_counter() - build_t0) * 1000.0) / max(len(symbols_post_orb_requested), 1),
            )
            return

        chunks_to_run = chunks_all[:max_chunks_allowed] if needed_chunks > max_chunks_allowed else chunks_all
        run_syms_set = {s for ch in chunks_to_run for s in ch}
        deferred_chunk = [s for s in symbols_capped if s not in run_syms_set]

        intraday_raw: Dict[str, List[Dict[str, Any]]] = {}
        batch_quotes: Dict[str, Dict[str, Any]] = {}
        intraday_fetch_error = ""
        quote_fetch_error = ""

        intraday_batch_calls = 0
        quote_batch_calls = 0
        trendline_intraday_requests = 0
        trendline_quote_requests = 0
        intraday_fetch_duration_ms = 0.0
        batch_quote_duration_ms = 0.0
        deferred_time: List[str] = []

        dm = getattr(self, "data_manager", None)
        processed_syms_ordered: List[str] = []

        for ci, chunk in enumerate(chunks_to_run):
            if max_build_ms > 0 and (time.perf_counter() - build_t0) * 1000.0 > max_build_ms:
                for tail in chunks_to_run[ci:]:
                    deferred_time.extend(tail)
                log.warning(
                    "TRENDLINE_PIPELINE | stage=build_fetch | action=degraded | reason=time_budget | "
                    "max_build_duration_ms=%d | deferred_from_this_chunk_onward=%d",
                    max_build_ms,
                    sum(len(t) for t in chunks_to_run[ci:]),
                )
                break
            if not dm:
                deferred_time.extend(s for tail in chunks_to_run[ci:] for s in tail)
                break
            t_i0 = time.perf_counter()
            try:
                part = await dm.get_batch_intraday_data(chunk, interval="15m", bars=1) or {}
            except Exception as ex:
                intraday_fetch_error = str(ex)
                part = {}
            intraday_fetch_duration_ms += (time.perf_counter() - t_i0) * 1000.0
            intraday_batch_calls += 1
            trendline_intraday_requests += len(chunk)
            for sym, rows in (part or {}).items():
                intraday_raw[sym] = rows

            t_q0 = time.perf_counter()
            try:
                qp = await dm.get_batch_quotes(chunk, skip_cache=True) or {}
            except Exception as qex:
                quote_fetch_error = str(qex)
                qp = {}
            if qp:
                self._ingest_broker_quotes_into_session_tech(qp)
            try:
                from modules.broker_api_pacing import (
                    LANE_TRENDLINE_BUILD,
                    record_broker_lane_request,
                )

                record_broker_lane_request(LANE_TRENDLINE_BUILD)
            except Exception:
                pass
            batch_quote_duration_ms += (time.perf_counter() - t_q0) * 1000.0
            quote_batch_calls += 1
            trendline_quote_requests += len(chunk)
            for sym, qv in (qp or {}).items():
                batch_quotes[sym] = qv

            processed_syms_ordered.extend(chunk)

        # Primary TL1 *path* bars for A2 hull — **batched** Yahoo 1m [06:30, 07:30] PT
        # (one yf.download per chunk of ~20 — not 148 serial/parallel hits).
        # ORB2 A1 prices remain from frozen orb2_data (E*TRADE session H/L), not Yahoo.
        try:
            yf_on = str(os.getenv("TRENDLINE_BUILD_YF_1M_BACKFILL", "true")).strip().lower() not in (
                "0",
                "false",
                "no",
                "off",
            )
            try:
                max_yf = int(os.getenv("TRENDLINE_BUILD_YF_1M_MAX_SYMBOLS", "150") or 150)
            except (TypeError, ValueError):
                max_yf = 150
            try:
                yf_batch = int(os.getenv("TRENDLINE_BUILD_YF_1M_BATCH_SIZE", "20") or 20)
            except (TypeError, ValueError):
                yf_batch = 20
            try:
                yf_sleep = float(os.getenv("TRENDLINE_BUILD_YF_1M_BATCH_SLEEP_SEC", "0.5") or 0.5)
            except (TypeError, ValueError):
                yf_sleep = 0.75
            structure_syms = list(processed_syms_ordered)[: max(0, max_yf)]
            if yf_on and structure_syms:
                from modules.prime_data_manager import _yf_tl1_structure_1m_bars

                t_yf0 = time.perf_counter()
                yf_map = await _yf_tl1_structure_1m_bars(
                    structure_syms,
                    batch_size=yf_batch,
                    inter_batch_sleep_sec=yf_sleep,
                )
                yf_hits = 0
                yf_bars = 0
                for sym, rows in (yf_map or {}).items():
                    if not rows:
                        continue
                    existing = intraday_raw.get(sym) or []
                    # Prefer real 1m path over single broker quote-OHLC seed.
                    if len(rows) >= max(2, len(existing)):
                        intraday_raw[sym] = list(rows)
                        yf_hits += 1
                        yf_bars += len(rows)
                log.warning(
                    "TRENDLINE_PIPELINE | stage=build_fetch | action=tl1_structure_yf_1m | "
                    "requested=%d | hits=%d | bars=%d | batch_size=%d | sleep_sec=%.2f | "
                    "duration_ms=%.1f | note=orb2_levels_remain_etrade_session_ohlc|batched_yf",
                    len(structure_syms),
                    yf_hits,
                    yf_bars,
                    yf_batch,
                    yf_sleep,
                    (time.perf_counter() - t_yf0) * 1000.0,
                )
        except Exception as yex:
            log.warning(
                "TRENDLINE_PIPELINE | stage=build_fetch | action=tl1_structure_yf_1m_failed | err=%s",
                yex,
            )

        if not intraday_raw and intraday_fetch_error:
            log.warning(
                "TRENDLINE_PIPELINE | stage=build_fetch | action=intraday_empty | symbols_requested=%d | error=%s",
                trendline_intraday_requests,
                intraday_fetch_error or "empty_dict",
            )
        if not batch_quotes and quote_fetch_error:
            log.warning(
                "TRENDLINE_PIPELINE | stage=build_fetch | action=batch_quotes_failed | reason=%s",
                quote_fetch_error,
            )

        symbols = processed_syms_ordered
        deferred_all = list(dict.fromkeys(deferred_cap + deferred_chunk + deferred_time))
        skipped_budget = len(deferred_all)

        degrade_reason_parts: List[str] = []
        if deferred_cap:
            degrade_reason_parts.append("max_symbols_per_build")
        if deferred_chunk:
            degrade_reason_parts.append("request_budget")
        if deferred_time:
            degrade_reason_parts.append("time_budget")
        if skipped_budget:
            log.warning(
                "TRENDLINE_PIPELINE | stage=build_degraded | requested=%d | attempted=%d | deferred=%d | reason=%s",
                len(symbols_post_orb_requested),
                len(symbols),
                skipped_budget,
                ",".join(degrade_reason_parts) if degrade_reason_parts else "deferred",
            )

        prefetch_map = getattr(self, "_prefetched_intraday", None)
        open_700_map = getattr(self, "_validation_open_700", None)

        raw_rows_total = sum(len(intraday_raw.get(s) or []) for s in symbols)
        symbols_with_raw_rows = sum(1 for s in symbols if len(intraday_raw.get(s) or []) > 0)
        symbols_with_quotes = sum(1 for s in symbols if s in batch_quotes and batch_quotes.get(s))

        intraday_by_symbol: Dict[str, List[Any]] = {}
        orb_context_by_symbol: Dict[str, Dict[str, Any]] = {}

        initial_lt2 = 0
        fallback_attempts = len(symbols)
        fallback_successes = 0
        insufficient_final = 0
        pre730_filter_zero_bars = 0
        insufficient_window_bars = 0
        fail_reason_counts: Dict[str, int] = defaultdict(int)
        if skipped_budget:
            fail_reason_counts["request_budget_exhausted"] = skipped_budget
        fail_diag_samples: List[str] = []
        ok_diag_samples: List[str] = []

        for symbol in symbols:
            final_reason = "unknown"
            items = list(intraday_raw.get(symbol) or [])
            raw_bars_fetched = len(items)
            parsed: List[Any] = []
            parse_fail = 0
            for item in items:
                if not isinstance(item, dict):
                    parse_fail += 1
                    continue
                b = self._trendline_parse_intraday_row_to_bar(item)
                if b:
                    parsed.append(b)
                else:
                    parse_fail += 1

            bars_after_tz = len(parsed)
            if bars_after_tz < 2:
                initial_lt2 += 1

            quote = batch_quotes.get(symbol, {}) if isinstance(batch_quotes, dict) else {}
            merge_error = ""
            try:
                merged, synth_added = self._trendline_merge_structure_bars(
                    symbol, parsed, prefetch_map, open_700_map, quote, ts_700_pt, ts_730_pt
                )
            except Exception as mex:
                merge_error = str(mex)
                merged, synth_added = [], 0
                log.warning(
                    "TRENDLINE_PIPELINE | stage=build_merge_failed | symbol=%s | detail=%s",
                    symbol,
                    merge_error,
                )

            pre730_cutoff_utc = ts_730_pt.astimezone(timezone.utc)
            pre730_bars = [b for b in merged if b.ts <= pre730_cutoff_utc]
            window_ct = self._trendline_count_window_bars_pt(merged, PT_TZ)
            selector_input_bars = merged

            if len(pre730_bars) < 2:
                pre730_filter_zero_bars += 1
            if window_ct < 2:
                insufficient_window_bars += 1

            if len(merged) < 2:
                insufficient_final += 1
                qmiss = not isinstance(batch_quotes, dict) or symbol not in batch_quotes or not batch_quotes.get(symbol)
                if merge_error:
                    final_reason = "fallback_failed"
                elif raw_bars_fetched == 0 and qmiss:
                    final_reason = "raw_fetch_no_bars"
                elif qmiss:
                    final_reason = "quote_unavailable"
                else:
                    final_reason = "fallback_insufficient_bars"
            else:
                fallback_successes += 1
                final_reason = "merged_ok"

            fail_reason_counts[final_reason] += 1

            intraday_by_symbol[symbol] = selector_input_bars

            orb_obj = self._orb2_obj_for_symbol(symbol)
            try:
                from modules.trendline_orb2_timestamp_refinement import (
                    refine_orb2_extreme_timestamps_from_bars,
                )

                abs_tol = float(os.getenv("TRENDLINE_ORB2_TS_REFINE_ABS_TOL", "0.05") or 0.05)
                pct_tol = float(os.getenv("TRENDLINE_ORB2_TS_REFINE_PCT_TOL", "0.0002") or 0.0002)
                ts_ref = refine_orb2_extreme_timestamps_from_bars(
                    orb_obj,
                    selector_input_bars,
                    window_start=ts_630_pt,
                    window_end=ts_730_pt,
                    abs_tolerance=abs_tol,
                    pct_tolerance=pct_tol,
                )
                if bool(ts_ref.get("high_refined") or ts_ref.get("low_refined")):
                    log.info(
                        "TRENDLINE_PIPELINE | stage=build | action=orb2_ts_refined | "
                        "symbol=%s | high_refined=%s | low_refined=%s | "
                        "high_ts=%s | low_ts=%s | source=structure_1m_match",
                        symbol,
                        bool(ts_ref.get("high_refined")),
                        bool(ts_ref.get("low_refined")),
                        ts_ref.get("high_ts"),
                        ts_ref.get("low_ts"),
                    )
            except Exception as ts_ref_ex:
                log.debug(
                    "TRENDLINE_PIPELINE | stage=build | action=orb2_ts_refine_skip | "
                    "symbol=%s | reason=%s",
                    symbol,
                    ts_ref_ex,
                )
            # Prefer extreme_ts; never fall back to capture_time (~7:30) — that pins
            # envelope A1 at cutoff and yields no_structure for the full universe.
            orb_high_ts = getattr(orb_obj, "orb_high_extreme_ts", None) if orb_obj else None
            orb_low_ts = getattr(orb_obj, "orb_low_extreme_ts", None) if orb_obj else None
            if orb_high_ts is None or orb_low_ts is None:
                try:
                    win_open = ts_630_pt
                except Exception:
                    win_open = None
                if orb_high_ts is None:
                    orb_high_ts = win_open
                if orb_low_ts is None:
                    orb_low_ts = win_open
            orb_context_by_symbol[symbol] = {
                "orb_high": getattr(orb_obj, "orb_high", None) if orb_obj else None,
                "orb_low": getattr(orb_obj, "orb_low", None) if orb_obj else None,
                "orb_ts": getattr(orb_obj, "capture_time", None) if orb_obj else None,
                "orb_high_ts": orb_high_ts,
                "orb_low_ts": orb_low_ts,
                "orb_box_source": "orb2_630_730",
                # A1 prices are E*TRADE session H/L at ORB2 freeze — not derived from path bars.
                "orb_level_source": getattr(orb_obj, "source", None) if orb_obj else None,
            }

            has_intraday_row = raw_bars_fetched > 0
            has_quote_usable = bool(
                quote
                and isinstance(quote, dict)
                and (quote.get("last") or quote.get("close") or quote.get("price"))
            )
            diag_line = (
                f"symbol={symbol} | raw_bars_fetched={raw_bars_fetched} | bars_after_timezone_normalization={bars_after_tz} | "
                f"parse_fail={parse_fail} | pre730_bars={len(pre730_bars)} | bars_in_630_730_window={window_ct} | "
                f"fallback_bars_generated={synth_added} | selector_input_bars={len(selector_input_bars)} | "
                f"intraday_row_present={has_intraday_row} | quote_usable={has_quote_usable} | merge_error={bool(merge_error)} | "
                f"final_reason={final_reason}"
            )
            if final_reason != "merged_ok" and len(fail_diag_samples) < 5:
                fail_diag_samples.append(diag_line)
            elif final_reason == "merged_ok" and len(ok_diag_samples) < 5:
                ok_diag_samples.append(diag_line)

        log.warning(
            "TRENDLINE_PIPELINE | stage=build_context | session_pt_date=%s | ts_630_pt=%s | ts_700_pt=%s | ts_730_cutoff_pt=%s | "
            "cutoff_utc=%s | intraday_path=yahoo_1m_primary_with_broker_quote_merge_fallback | chunk_size=%d | "
            "intraday_batch_calls=%d | quote_batch_calls=%d | symbols_requested_post_orb=%d | symbols_attempted=%d | "
            "skipped_due_to_budget=%d | raw_rows_total=%d | symbols_with_intraday_row=%d | symbols_with_quotes=%d | "
            "batch_quotes_map_size=%d",
            session_date_pt.isoformat(),
            ts_630_pt.isoformat(),
            ts_700_pt.isoformat(),
            ts_730_pt.isoformat(),
            cutoff_display_utc,
            chunk_sz,
            intraday_batch_calls,
            quote_batch_calls,
            len(symbols_post_orb_requested),
            len(symbols),
            skipped_budget,
            raw_rows_total,
            symbols_with_raw_rows,
            symbols_with_quotes,
            len(batch_quotes) if isinstance(batch_quotes, dict) else 0,
        )

        for sample in fail_diag_samples:
            log.warning("TRENDLINE_PIPELINE | stage=build_bar_diagnostics | %s", sample)
        for sample in ok_diag_samples[:5]:
            log.warning("TRENDLINE_PIPELINE | stage=build_bar_diagnostics | %s", sample)

        tl_config = getattr(self.trendline_signal_engine, "config", None)
        candidate_objects: List[Any] = []
        no_structure = 0
        ambiguous_structure = 0
        for symbol in symbols:
            orb_obj = self._orb2_obj_for_symbol(symbol)
            orb_ctx = orb_context_by_symbol.get(symbol, {})
            bars_for_sel = intraday_by_symbol.get(symbol, [])
            selections = select_pre730_structure_setup(
                symbol,
                bars_for_sel,
                orb_ctx,
                config=tl_config,
            )
            if not selections:
                if len(bars_for_sel) >= 2:
                    no_structure += 1
                continue
            dual_lane_id = f"{symbol}_{now_utc.strftime('%Y%m%d')}"
            for selection in selections:
                peer_role = (
                    "peer_bear_call"
                    if selection.direction.value == "bear"
                    else "peer_bull_put"
                )
                setup_base = {
                    "signal_type": "TRENDLINE_UNIVERSE",
                    "strategy_name": "easyTrendline_0DTE",
                    "entry_type": "trendline_break",
                    "strategy_type": "trendline_0dte",
                    "source_path": "easyTrendline",
                    "trendline_slot": "trendline1",
                    "orb_box_source": "orb2_630_730",
                    "orb_high": getattr(orb_obj, "orb_high", None) if orb_obj else None,
                    "orb_low": getattr(orb_obj, "orb_low", None) if orb_obj else None,
                    "candidate_source": "full_0dte_list" if use_full_list else "rule_confirmed_list",
                    "setup_type": selection.setup_type.value,
                    "trigger_direction": selection.trigger_direction,
                    "expected_option_side": selection.expected_option_side,
                    "trendline_structure_source": "pre730_structure_envelope",
                    "structure_fit_mse": selection.fit_mse,
                    "structure_alternate_fit_mse": selection.alternate_fit_mse,
                    "structure_selection_reason": selection.selection_reason,
                    "structure_display_label": getattr(selection, "structure_display_label", "") or "",
                    "structure_explainability": dict(getattr(selection, "explainability", None) or {}),
                    "line_distance_at_cutoff_pct": (
                        (getattr(selection, "explainability", None) or {}).get("line_distance_pct")
                    ),
                    "line_geometry": selection.direction.value,
                    "dual_lane_pair_id": dual_lane_id,
                    "dual_lane_role": peer_role,
                    "control_score_primary": 0.0,
                    "control_score_secondary": 0.0,
                    # Keep false so emit does not invalidate the opposite peer via dual-lane kill.
                    "dual_lane_armed": False,
                    "geometry_dual_side_watch": True,
                }
                candidate_objects.append(
                    TrendlineCandidate(
                        symbol=symbol,
                        direction=selection.direction,
                        qualified_at=now_utc,
                        priority_score=0.0,
                        confidence=0.0,
                        trendline=selection.trendline,
                        setup_payload=setup_base,
                        state=TrendlineCandidateState.WAITING_FOR_BUILD,
                    )
                )
                sr = str(getattr(selection, "selection_reason", "") or "")
                if "ambiguous_tie_break" in sr:
                    ambiguous_structure += 1

        reason_snapshot = ""
        if fail_reason_counts:
            reason_snapshot = " | " + " | ".join(f"reason_{k}={v}" for k, v in sorted(fail_reason_counts.items()))

        # Always seed engine bar cache from TL1 path bars (Yahoo 1m / merge) —
        # including symbols that did not qualify TL1 — so TL2/TL3 inject has A2 hull data.
        try:
            eng = getattr(self, "trendline_signal_engine", None)
            if eng is not None and hasattr(eng, "seed_bar_cache_from_intraday"):
                n_seed = int(eng.seed_bar_cache_from_intraday(intraday_by_symbol) or 0)
                if n_seed:
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=build | action=seed_bar_cache | symbols=%d | "
                        "note=tl2_tl3_path_ready_even_if_empty_tl1",
                        n_seed,
                    )
        except Exception as seed_ex:
            log.debug("TRENDLINE_PIPELINE | stage=build | action=seed_bar_cache_failed | err=%s", seed_ex)

        if not candidate_objects:
            self._trendline_finalize_empty_tl1_build(
                reason="no_structure_qualified_candidates"
            )
            log.info(
                "TRENDLINE_PIPELINE | stage=build | detail=empty_tl1 | "
                f"symbols_requested_post_orb={len(symbols_post_orb_requested)} | symbols_attempted={len(symbols)} | "
                f"watch_active={bool(getattr(self, '_trendline_watch_active', False))}"
            )
        else:
            self.trendline_signal_engine.initialize_candidates(
                candidates=candidate_objects,
                intraday_by_symbol=intraday_by_symbol,
                orb_context_by_symbol=orb_context_by_symbol,
                now_utc=now_utc,
                session_cutoff_utc=ts_730_pt.astimezone(timezone.utc),
            )
            self._pending_trendline_candidates = list(candidate_objects)
            self._trendline_watch_active = True
            self._ensure_trendline_buffer_floor(force=True)
            self._refresh_trendline_slot_capital()
            built_count = sum(1 for c in candidate_objects if getattr(c, "trendline", None) is not None)
            invalidated_count = sum(1 for c in candidate_objects if str(getattr(c, "state", "")) == "TrendlineCandidateState.INVALIDATED")
            try:
                self._persist_trendline_geometry_now(
                    candidate_objects,
                    include_break_state=False,
                    include_extreme_ts=True,
                    metadata={"source": "tl1_build", "built_count": built_count},
                )
            except Exception as persist_ex:
                log.warning(
                    "TRENDLINE_PIPELINE | stage=build | action=persist_geometry_failed | err=%s",
                    persist_ex,
                )
            log.warning(
                "TRENDLINE_PIPELINE | stage=build | "
                f"candidate_source={'full_0dte_list' if use_full_list else 'rule_confirmed_list'} | "
                f"candidates={len(candidate_objects)} | trendlines_built={built_count} | invalidated={invalidated_count} | "
                f"watch_active=true | "
                f"max_open={self._trendline_max_open_positions} | "
                f"slot_count={self._trendline_slot_count} | slot_capital={self._trendline_slot_capital:.2f} | "
                f"buffer_reserve={self._trendline_buffer_reserve:.2f} | available_cash={self._trendline_available_cash:.2f} | "
                f"entry_budget={self._trendline_entry_budget:.2f}"
            )
            try:
                max_anchor_samples = int(float(get_config_value("TRENDLINE_BUILD_ANCHOR_LOG_MAX", 15)))
            except Exception:
                max_anchor_samples = 15
            max_anchor_samples = max(0, min(40, max_anchor_samples))
            if max_anchor_samples > 0:
                from zoneinfo import ZoneInfo

                _pt = ZoneInfo("America/Los_Angeles")
                anchor_parts: List[str] = []
                for c in sorted(candidate_objects, key=lambda x: str(getattr(x, "symbol", ""))):
                    tl = getattr(c, "trendline", None)
                    if tl is None:
                        continue
                    a1, a2 = tl.anchor_one, tl.anchor_two
                    anchor_parts.append(
                        f"{c.symbol}:{tl.direction.value}|"
                        f"A1({a1.source})={float(a1.price):.4f}@{a1.ts.astimezone(_pt).strftime('%H:%M')}PT|"
                        f"A2({a2.source})={float(a2.price):.4f}@{a2.ts.astimezone(_pt).strftime('%H:%M')}PT"
                    )
                    if len(anchor_parts) >= max_anchor_samples:
                        break
                if anchor_parts:
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=build_anchors_sample | shown=%d | rule=bull_ORB_low_plus_min_higher_low_bear_ORB_high_plus_max_lower_high | %s",
                        len(anchor_parts),
                        " || ".join(anchor_parts),
                    )

        build_wall_end = datetime.now(timezone.utc)
        total_build_duration_ms = (time.perf_counter() - build_t0) * 1000.0
        avg_symbol_processing_ms = total_build_duration_ms / max(len(symbols_post_orb_requested), 1)
        trendline_symbols_merged_successfully = fallback_successes

        timing_extra = (
            f" | symbols_requested_post_orb={len(symbols_post_orb_requested)} | symbols_attempted={len(symbols)} | "
            f"skipped_due_to_budget={skipped_budget} | build_start_utc={build_wall_start.isoformat()} | "
            f"build_end_utc={build_wall_end.isoformat()} | total_build_duration_ms={total_build_duration_ms:.1f} | "
            f"avg_symbol_processing_ms={avg_symbol_processing_ms:.2f} | batch_quote_duration_ms={batch_quote_duration_ms:.1f} | "
            f"intraday_fetch_duration_ms={intraday_fetch_duration_ms:.1f}"
        )

        telemetry_pkg: Dict[str, Any] = {
            "trendline_intraday_requests": trendline_intraday_requests,
            "trendline_quote_requests": trendline_quote_requests,
            "trendline_batch_quote_calls": quote_batch_calls,
            "trendline_intraday_batch_calls": intraday_batch_calls,
            "trendline_symbols_requested": len(symbols_post_orb_requested),
            "trendline_symbols_with_intraday_row": symbols_with_raw_rows,
            "trendline_symbols_with_quotes": symbols_with_quotes,
            "trendline_symbols_merged_successfully": trendline_symbols_merged_successfully,
            "trendline_symbols_skipped_due_to_request_budget": skipped_budget,
        }
        self._trendline_last_build_telemetry = dict(
            telemetry_pkg,
            total_build_duration_ms=round(total_build_duration_ms, 2),
            build_start_utc=build_wall_start.isoformat(),
            build_end_utc=build_wall_end.isoformat(),
        )
        self._accumulate_trendline_build_telemetry(telemetry_pkg)

        log.warning(
            "TRENDLINE_PIPELINE | stage=request_summary | symbols_requested=%d | intraday_calls=%d | quote_calls=%d | "
            "batch_quote_calls=%d | merged_success=%d | skipped_budget=%d | trendline_intraday_requests=%d | "
            "trendline_quote_requests=%d | symbols_with_intraday_row=%d | symbols_with_quotes=%d | "
            "total_build_duration_ms=%.1f | avg_symbol_processing_ms=%.2f | batch_quote_duration_ms=%.1f | "
            "intraday_fetch_duration_ms=%.1f",
            len(symbols_post_orb_requested),
            intraday_batch_calls,
            quote_batch_calls,
            quote_batch_calls,
            trendline_symbols_merged_successfully,
            skipped_budget,
            trendline_intraday_requests,
            trendline_quote_requests,
            symbols_with_raw_rows,
            symbols_with_quotes,
            total_build_duration_ms,
            avg_symbol_processing_ms,
            batch_quote_duration_ms,
            intraday_fetch_duration_ms,
        )

        if not candidate_objects:
            log.warning(
                "TRENDLINE_PIPELINE | stage=build_summary | symbols=%d | initial_failures=%d | fallback_attempts=%d | "
                "fallback_successes=%d | qualified_candidates=0 | no_structure=%d | missing_orb=%d | "
                "insufficient_bars_final=%d | pre730_filter_zero_bars=%d | insufficient_window_bars=%d | "
                "ambiguous_structure=%d | outcome=no_qualified_candidates%s%s",
                len(symbols),
                initial_lt2,
                fallback_attempts,
                fallback_successes,
                no_structure,
                missing_orb,
                insufficient_final,
                pre730_filter_zero_bars,
                insufficient_window_bars,
                ambiguous_structure,
                reason_snapshot,
                timing_extra,
            )
            # Empty TL1 still unlocks watch for TL2/TL3; queue the same post-build
            # discovery tick BO uses after Step 5 release.
            if getattr(self, "_trendline_watch_active", False):
                defer_post_build_watch = (
                    str(
                        get_config_value(
                            "TRENDLINE_DEFER_POST_BUILD_WATCH_UNTIL_ORB_BATCH", "true"
                        )
                    )
                    .strip()
                    .lower()
                    in ("1", "true", "yes", "on")
                )
                watch_mode = False
                try:
                    from modules.orb1_0dte_watch import discovery_mode_is_watch

                    watch_mode = bool(discovery_mode_is_watch())
                except Exception:
                    watch_mode = False
                if watch_mode:
                    # Watch mode: BO already unlocked after ORB2; only hold first TL
                    # tick until TL1 discovery release (no legacy Signal Collection wait).
                    self._trendline_post_build_watch_pending = True
                    log.info(
                        "TRENDLINE_PIPELINE | stage=watch | "
                        "action=defer_first_watch_until_tl_unlock | "
                        "reason=watch_mode_post_tl1 | watch_active=true"
                    )
                elif defer_post_build_watch:
                    self._trendline_post_build_watch_pending = True
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=watch | action=deferred_post_build | "
                        "reason=empty_tl1_await_orb_batch_release | watch_active=true",
                    )
            return

        log.warning(
            "TRENDLINE_PIPELINE | stage=build_summary | symbols=%d | initial_failures=%d | fallback_attempts=%d | "
            "fallback_successes=%d | qualified_candidates=%d | no_structure=%d | missing_orb=%d | "
            "insufficient_bars_final=%d | pre730_filter_zero_bars=%d | insufficient_window_bars=%d | "
            "ambiguous_structure=%d | outcome=candidates_initialized%s%s",
            len(symbols),
            initial_lt2,
            fallback_attempts,
            fallback_successes,
            len(candidate_objects),
            no_structure,
            missing_orb,
            insufficient_final,
            pre730_filter_zero_bars,
            insufficient_window_bars,
            ambiguous_structure,
            reason_snapshot,
            timing_extra,
        )
        self._log_trendline_feature_events(candidate_objects, stage="build")
        defer_post_build_watch = (
            str(get_config_value("TRENDLINE_DEFER_POST_BUILD_WATCH_UNTIL_ORB_BATCH", "true")).strip().lower()
            in ("1", "true", "yes", "on")
        )
        watch_mode = False
        try:
            from modules.orb1_0dte_watch import discovery_mode_is_watch

            watch_mode = bool(discovery_mode_is_watch())
        except Exception:
            watch_mode = False
        if watch_mode:
            self._trendline_post_build_watch_pending = True
            log.info(
                "TRENDLINE_PIPELINE | stage=watch | "
                "action=defer_first_watch_until_tl_unlock | "
                "reason=watch_mode_post_tl1 | watch_active=true"
            )
        elif defer_post_build_watch:
            self._trendline_post_build_watch_pending = True
            log.warning(
                "TRENDLINE_PIPELINE | stage=watch | action=deferred_post_build | "
                "reason=await_signal_collection_and_orb_batch | watch_active=true",
            )
        else:
            try:
                await self._run_trendline_watch_cycle()
            except Exception as post_build_watch_err:
                log.warning(
                    "TRENDLINE_PIPELINE | stage=watch | action=post_build_tick_error | reason=%s",
                    post_build_watch_err,
                )

    async def _maybe_build_and_watch_tl0(self) -> None:
        """After ORB1 ≥06:45 secure: Yahoo 1m + TL0 inject, then arm TL0 + ORB1 BO discovery."""
        if not getattr(self, "_enable_trendline_strategy", False):
            return
        try:
            from modules.trendline_tl0_build import maybe_run_tl0_build

            n = await maybe_run_tl0_build(self)
            if n:
                log.info(
                    "TRENDLINE_PIPELINE | stage=tl0 | action=built | candidates=%d | gate=orb1_ge_0645",
                    n,
                )
        except Exception as tl0_err:
            log.warning("TRENDLINE_PIPELINE | stage=tl0 | action=build_error | err=%s", tl0_err)
        # Close the former 06:45→06:50 gap: once TL0 structure is ready, activate ORB1 BO
        # on the same handoff so TL0 + ORB1 discovery share the post-645 window to 07:25.
        if getattr(self, "_trendline0_ready", False):
            try:
                from modules.orb1_0dte_watch import activate_orb1_0dte_watch, discovery_mode_is_watch

                if discovery_mode_is_watch() and getattr(self, "_enable_0dte_strategy", True):
                    activated = activate_orb1_0dte_watch(self)
                    if activated:
                        log.info(
                            "SCHEDULER_ORDER | stage=orb1_watch | action=activate_with_tl0 | "
                            "watch_count=%d | reason=morning_structure_complete",
                            activated,
                        )
            except Exception as orb1_arm_err:
                log.debug(
                    "SCHEDULER_ORDER | stage=orb1_watch | action=activate_with_tl0_skip | err=%s",
                    orb1_arm_err,
                )
        # Watch/discovery runs only via the shared 10s unified discovery scheduler —
        # do not dual-drive TL0 on every main-loop tick (API budget).

    def _orb1_memory_freeze_valid(self) -> bool:

        """True when in-memory ORB#1 is a same-day post-06:45 freeze."""
        mgr = getattr(self, "orb_strategy_manager", None)
        rows = getattr(mgr, "orb_data", None) if mgr is not None else None
        if not rows:
            return False
        try:
            from modules.session_clock import orb1_capture_window_pt
            from modules.daily_run_tracker import _current_trading_date
            from zoneinfo import ZoneInfo

            pt_tz = ZoneInfo("America/Los_Angeles")
            today = _current_trading_date()
            _, orb1_ready = orb1_capture_window_pt()
            for row in rows.values():
                ct = getattr(row, "capture_time", None)
                if ct is None and isinstance(row, dict):
                    ct = row.get("capture_time")
                if ct is None:
                    return False
                if isinstance(ct, str):
                    ct = datetime.fromisoformat(ct.replace("Z", "+00:00"))
                if getattr(ct, "tzinfo", None) is None:
                    ct = ct.replace(tzinfo=pt_tz)
                else:
                    ct = ct.astimezone(pt_tz)
                if ct.date() != today or ct.time() < orb1_ready:
                    return False
                try:
                    if isinstance(row, dict):
                        hi = float(row.get("orb_high") or 0)
                        lo = float(row.get("orb_low") or 0)
                    else:
                        hi = float(getattr(row, "orb_high", 0) or 0)
                        lo = float(getattr(row, "orb_low", 0) or 0)
                except Exception:
                    return False
                if hi <= 0 or lo <= 0 or hi < lo:
                    return False
            return True
        except Exception:
            return False

    def _hydrate_orb1_from_daily_markers(self) -> int:
        """Load day-locked ORB#1 from GCS/local markers when memory is empty/invalid."""
        if self._orb1_memory_freeze_valid():
            n = len(getattr(getattr(self, "orb_strategy_manager", None), "orb_data", None) or {})
            return n
        tracker = getattr(self, "daily_run_tracker", None)
        mgr = getattr(self, "orb_strategy_manager", None)
        if tracker is None or mgr is None or not hasattr(tracker, "get_today_state"):
            return 0
        try:
            from modules.daily_run_tracker import orb1_marker_is_valid_day_freeze

            state = tracker.get_today_state() or {}
            orb_info = state.get("orb") or {}
            if not orb1_marker_is_valid_day_freeze(orb_info):
                return 0
            snapshot = orb_info.get("snapshot") or {}
            if not snapshot:
                return 0
            loaded = int(mgr.load_orb_snapshot(snapshot) or 0)
            if loaded > 0:
                self._orb_captured_today = True
                self._orb_backfill_attempted = True
                log.info(
                    "ORB_CAPTURE | orb_label=ORB#1 | action=hydrate_from_markers | captured=%d",
                    loaded,
                )
            return loaded
        except Exception as hydrate_err:
            log.warning(
                "ORB_CAPTURE | orb_label=ORB#1 | action=hydrate_failed | reason=%s",
                hydrate_err,
            )
            return 0

    def _persist_trendline_geometry_now(
        self,
        candidates: Optional[Any] = None,
        *,
        include_break_state: bool = True,
        include_extreme_ts: bool = True,
        metadata: Optional[Dict[str, Any]] = None,
        prune_prior_slots_for_symbol: Optional[str] = None,
        prune_keep_slot: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Merge current TL A1/A2/slope (+ inject state) into daily markers freeze."""
        tracker = getattr(self, "daily_run_tracker", None)
        if tracker is None or not hasattr(tracker, "record_trendline_geometry_merge"):
            return {"ok": False, "reason": "no_tracker"}
        try:
            from modules.trendline_geometry_persist import (
                collect_orb2_extreme_ts,
                serialize_candidates,
            )

            if candidates is None:
                eng = getattr(self, "trendline_signal_engine", None)
                cand_map = getattr(eng, "candidates", None) if eng is not None else None
                if not cand_map:
                    cand_map = getattr(self, "_pending_trendline_candidates", None)
                candidates = cand_map
            serialized = serialize_candidates(candidates)
            break_events = None
            built_map = None
            if include_break_state:
                be = getattr(self, "_trendline_orb2_break_events_today", None)
                if isinstance(be, dict) and be:
                    break_events = {str(k).upper(): dict(v) for k, v in be.items() if isinstance(v, dict)}
                bm = getattr(self, "_trendline_orb2_extension_lines_built_today", None)
                if isinstance(bm, dict) and bm:
                    built_map = dict(bm)
            extreme = collect_orb2_extreme_ts(self) if include_extreme_ts else None
            if not serialized and not break_events and not extreme and not (
                prune_prior_slots_for_symbol and prune_keep_slot
            ):
                return {"ok": False, "reason": "nothing_to_persist"}
            return tracker.record_trendline_geometry_merge(
                candidates=serialized or None,
                orb2_break_events=break_events,
                orb2_extension_built=built_map,
                orb2_extreme_ts=extreme,
                metadata=metadata,
                prune_symbol=prune_prior_slots_for_symbol,
                prune_keep_slot=prune_keep_slot,
            )
        except Exception as exc:
            log.warning("TL_GEOMETRY_MARKER | action=persist_failed | err=%s", exc)
            return {"ok": False, "reason": str(exc)}

    def _hydrate_trendline_geometry_from_daily_markers(self) -> int:
        """Restore TL0/TL1/TL2/TL3 A1/A2/slope + inject state from day freeze.

        Returns number of candidates re-armed into the engine.
        """
        eng = getattr(self, "trendline_signal_engine", None)
        if eng is None:
            return 0
        existing = len(getattr(eng, "candidates", None) or {})
        tracker = getattr(self, "daily_run_tracker", None)
        if tracker is None:
            return 0
        try:
            from modules.daily_run_tracker import trendline_geometry_marker_is_valid
            from modules.trendline_geometry_persist import (
                apply_orb2_extreme_ts,
                apply_persisted_envelope_state,
                count_slots,
                deserialize_candidate,
            )

            geo = (
                tracker.get_trendline_geometry()
                if hasattr(tracker, "get_trendline_geometry")
                else (tracker.get_today_state() or {}).get("trendline_geometry")
            )
            if not trendline_geometry_marker_is_valid(geo):
                return 0

            # Restore refined ORB2 A1 timestamps before candidates.
            apply_orb2_extreme_ts(self, geo.get("orb2_extreme_ts") or {})

            events = geo.get("orb2_break_events") if isinstance(geo.get("orb2_break_events"), dict) else {}
            if events:
                store = getattr(self, "_trendline_orb2_break_events_today", None)
                if not isinstance(store, dict):
                    store = {}
                    self._trendline_orb2_break_events_today = store
                for sym, st in events.items():
                    if isinstance(st, dict):
                        store[str(sym).upper()] = dict(st)

            built = geo.get("orb2_extension_built") if isinstance(geo.get("orb2_extension_built"), dict) else {}
            if built:
                self._trendline_orb2_extension_lines_built_today = dict(built)

            cands_blob = geo.get("candidates") if isinstance(geo.get("candidates"), dict) else {}
            pending: List[Any] = list(getattr(self, "_pending_trendline_candidates", None) or [])
            pending_keys = {
                str(getattr(c, "candidate_id", "") or "")
                for c in pending
            }
            hydrated = 0
            restored: List[Any] = []
            for key, row in cands_blob.items():
                if key in (getattr(eng, "candidates", None) or {}):
                    continue
                cand = deserialize_candidate(row)
                if cand is None:
                    continue
                injected = eng.add_runtime_candidate(cand, bars=None, now_utc=datetime.now(timezone.utc))
                if not injected:
                    # If lane gate rejected, still keep definition on pending for desk.
                    continue
                apply_persisted_envelope_state(cand, row)
                hydrated += 1
                restored.append(cand)
                if injected not in pending_keys:
                    pending.append(cand)
                    pending_keys.add(injected)

            if restored or events:
                self._pending_trendline_candidates = pending
                self._trendline_watch_active = True
                try:
                    self._ensure_trendline_buffer_floor(force=True)
                    self._refresh_trendline_slot_capital()
                except Exception:
                    pass
                slots = count_slots(geo)
                # Ready only when TL0 actually landed in the engine — freeze slot
                # counts must not skip a Yahoo TL0 rebuild or arm ORB1 empty.
                if self._trendline_engine_has_tl0_candidates():
                    self._trendline0_ready = True
                # Aug 24 crash: TL0-only hydrate stamped primary TL1 finished → 07:30
                # skipped Yahoo dual-envelope draw. Only a freeze that actually has
                # trendline1 may consume the primary attempt.
                if int(slots.get("trendline1") or 0) > 0:
                    self._note_trendline_build_attempt_finished()
                else:
                    log.warning(
                        "TL_GEOMETRY_MARKER | action=hydrate_keep_tl1_pending | "
                        "candidates=%d | tl0=%d | tl1=0 | "
                        "note=tl0_only_must_not_finish_primary_tl1",
                        hydrated,
                        slots.get("trendline0", 0),
                    )
                from easyTrendline.trendline_models import MAX_TRENDLINE_SLOT as _max_tl_slot

                log.warning(
                    "TL_GEOMETRY_MARKER | action=hydrate | candidates=%d | prior_engine=%d | "
                    "%s | break_syms=%d | watch_active=true",
                    hydrated,
                    existing,
                    " | ".join(
                        f"tl{i}={int(slots.get(f'trendline{i}', 0) or 0)}"
                        for i in range(int(_max_tl_slot) + 1)
                    ),
                    len(events),
                )
            # Overlay CONFIRM/READY after geometry restore (deserialize always WAIT).
            try:
                from modules.discovery_watch_fsm_persist import hydrate_watch_fsm_from_markers

                hydrate_watch_fsm_from_markers(self)
            except Exception:
                pass
            return hydrated
        except Exception as hydrate_err:
            log.warning(
                "TL_GEOMETRY_MARKER | action=hydrate_failed | err=%s",
                hydrate_err,
            )
            return 0

    def _trendline_geometry_freeze_has_tl1(self) -> bool:
        tracker = getattr(self, "daily_run_tracker", None)
        if tracker is None:
            return False
        try:
            from modules.trendline_geometry_persist import count_slots

            geo = (
                tracker.get_trendline_geometry()
                if hasattr(tracker, "get_trendline_geometry")
                else {}
            )
            return int(count_slots(geo).get("trendline1") or 0) > 0
        except Exception:
            return False

    def _hydrate_orb2_from_daily_markers(self) -> int:
        """Load day-locked ORB#2 from GCS/local markers when memory is empty.

        Prevents mid-session Cloud Run restarts from re-fetching live session OHLC
        (which expands the box past the 06:30–07:30 freeze).
        """
        mgr = getattr(self, "orb_strategy_manager", None)
        if mgr is None:
            return 0
        existing = getattr(mgr, "orb2_data", None) or {}
        if existing and hasattr(mgr, "orb2_already_captured_today"):
            try:
                from modules.breakout_watch import orb2_freeze_is_premature

                if mgr.orb2_already_captured_today() and not orb2_freeze_is_premature(self):
                    return len(existing)
            except Exception:
                # Do not treat a failed premature-check as a valid ≥07:30 freeze.
                pass
        tracker = getattr(self, "daily_run_tracker", None)
        if tracker is None or not hasattr(tracker, "get_today_state"):
            return 0
        try:
            from modules.daily_run_tracker import orb2_marker_is_valid_day_freeze

            state = tracker.get_today_state() or {}
            orb2_info = state.get("orb2") or {}
            if not orb2_marker_is_valid_day_freeze(orb2_info):
                return 0
            snapshot = orb2_info.get("snapshot") or {}
            if not snapshot or not hasattr(mgr, "load_orb2_snapshot"):
                return 0
            from zoneinfo import ZoneInfo

            pt_today = datetime.now(ZoneInfo("America/Los_Angeles")).strftime("%Y-%m-%d")
            loaded = int(mgr.load_orb2_snapshot(snapshot, captured_pt_date=pt_today) or 0)
            if loaded > 0:
                self._orb2_data = mgr.orb2_data
                self._orb2_captured_pt_date = getattr(mgr, "_orb2_captured_pt_date", pt_today)
                self._orb2_capture_permitted_post_0dte = True
                log.info(
                    "ORB_CAPTURE | orb_label=ORB#2 | action=hydrate_from_markers | captured=%d",
                    loaded,
                )
                try:
                    self._hydrate_trendline_geometry_from_daily_markers()
                except Exception:
                    pass
            return loaded
        except Exception as hydrate_err:
            log.warning(
                "ORB_CAPTURE | orb_label=ORB#2 | action=hydrate_failed | reason=%s",
                hydrate_err,
            )
            return 0

    async def _ensure_orb2_captured_for_tl_bo(self) -> tuple:
        """
        Run ORB #2 capture to completion before TL1 / BO.

        Only after Step 5 ORB1 Breakout handoff permission + PT at/after 07:30
        (full 06:30–07:30 E*TRADE session OHLC). Premature freezes are cleared
        and force-recaptured. Returns ``(complete, symbol_count)``.

        Valid day freezes are hydrated from GCS markers before any live re-fetch
        so Cloud Run redeploys keep the same 06:30–07:30 box all session.
        """
        try:
            from modules.breakout_watch import (
                capture_orb2_breakout_ranges,
                clear_orb2_freeze,
                orb2_freeze_is_premature,
                orb2_freeze_valid_for_tl_bo,
                orb2_session_ohlc_ready,
            )

            # Permit capture only on this post-0DTE / recovery path.
            self._orb2_capture_permitted_post_0dte = True

            # Prefer day-locked marker over live ETrade session OHLC after restart.
            self._hydrate_orb2_from_daily_markers()

            force = False
            if orb2_freeze_is_premature(self):
                clear_orb2_freeze(self, reason="post_0dte_reject_premature_orb2")
                force = True
            if not orb2_session_ohlc_ready():
                log.warning(
                    "ORB_CAPTURE | orb_label=ORB#2 | action=hold | reason=await_at_or_after_0730_pt"
                )
                return False, 0
            if orb2_freeze_valid_for_tl_bo(self, require_session_ready=True):
                n_ready = len(getattr(getattr(self, "orb_strategy_manager", None), "orb2_data", None) or {})
                log.info(
                    "ORB_CAPTURE | orb_label=ORB#2 | action=reuse_hydrated_or_memory | captured=%d",
                    n_ready,
                )
                try:
                    await self._send_orb2_capture_alert_if_needed(capture_time_seconds=0.0)
                except Exception:
                    pass
                return True, n_ready
            await capture_orb2_breakout_ranges(self, force=force, permitted=True)
        except Exception as orb2_cap_err:
            log.warning(
                "ORB_CAPTURE | orb_label=ORB#2 | action=post_0dte_error | reason=%s",
                orb2_cap_err,
            )

        mgr = getattr(self, "orb_strategy_manager", None)
        n = 0
        try:
            n = len(getattr(mgr, "orb2_data", None) or {}) or len(
                getattr(self, "_orb2_data", None) or {}
            )
        except Exception:
            n = 0

        complete = False
        try:
            from modules.breakout_watch import orb2_freeze_valid_for_tl_bo

            # Reject premature / pre-07:30 stamps even if ``orb2_already_captured_today``.
            complete = bool(orb2_freeze_valid_for_tl_bo(self, require_session_ready=True))
        except Exception:
            complete = False

        # Coverage vs Breakout/TL universe (informational + soft completeness).
        universe_n = 0
        try:
            from modules.breakout_watch import resolve_breakout_universe

            universe_n = len(resolve_breakout_universe(self) or [])
        except Exception:
            universe_n = 0
        coverage = (float(n) / float(universe_n)) if universe_n > 0 else (1.0 if n > 0 else 0.0)
        log.info(
            "SCHEDULER_ORDER | stage=orb2_capture | action=%s | orb2_symbols=%d | "
            "universe=%d | coverage=%.3f | stamped_today=%s",
            "complete" if complete else "incomplete",
            n,
            universe_n,
            coverage,
            str(complete).lower(),
        )
        # Require a finished freeze for today; allow minor quote misses but not an empty/partial unstamped store.
        if complete and universe_n > 0 and n < max(1, int(universe_n * 0.5)):
            log.warning(
                "ORB_CAPTURE | orb_label=ORB#2 | action=low_coverage | captured=%d | universe=%d | "
                "holding_tl1_until_retry",
                n,
                universe_n,
            )
            complete = False
        return complete, n

    def _orb2_obj_for_symbol(self, symbol: str) -> Any:
        """TL1 / BO box: ORB2 store only (ORB1 is reserved for ORB1 Breakout)."""
        sym = str(symbol or "").strip().upper()
        mgr = getattr(self, "orb_strategy_manager", None)
        if mgr is not None:
            od = (getattr(mgr, "orb2_data", None) or {}).get(sym)
            if od is not None:
                return od
        return (getattr(self, "_orb2_data", None) or {}).get(sym)

    async def _release_tl_bo_after_orb_0dte(self) -> None:
        """
        Post ORB1 Breakout Step 5 best-performance handoff:

          1) ORB2 capture/hydrate (~3–4s)
          2) Unlock BO discovery immediately (unified scan may start)
          3) TL1 build/hydrate (~4–6.5s) while TL discovery is held
          4) Release TL discovery to join the same BO/TL rotating scan

        TL discovery must not evaluate breaks until TL1 A1/A2/slope (or day-freeze
        restore) finishes — avoids false signals on missing/incorrect TL1 lines.
        Empty TL1 still releases TL watch for TL2/TL3 inject.

        Before 07:30 PT: arm TL1 pending only (no ORB2 capture / unlock spam).
        """
        try:
            from modules.session_clock import orb2_tl_window_pt

            pt_now = None
            if hasattr(self, "orb_strategy_manager") and self.orb_strategy_manager:
                pt_now = self.orb_strategy_manager._get_current_time_pt()
            _orb2_start, _ = orb2_tl_window_pt()
            if pt_now is not None and pt_now < _orb2_start:
                armed = self._arm_deferred_trendline_build_if_needed(
                    pending_so_signals=list(getattr(self, "_pending_so_signals", None) or []),
                    pending_dte_signals=list(getattr(self, "_pending_dte_signals", None) or []),
                )
                if armed:
                    log.info(
                        "SCHEDULER_ORDER | stage=trendline_build | action=arm_pre_0730 | "
                        "reason=release_gated_until_orb2_window"
                    )
                return
        except Exception:
            pass

        # Idempotent post-ORB2 handoff: keep BO alive; finish TL1 if still held.
        if getattr(self, "_orb_0dte_batch_complete_for_trendline", False):
            try:
                await self._ensure_breakout_watch_activated()
            except Exception:
                pass
            if getattr(self, "_trendline_discovery_hold_for_tl1", False):
                task = getattr(self, "_tl1_post_orb2_task", None)
                if task is not None and not task.done():
                    return
                await self._finish_tl1_and_release_tl_discovery()
                return
            tl_ready = (
                not getattr(self, "_enable_trendline_strategy", False)
                or self._trendline_tl1_primary_completed_today()
                or self._trendline_engine_has_tl1_candidates()
                or bool(getattr(self, "_trendline_build_pending_at_730", None))
            )
            if tl_ready and not getattr(self, "_trendline_build_pending_at_730", None):
                # Still need primary TL1 when only TL0 lines are present.
                if not self._trendline_primary_tl1_still_needed():
                    return
            # Unlocked BO earlier without a finished TL1 — finish now.
            await self._finish_tl1_and_release_tl_discovery()
            return

        self._orb2_capture_permitted_post_0dte = True
        if not getattr(self, "_orb2_handoff_permit_logged_today", False):
            self._orb2_handoff_permit_logged_today = True
            log.info(
                "SCHEDULER_ORDER | stage=orb2_handoff | action=permit_orb2_capture | "
                "gate=post_orb_0dte_step5"
            )
        # Arm before capture wait so ORB2-incomplete retries keep a pending TL1 build.
        armed = self._arm_deferred_trendline_build_if_needed(
            pending_so_signals=list(getattr(self, "_pending_so_signals", None) or []),
            pending_dte_signals=list(getattr(self, "_pending_dte_signals", None) or []),
        )
        if armed:
            log.info(
                "SCHEDULER_ORDER | stage=trendline_build | action=armed_on_release | "
                "reason=ensure_tl1_pending_post_orb1_watch"
            )
        complete, orb2_n = await self._ensure_orb2_captured_for_tl_bo()
        log.info(
            "SCHEDULER_ORDER | stage=orb2_then_tl1 | action=post_0dte | "
            "orb2_complete=%s | orb2_symbols=%d | tl1_pending=%s",
            str(complete).lower(),
            orb2_n,
            str(bool(getattr(self, "_trendline_build_pending_at_730", None))).lower(),
        )
        if not complete:
            self._log_throttled_warning(
                "orb2_capture_incomplete_before_tl1",
                (
                    "TRENDLINE_PIPELINE | stage=build | action=hold | "
                    f"reason=orb2_capture_incomplete_before_tl1 | orb2_symbols={orb2_n}"
                ),
                interval_sec=30.0,
            )
            return

        # Hold TL discovery for TL1+; keep watch_active if TL0 already armed.
        if getattr(self, "_enable_trendline_strategy", False):
            self._trendline_discovery_hold_for_tl1 = True
            if not getattr(self, "_trendline0_ready", False):
                self._trendline_watch_active = False
        await self._mark_orb_0dte_batch_complete_for_trendline()
        log.info(
            "SCHEDULER_ORDER | stage=breakout_release | action=bo_unlocked_after_orb2 | "
            "tl_discovery_held=%s | note=tl_joins_after_tl1",
            str(bool(getattr(self, "_trendline_discovery_hold_for_tl1", False))).lower(),
        )

        if not getattr(self, "_enable_trendline_strategy", False):
            self._trendline_discovery_hold_for_tl1 = False
            return

        # Concurrent TL1 so main-loop BO discovery can run during the build window.
        try:
            import asyncio

            loop = asyncio.get_running_loop()
            prior = getattr(self, "_tl1_post_orb2_task", None)
            if prior is not None and not prior.done():
                return
            self._tl1_post_orb2_task = loop.create_task(
                self._finish_tl1_and_release_tl_discovery(),
                name="tl1_after_orb2_bo_unlocked",
            )
        except Exception as spawn_err:
            log.warning(
                "SCHEDULER_ORDER | stage=trendline_build | action=tl1_inline_fallback | "
                "reason=%s",
                spawn_err,
            )
            await self._finish_tl1_and_release_tl_discovery()

    async def _finish_tl1_and_release_tl_discovery(self) -> None:
        """Build/hydrate TL1 then clear the TL discovery hold (BO already unlocked)."""
        try:
            # Midday restart / redeploy: prefer day-frozen TL geometry over blank rebuild.
            try:
                if (
                    self._trendline_geometry_freeze_has_tl1()
                    and not self._trendline_engine_has_tl1_candidates()
                ):
                    n_hyd = int(self._hydrate_trendline_geometry_from_daily_markers() or 0)
                    if self._trendline_engine_has_tl1_candidates():
                        self._trendline_build_pending_at_730 = None
                        log.warning(
                            "SCHEDULER_ORDER | stage=trendline_build | "
                            "action=hydrate_before_tl_unlock | hydrated=%d | "
                            "reason=day_freeze_prefer_over_rebuild_or_inject",
                            n_hyd,
                        )
            except Exception as hyd_err:
                log.debug(
                    "SCHEDULER_ORDER | stage=trendline_build | hydrate_before_tl_unlock_skip=%s",
                    hyd_err,
                )

            needs_tl1 = self._trendline_primary_tl1_still_needed()
            if not needs_tl1:
                log.info(
                    "SCHEDULER_ORDER | stage=trendline_build | action=skip_primary_tl1 | "
                    "reason=already_has_tl1_or_primary_completed | has_tl1=%s | completed=%s",
                    str(self._trendline_engine_has_tl1_candidates()).lower(),
                    str(self._trendline_tl1_primary_completed_today()).lower(),
                )
            if needs_tl1:
                if self._tl1_build_single_flight_active() and not getattr(
                    self, "_trendline_build_pending_at_730", None
                ):
                    # Another caller already owns the in-flight build.
                    pass
                else:
                    if not getattr(self, "_trendline_build_pending_at_730", None):
                        # Prefer 07:10 arm surviving to ORB2; heal only if pending was lost.
                        healed = self._arm_deferred_trendline_build_if_needed(
                            pending_so_signals=list(
                                getattr(self, "_pending_so_signals", None) or []
                            ),
                            pending_dte_signals=list(
                                getattr(self, "_pending_dte_signals", None) or []
                            ),
                        )
                        if healed:
                            log.warning(
                                "TRENDLINE_PIPELINE | stage=build | action=arm_heal_missing_pending | "
                                "reason=pending_lost_before_orb2_build | watch_active=%s | "
                                "engine_candidates=%d | has_tl1=%s",
                                str(bool(getattr(self, "_trendline_watch_active", False))).lower(),
                                self._trendline_existing_engine_candidate_count(),
                                str(self._trendline_engine_has_tl1_candidates()).lower(),
                            )
                    try:
                        await self._run_deferred_trendline_build_if_pending()
                    except Exception as tl_post_0dte_build_err:
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=build | action=post_0dte_run_error | "
                            "reason=%s",
                            tl_post_0dte_build_err,
                        )
                if (
                    self._trendline_primary_tl1_still_needed()
                    and not getattr(self, "_trendline_build_pending_at_730", None)
                    and not self._tl1_build_single_flight_active()
                    and not self._trendline_past_primary_build_window()
                ):
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=build | action=force_direct_tl1_build | "
                        "reason=pending_missing_after_orb2_complete | engine_candidates=%d | has_tl1=%s",
                        self._trendline_existing_engine_candidate_count(),
                        str(self._trendline_engine_has_tl1_candidates()).lower(),
                    )
                    try:
                        await self._build_trendline_candidates_at_730(
                            pending_so_signals=list(
                                getattr(self, "_pending_so_signals", None) or []
                            ),
                            pending_dte_signals=list(
                                getattr(self, "_pending_dte_signals", None) or []
                            ),
                        )
                    except Exception as force_tl1_err:
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=build | action=force_direct_tl1_error | "
                            "reason=%s",
                            force_tl1_err,
                        )
                    self._note_trendline_build_attempt_finished()
            elif getattr(self, "_trendline_build_pending_at_730", None):
                try:
                    await self._run_deferred_trendline_build_if_pending()
                except Exception as tl_pending_err:
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=build | action=post_0dte_pending_error | "
                        "reason=%s",
                        tl_pending_err,
                    )
        finally:
            # Always release the TL hold after the attempt (empty TL1 → TL2/TL3 path OK).
            self._trendline_discovery_hold_for_tl1 = False
            if (
                getattr(self, "_enable_trendline_strategy", False)
                and (
                    self._trendline_existing_engine_candidate_count() > 0
                    or self._trendline_build_attempted_today()
                    or self._trendline_orb2_ready_for_watch()
                )
            ):
                # Build/hydrate usually sets this; empty-TL1 finalize arms TL2/TL3 watch.
                if not getattr(self, "_trendline_watch_active", False):
                    self._trendline_finalize_empty_tl1_build(
                        reason="tl_discovery_release_after_tl1_attempt"
                    )
            log.info(
                "SCHEDULER_ORDER | stage=trendline_release | action=tl_unlocked_after_tl1 | "
                "watch_active=%s | candidates=%d | attempted=%s",
                str(bool(getattr(self, "_trendline_watch_active", False))).lower(),
                self._trendline_existing_engine_candidate_count(),
                str(self._trendline_build_attempted_today()).lower(),
            )
            try:
                await self._run_trendline_post_build_watch_if_pending()
            except Exception as tl_post_batch_err:
                log.warning(
                    "TRENDLINE_PIPELINE | stage=watch | action=post_orb_batch_error | reason=%s",
                    tl_post_batch_err,
                )

    def _tl0_discovery_cutoff_pt(self):
        """TL0 no-new-entries cutoff — Shared.env DISCOVERY_ORB1_TL0_END_PT."""
        from modules.session_clock import orb1_tl0_window_pt

        _, end = orb1_tl0_window_pt()
        return end

    def _tl0_discovery_session_open(self, now_pt=None) -> bool:
        """True while TL0 may discover/enter (after build, same window as ORB1)."""
        if not getattr(self, "_trendline0_ready", False):
            return False
        if now_pt is None:
            try:
                if hasattr(self, "orb_strategy_manager") and self.orb_strategy_manager:
                    now_pt = self.orb_strategy_manager._get_current_time_pt()
                else:
                    from datetime import datetime
                    from zoneinfo import ZoneInfo

                    now_pt = datetime.now(ZoneInfo("America/Los_Angeles")).time()
            except Exception:
                return False
        from modules.session_clock import orb1_tl0_session_open

        return orb1_tl0_session_open(now_pt)

    def _expire_tl0_geometry_after_cutoff(self, *, reason: str = "tl0_geometry_cutoff_0710") -> int:
        """
        Hard-expire all TL0 line candidates at/after 07:25 PT.

        TL1–TL10 keep ``TRENDLINE_TRADE_ACTIVATE_MAX_AGE_SEC`` (3h). TL0 discovery and
        geometry both end at the morning cutoff so process_new_bar(symbol) cannot
        keep advancing sibling TL0 slots after the window.

        Uses wall-clock cutoff (not ``_trendline0_ready``) so pre-ready mornings
        do not wipe TL0, and post-07:25 always expires regardless of ready flag.
        """
        try:
            from datetime import datetime as _dt
            from zoneinfo import ZoneInfo

            if hasattr(self, "orb_strategy_manager") and self.orb_strategy_manager:
                now_pt = self.orb_strategy_manager._get_current_time_pt()
            else:
                now_pt = _dt.now(ZoneInfo("America/Los_Angeles")).time()
        except Exception:
            return 0
        if now_pt < self._tl0_discovery_cutoff_pt():
            return 0
        eng = getattr(self, "trendline_signal_engine", None)
        cands = getattr(eng, "candidates", None) or {}
        if not cands:
            return 0
        from easyTrendline.trendline_models import (
            TrendlineCandidateState,
            trendline_slot_from_payload,
        )

        expired_n = 0
        for cand in list(cands.values()):
            try:
                slot = trendline_slot_from_payload(getattr(cand, "setup_payload", None) or {})
            except Exception:
                slot = ""
            if slot != "trendline0":
                continue
            st = str(getattr(cand, "state", "") or "")
            if any(x in st for x in ("EXECUTED", "EXPIRED", "INVALIDATED")):
                continue
            try:
                if hasattr(eng, "_set_state"):
                    eng._set_state(cand, TrendlineCandidateState.EXPIRED, reason)
                else:
                    cand.state = TrendlineCandidateState.EXPIRED
                    cand.state_reason = reason
            except Exception:
                try:
                    cand.state = TrendlineCandidateState.EXPIRED
                    cand.state_reason = reason
                except Exception:
                    continue
            try:
                from easyTrendline.trendline_simple_mode import (
                    SimpleTrendlineState,
                    set_simple_state,
                )

                set_simple_state(cand, SimpleTrendlineState.EXPIRED, reason)
            except Exception:
                pass
            expired_n += 1
        if expired_n:
            log.warning(
                "TRENDLINE_PIPELINE | stage=expired | action=tl0_geometry_cutoff | "
                "expired=%d | reason=%s | note=no_tl0_trades_after_0710",
                expired_n,
                reason,
            )
        return expired_n

    def _trendline_discovery_allowed(self) -> bool:
        """TL path may join discovery for TL0 (≤07:25) or TL1+ after hold clears."""
        if not getattr(self, "_enable_trendline_strategy", False):
            return False
        # Morning TL0 window only — ends at 07:25 (no TL0 during 07:25–07:30 or TL1 hold).
        if self._tl0_discovery_session_open():
            return True
        if getattr(self, "_trendline_discovery_hold_for_tl1", False):
            return False
        return bool(getattr(self, "_trendline_watch_active", False))

    async def _mark_orb_0dte_batch_complete_for_trendline(self) -> None:
        """
        Unlock Breakout discovery after ORB2 freeze (TL may still be held for TL1).

        Breakout activates from **frozen ORB #2**. TL discovery stays gated by
        ``_trendline_discovery_hold_for_tl1`` / ``_trendline_discovery_allowed``.
        """
        if not getattr(self, "_orb_0dte_batch_complete_for_trendline", False):
            self._orb_0dte_batch_complete_for_trendline = True
            log.info(
                "SCHEDULER_ORDER | stage=orb_0dte_batch_complete | action=bo_discovery_unlocked | "
                "lock=orb_step5_orb2_complete | tl_discovery_held=%s",
                str(bool(getattr(self, "_trendline_discovery_hold_for_tl1", False))).lower(),
            )
        await self._ensure_breakout_watch_activated()
    def _tl_bo_discovery_session_open(self) -> bool:
        """True when the ≥07:30 discovery *session* is open.

        ORB2 Breakout may run as soon as ORB2 is captured (batch-complete).
        TL discovery is a separate gate (``_trendline_discovery_allowed``) that
        waits for TL1. A TL1 miss must not close this session or kill BO.
        """
        from modules.session_clock import now_pt_time, orb2_tl_session_open

        try:
            now_pt = now_pt_time()
            if not orb2_tl_session_open(now_pt):
                return False
        except Exception:
            return False
        if getattr(self, "_orb_0dte_batch_complete_for_trendline", False):
            return True
        # Recovery only: an already-active POST-ORB2 watch. TL0 morning
        # ``_trendline_watch_active`` must not unlock BO / TL1+ before ORB2.
        if getattr(self, "_breakout_watch_active", False):
            return True
        if getattr(self, "_trendline_watch_active", False) and (
            self._trendline_engine_has_tl1_candidates()
            or self._trendline_tl1_primary_completed_today()
            or self._trendline_orb2_ready_for_watch()
        ):
            return True
        return False

    def _schedule_unified_discovery_watch(
        self, *, tl_active: bool, orb1_active: bool = False
    ) -> bool:
        """Run the 10s equity rotate off the main loop (never block 2s monitor).

        Watches stay single-flight on a separate task so a 70–300s ORB1/TL/BO
        pass cannot skip the next 24-name scan. Returns True if a new scan
        was started (advances the 10s clock).
        """
        self._unified_discovery_last_skip = ""
        try:
            self.memory_manager.check_memory_usage()
            rss = float(self.memory_manager.memory_usage or 0.0)
            critical_gb = float(os.getenv("MEMORY_CRITICAL_GB", "1.75") or 1.75)
            if rss >= max(1.0, critical_gb):
                self._unified_discovery_last_skip = "memory_pressure"
                log.warning(
                    "DISCOVERY_UNIFIED | stage=background_skip | reason=memory_pressure | "
                    "rss_gb=%.2f | grep=MONITOR_CADENCE|DISCOVERY_UNIFIED",
                    rss,
                )
                return False
        except Exception:
            pass

        async def _run_scan() -> None:
            started = time.monotonic()
            try:
                from modules.open_position_quote_orchestration import (
                    reset_qg_live_chain_budget,
                    yield_to_open_position_monitor,
                )

                await yield_to_open_position_monitor(self, max_wait_s=0.8)
                reset_qg_live_chain_budget(self)
                self._discovery_task_age_cap_chains = 0
            except Exception:
                try:
                    from modules.open_position_quote_orchestration import reset_qg_live_chain_budget

                    reset_qg_live_chain_budget(self)
                except Exception:
                    pass
                self._discovery_task_age_cap_chains = 0
            try:
                from modules.discovery_watch_batch import run_unified_0dte_discovery_scan

                await run_unified_0dte_discovery_scan(self)
            except Exception as unified_scan_err:
                log.warning(
                    "DISCOVERY_UNIFIED | stage=scan_error | error=%s",
                    unified_scan_err,
                )
            log.info(
                "DISCOVERY_UNIFIED | stage=scan_done | elapsed_s=%.1f | "
                "grep=MONITOR_CADENCE|DISCOVERY_UNIFIED",
                max(0.0, time.monotonic() - started),
            )

        async def _run_watches() -> None:
            started = time.monotonic()
            try:
                from modules.open_position_quote_orchestration import (
                    yield_to_open_position_monitor,
                )

                await yield_to_open_position_monitor(self, max_wait_s=0.35)
            except Exception:
                pass
            if orb1_active:
                try:
                    from modules.orb1_0dte_watch import run_orb1_0dte_watch_cycle

                    await run_orb1_0dte_watch_cycle(self)
                except Exception as orb1_watch_error:
                    log.error(
                        "ORB1_0DTE_WATCH | stage=unified_watch | action=error | reason=%s",
                        orb1_watch_error,
                    )
            if tl_active:
                try:
                    await self._run_trendline_watch_cycle()
                except Exception as trendline_watch_error:
                    log.error(
                        "TRENDLINE_PIPELINE | stage=watch | action=error | reason=%s",
                        trendline_watch_error,
                    )
            if self._enable_breakout_strategy and self._tl_bo_discovery_session_open():
                if not getattr(self, "_breakout_watch_active", False):
                    try:
                        await self._ensure_breakout_watch_activated()
                    except Exception as bo_retry_err:
                        log.debug(
                            "BREAKOUT_PIPELINE | stage=activate_retry | error=%s",
                            bo_retry_err,
                        )
                if getattr(self, "_breakout_watch_active", False):
                    try:
                        from modules.breakout_watch import run_breakout_watch_cycle

                        await run_breakout_watch_cycle(self)
                    except Exception as breakout_watch_error:
                        log.error(
                            "BREAKOUT_PIPELINE | stage=watch | action=error | reason=%s",
                            breakout_watch_error,
                        )
            try:
                await self._trendline_run_deferred_bar_hydrate()
            except Exception as tl_hydrate_err:
                log.debug(
                    "TRENDLINE_PIPELINE | stage=watch_hydrate_deferred | error=%s",
                    tl_hydrate_err,
                )
            try:
                refreshed = await self._refresh_held_path_chain_skew_off_eval()
                if refreshed:
                    log.info(
                        "DISCOVERY_UNIFIED | stage=path_chain_refresh | refreshed=%d | "
                        "grep=MONITOR_CADENCE|PATH_CHAIN_SKEW_REFRESH",
                        int(refreshed),
                    )
            except Exception as path_refresh_err:
                log.debug(
                    "DISCOVERY_UNIFIED | stage=path_chain_refresh | error=%s",
                    path_refresh_err,
                )
            log.info(
                "DISCOVERY_UNIFIED | stage=background_done | elapsed_s=%.1f | "
                "grep=MONITOR_CADENCE|DISCOVERY_UNIFIED",
                max(0.0, time.monotonic() - started),
            )
            try:
                from modules.desk_discovery_pulse import emit_desk_discovery

                emit_desk_discovery(self)
            except Exception as desk_scan_err:
                log.debug("DESK_DISCOVERY_PULSE | emit skipped | %s", desk_scan_err)

        from modules.discovery_watch_batch import unified_discovery_scan_slot_free

        scan_task = getattr(self, "_unified_discovery_scan_task", None)
        watch_task = getattr(self, "_unified_discovery_watch_task", None)
        started_scan = False
        if not unified_discovery_scan_slot_free(scan_task):
            self._unified_discovery_last_skip = "already_running"
            last_skip_log = float(
                getattr(self, "_last_discovery_already_running_log_ts", 0.0) or 0.0
            )
            now_skip = time.time()
            if (now_skip - last_skip_log) >= 15.0:
                self._last_discovery_already_running_log_ts = now_skip
                log.info(
                    "DISCOVERY_UNIFIED | stage=background_skip | reason=already_running | "
                    "lane=scan | grep=MONITOR_CADENCE|DISCOVERY_UNIFIED"
                )
        else:
            self._unified_discovery_scan_task = asyncio.create_task(_run_scan())
            started_scan = True
            log.info(
                "DISCOVERY_UNIFIED | stage=background_scheduled | lane=scan | "
                "tl_active=%s | orb1_active=%s | grep=MONITOR_CADENCE|DISCOVERY_UNIFIED",
                str(bool(tl_active)).lower(),
                str(bool(orb1_active)).lower(),
            )
        if watch_task is None or watch_task.done():
            self._unified_discovery_watch_task = asyncio.create_task(_run_watches())
            log.info(
                "DISCOVERY_UNIFIED | stage=background_scheduled | lane=watch | "
                "tl_active=%s | orb1_active=%s | grep=MONITOR_CADENCE|DISCOVERY_UNIFIED",
                str(bool(tl_active)).lower(),
                str(bool(orb1_active)).lower(),
            )
        return started_scan

    async def _ensure_breakout_watch_activated(self) -> int:
        """Activate Breakout from frozen ORB #2; retry while inactive and before entry cutoff."""
        if not getattr(self, "_enable_breakout_strategy", False):
            return 0
        if getattr(self, "_breakout_watch_active", False) and (
            getattr(self, "_breakout_watch_candidates", None) or {}
        ):
            return len(getattr(self, "_breakout_watch_candidates", None) or {})

        if not self._tl_bo_discovery_session_open():
            log.debug(
                "BREAKOUT_PIPELINE | stage=activate | action=skip_retry | "
                "reason=tl_bo_discovery_not_open_until_0730_post_0dte"
            )
            return 0

        # No BO discovery before valid post-07:30 ORB2 (and normally post-0DTE release).
        try:
            from modules.breakout_watch import orb2_freeze_valid_for_tl_bo

            if not orb2_freeze_valid_for_tl_bo(self, require_session_ready=True):
                log.debug(
                    "BREAKOUT_PIPELINE | stage=activate | action=skip_retry | "
                    "reason=orb2_not_ready_post_0730"
                )
                return 0
        except Exception:
            # Helper crashed. After ORB2 unlock, BO must still arm — do not
            # couple Breakout to a broken validity check. Before unlock,
            # fail closed so a 06:30 incomplete freeze cannot start BO.
            if not getattr(self, "_orb_0dte_batch_complete_for_trendline", False):
                return 0

        # Respect Breakout no-new-entries cutoff for retries
        try:
            from zoneinfo import ZoneInfo
            from easyBreakout.breakout_config_loader import load_breakout_config_from_env
            from modules.config_loader import get_config_value

            cfg = getattr(self, "_breakout_config", None) or load_breakout_config_from_env(get_config_value)
            self._breakout_config = cfg
            cutoff = str(cfg.no_new_entries_after_pt or "12:30")
            hh, mm = [int(x) for x in cutoff.split(":")[:2]]
            now_pt = datetime.now(ZoneInfo("America/Los_Angeles")).time()
            if now_pt > __import__("datetime").time(hh, mm):
                log.info(
                    "BREAKOUT_PIPELINE | stage=activate | action=skip_retry | reason=past_entry_cutoff | cutoff=%s",
                    cutoff,
                )
                return 0
        except Exception:
            pass

        now_ts = time.time()
        last = float(getattr(self, "_breakout_activate_retry_ts", 0.0) or 0.0)
        if last and (now_ts - last) < 20.0 and not getattr(self, "_breakout_watch_active", False):
            return 0
        self._breakout_activate_retry_ts = now_ts

        try:
            from modules.breakout_watch import activate_breakout_watch_async

            n_bo = await activate_breakout_watch_async(self)
            log.info(
                "SCHEDULER_ORDER | stage=breakout_activate | watch_count=%d | "
                "orb_label=ORB#2 | box_source=orb2_630_730 | data=etrade_frozen",
                n_bo,
            )
            if n_bo > 0 and hasattr(self, "_save_breakout_watch_activation_snapshot"):
                self._save_breakout_watch_activation_snapshot()
            return int(n_bo or 0)
        except Exception as bo_act_err:
            log.warning(
                "BREAKOUT_PIPELINE | stage=activate | action=error | reason=%s",
                bo_act_err,
            )
            return 0

    def _trendline_orb_0dte_batch_complete(self) -> bool:
        return bool(getattr(self, "_orb_0dte_batch_complete_for_trendline", False))

    def _trendline_pt_today(self) -> str:
        try:
            from zoneinfo import ZoneInfo

            return datetime.now(ZoneInfo("America/Los_Angeles")).strftime("%Y-%m-%d")
        except Exception:
            return datetime.now(timezone.utc).strftime("%Y-%m-%d")

    def _trendline_past_primary_build_window(self) -> bool:
        """True after 08:00 PT — mid-session TL1 rebuild lacks reliable pre-7:30 structure bars."""
        try:
            from zoneinfo import ZoneInfo

            now_pt = datetime.now(ZoneInfo("America/Los_Angeles"))
            return (now_pt.hour, now_pt.minute) >= (8, 0)
        except Exception:
            return False

    def _trendline_orb2_ready_for_watch(self) -> bool:
        """Valid post-07:30 ORB2 freeze — enough to run TL2/TL3 inject on the watch cycle."""
        try:
            from modules.breakout_watch import orb2_freeze_valid_for_tl_bo

            # Session clock may already be past 07:30 when this is consulted; still
            # reject premature freezes so TL2/TL3 never arm on a 06:30 incomplete box.
            return bool(orb2_freeze_valid_for_tl_bo(self, require_session_ready=False))
        except Exception:
            return False

    def _trendline_keep_orb2_extension_watch_alive(self, no_trade_after: time_class) -> bool:
        """Keep watch running for TL2/TL3 even when all TL1 candidates are gone."""
        try:
            cfg = getattr(getattr(self, "trendline_signal_engine", None), "config", None)
            return (
                bool(getattr(cfg, "orb2_extension_envelope_enabled", True))
                and self._trendline_orb2_ready_for_watch()
                and self.orb_strategy_manager._get_current_time_pt() <= no_trade_after
            )
        except Exception:
            return False

    def _trendline_existing_engine_candidate_count(self) -> int:
        try:
            eng = getattr(self, "trendline_signal_engine", None)
            return len(getattr(eng, "candidates", None) or {})
        except Exception:
            return 0

    def _trendline_engine_has_tl0_candidates(self) -> bool:
        """True when engine already holds trendline0 geometry."""
        try:
            eng = getattr(self, "trendline_signal_engine", None)
            cands = getattr(eng, "candidates", None) or {}
            for key, cand in cands.items():
                key_s = str(key or "").lower()
                if ":trendline0" in key_s or key_s.endswith(":tl0"):
                    return True
                setup = getattr(cand, "setup_payload", None)
                if not isinstance(setup, dict):
                    setup = {}
                slot = str(setup.get("trendline_slot") or getattr(cand, "trendline_slot", "") or "").lower()
                if slot in ("trendline0", "tl0"):
                    return True
                tid = str(
                    getattr(cand, "trade_id", "")
                    or getattr(cand, "candidate_id", "")
                    or ""
                ).upper()
                if "_TL0_" in tid:
                    return True
            return False
        except Exception:
            return False

    def _trendline_engine_has_tl1_candidates(self) -> bool:
        """True when engine already holds trendline1 geometry (not TL0-only)."""
        try:
            eng = getattr(self, "trendline_signal_engine", None)
            cands = getattr(eng, "candidates", None) or {}
            for key, cand in cands.items():
                key_s = str(key or "").lower()
                if ":trendline1" in key_s or key_s.endswith(":tl1"):
                    return True
                setup = getattr(cand, "setup_payload", None)
                if not isinstance(setup, dict):
                    setup = {}
                slot = str(setup.get("trendline_slot") or getattr(cand, "trendline_slot", "") or "").lower()
                if slot in ("trendline1", "tl1"):
                    return True
                tid = str(
                    getattr(cand, "trade_id", "")
                    or getattr(cand, "candidate_id", "")
                    or ""
                ).upper()
                if "_TL1_" in tid:
                    return True
            return False
        except Exception:
            return False

    def _trendline_tl1_primary_completed_today(self) -> bool:
        """True after a real Yahoo TL1 build/empty or hydrate of freeze with trendline1."""
        return getattr(self, "_tl1_primary_completed_pt_date", None) == self._trendline_pt_today()

    def _trendline_primary_tl1_still_needed(self) -> bool:
        """
        Primary post-ORB2 TL1 build is still required.

        TL0 candidates must never satisfy this — schedule is TL0 (≤07:25) then
        Yahoo 1m + dual-envelope TL1 at ≥07:30 after ORB2 capture.

        Do not treat `_trendline_build_attempted_pt_date` alone as done: Aug 24
        TL0-only hydrate stamped that flag and skipped the dual-envelope draw.
        """
        if self._trendline_engine_has_tl1_candidates():
            return False
        if self._trendline_tl1_primary_completed_today():
            return False
        return True

    def _trendline_finalize_empty_tl1_build(self, *, reason: str) -> None:
        """
        Empty TL1 must not kill the Trendline path.

        Aug 3: mid-session deploy rebuilt TL1 on sparse bars → 0 qualified →
        watch_active=false, which also blocked TL2/TL3 ORB2 inject for the rest of the day.
        Preserve existing candidates when present; otherwise keep watch armed for TL2/TL3
        whenever ORB2 is ready.
        """
        existing = self._trendline_existing_engine_candidate_count()
        orb2_ready = self._trendline_orb2_ready_for_watch()
        if existing > 0:
            self._trendline_watch_active = True
            log.warning(
                "TRENDLINE_PIPELINE | stage=build | action=preserve_watch | reason=%s | "
                "existing_candidates=%d | note=empty_tl1_kept_prior_candidates",
                reason,
                existing,
            )
            return
        self._pending_trendline_candidates = []
        if orb2_ready:
            self._trendline_watch_active = True
            log.warning(
                "TRENDLINE_PIPELINE | stage=build | action=arm_watch_tl2_tl3 | reason=%s | "
                "note=empty_tl1_keep_orb2_extension_path",
                reason,
            )
            return
        self._trendline_watch_active = False
        log.info(
            "TRENDLINE_PIPELINE | stage=build | action=skip | reason=%s | watch_active=false",
            reason,
        )

    def _trendline_defer_build_enabled(self) -> bool:
        """LIVE always defers; Demo follows TRENDLINE_DEFER_BUILD_UNTIL_ORB_BATCH (default true)."""
        try:
            from .runtime_mode import is_live_mode
            from .config_loader import get_config_value

            if is_live_mode():
                return True
            return str(
                get_config_value("TRENDLINE_DEFER_BUILD_UNTIL_ORB_BATCH", "true")
            ).strip().lower() in ("1", "true", "yes")
        except Exception:
            return True

    def _trendline_build_attempted_today(self) -> bool:
        return getattr(self, "_trendline_build_attempted_pt_date", None) == self._trendline_pt_today()

    def _tl1_build_single_flight_active(self) -> bool:
        """True while another caller owns the TL1 build handoff.

        The post-ORB2 release task itself is not treated as external contention —
        that task is the owner. Recover / main-loop callers still see it as busy.

        A leftover `_tl1_status=running` after restart/error is stale — not in
        flight. `_run_deferred_trendline_build_if_pending` heals that claim.
        """
        if bool(getattr(self, "_tl1_build_in_flight", False)):
            return True
        task = getattr(self, "_tl1_post_orb2_task", None)
        try:
            if task is not None and not task.done():
                import asyncio

                try:
                    cur = asyncio.current_task()
                except Exception:
                    cur = None
                if cur is not None and cur is task:
                    return False
                return True
        except Exception:
            pass
        return False

    def _get_tl1_build_asyncio_lock(self):
        import asyncio

        lock = getattr(self, "_tl1_build_asyncio_lock", None)
        if lock is None:
            lock = asyncio.Lock()
            self._tl1_build_asyncio_lock = lock
        return lock

    def _persist_tl1_build_pending(self, *, armed: bool) -> None:
        """Write TL1 pending to daily markers. No-op when tracker is absent."""
        tracker = getattr(self, "daily_run_tracker", None)
        if tracker is None or not hasattr(tracker, "record_tl1_build_pending"):
            return
        try:
            tracker.record_tl1_build_pending(armed=armed)
        except Exception as persist_err:
            log.debug("TL1 pending persist skipped: %s", persist_err)

    def _restore_tl1_build_pending_from_markers(self) -> bool:
        """Re-arm in-memory TL1 pending after Cloud Run replacement."""
        if getattr(self, "_trendline_build_pending_at_730", None):
            return True
        if not self._trendline_primary_tl1_still_needed():
            return False
        tracker = getattr(self, "daily_run_tracker", None)
        if tracker is None or not hasattr(tracker, "get_tl1_build_pending"):
            return False
        try:
            if not tracker.get_tl1_build_pending():
                return False
        except Exception:
            return False
        self._trendline_build_pending_at_730 = {
            "pending_so_signals": list(getattr(self, "_pending_so_signals", None) or []),
            "pending_dte_signals": list(getattr(self, "_pending_dte_signals", None) or []),
            "restored_from_marker": True,
        }
        log.warning(
            "TRENDLINE_PIPELINE | stage=build | action=restore_tl1_pending_from_marker | "
            "reason=cloud_run_restart"
        )
        return True

    def _note_trendline_build_attempt_finished(self) -> None:
        """Record a finished (non-requeued) build attempt for this PT day."""
        pending = getattr(self, "_trendline_build_pending_at_730", None)
        if isinstance(pending, dict) and pending.get("requeued_reason"):
            return  # still requeued for open-quote budget
        if isinstance(pending, dict) and str(pending.get("_tl1_status") or "") == "running":
            return
        if pending:
            return
        today = self._trendline_pt_today()
        self._trendline_build_attempted_pt_date = today
        self._tl1_primary_completed_pt_date = today
        self._persist_tl1_build_pending(armed=False)

    def _arm_deferred_trendline_build_if_needed(
        self,
        *,
        pending_so_signals: Optional[List[Any]] = None,
        pending_dte_signals: Optional[List[Any]] = None,
    ) -> bool:
        """
        Arm Trendline defer pending once post-ORB1 cutoff; survives until ORB2 + TL1 claim.

        Idempotent when already armed today (pending present), watch-active with lines,
        build in flight, or a non-requeued attempt finished today.
        """
        if not getattr(self, "_enable_trendline_strategy", False):
            return False
        if not self._trendline_defer_build_enabled():
            return False
        # Stale `_trendline_build_attempted_pt_date` from TL0-only hydrate must not
        # block arm — only a real TL1 draw or freeze-with-TL1 (primary_completed /
        # engine has TL1) consumes the step.
        if not self._trendline_primary_tl1_still_needed():
            log.info(
                "SCHEDULER_ORDER | stage=trendline_build | action=arm_skip | "
                "reason=tl1_already_present_or_primary_completed | has_tl1=%s | completed=%s",
                str(self._trendline_engine_has_tl1_candidates()).lower(),
                str(self._trendline_tl1_primary_completed_today()).lower(),
            )
            return False
        if self._tl1_build_single_flight_active():
            return False
        if getattr(self, "_trendline_build_pending_at_730", None):
            return False
        today = self._trendline_pt_today()
        already_armed = getattr(self, "_trendline_tl1_armed_pt_date", None) == today
        # Cloud Run restart after 08:00: hydrate freeze if present, but still arm
        # TL1 when the primary Yahoo draw never completed.
        if self._trendline_past_primary_build_window():
            try:
                n_hyd = int(self._hydrate_trendline_geometry_from_daily_markers() or 0)
            except Exception:
                n_hyd = 0
            try:
                self._restore_tl1_build_pending_from_markers()
            except Exception:
                pass
            if not self._trendline_primary_tl1_still_needed():
                self._trendline_watch_active = True
                log.warning(
                    "SCHEDULER_ORDER | stage=trendline_build | action=hydrate_day_freeze | "
                    "hydrated=%d | engine=%d | reason=past_0800_pt",
                    n_hyd,
                    self._trendline_existing_engine_candidate_count(),
                )
                return False
            if n_hyd > 0 or self._trendline_existing_engine_candidate_count() > 0:
                self._trendline_watch_active = True
            log.warning(
                "SCHEDULER_ORDER | stage=trendline_build | action=arm_late_tl1_after_restart | "
                "reason=primary_never_completed | hydrated=%d",
                n_hyd,
            )
        # Exactly-once arm after ORB1 cutoff. Heal only when armed stamp exists but
        # pending was lost before a finished attempt (should be rare with single-flight).
        if already_armed:
            log.info(
                "SCHEDULER_ORDER | stage=trendline_build | action=arm_heal_pending | "
                "reason=armed_stamp_missing_pending | lock=orb_step5"
            )
        self._trendline_tl1_armed_pt_date = today
        self._trendline_build_pending_at_730 = {
            "pending_so_signals": list(pending_so_signals or []),
            "pending_dte_signals": list(pending_dte_signals or []),
        }
        self._persist_tl1_build_pending(armed=True)
        log.info(
            "SCHEDULER_ORDER | stage=trendline_build | action=deferred | "
            "reason=wait_orb_0dte_then_orb2 | lock=orb_step5"
        )
        return True

    async def _maybe_recover_deferred_trendline_build(self) -> None:
        """
        Retry ORB2 → TL1 when pending survived requeue/restart. Never build TL1 before ORB2.
        Unlocks watch after 7:40 PT or once 0DTE batch ran.
        """
        if not getattr(self, "_enable_trendline_strategy", False):
            return
        # Skip only when primary TL1 is actually done. A stale attempted stamp from
        # TL0-only hydrate must not suppress recovery of the dual-envelope draw.
        if self._trendline_orb_0dte_batch_complete() and not self._trendline_primary_tl1_still_needed():
            return
        # Release task owns the single TL1 build — do not dual-run from recover.
        if self._tl1_build_single_flight_active():
            return

        pt_t = None
        try:
            if hasattr(self, "orb_strategy_manager") and self.orb_strategy_manager:
                pt_t = self.orb_strategy_manager._get_current_time_pt()
        except Exception:
            pt_t = None
        if pt_t is None or pt_t < time_class(7, 30):
            return

        today = self._trendline_pt_today()
        past_window = pt_t >= time_class(7, 40)
        # Watch-mode ORB1 never stamps `_dte0_batch_executed_pt_date`; treat the
        # post-ORB1 TL/BO unlock flag as Step 5 complete so recovery can still
        # arm+run TL1 before 08:00 when release unlocked BO without a build.
        dte_done = getattr(self, "_dte0_batch_executed_pt_date", None) == today or bool(
            getattr(self, "_orb_0dte_batch_complete_for_trendline", False)
        )
        # Wait for ORB1 Breakout unless past Step 5 window (restart recovery).
        if not dte_done and not past_window:
            return
        if getattr(self, "_step5_0dte_pp_deferred", False) and not past_window:
            return

        # Mid-session Cloud Run restart: hydrate freeze if present, but never
        # stamp TL1 complete unless the engine/freeze actually has TL1.
        late_window = self._trendline_past_primary_build_window()
        skip_build = False
        if late_window:
            try:
                n_hyd = int(self._hydrate_trendline_geometry_from_daily_markers() or 0)
            except Exception:
                n_hyd = 0
            try:
                self._restore_tl1_build_pending_from_markers()
            except Exception:
                pass
            if not self._trendline_primary_tl1_still_needed():
                self._trendline_build_pending_at_730 = None
                self._persist_tl1_build_pending(armed=False)
                self._trendline_watch_active = True
                log.warning(
                    "TRENDLINE_PIPELINE | stage=build | action=hydrate_day_freeze | "
                    "hydrated=%d | reason=recover_past_0800_pt_tl1_already_present",
                    n_hyd,
                )
                skip_build = True
            else:
                if n_hyd > 0 or self._trendline_existing_engine_candidate_count() > 0:
                    self._trendline_watch_active = True
                log.warning(
                    "TRENDLINE_PIPELINE | stage=build | action=late_tl1_after_restart | "
                    "reason=primary_never_completed | hydrated=%d | pending=%s",
                    n_hyd,
                    str(bool(getattr(self, "_trendline_build_pending_at_730", None))).lower(),
                )

        if not skip_build:
            needs_build = self._trendline_primary_tl1_still_needed() or bool(
                getattr(self, "_trendline_build_pending_at_730", None)
            )

            now_ts = time.time()
            last_ts = float(getattr(self, "_trendline_build_retry_ts", 0.0) or 0.0)
            if needs_build and (now_ts - last_ts) >= 20.0:
                if self._tl1_build_single_flight_active():
                    return
                self._trendline_build_retry_ts = now_ts
                # Arm must succeed with TL0 watch already active; do not clear watch.
                self._arm_deferred_trendline_build_if_needed(
                    pending_so_signals=list(getattr(self, "_pending_so_signals", None) or []),
                    pending_dte_signals=list(getattr(self, "_pending_dte_signals", None) or []),
                )
                complete, _orb2_n = await self._ensure_orb2_captured_for_tl_bo()
                if not complete:
                    self._log_throttled_warning(
                        "orb2_capture_incomplete_before_tl1_recover",
                        (
                            "TRENDLINE_PIPELINE | stage=build | action=recover_hold | "
                            f"reason=orb2_capture_incomplete_before_tl1 | orb2_symbols={_orb2_n}"
                        ),
                        interval_sec=30.0,
                    )
                    return
                # Prefer the release-owned task when present; otherwise run once here.
                task = getattr(self, "_tl1_post_orb2_task", None)
                if task is not None and not task.done():
                    return
                await self._run_deferred_trendline_build_if_pending()
                # Watch-mode race: Step 5 may already have unlocked BO before TL1.
                # Flush the deferred first watch tick here — the unlock branch below
                # is skipped when `_orb_0dte_batch_complete_for_trendline` is already set.
                if self._trendline_orb_0dte_batch_complete():
                    try:
                        await self._run_trendline_post_build_watch_if_pending()
                    except Exception as post_err:
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=watch | "
                            "action=recover_post_build_after_late_tl1_error | reason=%s",
                            post_err,
                        )

        if (past_window or dte_done) and not self._trendline_orb_0dte_batch_complete():
            # Only unlock after a valid ≥07:30 ORB2 freeze (never a premature stamp).
            orb2_ready = False
            try:
                from modules.breakout_watch import orb2_freeze_valid_for_tl_bo

                orb2_ready = bool(
                    orb2_freeze_valid_for_tl_bo(self, require_session_ready=True)
                )
            except Exception:
                orb2_ready = False
            if not orb2_ready:
                return
            await self._mark_orb_0dte_batch_complete_for_trendline()
            try:
                await self._run_trendline_post_build_watch_if_pending()
            except Exception as post_err:
                log.warning(
                    "TRENDLINE_PIPELINE | stage=watch | action=recover_post_build_error | reason=%s",
                    post_err,
                )

    async def _run_deferred_trendline_build_if_pending(self) -> None:
        """Run deferred TL1 once after a valid ≥07:30 ORB2 freeze (single-flight)."""
        if getattr(self, "_tl1_build_in_flight", False):
            log.info(
                "SCHEDULER_ORDER | stage=trendline_build | action=skip | "
                "reason=tl1_build_in_flight"
            )
            return
        pending = getattr(self, "_trendline_build_pending_at_730", None)
        if not pending:
            return
        if isinstance(pending, dict) and str(pending.get("_tl1_status") or "") == "running":
            if getattr(self, "_tl1_build_in_flight", False):
                log.info(
                    "SCHEDULER_ORDER | stage=trendline_build | action=skip | "
                    "reason=tl1_build_already_running"
                )
                return
            pending.pop("_tl1_status", None)
            log.warning(
                "SCHEDULER_ORDER | stage=trendline_build | action=clear_stale_running_claim | "
                "reason=in_flight_false_after_restart_or_error"
            )

        mgr = getattr(self, "orb_strategy_manager", None)
        orb2_n = 0
        complete = False
        try:
            from modules.breakout_watch import orb2_freeze_valid_for_tl_bo

            orb2_n = len(getattr(mgr, "orb2_data", None) or {}) or len(
                getattr(self, "_orb2_data", None) or {}
            )
            complete = bool(orb2_freeze_valid_for_tl_bo(self, require_session_ready=True))
        except Exception:
            complete = False
            orb2_n = 0
        if not complete:
            # Keep pending armed until ORB2 completes — never clear early.
            log.warning(
                "SCHEDULER_ORDER | stage=trendline_build | action=wait | "
                "reason=orb2_not_complete_or_premature | orb2_symbols=%d",
                orb2_n,
            )
            return

        lock = self._get_tl1_build_asyncio_lock()
        if lock.locked():
            log.info(
                "SCHEDULER_ORDER | stage=trendline_build | action=skip | "
                "reason=tl1_build_lock_held"
            )
            return

        async with lock:
            if getattr(self, "_tl1_build_in_flight", False):
                return
            pending = getattr(self, "_trendline_build_pending_at_730", None)
            if not pending:
                return
            if isinstance(pending, dict) and str(pending.get("_tl1_status") or "") == "running":
                if getattr(self, "_tl1_build_in_flight", False):
                    return
                pending.pop("_tl1_status", None)

            claimed = dict(pending) if isinstance(pending, dict) else {"pending_so_signals": [], "pending_dte_signals": []}
            claimed.pop("_tl1_status", None)
            # Claim without dropping the arm: running sentinel blocks dual arm/build.
            self._tl1_build_in_flight = True
            self._trendline_build_pending_at_730 = {**claimed, "_tl1_status": "running"}
            log.info(
                "SCHEDULER_ORDER | stage=trendline_build | action=run_deferred | "
                "lock=post_orb2_complete | orb2_symbols=%d | single_flight=true",
                orb2_n,
            )
            try:
                try:
                    from modules.unified_0dte_account import refresh_unified_account_from_broker

                    await refresh_unified_account_from_broker(self)
                    self._refresh_trendline_slot_capital()
                except Exception as unified_refresh_err:
                    log.warning(
                        "UNIFIED_0DTE_ACCOUNT | stage=post_orb_refresh | error=%s",
                        unified_refresh_err,
                    )
                await self._build_trendline_candidates_at_730(
                    pending_so_signals=list(claimed.get("pending_so_signals") or []),
                    pending_dte_signals=list(claimed.get("pending_dte_signals") or []),
                )
                cur = getattr(self, "_trendline_build_pending_at_730", None)
                # Clear only our running claim; preserve open-quote requeue payload.
                if isinstance(cur, dict) and str(cur.get("_tl1_status") or "") == "running":
                    self._trendline_build_pending_at_730 = None
                self._note_trendline_build_attempt_finished()
            except Exception as build_err:
                log.warning(
                    "SCHEDULER_ORDER | stage=trendline_build | action=deferred_build_error | "
                    "reason=%s",
                    build_err,
                )
                cur = getattr(self, "_trendline_build_pending_at_730", None)
                if isinstance(cur, dict) and str(cur.get("_tl1_status") or "") == "running":
                    cur.pop("_tl1_status", None)
                    self._trendline_build_pending_at_730 = cur
            finally:
                self._tl1_build_in_flight = False

    async def _run_trendline_post_build_watch_if_pending(self) -> None:
        """First watch/execution tick after TL1 completes (BO may already be scanning)."""
        if not getattr(self, "_trendline_post_build_watch_pending", False):
            return
        if getattr(self, "_trendline_discovery_hold_for_tl1", False):
            return
        self._trendline_post_build_watch_pending = False
        if not getattr(self, "_trendline_watch_active", False):
            return
        log.info(
            "TRENDLINE_PIPELINE | stage=watch | action=post_orb_batch_tick | "
            "reason=first_watch_after_tl1_unlock",
        )
        try:
            from modules.unified_0dte_account import refresh_unified_account_from_broker

            await refresh_unified_account_from_broker(self)
            self._refresh_trendline_slot_capital()
        except Exception as unified_refresh_err:
            log.warning(
                "UNIFIED_0DTE_ACCOUNT | stage=pre_trendline_watch | error=%s",
                unified_refresh_err,
            )
        try:
            await self._run_trendline_watch_cycle()
        except Exception as post_build_watch_err:
            log.warning(
                "TRENDLINE_PIPELINE | stage=watch | action=post_orb_batch_tick_error | reason=%s",
                post_build_watch_err,
            )

    @staticmethod
    def _trendline_watch_state_priority(candidate: Any) -> int:
        st = str(getattr(candidate, "state", "") or "").upper()
        name = str(getattr(getattr(candidate, "state", None), "name", "") or "").upper()
        blob = f"{st} {name}"
        if "READY_TO_EXECUTE" in blob:
            return 0
        if "WAITING_FOR_CONFIRMATION" in blob:
            return 1
        if "WAITING_FOR_BREAK" in blob:
            return 2
        return 3

    def _trendline_select_watch_batch(
        self,
        watch_candidates: List[Any],
        *,
        per_tick_override: Optional[int] = None,
        advance_rotation: bool = True,
    ) -> List[Any]:
        """
        Fair-rotate the 0dte_list window (24 / 10s). Status does not pin slots.

        Default 24/tick @ 10s → every name at least once in ≤50s (118 → 50s).
        Path eval uses this scan's forced quote window only — CONFIRM/READY
        wait for their rotate slot like every other symbol.
        """
        from modules.discovery_watch_batch import (
            merged_discovery_window_symbols,
            select_tier_rotated_batch,
            take_forced_discovery_symbols,
        )

        per_tick = int(
            per_tick_override
            if per_tick_override is not None
            else getattr(self, "_trendline_watch_symbols_per_tick", 24) or 24
        )
        # Honor this tick's unified quote window. If the 45s forced attr aged
        # out during hydrate, reuse the merged quote-batch symbols so a name
        # just quoted is still evaluated (do not wait a full 90-name rotate).
        forced = take_forced_discovery_symbols(self)
        if not forced:
            forced = merged_discovery_window_symbols(self)
        offset = int(getattr(self, "_trendline_watch_slice_offset", 0) or 0)
        batch, new_offset, meta = select_tier_rotated_batch(
            watch_candidates,
            per_tick=per_tick,
            offset=offset,
            forced_symbols=forced,
        )
        if advance_rotation and meta.get("mode") in ("tier_rotate", "path_fallback_rotate"):
            self._trendline_watch_slice_offset = int(new_offset)
        if advance_rotation and len(watch_candidates) > len(batch):
            log.info(
                "TRENDLINE_PIPELINE | stage=watch_batch | total=%d | this_tick=%d | "
                "mode=%s | offset=%d | next_offset=%d | ready=%s | rotation=tier_list",
                len(watch_candidates),
                len(batch),
                meta.get("mode"),
                int(meta.get("offset", offset) or offset),
                int(meta.get("new_offset", new_offset) or new_offset),
                meta.get("ready", 0),
            )
        return batch

    async def _prefetch_merged_tl_bo_discovery_quotes(
        self,
        *,
        tl_due: bool = False,
        bo_due: bool = False,
    ) -> None:
        """Deprecated shim — unified scan owns the single equity batch."""
        del tl_due, bo_due
        from modules.discovery_watch_batch import run_unified_0dte_discovery_scan

        await run_unified_0dte_discovery_scan(self)

    def _request_immediate_0dte_monitor(self, *, reason: str = "fill") -> None:
        """Flag the next maybe_tick and wake the dedicated loop. Never start a second full tick.

        A second ``maybe_tick`` (fill_enroll) used to evaluate the entire open book
        while holding the monitor lock (30–106s), starving exits and failing enrollment.
        """
        self._0dte_force_monitor_tick = True
        self._trendline_immediate_monitor_requested = True
        try:
            from modules.unified_0dte_position_monitor import (
                get_unified_0dte_position_monitor,
            )

            get_unified_0dte_position_monitor(self).request_wake(reason=reason)
        except Exception:
            pass
        log.info(
            "UNIFIED_0DTE_MONITOR | action=force_tick | reason=%s | fill_enroll=flag_only",
            reason,
        )

    async def _maybe_run_fill_enroll_monitor(self, *, reason: str = "fill") -> None:
        """Legacy hook: flag the next main-loop tick only. Never run a full-book maybe_tick."""
        self._0dte_force_monitor_tick = True
        self._trendline_immediate_monitor_requested = True
        log.info(
            "UNIFIED_0DTE_MONITOR | action=fill_enroll_flag_only | reason=%s",
            reason,
        )

    def _trim_runtime_caches_for_memory(self) -> None:
        """Bound PO paths + unified quote maps when RSS is over MEMORY_PRESSURE_GB."""
        dropped_po = 0
        try:
            po = self._get_profit_optimizer()
            rec = getattr(po, "recorder", None) if po is not None else None
            if rec is not None and hasattr(rec, "trim_in_memory_paths"):
                dropped_po = int(rec.trim_in_memory_paths() or 0)
        except Exception:
            dropped_po = 0
        chain_n = 0
        try:
            chain = getattr(self, "_unified_0dte_chain_quotes_by_trade", None)
            if isinstance(chain, dict) and len(chain) > 32:
                chain_n = len(chain)
                self._unified_0dte_chain_quotes_by_trade = {}
        except Exception:
            chain_n = 0
        if dropped_po or chain_n:
            log.warning(
                "MEMORY_PRESSURE | action=trim_runtime | po_paths_trimmed=%d | chain_maps_cleared=%d",
                dropped_po,
                chain_n,
            )

    def _trendline_request_immediate_monitor(self, *, reason: str = "fill") -> None:
        self._request_immediate_0dte_monitor(reason=f"trendline|{reason}")

    async def _trendline_inject_orb2_extensions(self, pre_quotes: Optional[Dict[str, Any]]) -> None:
        """Arm TL2/TL3 from the ORB2 freeze. Caller decides when this may run."""
        if getattr(self, "_trendline_watch_tl0_only", False):
            return
        if not self._trendline_orb2_ready_for_watch():
            return
        try:
            from easyTrendline.trendline_orb2_extension import (
                maybe_inject_orb2_extension_trendlines,
                pending_orb2_inject_symbols,
            )

            pending_inj = pending_orb2_inject_symbols(self)
            if pending_inj:
                try:
                    await self._trendline_hydrate_watch_bar_cache(
                        pending_inj,
                        pre_quotes or None,
                        force_yf_symbols=pending_inj,
                    )
                    self._trendline_watch_last_bar_hydrate_ts = time.time()
                except Exception as force_hyd_err:
                    log.debug(
                        "TRENDLINE_PIPELINE | stage=watch_hydrate_force_inject | "
                        "action=skip | reason=%s",
                        force_hyd_err,
                    )
            n_inj = maybe_inject_orb2_extension_trendlines(self)
            if n_inj:
                log.info(
                    "TRENDLINE_PIPELINE | stage=watch | action=orb2_extension_inject | count=%d",
                    n_inj,
                )
            elif pending_inj:
                pending_s = ",".join(pending_inj[:12])
                extra = f" | extra={len(pending_inj) - 12}" if len(pending_inj) > 12 else ""
                self._log_throttled_warning(
                    "orb2_extension_inject_zero",
                    (
                        "TRENDLINE_PIPELINE | stage=watch | action=orb2_extension_inject | "
                        f"count=0 | pending={len(pending_inj)} | symbols={pending_s}{extra}"
                    ),
                    interval_sec=60.0,
                )
        except Exception as orb2_ext_err:
            log.warning(
                "TRENDLINE_PIPELINE | stage=watch | action=orb2_extension_inject_error | reason=%s",
                orb2_ext_err,
            )

    async def _trendline_run_deferred_bar_hydrate(self) -> None:
        """Bar hydrate and TL2 inject after the break check and the order."""
        job = getattr(self, "_tl_bar_hydrate_after_entries", None)
        self._tl_bar_hydrate_after_entries = None
        if not isinstance(job, dict):
            return
        syms = [str(s).strip().upper() for s in (job.get("symbols") or []) if str(s).strip()]
        pre_quotes = job.get("pre_quotes") if isinstance(job.get("pre_quotes"), dict) else None
        if job.get("hydrate_due") and syms:
            log.info(
                "TRENDLINE_PIPELINE | stage=watch_hydrate | action=after_compare | "
                "symbols=%d | grep=TRENDLINE_WATCH_HYDRATE",
                len(syms),
            )
            try:
                await self._trendline_hydrate_watch_bar_cache(syms, pre_quotes)
                self._trendline_pre_inject_hydrated_today = True
                self._trendline_watch_last_bar_hydrate_ts = time.time()
            except Exception as hydrate_ex:
                log.debug(
                    "TRENDLINE_PIPELINE | stage=watch_hydrate_deferred | action=skip | reason=%s",
                    hydrate_ex,
                )
        await self._trendline_inject_orb2_extensions(pre_quotes)

    async def _run_trendline_watch_cycle(self) -> None:
        """Monitor trendline candidates; TL0 only during morning window (≤07:25)."""
        tl0_only = False
        tl0_session = self._tl0_discovery_session_open()
        # Always kill TL0 geometry once past 07:25 — even on early-return paths.
        if not tl0_session:
            try:
                self._expire_tl0_geometry_after_cutoff()
            except Exception as tl0_exp_err:
                log.debug(
                    "TRENDLINE_PIPELINE | stage=expired | action=tl0_cutoff_skip | error=%s",
                    tl0_exp_err,
                )
        if not self._trendline_orb_0dte_batch_complete():
            if tl0_session:
                tl0_only = True
            else:
                self._log_throttled_warning(
                    "trendline_watch_blocked_orb_batch",
                    (
                        "TRENDLINE_PIPELINE | stage=watch | action=blocked | "
                        "reason=await_orb_0dte_step5_and_durability_or_tl0_cutoff | lock=orb_step5"
                    ),
                    interval_sec=30.0,
                )
                return
        if getattr(self, "_trendline_discovery_hold_for_tl1", False):
            # TL0 discovery ended at 07:25 — do not keep scanning TL0 during TL1 build.
            self._log_throttled_warning(
                "trendline_watch_held_until_tl1",
                (
                    "TRENDLINE_PIPELINE | stage=watch | action=held | "
                    "reason=await_tl1_geometry_complete | note=bo_discovery_may_run"
                ),
                interval_sec=15.0,
            )
            return
        self._trendline_watch_tl0_only = tl0_only
        if not self._enable_trendline_strategy or not self._trendline_watch_active:
            return
        if not getattr(self, "trendline_signal_engine", None) or not getattr(self, "trendline_options_executor", None):
            return
        if not hasattr(self, "orb_strategy_manager") or not self.orb_strategy_manager:
            return

        # Prefer day-freeze A1/A2/slope when engine candidates empty (restart mid-session).
        try:
            eng = self.trendline_signal_engine
            if not (getattr(eng, "candidates", None) or {}):
                n_hyd = int(self._hydrate_trendline_geometry_from_daily_markers() or 0)
                if n_hyd > 0:
                    log.info(
                        "TRENDLINE_PIPELINE | stage=watch | action=hydrate_from_markers | hydrated=%d",
                        n_hyd,
                    )
        except Exception as tl_hyd_err:
            log.debug(
                "TRENDLINE_PIPELINE | stage=watch | hydrate_skip=%s",
                tl_hyd_err,
            )

        # Rolling slot sizing should be based on Trendline equity basis, not remaining cash.
        self._refresh_trendline_slot_capital()

        # TL0 window (≤07:25): TL0-only. After 07:25 and before 07:30: never TL0;
        # wait for TL1+ (or 07:30) — do NOT force tl0_only (that re-opened TL0 trades).
        now_pt_watch = self.orb_strategy_manager._get_current_time_pt()
        if now_pt_watch < time_class(7, 30):
            if tl0_session:
                if not getattr(self, "_trendline_watch_tl0_only", False) and not getattr(
                    self, "_trendline0_ready", False
                ):
                    return
                self._trendline_watch_tl0_only = True
            else:
                self._trendline_watch_tl0_only = False
                if not self._trendline_engine_has_tl1_candidates():
                    self._log_throttled_warning(
                        "trendline_watch_gap_0710_0730",
                        (
                            "TRENDLINE_PIPELINE | stage=watch | action=held | "
                            "reason=tl0_expired_await_tl1_or_0730 | note=no_tl0_after_0710"
                        ),
                        interval_sec=15.0,
                    )
                    return
        else:
            # ≥07:30 — full TL1+ path; TL0 already expired above.
            self._trendline_watch_tl0_only = False

        # Bar hydrate feeds TL2/TL3 inject. When this scan's quotes are already
        # cached, that work is deferred until after the break check and the order.
        hydrate_syms: List[str] = []
        pre_quotes: Dict[str, Any] = {}
        try:
            from easyTrendline.trendline_orb2_extension import _orb2_levels

            hydrate_syms = sorted({str(s).upper() for s in (_orb2_levels(self) or {}).keys()})
        except Exception:
            hydrate_syms = []
        if not hydrate_syms:
            try:
                hydrate_syms = sorted(
                    {
                        str(getattr(c, "symbol", "") or "").strip().upper()
                        for c in (self.trendline_signal_engine.candidates or {}).values()
                        if str(getattr(c, "symbol", "") or "").strip()
                    }
                )
            except Exception:
                hydrate_syms = []

        if hydrate_syms:
            try:
                from modules.open_position_quote_orchestration import (
                    take_discovery_quotes_from_merged_cache,
                )

                cached = take_discovery_quotes_from_merged_cache(self, hydrate_syms)
                if cached is not None:
                    pre_quotes = cached
            except Exception:
                pass
            hydrate_sec = float(getattr(self, "_trendline_watch_bar_hydrate_sec", 60.0) or 60.0)
            now_hydrate = time.time()
            force_pre_inject = not bool(getattr(self, "_trendline_pre_inject_hydrated_today", False))
            hydrate_due = force_pre_inject or (
                hydrate_sec > 0
                and (now_hydrate - float(getattr(self, "_trendline_watch_last_bar_hydrate_ts", 0.0) or 0.0))
                >= hydrate_sec
            )
            # Compare this scan's quotes to armed lines first. Yahoo and the
            # next-line inject run after the order, whether or not the quote
            # cache is still inside 30s. A thin cache used to Yahoo the window
            # and then stamp the break (CAKE, 2026-10-30 10:55 PT).
            self._tl_bar_hydrate_after_entries = {
                "symbols": list(hydrate_syms),
                "pre_quotes": pre_quotes or None,
                "hydrate_due": bool(hydrate_due),
            }
        cutoff_hhmm = "12:30"
        try:
            cutoff_hhmm = str(self.trendline_signal_engine.config.no_new_entries_after_pt)
        except Exception:
            cutoff_hhmm = "12:30"
        try:
            _h, _m = cutoff_hhmm.split(":")
            no_trade_after = time_class(int(_h), int(_m))
        except Exception:
            no_trade_after = time_class(11, 30)
        if self.orb_strategy_manager._get_current_time_pt() > no_trade_after:
            self._trendline_watch_active = False
            log.warning(
                "TRENDLINE_PIPELINE | stage=expired | reason=no_trade_zone_after_cutoff | cutoff_pt=%s",
                cutoff_hhmm,
            )
            _tl_tick = str(getattr(self, "_unified_0dte_monitor_tick_id", "") or "").strip()
            _tick_in_flight = False
            try:
                from modules.unified_0dte_position_monitor import get_unified_0dte_position_monitor

                _tick_in_flight = bool(
                    getattr(get_unified_0dte_position_monitor(self), "_running", False)
                )
            except Exception:
                _tick_in_flight = False
            if _tick_in_flight and _tl_tick:
                await self._monitor_trendline_positions(tick_id=_tl_tick)
            return

        watch_candidates = []
        for candidate in self.trendline_signal_engine.candidates.values():
            state_name = str(getattr(candidate, "state", ""))
            from easyTrendline.trendline_models import trendline_slot_from_payload

            _slot = trendline_slot_from_payload(getattr(candidate, "setup_payload", None))
            if getattr(self, "_trendline_watch_tl0_only", False):
                if _slot != "trendline0":
                    continue
            elif _slot == "trendline0":
                # TL0 discovery ends at 07:25 — never evaluate TL0 after morning window.
                continue
            if "WAITING_FOR_BREAK" in state_name or "WAITING_FOR_CONFIRMATION" in state_name or "READY_TO_EXECUTE" in state_name:
                watch_candidates.append(candidate)
        if not watch_candidates:
            all_c = list(self.trendline_signal_engine.candidates.values())
            if all_c:
                idle_sec = float(getattr(self, "_trendline_watch_idle_log_sec", 0.0) or 0.0)
                now_idle = time.time()
                if idle_sec > 0 and (now_idle - float(getattr(self, "_trendline_last_idle_log_ts", 0.0))) >= idle_sec:
                    from collections import Counter

                    by_state = Counter(str(c.state) for c in all_c)
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=watch_idle | reason=no_watchable_candidates | total=%d | by_state=%s | "
                        "hint=all_invalidated_expired_or_executed_no_longer_scanning_for_breaks",
                        len(all_c),
                        dict(by_state),
                    )
                    self._trendline_last_idle_log_ts = now_idle
            return

        # Same task as the scan. This window's quotes go to the break check
        # and then Trade Profile. Open-quote latency does not return here.
        from modules.discovery_watch_batch import discovery_batch_size

        watch_candidates = self._trendline_select_watch_batch(
            watch_candidates,
            per_tick_override=discovery_batch_size(),
        )

        now_ts_watch = time.time()
        log_sec = float(getattr(self, "_trendline_watch_status_log_sec", 0.0) or 0.0)
        if log_sec > 0 and (
            now_ts_watch - float(getattr(self, "_trendline_last_watch_status_log_ts", 0.0))
        ) >= log_sec:
            n_break = sum(
                1 for c in watch_candidates if "WAITING_FOR_BREAK" in str(getattr(c, "state", ""))
            )
            n_confirm = sum(
                1
                for c in watch_candidates
                if "WAITING_FOR_CONFIRMATION" in str(getattr(c, "state", ""))
            )
            def _watch_prio(c: Any) -> tuple:
                lbl = str((getattr(c, "setup_payload", None) or {}).get("structure_display_label") or "")
                st = str((getattr(c, "setup_payload", None) or {}).get("setup_type") or "")
                if "below_orb" in lbl:
                    return (0, st, str(getattr(c, "symbol", "")))
                if st == "descending_resistance":
                    return (1, st, str(getattr(c, "symbol", "")))
                return (2, st, str(getattr(c, "symbol", "")))

            ranked = sorted(watch_candidates, key=_watch_prio)
            sym_preview = ",".join(c.symbol for c in ranked[:16])
            log.warning(
                "TRENDLINE_PIPELINE | stage=watch_status | waiting_break=%d | waiting_confirm=%d | "
                "watching=%d | executed_today=%d | open_positions=%d | max_open=%d | interval_sec=%.0f | symbols=%s",
                n_break,
                n_confirm,
                len(watch_candidates),
                len(self._trendline_executed_today_symbols()),
                self._trendline_option_positions_count(),
                int(self._trendline_open_cap()),
                log_sec,
                sym_preview,
            )
            self._trendline_last_watch_status_log_ts = now_ts_watch

        symbols = [c.symbol for c in watch_candidates]
        needs_fresh_quotes = any(
            "READY_TO_EXECUTE" in str(getattr(c, "state", "") or "") for c in watch_candidates
        )
        quotes: Dict[str, Any] = {}
        try:
            from modules.open_position_quote_orchestration import (
                take_discovery_quotes_from_merged_cache,
            )

            cached = take_discovery_quotes_from_merged_cache(self, symbols)
            if cached is not None:
                quotes = cached
                log.info(
                    "TRENDLINE_PIPELINE | stage=watch | action=use_merged_discovery_quotes | symbols=%d",
                    len(symbols),
                )
        except Exception:
            pass
        if not quotes:
            quotes = await self.data_manager.get_batch_quotes(
                symbols,
                skip_cache=bool(needs_fresh_quotes),
            )
            try:
                from modules.broker_api_pacing import (
                    LANE_TRENDLINE_WATCH_EQUITY,
                    record_broker_lane_request,
                )

                record_broker_lane_request(LANE_TRENDLINE_WATCH_EQUITY)
            except Exception:
                pass
        if quotes:
            self._ingest_broker_quotes_into_session_tech(quotes)
        if not quotes:
            eq_sec = float(getattr(self, "_trendline_watch_empty_quotes_log_sec", 60.0) or 60.0)
            now_eq = time.time()
            if now_eq - float(getattr(self, "_trendline_last_empty_quotes_log_ts", 0.0)) >= eq_sec:
                log.warning(
                    "TRENDLINE_PIPELINE | stage=watch_skip | reason=empty_batch_quotes | symbols_requested=%d | "
                    "hint=data_manager_returned_empty_watch_cannot_evaluate_breaks",
                    len(symbols),
                )
                self._trendline_last_empty_quotes_log_ts = now_eq
            return

        hydrate_sec = float(getattr(self, "_trendline_watch_bar_hydrate_sec", 60.0) or 60.0)
        now_hydrate = time.time()
        if hydrate_sec > 0 and (
            now_hydrate - float(getattr(self, "_trendline_watch_last_bar_hydrate_ts", 0.0) or 0.0)
        ) >= hydrate_sec:
            # Same defer as the pre-watch job. The price loop below uses the
            # bars already cached. Yahoo of a thin name does not sit in front
            # of a line that is already armed.
            job = getattr(self, "_tl_bar_hydrate_after_entries", None)
            if not isinstance(job, dict):
                job = {"symbols": [], "pre_quotes": None, "hydrate_due": False}
            merged_syms: List[str] = []
            seen_syms = set()
            for raw_sym in list(job.get("symbols") or []) + list(symbols or []):
                sym_u = str(raw_sym or "").strip().upper()
                if not sym_u or sym_u in seen_syms:
                    continue
                seen_syms.add(sym_u)
                merged_syms.append(sym_u)
            pre = job.get("pre_quotes") if isinstance(job.get("pre_quotes"), dict) else {}
            if isinstance(quotes, dict):
                pre = dict(pre)
                pre.update(quotes)
            self._tl_bar_hydrate_after_entries = {
                "symbols": merged_syms,
                "pre_quotes": pre or None,
                "hydrate_due": True,
            }

        from easyTrendline import OHLCVBar
        from easyTrendline.trendline_models import TrendlineDirection
        from modules.unified_0dte_account import total_0dte_max_positions

        now = datetime.now(timezone.utc)
        from modules.runtime_mode import mode_label as runtime_mode_label

        mode_label = runtime_mode_label()
        tl_cfg = getattr(self.trendline_signal_engine, "config", None)
        nearline_parts: List[str] = []

        def _nearline_prio(c: Any) -> tuple:
            st_pri = self._trendline_watch_state_priority(c)
            lbl = str((getattr(c, "setup_payload", None) or {}).get("structure_display_label") or "")
            orb_pri = 0 if "below_orb" in lbl else 1
            # Newest active slot first (TL3→TL2→TL1). Prior slots are expired on
            # ORB2 extension inject so discovery should only see the current line.
            try:
                from easyTrendline.trendline_models import (
                    trendline_slot_from_payload,
                    trendline_slot_watch_priority,
                )

                slot_pri = trendline_slot_watch_priority(
                    trendline_slot_from_payload(getattr(c, "setup_payload", None) or {})
                )
            except Exception:
                slot_pri = 9
            return (st_pri, orb_pri, slot_pri, str(getattr(c, "symbol", "")))

        yield_every = int(getattr(self, "_trendline_watch_yield_every_n", 12) or 12)
        for loop_idx, candidate in enumerate(sorted(watch_candidates, key=_nearline_prio)):
            if yield_every > 0 and loop_idx > 0 and loop_idx % yield_every == 0:
                await asyncio.sleep(0)
            cand_side = self._trendline_candidate_option_side(candidate)
            if cand_side and self._trendline_has_open_same_side(candidate.symbol, cand_side):
                log.warning(
                    "TRENDLINE_PIPELINE | stage=dedupe_guard | action=skip | "
                    "reason=open_same_side_symbol_strategy | symbol=%s | option_side=%s",
                    candidate.symbol,
                    cand_side,
                )
                continue
            quote = quotes.get(candidate.symbol, {}) if isinstance(quotes, dict) else {}
            px = quote.get("last", 0.0) or quote.get("close", 0.0) or quote.get("price", 0.0)
            try:
                price = float(px)
            except (TypeError, ValueError):
                now_qd = time.time()
                last_qd = float(self._trendline_watch_quote_diag_last.get(candidate.symbol, 0.0) or 0.0)
                if now_qd - last_qd >= 120.0:
                    self._trendline_watch_quote_diag_last[candidate.symbol] = now_qd
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=watch_quote_skip | symbol=%s | reason=quote_not_numeric | raw=%r",
                        candidate.symbol,
                        px,
                    )
                continue
            if price <= 0:
                now_qd = time.time()
                last_qd = float(self._trendline_watch_quote_diag_last.get(candidate.symbol, 0.0) or 0.0)
                if now_qd - last_qd >= 120.0:
                    self._trendline_watch_quote_diag_last[candidate.symbol] = now_qd
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=watch_quote_skip | symbol=%s | reason=zero_or_negative_price | raw=%r",
                        candidate.symbol,
                        px,
                    )
                continue

            self._trendline_last_price_by_symbol[candidate.symbol] = price
            signal = None
            try:
                session_vol = self._trendline_quote_session_volume(
                    quote if isinstance(quote, dict) else {}
                )
                bar = self.trendline_signal_engine.upsert_watch_quote_bar(
                    candidate.symbol,
                    price,
                    now,
                    session_volume=session_vol,
                )
                # Write-through to central session-tech store (do not read TL cache for BO/PO).
                try:
                    from modules.session_tech_indicators import upsert_session_tech_minute_bar

                    upsert_session_tech_minute_bar(
                        self,
                        candidate.symbol,
                        price,
                        ts=now,
                        session_volume=session_vol,
                    )
                except Exception:
                    pass

                st_name = str(getattr(candidate, "state", ""))
                if (
                    "WAITING_FOR_BREAK" in st_name
                    and getattr(candidate, "trendline", None) is not None
                    and tl_cfg is not None
                ):
                    try:
                        tl = candidate.trendline
                        line_px = tl.value_at(bar.ts)
                        thresh = max(float(tl_cfg.min_break_pct) * line_px, 0.0)
                        if getattr(tl_cfg, "use_atr_break", True) and bar.atr and bar.atr > 0:
                            thresh = max(
                                thresh,
                                float(bar.atr) * float(getattr(tl_cfg, "atr_break_multiplier", 0.25)),
                            )
                        geom = candidate.direction
                        if geom == TrendlineDirection.BULL:
                            broke = price < (line_px - thresh)
                            margin = price - (line_px - thresh)
                        else:
                            broke = price > (line_px + thresh)
                            margin = (line_px + thresh) - price
                        nearline_parts.append(
                            f"{candidate.symbol}|c={price:.4f}|L={line_px:.4f}|{geom.value}|brk={'Y' if broke else 'N'}|m={margin:+.5f}"
                        )
                    except Exception:
                        pass

                try:
                    signal = self.trendline_signal_engine.process_new_bar(
                        candidate.symbol,
                        bar,
                        candidate_id=str(getattr(candidate, "candidate_id", "") or "") or None,
                    )
                except RuntimeError as dedupe_error:
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=dedupe_guard | action=skip | symbol=%s | reason=%s",
                        candidate.symbol,
                        dedupe_error,
                    )
                    continue
                # Exec-ready TTL expire after capital/slot wait: reject only this TL signal.
                try:
                    from easyTrendline.trendline_simple_mode import (
                        SimpleTrendlineState,
                        _simple_payload,
                        get_simple_state,
                    )
                    from modules.path_exec_ready_ttl import EXEC_READY_TTL_REASON

                    if (
                        get_simple_state(candidate) == SimpleTrendlineState.EXPIRED
                        and str(
                            (_simple_payload(candidate) or {}).get("state_reason")
                            or getattr(candidate, "state_reason", "")
                            or ""
                        )
                        == EXEC_READY_TTL_REASON
                    ):
                        self._trendline_reject_current_exec_signal(
                            candidate, EXEC_READY_TTL_REASON
                        )
                        continue
                except Exception:
                    pass
            except Exception as trendline_watch_symbol_error:
                log.error(
                    "TRENDLINE_PIPELINE | stage=watch | action=error | symbol=%s | reason=%s",
                    candidate.symbol,
                    trendline_watch_symbol_error,
                )
                continue
            if not signal:
                continue

            self._trendline_confirmed_count += 1

            async def _tl_exec_fail(
                stage: str,
                reason: str,
                *,
                rearm: bool = False,
                extra: Optional[Dict[str, Any]] = None,
                send_alert: Optional[bool] = None,
            ) -> None:
                # Post-emit only: quality skips return before signal and never call this helper.
                if send_alert is None:
                    send_alert = _trendline_failed_row_may_send_execution_alert(
                        {
                            "execution_attempted": stage in _TRENDLINE_EXECUTION_REJECT_ALERT_STAGES,
                            "failure_stage": stage,
                        }
                    )
                fail_row = self._trendline_build_exec_failure_row(
                    signal,
                    candidate,
                    stage=stage,
                    reason=reason,
                )
                if isinstance(extra, dict) and extra:
                    fail_row.update(extra)
                if send_alert and _trendline_failed_row_may_send_execution_alert(fail_row):
                    await self._send_trendline_emit_execution_alert(
                        mode_label=mode_label,
                        failed_row=fail_row,
                    )
                else:
                    log.info(
                        "TRENDLINE_PIPELINE | stage=execution_alert_suppressed | symbol=%s | "
                        "cap_stage=%s | reason=%s | rearm=%s",
                        signal.symbol,
                        stage,
                        str(reason or "")[:240],
                        str(bool(rearm)).lower(),
                    )
                if rearm:
                    # Slot/cash defer must not outlive exec-ready TTL.
                    try:
                        from easyTrendline.trendline_simple_mode import _simple_payload
                        from modules.path_exec_ready_ttl import (
                            EXEC_READY_TTL_REASON,
                            is_exec_ready_expired,
                        )

                        if is_exec_ready_expired(
                            _simple_payload(candidate), path="trendline"
                        ):
                            self._trendline_reject_current_exec_signal(
                                candidate, EXEC_READY_TTL_REASON
                            )
                            return
                    except Exception:
                        pass
                    self._trendline_rearm_deferred(
                        signal.symbol,
                        f"{stage}:{reason}",
                        candidate_id=str(
                            getattr(candidate, "candidate_id", "")
                            or (getattr(signal, "metadata", None) or {}).get("candidate_id")
                            or ""
                        ),
                    )

            _unified_risk_on = self._unified_0dte_risk_enabled()
            if (
                getattr(self, "_red_day_filter_blocked", False)
                and get_config_value("TRENDLINE_RED_DAY_GATE_ENABLED", True)
            ):
                from .portfolio_protection import load_0dte_tier1_symbols, passes_red_day_0dte_style_gate

                tier1_symbols = getattr(self, "_cached_0dte_tier1_symbols", None)
                if tier1_symbols is None:
                    tier1_symbols = load_0dte_tier1_symbols()
                    self._cached_0dte_tier1_symbols = tier1_symbols
                option_side_gate = str(getattr(signal, "option_side", "") or "").strip().lower()
                allowed, gate_reason = passes_red_day_0dte_style_gate(
                    symbol=signal.symbol,
                    option_side_or_type=option_side_gate,
                    tier1_symbols=tier1_symbols,
                    red_day_active=True,
                    allow_tier1_call=bool(get_config_value("TRENDLINE_RED_DAY_ALLOW_TIER1_CALL", True)),
                    allow_put=bool(get_config_value("TRENDLINE_RED_DAY_ALLOW_PUT", True)),
                )
                if not allowed:
                    log.warning(
                        "TRENDLINE_RED_DAY_GATE | action=drop | symbol=%s | option_side=%s | "
                        "reason=%s | tier1_loaded=%d",
                        signal.symbol,
                        option_side_gate,
                        gate_reason,
                        len(tier1_symbols),
                    )
                    await _tl_exec_fail(
                        "red_day_tier2_call_blocked",
                        f"{gate_reason} tier1_only_on_red_day",
                        rearm=True,
                    )
                    continue

            if bool(
                getattr(self, "_0dte_entry_kill_switch_active", False)
                or getattr(self, "_orb_0dte_entry_kill_switch_active", False)
            ):
                log.info(
                    "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=entry_kill_switch | reason=0dte_degraded_quote_health",
                    signal.symbol,
                )
                await _tl_exec_fail(
                    "entry_kill_switch_active",
                    "0DTE entry kill switch active due to persistent degraded quote ratio",
                    rearm=True,
                )
                continue

            if self._option_entry_cooldown_remaining_sec() > 0:
                rem_cd = float(self._option_entry_cooldown_remaining_sec())
                now_c = time.time()
                last_c = float(self._trendline_cooldown_block_log_ts.get(signal.symbol, 0.0) or 0.0)
                if now_c - last_c >= 45.0:
                    self._trendline_cooldown_block_log_ts[signal.symbol] = now_c
                    log.info(
                        "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=option_entry_cooldown | remaining_sec=%.0f | reason=global_option_cooldown",
                        signal.symbol,
                        rem_cd,
                    )
                self._maybe_log_option_entry_cooldown_blocking(blocked_for_symbol=signal.symbol)
                await _tl_exec_fail(
                    "option_entry_cooldown",
                    f"global_option_cooldown remaining_sec={rem_cd:.0f}",
                    rearm=True,
                )
                continue
            sig_side = str(getattr(signal, "option_side", "") or "").strip().lower()
            # 1h reject cooldown is TL-slot + symbol + side (TL1 reject ≠ block TL2).
            try:
                from easyTrendline.trendline_models import (
                    trendline_slot_from_payload,
                    trendline_slot_short_label,
                )
                from modules.path_exec_day_exclude import (
                    is_trendline_slot_side_on_cooldown,
                )

                _meta = getattr(signal, "metadata", None) or {}
                _cd_slot = str(_meta.get("trendline_slot") or "").strip() or trendline_slot_from_payload(
                    getattr(candidate, "setup_payload", None) or {}
                )
                if sig_side and is_trendline_slot_side_on_cooldown(
                    self, signal.symbol, sig_side, slot=_cd_slot
                ):
                    now_c = time.time()
                    cd_key = f"{signal.symbol}:{_cd_slot}:{sig_side}"
                    last_c = float(
                        self._trendline_cooldown_block_log_ts.get(cd_key, 0.0) or 0.0
                    )
                    if now_c - last_c >= 45.0:
                        self._trendline_cooldown_block_log_ts[cd_key] = now_c
                        log.info(
                            "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=slot_side_cooldown | "
                            "trendline_slot=%s | slot_label=%s | side=%s | "
                            "reason=reject_cooldown_1h_same_slot_side | action=skip_quiet",
                            signal.symbol,
                            _cd_slot,
                            trendline_slot_short_label(_cd_slot),
                            sig_side,
                        )
                    continue
            except Exception as _cd_err:
                log.debug(
                    "TRENDLINE_PIPELINE | stage=slot_side_cooldown_check | symbol=%s | error=%s",
                    signal.symbol,
                    _cd_err,
                )
            if sig_side and self._trendline_has_open_same_side(signal.symbol, sig_side):
                log.warning(
                    "TRENDLINE_PIPELINE | stage=dedupe_guard | action=skip | "
                    "reason=open_same_side_symbol_strategy | symbol=%s | option_side=%s | stage_detail=pre_execute",
                    signal.symbol,
                    sig_side,
                )
                await _tl_exec_fail(
                    "open_same_side_dedupe",
                    f"open_same_side_symbol_strategy:{sig_side}",
                    rearm=True,
                )
                continue
            active_open = self._trendline_option_positions_count()
            max_total_option_positions = total_0dte_max_positions(get_config_value)
            if (
                not _unified_risk_on
                and self._total_option_positions_count() >= max_total_option_positions
            ):
                log.warning("OPTION_GLOBAL_CAP_REACHED")
                self._arm_option_entry_cooldown_global_cap()
                self._log_trendline_feature_events([candidate], stage="execution_skipped_cap")
                await _tl_exec_fail(
                    "option_global_cap",
                    f"TOTAL_0DTE_MAX_POSITIONS={max_total_option_positions}",
                    rearm=True,
                )
                continue
            if (
                not _unified_risk_on
                and active_open
                >= int(self._trendline_open_cap())
            ):
                self._trendline_daily_cap_skips += 1
                log.warning(
                    "TRENDLINE_PIPELINE | stage=open_cap_reached | max_open=%d | open=%d",
                    int(self._trendline_open_cap()),
                    active_open,
                )
                log.warning(
                    "TRENDLINE_PIPELINE | stage=execution_skipped_cap | symbol=%s | open_positions=%d",
                    signal.symbol,
                    active_open,
                )
                self._log_trendline_feature_events([candidate], stage="execution_skipped_cap")
                await _tl_exec_fail(
                    "open_cap_reached",
                    f"open_positions={active_open} max_open={int(self._trendline_open_cap())}",
                    rearm=True,
                )
                continue

            self._refresh_trendline_slot_capital()
            slot_capital = float(getattr(self, "_trendline_slot_capital", 0.0) or 0.0)
            entry_budget = float(getattr(self, "_trendline_entry_budget", 0.0) or 0.0)
            available_cash = float(getattr(self, "_trendline_available_cash", 0.0) or 0.0)
            buffer_reserve = float(getattr(self, "_trendline_buffer_reserve", 0.0) or 0.0)
            if entry_budget <= 0.0 or available_cash <= 0.0:
                self._trendline_sizing_skips += 1
                log.warning(
                    "TRENDLINE_PIPELINE | stage=buffer_reserve_exhausted | symbol=%s | buffer_reserve=%.2f | "
                    "slot_capital=%.2f | available_cash=%.2f | entry_budget=%.2f | open_positions=%d",
                    signal.symbol,
                    buffer_reserve,
                    slot_capital,
                    available_cash,
                    entry_budget,
                    active_open,
                )
                self._log_trendline_feature_events([candidate], stage="execution_skipped_cap")
                await _tl_exec_fail(
                    "buffer_reserve_exhausted",
                    f"available_cash={available_cash:.2f} buffer_reserve={buffer_reserve:.2f}",
                    rearm=True,
                )
                continue

            # GCS slot claim and cash hold run after the Trade Profile admits.
            _tl_slot_res = None
            slot_marker_path = None

            slot_index = active_open
            option_side_norm = str(getattr(signal, "option_side", "") or "").strip().lower()
            breakout_direction = "up" if option_side_norm == "call" else "down" if option_side_norm == "put" else "unknown"
            # Line geometry is NOT "momentum": bull = support (valid break is down → puts), bear = resistance (break up → calls).
            line_geom = getattr(signal, "direction", None)
            if isinstance(line_geom, str):
                _lg = line_geom.strip().lower()
                try:
                    line_geom = TrendlineDirection(_lg)
                except ValueError:
                    line_geom = None
            sig_meta_geom = signal.metadata if isinstance(getattr(signal, "metadata", None), dict) else {}
            if line_geom is None and sig_meta_geom:
                _lgm = str(sig_meta_geom.get("line_geometry") or "").strip().lower()
                if _lgm in ("bull", "bear"):
                    try:
                        line_geom = TrendlineDirection(_lgm)
                    except ValueError:
                        line_geom = None
            expected_breakout_direction = None
            line_geom_label = ""
            if line_geom == TrendlineDirection.BULL:
                expected_breakout_direction = "down"
                line_geom_label = "bull"
            elif line_geom == TrendlineDirection.BEAR:
                expected_breakout_direction = "up"
                line_geom_label = "bear"
            geometry_option_aligned = False
            if option_side_norm in ("call", "put"):
                if line_geom == TrendlineDirection.BULL and option_side_norm == "put":
                    geometry_option_aligned = True
                elif line_geom == TrendlineDirection.BEAR and option_side_norm == "call":
                    geometry_option_aligned = True
                elif not geometry_option_aligned and sig_meta_geom:
                    _lg2 = str(sig_meta_geom.get("line_geometry") or "").strip().lower()
                    if _lg2 == "bull" and option_side_norm == "put":
                        geometry_option_aligned = True
                    elif _lg2 == "bear" and option_side_norm == "call":
                        geometry_option_aligned = True
            be_obj = getattr(signal, "break_event", None) or getattr(candidate, "break_event", None)
            be_meta = (
                (getattr(be_obj, "metadata", {}) if be_obj is not None else {})
                if isinstance(getattr(be_obj, "metadata", {}), dict)
                else {}
            )

            break_distance = float(
                (
                    (getattr(be_obj, "break_distance", None) if be_obj is not None else None)
                    or be_meta.get("break_distance")
                    or 0.0
                )
                or 0.0
            )
            break_distance_pct_eff = float(
                (getattr(be_obj, "break_distance_pct", None) if be_obj is not None else None)
                or be_meta.get("break_distance_pct")
                or 0.0
            ) or 0.0
            if break_distance_pct_eff <= 0.0 and be_obj is not None:
                _tl_px = float(getattr(be_obj, "trendline_price", 0.0) or 0.0)
                if _tl_px > 0.0:
                    break_distance_pct_eff = abs(float(break_distance)) / _tl_px
            body_ratio = float(
                (
                    be_meta.get("body_ratio")
                    or (
                        (signal.metadata or {}).get("body_ratio")
                        if isinstance(getattr(signal, "metadata", None), dict)
                        else None
                    )
                    or 0.0
                )
                or 0.0
            )
            close_break_confirmed = bool(
                (
                    getattr(be_obj, "close_break_confirmed", None)
                    if be_obj is not None
                    else None
                )
                or be_meta.get("close_break_confirmed")
                or be_meta.get("valid_close_break")
                or False
            )
            break_ts = (
                getattr(be_obj, "candle_ts", None)
                or getattr(be_obj, "timestamp", None)
                or getattr(be_obj, "break_ts", None)
            ) if be_obj is not None else None
            now_ts = datetime.now(timezone.utc)
            seconds_since_break = 999999.0
            has_break_ts = False
            if isinstance(break_ts, datetime):
                if break_ts.tzinfo is None:
                    break_ts = break_ts.replace(tzinfo=timezone.utc)
                seconds_since_break = max(0.0, (now_ts - break_ts).total_seconds())
                has_break_ts = True
            peak_after_break = float(
                (
                    be_meta.get("peak_after_break")
                    or be_meta.get("peak_price_after_break")
                    or 0.0
                )
                or 0.0
            )
            has_peak_after_break = peak_after_break > 0.0
            current_price = float(
                (
                    getattr(be_obj, "close_price", None)
                    if be_obj is not None
                    else None
                )
                or be_meta.get("current_price")
                or be_meta.get("close_price")
                or 0.0
            )
            retrace_pct = (
                max(0.0, (peak_after_break - current_price) / max(peak_after_break, 1e-9))
                if peak_after_break > 0.0 and current_price > 0.0
                else 0.0
            )
            legacy_geometry_mismatch = (
                expected_breakout_direction is not None
                and breakout_direction in ("up", "down")
                and breakout_direction != expected_breakout_direction
            )
            direction_conflict = (not geometry_option_aligned) and bool(legacy_geometry_mismatch)
            if geometry_option_aligned and legacy_geometry_mismatch:
                log.warning(
                    "TRENDLINE_DIRECTION_ADVISORY | symbol=%s | trade_id=%s | decision=geometry_option_aligned_skip_legacy_mismatch | "
                    "breakout_direction=%s | line_geometry=%s | expected_breakout=%s | option_side=%s",
                    signal.symbol,
                    getattr(signal, "trade_id", f"{signal.symbol}_unknown"),
                    breakout_direction,
                    line_geom_label or str(getattr(line_geom, "value", line_geom) or "unknown"),
                    expected_breakout_direction or "unknown",
                    option_side_norm or "unknown",
                )
            if direction_conflict:
                allow_override = False
                sig_meta = signal.metadata if isinstance(getattr(signal, "metadata", None), dict) else {}
                execution_reason = str(sig_meta.get("execution_reason") or "").strip().lower()
                fresh_valid_confirmation = (
                    execution_reason == "executed_valid_confirmation"
                    and float(seconds_since_break) <= 20.0
                )
                catastrophic_reversal = bool(has_peak_after_break and float(retrace_pct) >= 0.01)
                if fresh_valid_confirmation and not catastrophic_reversal:
                    allow_override = True
                    log.warning(
                        "TRENDLINE_DIRECTION_ADVISORY | symbol=%s | breakout_direction=%s | line_geometry=%s | "
                        "expected_breakout=%s | option_side=%s | execution_reason=%s | seconds_since_break=%.1f | "
                        "retrace_pct=%.6f | decision=allow_fresh_valid_confirmation",
                        signal.symbol,
                        breakout_direction,
                        line_geom_label or "unknown",
                        expected_breakout_direction or "unknown",
                        option_side_norm or "unknown",
                        execution_reason or "unknown",
                        float(seconds_since_break),
                        float(retrace_pct),
                    )
                try:
                    bdm = float(get_config_value("TRENDLINE_BREAK_DISTANCE_MIN", 0.0015) or 0.0015)
                except (TypeError, ValueError):
                    bdm = 0.0015
                try:
                    br_strong = float(get_config_value("TRENDLINE_BODY_RATIO_MIN_STRONG", 0.5) or 0.5)
                except (TypeError, ValueError):
                    br_strong = 0.5
                strong_dist_floor = max(0.008, bdm)
                strong_body_floor = max(0.6, br_strong)
                strong_break = break_distance_pct_eff >= strong_dist_floor and body_ratio >= strong_body_floor
                if strong_break and not allow_override:
                    missing_fields: List[str] = []
                    if not has_break_ts:
                        missing_fields.append("break_ts")
                    if not has_peak_after_break:
                        missing_fields.append("peak_after_break")
                    if missing_fields:
                        log.warning(
                            "TRENDLINE_OVERRIDE_REJECTED_INSUFFICIENT_DATA | symbol=%s | missing_fields=%s",
                            signal.symbol,
                            "[" + ", ".join(missing_fields) + "]",
                        )
                    else:
                        allow_override = bool(
                            close_break_confirmed
                            and (seconds_since_break >= 20.0)
                            and (retrace_pct < 0.003)
                        )
                if allow_override:
                    log.info(
                        "TRENDLINE_DIRECTION_OVERRIDE_STRONG_BREAK | symbol=%s | breakout_direction=%s | line_geometry=%s | "
                        "expected_breakout=%s | option_side=%s | break_distance_pct=%.6f | body_ratio=%.3f | close_break_confirmed=%s | "
                        "seconds_since_break=%.1f | retrace_pct=%.6f | decision=allowed",
                        signal.symbol,
                        breakout_direction,
                        line_geom_label or "unknown",
                        expected_breakout_direction or "unknown",
                        option_side_norm or "unknown",
                        break_distance_pct_eff,
                        body_ratio,
                        bool(close_break_confirmed),
                        float(seconds_since_break),
                        float(retrace_pct),
                    )
                    log.warning(
                        "TRENDLINE_DECISION_SNAPSHOT | symbol=%s | entry_path=trendline | breakout_direction=%s | "
                        "line_geometry=%s | expected_breakout=%s | option_side=%s | break_distance_pct=%.6f | body_ratio=%.3f | "
                        "close_break_confirmed=%s | seconds_since_break=%.1f | retrace_pct=%.6f | decision=allowed",
                        signal.symbol,
                        breakout_direction,
                        line_geom_label or "unknown",
                        expected_breakout_direction or "unknown",
                        option_side_norm or "unknown",
                        break_distance_pct_eff,
                        body_ratio,
                        bool(close_break_confirmed),
                        float(seconds_since_break),
                        float(retrace_pct),
                    )
                else:
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=pre_execute_check | symbol=%s | trade_id=%s | passed=false | reason=option_side_geometry_mismatch",
                        signal.symbol,
                        getattr(signal, "trade_id", f"{signal.symbol}_unknown"),
                    )
                    log.warning(
                        "TRENDLINE_OPTION_SIDE_GEOMETRY_MISMATCH | symbol=%s | line_geometry=%s | option_side=%s | "
                        "breakout_from_option=%s | expected_breakout=%s | orchestrator_veto=true",
                        signal.symbol,
                        line_geom_label or "unknown",
                        option_side_norm or "unknown",
                        breakout_direction,
                        expected_breakout_direction or "unknown",
                    )
                    log.info(
                        "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=orchestrator_geometry | reason=option_side_geometry_mismatch",
                        signal.symbol,
                    )
                    log.warning(
                        "TRENDLINE_ENTRY_BLOCKED_DIRECTION_CONFLICT | symbol=%s | breakout_direction=%s | line_geometry=%s | "
                        "expected_breakout=%s | option_side=%s | break_distance=%.6f | break_distance_pct=%.6f | body_ratio=%.3f | "
                        "close_break_confirmed=%s | seconds_since_break=%.1f | retrace_pct=%.6f | decision=blocked",
                        signal.symbol,
                        breakout_direction,
                        line_geom_label or "unknown",
                        expected_breakout_direction or "unknown",
                        option_side_norm or "unknown",
                        break_distance,
                        break_distance_pct_eff,
                        body_ratio,
                        bool(close_break_confirmed),
                        float(seconds_since_break),
                        float(retrace_pct),
                    )
                    log.warning(
                        "TRENDLINE_DECISION_SNAPSHOT | symbol=%s | entry_path=trendline | breakout_direction=%s | "
                        "line_geometry=%s | expected_breakout=%s | option_side=%s | break_distance_pct=%.6f | body_ratio=%.3f | "
                        "close_break_confirmed=%s | seconds_since_break=%.1f | retrace_pct=%.6f | decision=blocked",
                        signal.symbol,
                        breakout_direction,
                        line_geom_label or "unknown",
                        expected_breakout_direction or "unknown",
                        option_side_norm or "unknown",
                        break_distance_pct_eff,
                        body_ratio,
                        bool(close_break_confirmed),
                        float(seconds_since_break),
                        float(retrace_pct),
                    )
                    log.warning(
                        "TRENDLINE_HARD_VETO_AUDIT | symbol=%s | stage=pre_execute_check | veto_reason=option_side_geometry_mismatch | "
                        "catastrophic=%s | stale=false | severe_chop=false | invalid_structure=false | liquidity_block=false | executor_called=false",
                        signal.symbol,
                        str(bool(catastrophic_reversal)).lower(),
                    )
                    if slot_marker_path:
                        self._trendline_release_global_daily_slot(slot_marker_path)
                    await _tl_exec_fail("orchestrator_geometry", "option_side_geometry_mismatch")
                    continue
            else:
                log.warning(
                    "TRENDLINE_DECISION_SNAPSHOT | symbol=%s | entry_path=trendline | breakout_direction=%s | "
                    "line_geometry=%s | expected_breakout=%s | option_side=%s | break_distance_pct=%.6f | body_ratio=%.3f | "
                    "close_break_confirmed=%s | seconds_since_break=%.1f | retrace_pct=%.6f | decision=normal_no_conflict",
                    signal.symbol,
                    breakout_direction,
                    line_geom_label or "unknown",
                    expected_breakout_direction or "unknown",
                    option_side_norm or "unknown",
                    break_distance_pct_eff,
                    body_ratio,
                    bool(close_break_confirmed),
                    float(seconds_since_break),
                    float(retrace_pct),
                )
            log.warning(
                "TRENDLINE_EXECUTION_HANDOFF | symbol=%s | line_geometry=%s | option_side=%s | expected_breakout=%s | "
                "stage=orchestrator_trendline_to_intent",
                signal.symbol,
                line_geom_label or "unknown",
                option_side_norm or "unknown",
                expected_breakout_direction or "unknown",
            )
            intent = (signal.metadata or {}).get("execution_intent") if isinstance(signal.metadata, dict) else None
            if not intent:
                log.info(
                    "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=orchestrator | reason=missing_execution_intent",
                    signal.symbol,
                )
                log.warning("TRENDLINE_PIPELINE | missing_execution_intent | symbol=%s", signal.symbol)
                await _tl_exec_fail("orchestrator", "missing_execution_intent")
                continue
            if not hasattr(intent, "symbol"):
                log.info(
                    "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=orchestrator | reason=invalid_execution_intent",
                    getattr(signal, "symbol", "UNKNOWN"),
                )
                log.warning("Invalid ExecutionIntent object")
                await _tl_exec_fail("orchestrator", "invalid_execution_intent")
                continue

            if _unified_risk_on:
                log.warning(
                    "TRENDLINE_PIPELINE | stage=risk_check | symbol=%s | approved=deferred | "
                    "risk_path=unified_0dte_portfolio_risk_manager | safe_mode_active=false",
                    intent.symbol,
                )
            else:
                # Legacy Prime risk_manager path is quarantined for Live 0DTE:
                # only Demo risk managers with evaluate_intent may run it.
                risk_manager = getattr(self, "risk_manager", None)
                if risk_manager and hasattr(risk_manager, "evaluate_intent"):
                    from modules.trendline_legacy_risk_gate import (
                        evaluate_trendline_legacy_risk,
                        trendline_risk_rejection_hint,
                    )

                    try:
                        approved, risk_path, safe_mode = await evaluate_trendline_legacy_risk(
                            risk_manager, intent
                        )
                    except Exception as risk_err:
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=risk_check_error | symbol=%s | error=%s",
                            intent.symbol,
                            risk_err,
                        )
                        approved = False
                        risk_path = "evaluate_intent"
                        safe_mode = False
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=risk_check | symbol=%s | approved=%s | risk_path=%s | safe_mode_active=%s",
                        intent.symbol,
                        str(bool(approved)).lower(),
                        risk_path,
                        str(safe_mode).lower(),
                    )
                    if not approved:
                        risk_hint = trendline_risk_rejection_hint(risk_path, safe_mode)
                        log.info(
                            "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=risk_manager | reason=risk_rejected | risk_hint=%s",
                            intent.symbol,
                            risk_hint,
                        )
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=risk_rejected | symbol=%s | risk_hint=%s",
                            intent.symbol,
                            risk_hint,
                        )
                        if slot_marker_path:
                            self._trendline_release_global_daily_slot(slot_marker_path)
                        await _tl_exec_fail("risk_manager", risk_hint)
                        continue
                else:
                    log.info(
                        "TRENDLINE_PIPELINE | stage=risk_check | symbol=%s | approved=true | "
                        "risk_path=legacy_risk_gate_quarantined | safe_mode_active=false",
                        intent.symbol,
                    )

            log.warning(
                "TRENDLINE_EXECUTION_HANDOFF | symbol=%s | stage=pre_executor | risk_approved=true",
                intent.symbol,
            )
            _tl_meta_cap = (signal.metadata or {}) if isinstance(signal.metadata, dict) else {}
            _tl_emit_tid = str(_tl_meta_cap.get("trade_id") or _tl_meta_cap.get("candidate_id") or "")
            _orb_open = 0
            try:
                if hasattr(self, "dte0_manager") and self.dte0_manager and hasattr(
                    self.dte0_manager, "options_executor"
                ):
                    ex = self.dte0_manager.options_executor
                    _orb_open = len(getattr(ex, "active_positions", {}) or {})
            except Exception:
                _orb_open = 0
            _tl_deployed = float(getattr(self, "_trendline_capital_deployed_today", 0.0) or 0.0)
            _acct_avail = float(available_cash or 0.0)
            from modules.trendline_pc_oi_gate import confirm_trendline_dir_pct_before_execution

            _pc_ok, _pc_reason, _pc_skew = await confirm_trendline_dir_pct_before_execution(self, signal)
            if not _pc_ok:
                _pc_reason_s = str(_pc_reason or "")
                if _pc_reason_s == "max_open_positions_reached":
                    # Oct 13 2026: book full. Same capacity retry as open_cap_reached
                    # (rearm, exec-ready TTL still applies); never a dir% cooldown.
                    _cap_info = (_pc_skew or {}).get("max_open_positions") if isinstance(_pc_skew, dict) else None
                    _cap_info = _cap_info if isinstance(_cap_info, dict) else {}
                    log.info(
                        "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=max_open_positions_reached | "
                        "cap_kind=%s | open_n=%s | cap=%s | action=rearm_capacity_retry | cooldown=none",
                        signal.symbol,
                        _cap_info.get("cap_kind"),
                        _cap_info.get("open_n"),
                        _cap_info.get("cap"),
                    )
                    if slot_marker_path:
                        self._trendline_release_global_daily_slot(slot_marker_path)
                    await _tl_exec_fail(
                        "max_open_positions_reached",
                        f"open_n={_cap_info.get('open_n')} cap={_cap_info.get('cap')} "
                        f"cap_kind={_cap_info.get('cap_kind')}",
                        rearm=True,
                    )
                    continue
                if _pc_reason_s == "dir_pct_data_unavailable":
                    # Oct 13 2026: bounded dir% data wait ran out -> retire this break
                    # (next break re-arms), no slot/side cooldown.
                    log.info(
                        "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=dir_pct_data_unavailable | "
                        "action=retire_break | cooldown=none",
                        signal.symbol,
                    )
                    if slot_marker_path:
                        self._trendline_release_global_daily_slot(slot_marker_path)
                    self._trendline_reject_current_exec_signal(
                        candidate, "dir_pct_data_unavailable", arm_slot_side_cooldown=False
                    )
                    continue
                if _pc_reason_s in ("required_data_not_ready",):
                    # Oct 13 2026: a data wait (incl. the bounded dir% chain wait)
                    # never arms the slot/side cooldown; the break stays pending.
                    log.info(
                        "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=%s | "
                        "action=rearm_same_break | cooldown=none",
                        signal.symbol,
                        _pc_reason_s,
                    )
                    if slot_marker_path:
                        self._trendline_release_global_daily_slot(slot_marker_path)
                    self._trendline_rearm_deferred(
                        signal.symbol,
                        "required_data_not_ready",
                        candidate_id=str(getattr(candidate, "candidate_id", "") or ""),
                    )
                    continue
                # Confirm runs the Trade Profile only. Dir% and open interest
                # are profile keys, not separate filters.
                _lc_stage = "trade_profile"
                _lc_reject = f"{_lc_stage}_reject"
                if _pc_reason_s.startswith(("dir_vol_", "dir_pct")):
                    # Oct 13 2026: label a real dir% < floor reject as dir%
                    # (same terminal class and cooldown as before).
                    _lc_stage = "dir_pct_filter"
                    _lc_reject = "dir_pct_filter_reject"
                log.info(
                    "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=%s | reason=%s | detail=%s",
                    signal.symbol,
                    _lc_stage,
                    _lc_reject,
                    _pc_reason,
                )
                log.warning(
                    "TRENDLINE_PIPELINE | stage=%s | symbol=%s | option_side=%s | detail=%s",
                    _lc_reject,
                    signal.symbol,
                    str(getattr(signal, "option_side", "") or ""),
                    _pc_reason,
                )
                if slot_marker_path:
                    self._trendline_release_global_daily_slot(slot_marker_path)
                try:
                    if not str(getattr(candidate, "option_side", "") or "").strip():
                        candidate.option_side = str(
                            getattr(signal, "option_side", "") or ""
                        ).strip().lower()
                except Exception:
                    pass
                self._trendline_reject_current_exec_signal(
                    candidate, f"{_lc_reject}:{_pc_reason}"
                )
                await _tl_exec_fail(
                    _lc_stage,
                    f"{_lc_reject}: {_pc_reason}",
                    extra={"pc_oi_skew": _pc_skew, "reject_reason": _lc_reject},
                )
                continue
            from modules.tl_slot_admit import claim_slot_and_reserve

            _tl_slot_res, _tl_slot_rej = claim_slot_and_reserve(self, signal.symbol, active_open)
            if _tl_slot_res is None:
                self._log_trendline_feature_events([candidate], stage="execution_skipped_cap")
                if _tl_slot_rej == "global_daily_cap":
                    self._trendline_daily_cap_skips += 1
                    await _tl_exec_fail("global_daily_cap", "global_slot_unavailable", rearm=True)
                else:
                    self._trendline_sizing_skips += 1
                    await _tl_exec_fail(
                        "buffer_reserve_exhausted",
                        "post_tp_cash_check: available_cash minus in-flight <= 0",
                        rearm=True,
                    )
                continue
            slot_marker_path = _tl_slot_res.marker_path
            slot_capital = _tl_slot_res.slot_capital
            entry_budget = _tl_slot_res.entry_budget
            available_cash = _tl_slot_res.available_cash
            buffer_reserve = _tl_slot_res.buffer_reserve
            self._save_trendline_execution_priority_snapshot(
                signal=signal,
                candidate=candidate,
                stage="trendline_emit_handoff",
                order_payload={},
                broker_success=None,
            )
            try:
                from easyTrendline.trendline_simple_mode import _simple_payload as _stamp_sp
                from modules.path_exec_ready_ttl import stamp_exec_ready_at

                stamp_exec_ready_at(_stamp_sp(candidate), now=now)
            except Exception:
                pass
            try:
                result = await self.trendline_options_executor.execute(
                    signal,
                    slot_index=slot_index,
                    slot_capital=slot_capital,
                    entry_budget=entry_budget,
                    buffer_reserve=buffer_reserve,
                    available_cash=available_cash,
                    trendline_daily_trade_number=(active_open + 1),
                )
            except BaseException:
                from modules.tl_slot_admit import release as _tl_slot_release

                _tl_slot_release(self, _tl_slot_res, "executor_exception")
                raise
            from modules.tl_slot_admit import release as _tl_slot_release, settle_fill

            if getattr(result, "success", False):
                settle_fill(self, _tl_slot_res)
            else:
                _tl_slot_release(self, _tl_slot_res, "executor_failed")
                slot_marker_path = None
            _p = getattr(result, "order_payload", {}) or {}
            log.warning(
                "TRENDLINE_PIPELINE | stage=slot_sizing | symbol=%s | slot_index=%d | slot_capital=%.2f | "
                "entry_budget=%.2f | buffer_reserve=%.2f | available_cash=%.2f | estimated_cost=%.2f | quantity=%s | success=%s",
                signal.symbol,
                slot_index,
                float(_p.get("slot_capital_target", slot_capital) or slot_capital),
                float(_p.get("entry_budget", entry_budget) or entry_budget),
                float(_p.get("buffer_reserve", buffer_reserve) or buffer_reserve),
                available_cash,
                float(_p.get("estimated_total_cost", 0.0) or 0.0),
                _p.get("quantity"),
                str(bool(result.success)).lower(),
            )
            if result.success:
                log.warning(
                    "TRENDLINE_EXECUTION_ALLOWED | symbol=%s | position_id=%s | stage=executor_fill_ok",
                    signal.symbol,
                    str(getattr(result, "position_id", "") or ""),
                )
                try:
                    from modules.execution_telemetry import build_execution_payload, log_execution_event

                    _op = getattr(result, "order_payload", {}) or {}
                    log_execution_event(
                        "EXECUTION_FILL_SUMMARY",
                        "TRENDLINE_0DTE",
                        build_execution_payload(
                            symbol=signal.symbol,
                            trade_id=str(getattr(result, "position_id", "") or ""),
                            strategy="TRENDLINE_0DTE",
                            signal_ts=str(getattr(signal, "emitted_at", "") or ""),
                            fill_ts=datetime.now(timezone.utc).isoformat(),
                            order_type="DEMO_SIM" if getattr(self.trendline_options_executor, "demo_mode", True) else "LIVE_PENDING",
                            quote_mid=float(_op.get("estimated_contract_price", 0.0) or 0.0),
                            fill_price=float(_op.get("estimated_contract_price", 0.0) or 0.0),
                            extra={"estimated_total_cost": float(_op.get("estimated_total_cost", 0.0) or 0.0)},
                        ),
                    )
                except Exception:
                    pass
                self.trendline_signal_engine.mark_executed(
                    signal.symbol,
                    option_side=str(getattr(signal, "option_side", "") or ""),
                    candidate_id=str(
                        getattr(candidate, "candidate_id", "")
                        or (getattr(signal, "metadata", None) or {}).get("candidate_id")
                        or ""
                    ),
                )
                try:
                    if isinstance(getattr(candidate, "setup_payload", None), dict):
                        candidate.setup_payload["attempt_consumed"] = True
                    persist = getattr(self, "_persist_trendline_geometry_now", None)
                    if callable(persist):
                        persist(metadata={"source": "tl_fill_consumed", "symbol": signal.symbol})
                except Exception:
                    pass
                self._trendline_signals_executed_today.add(signal.symbol)
                self._trendline_capital_deployed_today += float((result.order_payload or {}).get("estimated_total_cost", 0.0) or 0.0)
                tl_trade_id = str(getattr(result, "position_id", "") or "").strip()
                if tl_trade_id:
                    from modules.unified_0dte_account import (
                        get_unified_position,
                        normalize_trendline_position_attrs,
                    )

                    tl_pos_for_registry = normalize_trendline_position_attrs(
                        get_unified_position(self, tl_trade_id)
                    )
                else:
                    tl_pos_for_registry = None
                if tl_trade_id and tl_pos_for_registry is not None:
                        self._rebuild_0dte_system_position_registry()
                        tl_meta_reg = (
                            getattr(tl_pos_for_registry, "metadata", {})
                            if isinstance(getattr(tl_pos_for_registry, "metadata", {}), dict)
                            else {}
                        )
                        tl_norm_reg = tl_meta_reg.get("normalized_options") if isinstance(tl_meta_reg, dict) else {}
                        tl_exec_payload_reg = tl_meta_reg.get("execution_payload") if isinstance(tl_meta_reg, dict) else {}
                        tl_strategy_type_reg = str(
                            (
                                tl_norm_reg.get("strategy_type")
                                if isinstance(tl_norm_reg, dict)
                                else None
                            )
                            or (
                                tl_exec_payload_reg.get("strategy_type")
                                if isinstance(tl_exec_payload_reg, dict)
                                else None
                            )
                            or "trendline_0dte"
                        ).strip().lower()
                        tl_option_side_reg = str(
                            (
                                (tl_norm_reg.get("legs", [{}])[0].get("option_side"))
                                if isinstance(tl_norm_reg, dict)
                                and isinstance(tl_norm_reg.get("legs"), list)
                                and tl_norm_reg.get("legs")
                                and isinstance(tl_norm_reg.get("legs")[0], dict)
                                else None
                            )
                            or getattr(tl_pos_for_registry, "option_side", "")
                            or ""
                        ).strip().lower()
                        tl_entry_premium_reg = float(
                            (
                                tl_norm_reg.get("entry_value")
                                if isinstance(tl_norm_reg, dict)
                                else None
                            )
                            or (
                                tl_exec_payload_reg.get("estimated_contract_price")
                                if isinstance(tl_exec_payload_reg, dict)
                                else None
                            )
                            or 0.0
                        )
                        log.warning(
                            "OPTION_POSITION_REGISTERED | strategy=%s | trade_id=%s | symbol=%s | option_side=%s | entry_premium=%.6f",
                            tl_strategy_type_reg,
                            tl_trade_id,
                            str(getattr(tl_pos_for_registry, "symbol", "") or ""),
                            tl_option_side_reg or "unknown",
                            tl_entry_premium_reg,
                        )
                        try:
                            from modules.exit_grade_durability import (
                                EVT_FILL,
                                EVT_REGISTRY,
                                stamp_session_event,
                            )

                            _tl_md = getattr(tl_pos_for_registry, "metadata", None)
                            if not isinstance(_tl_md, dict):
                                tl_pos_for_registry.metadata = {}
                                _tl_md = tl_pos_for_registry.metadata
                            _tl_dur = _tl_md.setdefault("orb_0dte_durability", {})
                            _tl_dur["fill_confirmed"] = True
                            _tl_dur["position_registered"] = True
                            stamp_session_event(_tl_md, EVT_FILL)
                            stamp_session_event(_tl_md, EVT_REGISTRY)
                        except Exception:
                            pass
                        from modules.unified_0dte_monitor_registry import enqueue_0dte_pending_monitor

                        enqueue_0dte_pending_monitor(
                            self._0dte_pending_monitor_registrations,
                            trade_id=tl_trade_id,
                            symbol=str(getattr(tl_pos_for_registry, "symbol", "") or ""),
                            strategy_type=tl_strategy_type_reg or "trendline_0dte",
                        )
                        self._0dte_not_monitored_logged.discard(tl_trade_id)
                        _tl_entry_spot = 0.0
                        if isinstance(tl_exec_payload_reg, dict) and tl_exec_payload_reg.get("entry_underlying_price"):
                            _tl_entry_spot = float(tl_exec_payload_reg.get("entry_underlying_price") or 0.0)
                        else:
                            _tl_break = getattr(signal, "break_event", None)
                            if _tl_break is not None:
                                _tl_entry_spot = float(getattr(_tl_break, "close_price", 0.0) or 0.0)
                        self._profit_optimizer_track_trendline_fill(
                            position=tl_pos_for_registry,
                            signal=signal,
                            trade_id=tl_trade_id,
                            order_payload=_p if isinstance(_p, dict) else {},
                            entry_spot=_tl_entry_spot,
                        )
                for c in self._pending_trendline_candidates:
                    if c.symbol == signal.symbol and c.direction == signal.direction:
                        c.executed_trade_id = result.position_id
                stealth = getattr(self, "trendline_options_stealth", None)
                try:
                    if stealth and result.position_id:
                        from modules.unified_0dte_account import (
                            get_unified_position,
                            normalize_trendline_position_attrs,
                        )

                        pos = normalize_trendline_position_attrs(
                            get_unified_position(self, str(result.position_id))
                        )
                        pl = result.order_payload or {}
                        if pos:
                            if slot_marker_path and isinstance(getattr(pos, "metadata", None), dict):
                                pos.metadata["trendline_open_slot_marker"] = str(slot_marker_path)
                            from easy0DTE.modules.options_execution_normalize import (
                                validate_normalized_options_for_stealth,
                            )

                            trendline_d = pl.get("trendline_for_exit") if isinstance(pl, dict) else {}
                            if not isinstance(trendline_d, dict):
                                trendline_d = {}
                            norm_tl = pos.metadata.get("normalized_options") if isinstance(pos.metadata, dict) else None
                            tl_pid = str(result.position_id)
                            norm_ok_tl, norm_miss_tl = (
                                validate_normalized_options_for_stealth(norm_tl)
                                if isinstance(norm_tl, dict)
                                else (False, ["normalized_options_absent"])
                            )
                            sig_meta = signal.metadata or {}
                            if norm_ok_tl and isinstance(norm_tl, dict):
                                norm_trade_tl = str(norm_tl.get("trade_id") or tl_pid)
                                log.info(
                                    "OPTIONS_STEALTH | stage=normalized_metadata_used | trade_id=%s | position_type=%s | norm_trade_id=%s",
                                    tl_pid,
                                    str(norm_tl.get("position_type") or ""),
                                    norm_trade_tl,
                                )
                                legs_tl = [dict(x) for x in norm_tl["legs"] if isinstance(x, dict)]
                                expiry_tl = str(norm_tl.get("expiration_ymd") or "")
                                und_tl = str(norm_tl.get("underlying_symbol") or signal.symbol)
                                setup_tl = str(
                                    norm_tl.get("setup_type")
                                    or sig_meta.get("setup_type")
                                    or pl.get("setup_type")
                                    or ""
                                )
                                trig_tl = str(
                                    norm_tl.get("trigger_direction")
                                    or sig_meta.get("trigger_direction")
                                    or pl.get("trigger_direction")
                                    or ""
                                )
                                src_tl = str(norm_tl.get("source_path") or "trendline_0dte")
                                pos_type_tl = str(norm_tl.get("position_type") or "")
                                if pos_type_tl not in ("single_leg_long_call", "single_leg_long_put"):
                                    pos_type_tl = (
                                        "single_leg_long_put"
                                        if str(signal.option_side).lower() == "put"
                                        else "single_leg_long_call"
                                    )
                                entry_val_tl = float(norm_tl.get("entry_value") or pl.get("estimated_contract_price") or 0.0)
                                if norm_tl.get("entry_debit") is not None:
                                    entry_debit_tl = float(norm_tl.get("entry_debit"))
                                else:
                                    entry_debit_tl = entry_val_tl
                                entry_credit_tl = (
                                    float(norm_tl["entry_credit"])
                                    if norm_tl.get("entry_credit") is not None
                                    else None
                                )
                                fl0 = legs_tl[0] if legs_tl else {}
                                strike_tl = float(fl0.get("strike") or pl.get("strike") or 0.0)
                                delta_tl = float(
                                    fl0.get("delta_at_entry")
                                    or norm_tl.get("delta_at_entry")
                                    or pl.get("delta_at_entry")
                                    or 0.25
                                )
                                option_side_tl = str(fl0.get("option_side") or signal.option_side)
                            else:
                                if isinstance(norm_tl, dict):
                                    log.info(
                                        "OPTIONS_STEALTH | stage=normalized_metadata_invalid | trade_id=%s | missing=%s",
                                        tl_pid,
                                        ",".join(norm_miss_tl) if norm_miss_tl else "unknown",
                                    )
                                log.info(
                                    "OPTIONS_STEALTH | stage=legacy_metadata_fallback | trade_id=%s | reason=%s",
                                    tl_pid,
                                    "validation_failed"
                                    if isinstance(norm_tl, dict)
                                    else "normalized_options_absent_or_invalid",
                                )
                                expiry_tl = str(pl.get("expiry_ymd") or pl.get("expiration_ymd") or "")
                                und_tl = str(pl.get("underlying_symbol") or signal.symbol)
                                setup_tl = str(sig_meta.get("setup_type") or pl.get("setup_type") or "")
                                trig_tl = str(sig_meta.get("trigger_direction") or pl.get("trigger_direction") or "")
                                src_tl = "trendline_0dte"
                                pos_type_tl = (
                                    "single_leg_long_put"
                                    if str(signal.option_side).lower() == "put"
                                    else "single_leg_long_call"
                                )
                                legs_tl = [
                                    {
                                        "leg_id": f"{signal.symbol}_{pl.get('expiry_ymd')}_{pl.get('strike')}_{signal.option_side}",
                                        "long_or_short": "long",
                                        "option_side": str(signal.option_side).lower(),
                                        "strike": float(pl.get("strike", 0.0) or 0.0),
                                        "quantity": int(max(1, int(pl.get("quantity", 1) or 1))),
                                        "entry_price": float(pl.get("estimated_contract_price", 0.0) or 0.0),
                                        "delta_at_entry": float(pl.get("delta_at_entry", 0.0) or 0.0),
                                    }
                                ]
                                entry_val_tl = float(
                                    getattr(pos, "entry_price", 0.0)
                                    or pl.get("estimated_contract_price", 0.0)
                                    or 0.0
                                )
                                entry_debit_tl = entry_val_tl
                                entry_credit_tl = None
                                strike_tl = float(pl.get("strike", 0.0) or 0.0)
                                delta_tl = float(pl.get("delta_at_entry", 0.25) or 0.25)
                                option_side_tl = str(signal.option_side)
                            stealth.register_on_open(
                                result.position_id,
                                entry_premium_per_contract=entry_val_tl,
                                underlying_entry=float(
                                    pl.get("entry_underlying_price", signal.break_event.close_price) or 0.0
                                ),
                                option_side=option_side_tl,
                                line_geometry=str(signal.direction.value),
                                strike=strike_tl,
                                delta=delta_tl,
                                trendline_dict=trendline_d,
                                metadata_target=pos.metadata,
                                underlying_symbol=und_tl,
                                expiration_ymd=expiry_tl,
                                setup_type=setup_tl,
                                trigger_direction=trig_tl,
                                trendline_mode=str(sig_meta.get("trendline_mode") or "STANDARD"),
                                impulse_mode=bool(sig_meta.get("impulse_mode")),
                                early_entry_mode=bool(sig_meta.get("early_entry_mode")),
                                position_type=pos_type_tl,
                                strategy_name=str(pl.get("strategy_name") or "easyTrendline_0DTE"),
                                strategy_type=str(pl.get("strategy_type") or "trendline_0dte"),
                                entry_value=entry_val_tl,
                                entry_debit=entry_debit_tl,
                                entry_credit=entry_credit_tl,
                                legs=legs_tl,
                                structure_invalidation_enabled=True,
                                source_path=src_tl,
                                break_archetype=str(sig_meta.get("break_archetype") or ""),
                            )
                            log.info(
                                "OPTIONS_STEALTH_REGISTER | symbol=%s | strategy=%s | trade_id=%s",
                                und_tl or signal.symbol,
                                str(pl.get("strategy_type") or "trendline_0dte"),
                                result.position_id,
                            )
                            log.info(
                                "TRENDLINE_POSITION_REGISTERED_FOR_STEALTH | trade_id=%s | symbol=%s | strategy_type=trendline_0dte",
                                result.position_id,
                                und_tl or signal.symbol,
                            )
                except Exception as trendline_stealth_reg_err:
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=executed | action=stealth_register_failed | symbol=%s | reason=%s",
                        signal.symbol,
                        trendline_stealth_reg_err,
                    )
                log.info(
                    "TRENDLINE_PIPELINE | stage=executed | "
                    f"symbol={signal.symbol} | trade_id={result.position_id}"
                )
                _equity_at_entry = None
                try:
                    from modules.unified_0dte_account import sync_unified_account_balance

                    _equity_at_entry = float(sync_unified_account_balance(self))
                except (TypeError, ValueError):
                    _equity_at_entry = None
                _sig_meta = signal.metadata if isinstance(signal.metadata, dict) else {}
                _setup_nested = (
                    _sig_meta.get("setup_payload")
                    if isinstance(_sig_meta.get("setup_payload"), dict)
                    else {}
                )
                _slot_raw = (
                    _sig_meta.get("trendline_slot")
                    or _setup_nested.get("trendline_slot")
                    or "trendline1"
                )
                try:
                    from easyTrendline.trendline_models import normalize_trendline_slot

                    _tl_slot = normalize_trendline_slot(_slot_raw)
                except Exception:
                    _tl_slot = "trendline1"
                exec_alert_row = {
                    "symbol": signal.symbol,
                    "setup_type": (signal.metadata or {}).get("setup_type", "n/a"),
                    "structure_display_label": str((signal.metadata or {}).get("structure_display_label") or ""),
                    "trigger_direction": (signal.metadata or {}).get("trigger_direction", "n/a"),
                    "line_geometry": signal.direction.value.upper(),
                    "option_side": str(signal.option_side).upper(),
                    "trade_id": result.position_id,
                    "trendline_slot": _tl_slot,
                    "quantity": int((_p.get("quantity") if isinstance(_p, dict) else 1) or 1),
                    "strike": float((_p.get("strike") if isinstance(_p, dict) else 0.0) or 0.0),
                    "delta_at_entry": float(
                        (_p.get("delta_at_entry") if isinstance(_p, dict) else 0.0) or 0.0
                    ),
                    "entry_premium": float(
                        (_p.get("estimated_contract_price") if isinstance(_p, dict) else 0.0) or 0.0
                    ),
                    "estimated_total_cost": float(
                        (_p.get("estimated_total_cost") if isinstance(_p, dict) else 0.0) or 0.0
                    ),
                    "account_equity_at_entry": _equity_at_entry,
                }
                if isinstance(_p, dict):
                    _exp = str(
                        _p.get("expiry_ymd")
                        or _p.get("selected_expiry_ymd")
                        or _p.get("expiration_ymd")
                        or _p.get("expiry")
                        or ""
                    ).strip()
                    if _exp:
                        exec_alert_row["expiry_ymd"] = _exp
                _sex = (signal.metadata or {}).get("structure_explainability")
                if isinstance(_sex, dict) and _sex:
                    _tp: List[str] = []
                    ol, oh = _sex.get("orb_low"), _sex.get("orb_high")
                    if ol is not None and oh is not None:
                        try:
                            _tp.append(f"ORB {float(ol):.2f}-{float(oh):.2f}")
                        except (TypeError, ValueError):
                            _tp.append("ORB n/a")
                    px = _sex.get("price_last_close_pre_cutoff")
                    if px is not None:
                        try:
                            _tp.append(f"last_px_pre730 {float(px):.2f}")
                        except (TypeError, ValueError):
                            pass
                    ppl = _sex.get("price_pct_from_orb_low")
                    if ppl is not None:
                        try:
                            _tp.append(f"pct_from_orb_low {float(ppl):.2f}")
                        except (TypeError, ValueError):
                            pass
                    cs = _sex.get("compression_score")
                    if cs is not None:
                        try:
                            _tp.append(f"compression {float(cs):.3f}")
                        except (TypeError, ValueError):
                            pass
                    ms, mr = _sex.get("mse_support"), _sex.get("mse_resistance")
                    if ms is not None or mr is not None:
                        try:
                            _tp.append(f"MSE sup/res {float(ms) if ms is not None else 'n'}/{float(mr) if mr is not None else 'n'}")
                        except (TypeError, ValueError):
                            _tp.append("MSE sup/res n/a")
                    sl = _sex.get("selected_line") if isinstance(_sex.get("selected_line"), dict) else {}
                    if isinstance(sl, dict):
                        lv = sl.get("line_price_at_cutoff")
                        sg = sl.get("slope_sign")
                        if lv is not None:
                            try:
                                _tp.append(f"line@cutoff {float(lv):.3f}")
                            except (TypeError, ValueError):
                                pass
                        if sg:
                            _tp.append(f"slope {sg}")
                    exec_alert_row["structure_telemetry_line"] = " | ".join(_tp)
                exec_alert_row.update(self._trendline_order_payload_health(_p))
                exec_alert_row["diagnostic_stage"] = "executed"
                exec_alert_row["execution_attempted"] = True
                await self._send_trendline_emit_execution_alert(
                    mode_label=mode_label,
                    executed_row=exec_alert_row,
                )
                # Do NOT stamp first_seen / clear pending here — that disables
                # TRENDLINE_POSITION_NOT_MONITORED and OPTION_POSITION_MONITOR_START.
                # Pending stays until _monitor_trendline_positions actually ticks.
                if tl_trade_id:
                    self._trendline_not_monitored_logged.discard(tl_trade_id)
                self._trendline_request_immediate_monitor(reason="execution_fill")
                self._record_trendline_execution_dataset(
                    signal=signal,
                    candidate=candidate,
                    trade_result=result,
                )
                self._save_trendline_execution_priority_snapshot(
                    signal=signal,
                    candidate=candidate,
                    stage="trendline_options_executed",
                    order_payload=dict(_p) if isinstance(_p, dict) else {},
                    broker_success=True,
                    broker_error=None,
                )
                self._log_trendline_feature_events([candidate], stage="executed", trade_result=result)
            else:
                if slot_marker_path:
                    self._trendline_release_global_daily_slot(slot_marker_path)
                err_s = str(getattr(result, "error", "") or "")
                rej = _p.get("reject_reason") if isinstance(_p, dict) else None
                log.info(
                    "TRENDLINE_EXECUTION_BLOCKED | symbol=%s | stage=post_executor | error=%s | reject_reason=%s",
                    signal.symbol,
                    err_s,
                    str(rej) if rej is not None else "",
                )
                self._save_trendline_execution_priority_snapshot(
                    signal=signal,
                    candidate=candidate,
                    stage="trendline_options_executed",
                    order_payload=dict(_p) if isinstance(_p, dict) else {},
                    broker_success=False,
                    broker_error=str(getattr(result, "error", "") or ""),
                )
                if err_s == "live_chain_required_unavailable" or rej == "live_chain_required_unavailable":
                    stealth_t = getattr(self, "trendline_options_stealth", None)
                    if stealth_t is not None and hasattr(stealth_t, "bump_skipped_entry_no_quote"):
                        stealth_t.bump_skipped_entry_no_quote(str(signal.symbol or ""), "-")
                from modules.path_exec_day_exclude import (
                    is_trendline_candidate_only_exec_reject,
                    is_trendline_exec_retryable,
                )

                fail_reason_code = str(err_s or rej or getattr(result, "error", "") or "execution_failed")
                if rej and str(rej) not in fail_reason_code:
                    fail_reason_code = f"{fail_reason_code}|{rej}"
                selected_delta = None
                try:
                    selected_delta = (_p or {}).get("selected_delta") or (_p or {}).get("delta")
                except Exception:
                    selected_delta = None
                retryable = is_trendline_exec_retryable(
                    err_s, selected_delta=selected_delta
                ) or (
                    rej is not None
                    and is_trendline_exec_retryable(
                        str(rej), selected_delta=selected_delta
                    )
                )
                candidate_only = (not retryable) and (
                    is_trendline_candidate_only_exec_reject(
                        err_s, selected_delta=selected_delta
                    )
                    or (
                        rej is not None
                        and is_trendline_candidate_only_exec_reject(
                            str(rej), selected_delta=selected_delta
                        )
                    )
                )
                if str(getattr(result, "error", "")) in {
                    "execution_skipped_due_to_slot_sizing",
                    "buffer_reserve_exhausted",
                    "insufficient_balance_or_invalid_cost",
                }:
                    self._trendline_sizing_skips += 1
                if retryable:
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=entry_blocked | symbol=%s | stage=contract_or_execution | "
                        "reason=%s | action=retry_rearm",
                        signal.symbol,
                        getattr(result, "error", ""),
                    )
                    self._trendline_rearm_deferred(
                        signal.symbol,
                        str(getattr(result, "error", "") or "execution_retry"),
                        candidate_id=str(
                            getattr(candidate, "candidate_id", "")
                            or (getattr(signal, "metadata", None) or {}).get("candidate_id")
                            or ""
                        ),
                    )
                else:
                    # Candidate-only hard reject (spread / premium / no contract / …).
                    # Do NOT day-exclude the symbol — TL2/TL3 siblings stay watchable.
                    err_veto = str(getattr(result, "error", "") or "")
                    liquidity_block = err_veto in {
                        "live_chain_required_unavailable",
                        "option_live_chain_required",
                        "spread_too_wide",
                        "option_spread_too_wide",
                        "low_open_interest",
                        "option_low_open_interest",
                        "low_volume",
                        "option_low_volume",
                        "option_premium_too_low",
                        "option_quote_stale",
                        "option_too_expensive_for_budget",
                        "contract_selection_failed",
                        "option_liquidity_failed",
                        "no_affordable_contract_for_slot",
                        "option_no_bid",
                        "buffer_reserve_exhausted",
                        "execution_skipped_due_to_slot_sizing",
                        "insufficient_balance_or_invalid_cost",
                        "timeout",
                        "broker_timeout",
                    }
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=entry_blocked | symbol=%s | stage=contract_or_execution | "
                        "reason=%s | action=reject_current_candidate_only | candidate_only=%s",
                        signal.symbol,
                        getattr(result, "error", ""),
                        str(bool(candidate_only)).lower(),
                    )
                    log.warning(
                        "TRENDLINE_HARD_VETO_AUDIT | symbol=%s | stage=execution | veto_reason=%s | catastrophic=false | stale=false | "
                        "severe_chop=false | invalid_structure=false | liquidity_block=%s | executor_called=true | "
                        "scope=current_signal_only",
                        signal.symbol,
                        err_veto or "execution_failed",
                        str(bool(liquidity_block)).lower(),
                    )
                    try:
                        if not str(getattr(candidate, "option_side", "") or "").strip():
                            candidate.option_side = str(
                                getattr(signal, "option_side", "") or ""
                            ).strip().lower()
                    except Exception:
                        pass
                    self._trendline_reject_current_exec_signal(candidate, fail_reason_code)
                log.warning(
                    "TRENDLINE_PIPELINE | stage=invalidated | "
                    f"symbol={signal.symbol} | reason=execution_failed | error={result.error}"
                )
                self._log_trendline_feature_events([candidate], stage="execution_failed", trade_result=result)
                fail_reason = str(err_s or rej or getattr(result, "error", "") or "execution_failed")
                if rej and str(rej) not in fail_reason:
                    fail_reason = f"{fail_reason} | reject_reason={rej}"
                await _tl_exec_fail(
                    "post_executor",
                    fail_reason,
                    extra=self._trendline_order_payload_health(_p),
                )

        try:
            await self._flush_pending_trendline_quality_reject_alerts()
        except Exception as flush_q_err:
            log.debug(
                "TRENDLINE_PIPELINE | stage=quality_reject_alert_flush | error=%s",
                flush_q_err,
            )

        nl_sec = float(getattr(self, "_trendline_watch_nearline_log_sec", 0.0) or 0.0)
        now_nl = time.time()
        if (
            nearline_parts
            and nl_sec > 0
            and (now_nl - float(getattr(self, "_trendline_last_watch_nearline_log_ts", 0.0))) >= nl_sec
        ):
            preview = " | ".join(nearline_parts[:14])
            log.warning(
                "TRENDLINE_PIPELINE | stage=watch_nearline | waiting_break_symbols=%d | sample=%s",
                len(nearline_parts),
                preview,
            )
            self._trendline_last_watch_nearline_log_ts = now_nl

        has_watchable_tl_candidate = any(
            str(getattr(c, "state", "")) in (
                "TrendlineCandidateState.WAITING_FOR_BREAK",
                "TrendlineCandidateState.WAITING_FOR_CONFIRMATION",
            )
            for c in self._pending_trendline_candidates
        )
        self._trendline_watch_active = bool(
            has_watchable_tl_candidate
            or self._trendline_keep_orb2_extension_watch_alive(no_trade_after)
        )

        # Open-position stealth runs on the dedicated ~2s unified monitor tick; do not block the watch
        # loop on a full monitor pass (was 90+ symbols + N positions every 15–30s).
        try:
            from modules.discovery_watch_fsm_persist import sync_watch_fsm_after_cycle

            sync_watch_fsm_after_cycle(self)
        except Exception:
            pass

    def _trendline_unified_open_positions(self) -> Dict[str, Any]:
        from modules.unified_0dte_account import (
            list_trendline_open_positions,
            normalize_trendline_position_attrs,
        )

        out: Dict[str, Any] = {}
        for pos in list_trendline_open_positions(self):
            pid = str(getattr(pos, "position_id", "") or "").strip()
            if pid:
                out[pid] = normalize_trendline_position_attrs(pos)
        return out

    def _trendline_has_open_option_positions(self) -> bool:
        return bool(self._trendline_unified_open_positions())

    def _ensure_trendline_buffer_floor(self, *, force: bool = False) -> None:
        """Lock the sacred buffer floor once per PT session (7:30 build or first watch refresh)."""
        from zoneinfo import ZoneInfo

        from easyTrendline.trendline_capital_allocation import (
            buffer_pct_from_allocation,
            compute_session_buffer_floor,
        )
        from modules.unified_0dte_account import (
            _deployed_entry_costs,
            sync_unified_account_balance,
            unified_trading_capital_pct,
        )

        today_pt = datetime.now(ZoneInfo("America/Los_Angeles")).date().isoformat()
        if (
            not force
            and self._trendline_buffer_floor_pt_date == today_pt
            and float(getattr(self, "_trendline_buffer_reserve_floor", 0.0) or 0.0) > 0.0
        ):
            return
        try:
            cash_balance = sync_unified_account_balance(self)
            reserved_capital = _deployed_entry_costs(self)
            equity_basis = max(0.0, cash_balance + reserved_capital)
            alloc_pct = unified_trading_capital_pct()
            buf_pct = buffer_pct_from_allocation(alloc_pct)
            floor = compute_session_buffer_floor(equity_basis, buffer_pct=buf_pct)
            self._trendline_buffer_reserve_floor = floor
            self._trendline_buffer_floor_pt_date = today_pt
            self._trendline_account_allocation_pct = alloc_pct
            log.info(
                "TRENDLINE_PIPELINE | stage=buffer_floor_locked | pt_date=%s | equity_basis=%.2f | "
                "buffer_pct=%.1f | buffer_floor=%.2f | source=unified_0dte_account",
                today_pt,
                equity_basis,
                buf_pct,
                floor,
            )
        except Exception as floor_err:
            log.warning(
                "TRENDLINE_PIPELINE | stage=buffer_floor_locked | error=%s",
                floor_err,
            )

    def _trendline_rearm_deferred(
        self, symbol: str, reason: str, *, candidate_id: str = ""
    ) -> None:
        engine = getattr(self, "trendline_signal_engine", None)
        if engine is None or not hasattr(engine, "rearm_deferred_execution"):
            return
        try:
            engine.rearm_deferred_execution(
                str(symbol or ""),
                reason=reason,
                candidate_id=str(candidate_id or "") or None,
            )
        except Exception as rearm_err:
            log.debug("TRENDLINE_PIPELINE | stage=execution_rearm | symbol=%s | error=%s", symbol, rearm_err)

    def _trendline_reject_current_exec_signal(
        self,
        candidate: Any,
        reason: str,
        *,
        arm_slot_side_cooldown: Optional[bool] = None,
    ) -> None:
        """Reject the current TL slot/side attempt.

        Hard rejects / TTL expire that envelope for the rest of the session
        (one attempt). A1/A2 stay on the candidate for plots. Opposite envelope
        and sibling slots stay eligible. Capital / broker waits still re-arm.
        """
        reason_raw = str(reason or "global_slot_unavailable")[:160]
        if reason_raw == "exec_ready_ttl_expired":
            reason_code = reason_raw
            classification = "expire"
            try:
                from modules.path_exec_ready_ttl import (
                    EXEC_READY_TTL_RETIRE_REASON,
                    ttl_retire_no_cooldown_enabled,
                )

                if ttl_retire_no_cooldown_enabled():
                    # Oct 13 2026: capacity wait ran out before any execution attempt.
                    reason_code = EXEC_READY_TTL_RETIRE_REASON
                    classification = "expire_retire"
            except Exception:
                pass
        elif reason_raw.startswith(
            (
                "slot_unavailable_reject:",
                "slot_side_cooldown:",
                "quality_reject:",
                "trade_profile_reject:",
                "pc_oi_filter_reject:",
                "dir_pct_filter_reject:",
                "chain_skew_filter_reject:",
                "exec_reject:",
            )
        ):
            reason_code = reason_raw
            classification = "skip_reject"
        elif "|" in reason_raw or any(
            tok in reason_raw.lower()
            for tok in (
                "spread",
                "premium",
                "contract",
                "liquidity",
                "no_bid",
                "open_interest",
                "volume",
                "delta",
                "pc_oi",
                "otm",
                "chain",
                "ask_size",
                "bid_size",
                "market_quality",
            )
        ):
            # Post-exec hard class (spread / premium / no contract / …) — candidate only.
            reason_code = f"exec_reject:{reason_raw[:140]}"
            classification = "skip_reject"
        else:
            reason_code = f"slot_unavailable_reject:{reason_raw[:120]}"
            classification = "skip_reject"
        side_for_cd = ""
        slot = "unknown"
        try:
            from easyTrendline.trendline_models import trendline_slot_from_payload
            from easyTrendline.trendline_simple_mode import (
                candidate_expected_option_side,
                expire_simple_candidate_after_attempt,
                rearm_simple_candidate_for_next_break,
            )

            slot = trendline_slot_from_payload(getattr(candidate, "setup_payload", None) or {})
            side_for_cd = candidate_expected_option_side(candidate)
            engine = getattr(self, "trendline_signal_engine", None)
            emitted = getattr(engine, "_emitted_candidate_ids", None) if engine is not None else None
            # Prefer engine helper emitted set used by simple processor.
            simple = getattr(engine, "_simple_processor", None) if engine is not None else None
            if simple is not None:
                emitted = getattr(simple, "_emitted_ids", emitted)
            from modules.path_exec_day_exclude import should_arm_trendline_slot_side_cooldown

            consume_envelope = (
                bool(arm_slot_side_cooldown)
                if arm_slot_side_cooldown is not None
                else should_arm_trendline_slot_side_cooldown(reason_raw)
            )
            if consume_envelope:
                expire_simple_candidate_after_attempt(
                    candidate,
                    reason_code,
                    clear_emitted_ids=emitted if isinstance(emitted, set) else None,
                )
            else:
                rearm_simple_candidate_for_next_break(
                    candidate,
                    reason_code,
                    clear_emitted_ids=emitted if isinstance(emitted, set) else None,
                )
        except Exception:
            try:
                candidate.state_reason = reason_code
            except Exception:
                pass

        engine = getattr(self, "trendline_signal_engine", None)
        emitted = getattr(engine, "_emitted_candidate_ids", None)
        cid = str(getattr(candidate, "candidate_id", "") or "")
        if cid and hasattr(emitted, "discard"):
            try:
                emitted.discard(cid)
            except Exception:
                pass
        already_cd = False
        try:
            from modules.path_exec_day_exclude import is_trendline_slot_side_on_cooldown

            if side_for_cd:
                already_cd = is_trendline_slot_side_on_cooldown(
                    self,
                    str(getattr(candidate, "symbol", "") or ""),
                    side_for_cd,
                    slot=slot,
                )
        except Exception:
            already_cd = False
        if not already_cd:
            log.warning(
                "TRENDLINE_PIPELINE | stage=slot_signal_rejected | classification=%s | "
                "symbol=%s | trade_id=%s | trendline_slot=%s | reason=%s | "
                "scope=current_signal_only | action=expire_envelope_or_rearm",
                classification,
                str(getattr(candidate, "symbol", "") or ""),
                cid,
                slot,
                reason_code,
            )
            # Persist path-SS reject-time admit features for later synthetic tuning.
            try:
                if "gate_stack:path_ss:" in str(reason_code or ""):
                    from modules.path_ss_reject_snapshot_store import (
                        capture_path_ss_reject_snapshot,
                    )

                    sym = str(getattr(candidate, "symbol", "") or "").upper()
                    side_raw = str(side_for_cd or "").strip()
                    side_l = side_raw.lower()
                    side_lbl = (
                        "CALL"
                        if "call" in side_l
                        else "PUT"
                        if "put" in side_l
                        else side_raw.upper()
                    )

                    tech_row = {}
                    meta = getattr(candidate, "metadata", None)
                    if isinstance(meta, dict):
                        tech_row.update(meta)
                        if isinstance(meta.get("qg_admit"), dict):
                            qg_admit = meta.get("qg_admit")
                        else:
                            qg_admit = None
                    else:
                        qg_admit = None

                    setup = getattr(candidate, "setup_payload", None)
                    if isinstance(setup, dict):
                        tech_row.update(setup)
                    if slot:
                        tech_row.setdefault("trendline_slot", slot)
                    if side_lbl:
                        tech_row.setdefault("side", side_lbl)

                    capture_path_ss_reject_snapshot(
                        self,
                        source="TRENDLINE_PIPELINE_slot_signal_rejected",
                        symbol=sym,
                        side=side_lbl,
                        trade_id=cid or None,
                        slot=slot or None,
                        reason_code=str(reason_code or ""),
                        qg_admit=qg_admit,
                        tech_row=tech_row,
                        gate_report=(
                            tech_row.get("quality_gate_report")
                            if isinstance(tech_row.get("quality_gate_report"), dict)
                            else (
                                meta.get("quality_gate_report")
                                if isinstance(meta, dict)
                                and isinstance(meta.get("quality_gate_report"), dict)
                                else None
                            )
                        ),
                        extra={
                            "classification": classification,
                            "scope": "current_signal_only",
                        },
                    )
            except Exception:
                pass
        try:
            from modules.path_exec_day_exclude import (
                mark_trendline_slot_side_cooldown,
                should_arm_trendline_slot_side_cooldown,
            )

            do_arm = (
                bool(arm_slot_side_cooldown)
                if arm_slot_side_cooldown is not None
                else should_arm_trendline_slot_side_cooldown(reason_raw)
            )
            if do_arm and side_for_cd:
                mark_trendline_slot_side_cooldown(
                    self,
                    str(getattr(candidate, "symbol", "") or ""),
                    side_for_cd,
                    slot=slot,
                    reason=reason_code,
                )
        except Exception as arm_err:
            log.debug(
                "TRENDLINE_PIPELINE | stage=slot_side_cooldown_arm | symbol=%s | error=%s",
                getattr(candidate, "symbol", ""),
                arm_err,
            )
        try:
            st_now = str(getattr(candidate, "state", "") or "")
            if "EXPIRED" in st_now.upper() or "EXECUTED" in st_now.upper():
                persist = getattr(self, "_persist_trendline_geometry_now", None)
                if callable(persist):
                    persist(metadata={"source": "tl_attempt_consumed", "reason": reason_code[:80]})
        except Exception:
            pass
        # Queue Reject Telegram for hard quality / reclaim (sync path; flushed in watch cycle).
        # Post-executor rejects already alert via _tl_exec_fail — do not double-send.
        # Repeat rejects while the 1h cooldown is already live stay silent.
        try:
            rc_l = reason_code.lower()
            if (
                not already_cd
                and (rc_l.startswith("quality_reject:") or "reclaim_persisted" in rc_l)
            ):
                pending = getattr(self, "_pending_trendline_quality_reject_alerts", None)
                if not isinstance(pending, list):
                    pending = []
                    self._pending_trendline_quality_reject_alerts = pending
                setup = getattr(candidate, "setup_payload", None) or {}
                setup_type = ""
                if isinstance(setup, dict):
                    setup_type = str(
                        setup.get("setup_type")
                        or setup.get("structure_display_label")
                        or ""
                    )
                # Prefer gate_stack tag for Telegram Reason (0DTEQualityGates §3.2).
                reason_body = reason_code
                if reason_body.lower().startswith("quality_reject:"):
                    reason_body = reason_body.split(":", 1)[-1]
                try:
                    from modules.prime_alert_manager import PrimeAlertManager

                    reason_code_display = PrimeAlertManager._execution_reject_display_code(
                        reason_code
                    )
                except Exception:
                    reason_code_display = reason_body[:120]
                pending.append(
                    {
                        "symbol": str(getattr(candidate, "symbol", "") or ""),
                        "setup_type": setup_type or "trendline_break",
                        "option_side": (side_for_cd or "").upper(),
                        "trade_id": cid or "n/a",
                        "trendline_slot": slot,
                        "diagnostic_stage": "quality_reject",
                        "failure_stage": "quality_reject",
                        "failure_reason": reason_code,
                        "failure_reason_code": str(reason_code_display or reason_body)[:160],
                        "execution_attempted": True,
                        "status": "failed",
                    }
                )
        except Exception as q_alert_err:
            log.debug(
                "TRENDLINE_PIPELINE | stage=quality_reject_alert_queue | symbol=%s | error=%s",
                getattr(candidate, "symbol", ""),
                q_alert_err,
            )

    def _trendline_day_exclude_exec_reject(self, symbol: str, reason: str) -> None:
        """Legacy name. Dual envelopes stay independent — do not symbol-day-exclude.

        Hard rejects use ``_trendline_reject_current_exec_signal`` (1h slot+side).
        """
        log.warning(
            "TRENDLINE_PIPELINE | stage=exec_reject_keep_peer_envelopes | symbol=%s | "
            "reason=%s | action=no_symbol_day_exclude",
            symbol,
            str(reason or "")[:160],
        )

    def _begin_0dte_orb_batch_capital(self) -> None:
        """Lock slot capital for one ORB batch; only cash/entry_budget update after fills."""
        self._0dte_orb_batch_capital_locked = True
        self._0dte_orb_batch_capital_snapshotted = False

    def _debit_0dte_orb_batch_cash(self, deployed_usd: float) -> None:
        """After a fill in the ORB batch: reduce available cash only (no equity re-snap)."""
        if not getattr(self, "_0dte_orb_batch_capital_locked", False):
            return
        try:
            from easyTrendline.trendline_capital_allocation import compute_entry_budget

            deployed = max(0.0, float(deployed_usd or 0.0))
            cash = max(0.0, float(getattr(self, "_trendline_available_cash", 0.0) or 0.0) - deployed)
            slot = float(getattr(self, "_trendline_slot_capital", 0.0) or 0.0)
            self._trendline_available_cash = cash
            self._trendline_entry_budget = float(compute_entry_budget(slot, cash))
            log.info(
                "0DTE_PIPELINE | stage=orb_batch_cash_debit | deployed=%.2f | "
                "available_cash=%.2f | slot_capital=%.2f | entry_budget=%.2f",
                deployed,
                cash,
                slot,
                float(self._trendline_entry_budget),
            )
        except Exception as debit_err:
            log.debug("0DTE_PIPELINE | stage=orb_batch_cash_debit | error=%s", debit_err)

    def _end_0dte_orb_batch_capital(self) -> None:
        """Unlock and refresh full shared slot snapshot after the ORB batch."""
        if not getattr(self, "_0dte_orb_batch_capital_locked", False):
            return
        self._0dte_orb_batch_capital_locked = False
        self._0dte_orb_batch_capital_snapshotted = False
        try:
            self._refresh_0dte_slot_capital()
        except Exception as end_err:
            log.warning("0DTE_PIPELINE | stage=orb_batch_capital_unlock | error=%s", end_err)

    def _refresh_0dte_slot_capital(self) -> None:
        """
        Recompute shared 0DTE slot budget (sacred buffer + tradable / N).

        entry_budget = min(slot_capital, available_cash) — full 1/N when cash allows, else
        deploy released proceeds.

        During an ORB batch lock, skip full equity re-snap (cash is debited after fills only).
        """
        if getattr(self, "_0dte_orb_batch_capital_locked", False) and getattr(
            self, "_0dte_orb_batch_capital_snapshotted", False
        ):
            log.debug(
                "0DTE_PIPELINE | stage=slot_cap_refresh | skipped=orb_batch_locked | "
                "available_cash=%.2f | entry_budget=%.2f",
                float(getattr(self, "_trendline_available_cash", 0.0) or 0.0),
                float(getattr(self, "_trendline_entry_budget", 0.0) or 0.0),
            )
            return

        from modules.config_loader import get_config_value
        from modules.unified_0dte_account import (
            apply_unified_0dte_capital_to_system,
            compute_unified_0dte_capital_snapshot,
        )

        self._ensure_trendline_buffer_floor()
        try:
            snap = compute_unified_0dte_capital_snapshot(
                self,
                buffer_floor=float(getattr(self, "_trendline_buffer_reserve_floor", 0.0) or 0.0),
                get_config_value=get_config_value,
            )
            apply_unified_0dte_capital_to_system(self, snap)
            if getattr(self, "_0dte_orb_batch_capital_locked", False):
                self._0dte_orb_batch_capital_snapshotted = True
            log.info(
                "0DTE_PIPELINE | stage=slot_cap_refresh | source=unified_0dte_account | "
                "equity_basis=%.2f | cash_balance=%.2f | reserved_capital=%.2f | buffer_reserve=%.2f | "
                "buffer_floor=%.2f | available_cash=%.2f | tradable_equity=%.2f | allocation_pct=%.1f | "
                "slot_count=%d | slot_capital=%.2f | entry_budget=%.2f",
                float(snap.get("equity_basis", 0.0)),
                float(snap.get("cash_balance", 0.0)),
                float(snap.get("reserved_open_entry_cost", 0.0)),
                float(snap.get("buffer_reserve", 0.0)),
                float(snap.get("buffer_reserve_floor", 0.0)),
                float(snap.get("available_cash", 0.0)),
                float(snap.get("tradable_equity", 0.0)),
                float(snap.get("allocation_pct", 0.0)),
                int(snap.get("slot_count", 1)),
                float(snap.get("slot_capital", 0.0)),
                float(snap.get("entry_budget", 0.0)),
            )
        except Exception as slot_refresh_err:
            log.warning(
                "0DTE_PIPELINE | stage=slot_cap_refresh | error=%s",
                slot_refresh_err,
            )

    # Back-compat name used by Trendline pipeline call sites.
    _refresh_trendline_slot_capital = _refresh_0dte_slot_capital

    def _log_trendline_fast_monitor_metrics(self) -> None:
        m = getattr(self, "_trendline_fast_monitor_metrics", None) or {}
        premium_sources = m.get("premium_sources", {})
        log.info(
            "TRENDLINE_PIPELINE | stage=fast_monitor_metrics | ticks=%s | equity_batches=%s | chain_calls=%s | "
            "chain_cache_hits=%s | chain_cache_misses=%s | premium_sources=%s",
            m.get("ticks", 0),
            m.get("equity_batches", 0),
            m.get("chain_calls", 0),
            m.get("chain_cache_hits", 0),
            m.get("chain_cache_misses", 0),
            premium_sources,
        )


    def _0dte_position_monitor_interval_sec(self) -> float:
        """Single 0DTE open-position monitor cadence for ORB + Trendline (default 2s)."""
        try:
            from modules.dte0_exit_monitor_config import resolve_0dte_position_monitor_interval_sec

            return float(resolve_0dte_position_monitor_interval_sec())
        except Exception:
            return float(getattr(self, "_orb_0dte_fast_monitor_interval_sec", 2.0) or 2.0)

    def _compute_dynamic_options_monitor_interval(
        self,
        *,
        base_interval_sec: float,
        active_symbols: int,
        dynamic_enabled: bool,
    ) -> float:
        """Adaptive options monitor interval by active symbol count."""
        base = max(1.0, float(base_interval_sec or 5.0))
        if not dynamic_enabled:
            return base
        count = int(max(0, active_symbols))
        if count <= 5:
            return base
        if count <= 10:
            return base + 2.0
        if count <= 15:
            return base + 5.0
        return base + 8.0

    def _record_option_chain_latency(self, latency_ms: float, source: str = "unknown") -> None:
        """Record one chain call latency sample and update adaptive backoff state."""
        try:
            v = float(latency_ms)
        except (TypeError, ValueError):
            return
        if v <= 0:
            return
        self._options_chain_latency_ms_window.append(v)
        if not self._options_chain_latency_ms_window:
            return
        avg_ms = float(sum(self._options_chain_latency_ms_window) / len(self._options_chain_latency_ms_window))
        self._options_chain_latency_avg_ms = avg_ms

        status = _option_chain_latency_status(avg_ms)
        log.info(
            "OPTION_LATENCY_STATUS | avg_latency=%.1f | status=%s | source=%s",
            avg_ms,
            status,
            str(source or "unknown"),
        )

        current_extra = float(getattr(self, "_options_latency_backoff_extra_sec", 0.0) or 0.0)
        target_extra = current_extra
        if avg_ms > _orb_0dte_chain_latency_warning_ms():
            target_extra = 3.0
        elif avg_ms < _orb_0dte_chain_latency_good_ms() and current_extra > 0.0:
            # Gradual recovery when API latency normalizes.
            target_extra = max(0.0, current_extra - 1.0)
        if abs(target_extra - current_extra) > 1e-9:
            self._options_latency_backoff_extra_sec = target_extra
            log.warning(
                "OPTION_LATENCY_BACKOFF | avg_latency=%.1f | new_interval=%.1f",
                avg_ms,
                float(target_extra),
            )

        current_level = int(getattr(self, "_options_latency_symbol_backoff_level", 0) or 0)
        target_level = current_level
        if avg_ms > _orb_0dte_chain_latency_critical_ms():
            target_level = 2
        elif avg_ms < _orb_0dte_chain_latency_good_ms() and current_level > 0:
            # Gradually restore monitored symbol breadth.
            target_level = current_level - 1
        if target_level != current_level:
            self._options_latency_symbol_backoff_level = target_level

        reduced_now = bool(int(getattr(self, "_options_latency_symbol_backoff_level", 0) or 0) > 0)
        reduced_prev = bool(getattr(self, "_options_latency_symbol_reduced", False))
        if reduced_now and not reduced_prev:
            log.warning("OPTION_SYMBOL_BACKOFF | symbols_reduced=true")
        elif (not reduced_now) and reduced_prev:
            log.info("OPTION_SYMBOL_BACKOFF | symbols_reduced=false")
        self._options_latency_symbol_reduced = reduced_now

    def _effective_symbol_monitor_cap(self, active_symbols: int) -> int:
        """Return effective symbol cap under latency backoff."""
        total = int(max(0, active_symbols))
        level = int(getattr(self, "_options_latency_symbol_backoff_level", 0) or 0)
        if total <= 1 or level <= 0:
            return total
        ratio = 0.85 if level == 1 else 0.70
        cap = int(max(1, round(float(total) * ratio)))
        # Ensure reduction is meaningful when possible.
        if cap >= total:
            cap = total - 1
        return max(1, cap)

    def _record_option_api_usage(
        self,
        *,
        chain_calls: int = 0,
        quote_calls: int = 0,
        symbols_active: int = 0,
    ) -> None:
        """Track minute API usage and enforce hard cap throttling."""
        now = time.time()
        start = float(getattr(self, "_option_api_usage_window_start_ts", now) or now)
        if now - start >= 60.0:
            chain_total = int(getattr(self, "_option_api_usage_chain_calls", 0) or 0)
            quote_total = int(getattr(self, "_option_api_usage_quote_calls", 0) or 0)
            symbols_max = int(getattr(self, "_option_api_usage_symbols_active_max", 0) or 0)
            estimated_calls_per_min = int((chain_total * 2) + quote_total)
            try:
                from modules.option_api_accounting import snapshot_usage

                real_snap = snapshot_usage(self)
                real_total = int(real_snap.get("real_broker_total") or 0)
            except Exception:
                real_snap = {}
                real_total = estimated_calls_per_min
            log.info(
                "OPTION_API_USAGE | chain_calls=%d | quote_calls=%d | symbols_active=%d | "
                "estimated_calls_per_min=%d | real_broker_total=%d | accounted_total=%d",
                chain_total,
                quote_total,
                symbols_max,
                estimated_calls_per_min,
                real_total,
                int(real_snap.get("accounted_total") or real_total),
            )
            hard_cap = int(getattr(self, "_option_api_hard_cap_per_min", 140) or 140)
            cap_basis = real_total
            if cap_basis > hard_cap:
                self._options_api_hard_cap_extra_sec = max(
                    3.0,
                    float(getattr(self, "_options_api_hard_cap_extra_sec", 0.0) or 0.0) + 3.0,
                )
                self._options_latency_symbol_backoff_level = max(
                    1,
                    int(getattr(self, "_options_latency_symbol_backoff_level", 0) or 0),
                )
                log.warning(
                    "OPTION_API_HARD_CAP | calls_per_min=%d | action=throttle | basis=real_broker_total",
                    cap_basis,
                )
            elif float(getattr(self, "_options_api_hard_cap_extra_sec", 0.0) or 0.0) > 0.0:
                self._options_api_hard_cap_extra_sec = max(
                    0.0,
                    float(getattr(self, "_options_api_hard_cap_extra_sec", 0.0) or 0.0) - 1.0,
                )
            self._option_api_usage_window_start_ts = now
            self._option_api_usage_chain_calls = 0
            self._option_api_usage_quote_calls = 0
            self._option_api_usage_symbols_active_max = 0

        self._option_api_usage_chain_calls = int(getattr(self, "_option_api_usage_chain_calls", 0) or 0) + int(
            max(0, chain_calls)
        )
        # Oct 13 2026: live chains count toward the 140/min real-call hard cap
        # (one E*TRADE chain = CHAIN_FETCH_REAL_CALLS_PER_CHAIN real calls).
        if int(chain_calls or 0) > 0:
            try:
                from central_tech.chain_fetch_manager import chain_calls_count_toward_cap, real_calls_per_chain
                from modules.option_api_accounting import record_real_broker_request

                if chain_calls_count_toward_cap():
                    record_real_broker_request(
                        self, lane="chain", count=int(round(int(chain_calls) * real_calls_per_chain()))
                    )
            except Exception:
                pass
        self._option_api_usage_quote_calls = int(getattr(self, "_option_api_usage_quote_calls", 0) or 0) + int(
            max(0, quote_calls)
        )
        self._option_api_usage_symbols_active_max = max(
            int(getattr(self, "_option_api_usage_symbols_active_max", 0) or 0),
            int(max(0, symbols_active)),
        )

    def _is_trendline_breakout_confirmed(self, pos: Any) -> bool:
        """Trendline option-chain access guard: confirmed breakout or post-fill book row.

        Pre-execution callers may require explicit breakout flags. Open positions created by
        ``TrendlineOptionsExecutor`` carry ``execution_payload`` / ``normalized_options`` but
        historically omitted ``breakout_confirmed``; without live quotes the stealth engine
        cannot trail or exit intraday.
        """
        try:
            md = getattr(pos, "metadata", {})
            if not isinstance(md, dict):
                return False
            ep = md.get("execution_payload")
            if isinstance(ep, dict) and (
                ep.get("expiry_ymd")
                or ep.get("expiration_ymd")
                or ep.get("expiry")
            ):
                return True
            norm = md.get("normalized_options")
            if isinstance(norm, dict):
                legs = norm.get("legs")
                if isinstance(legs, list) and len(legs) > 0:
                    return True
            for block_key in ("execution_payload", "signal_snapshot", "breakout_event"):
                block = md.get(block_key)
                if not isinstance(block, dict):
                    continue
                for key in (
                    "breakout_confirmed",
                    "close_break_confirmed",
                    "break_confirmed",
                    "is_breakout_confirmed",
                    "confirmed",
                ):
                    raw = block.get(key)
                    if isinstance(raw, bool):
                        return bool(raw)
                    if isinstance(raw, str) and raw.strip().lower() in ("true", "1", "yes", "y"):
                        return True
                if str(block.get("breakout_state", "") or "").strip().lower() in (
                    "confirmed",
                    "close_break_confirmed",
                ):
                    return True
        except Exception:
            return False
        return False

    def _position_priority_score(self, pos: Any) -> float:
        """Best-effort priority score for monitor backoff sorting."""
        try:
            md = getattr(pos, "metadata", {}) if isinstance(getattr(pos, "metadata", {}), dict) else {}
            candidates: List[float] = []
            for block_key in ("normalized_options", "signal_snapshot", "execution_payload"):
                block = md.get(block_key) if isinstance(md, dict) else {}
                if isinstance(block, dict):
                    raw = block.get("priority_score")
                    if isinstance(raw, (int, float)):
                        candidates.append(float(raw))
                    rank_raw = block.get("rank")
                    if isinstance(rank_raw, (int, float)) and float(rank_raw) > 0:
                        # Lower rank number => higher priority.
                        candidates.append(1000.0 - float(rank_raw))
            return max(candidates) if candidates else 0.0
        except Exception:
            return 0.0

    def _position_confidence_score(self, pos: Any) -> float:
        """Best-effort confidence score for monitor backoff sorting."""
        try:
            candidates: List[float] = []
            attr_conf = getattr(pos, "confidence", None)
            if isinstance(attr_conf, (int, float)):
                candidates.append(float(attr_conf))
            md = getattr(pos, "metadata", {}) if isinstance(getattr(pos, "metadata", {}), dict) else {}
            for block_key in ("normalized_options", "signal_snapshot", "execution_payload"):
                block = md.get(block_key) if isinstance(md, dict) else {}
                if not isinstance(block, dict):
                    continue
                for key in ("confidence_score", "confidence", "eligibility_score"):
                    raw = block.get(key)
                    if isinstance(raw, (int, float)):
                        candidates.append(float(raw))
            return max(candidates) if candidates else 0.0
        except Exception:
            return 0.0

    def _position_current_pnl_pct(self, pos: Any) -> float:
        """Best-effort current pnl_pct for monitor backoff sorting."""
        try:
            md = getattr(pos, "metadata", {}) if isinstance(getattr(pos, "metadata", {}), dict) else {}
            perf = md.get("exit_performance") if isinstance(md, dict) else {}
            if isinstance(perf, dict):
                raw = perf.get("current_pnl_pct")
                if isinstance(raw, (int, float)):
                    return float(raw)
            entry_price = float(getattr(pos, "entry_price", 0.0) or 0.0)
            current_value = float(getattr(pos, "current_price", 0.0) or 0.0)
            if entry_price > 0.0 and current_value > 0.0:
                position_type = str(getattr(pos, "position_type", "") or "").lower()
                is_credit = position_type == "credit_spread"
                return (
                    (entry_price - current_value) / entry_price
                    if is_credit
                    else (current_value - entry_price) / entry_price
                )
        except Exception:
            pass
        return 0.0

    def _position_backoff_sort_tuple(self, pos: Any) -> Tuple[int, int, float, float, float]:
        """
        Sort by future potential first, then current pnl as tie-breaker.

        Ranking tuple:
        (
            is_high_confidence,  # confidence >= 85
            is_strong_winner,    # pnl_pct >= 0.10
            confidence_score,
            priority_score,
            pnl_pct,
        )
        """
        pnl_pct = float(self._position_current_pnl_pct(pos))
        confidence_raw = float(self._position_confidence_score(pos))
        # Confidence may be stored as 0-1 or 0-100; normalize threshold logic to percentage.
        confidence_pct = confidence_raw * 100.0 if confidence_raw <= 1.0 else confidence_raw
        is_high_confidence = 1 if confidence_pct >= 85.0 else 0
        is_strong_winner = 1 if pnl_pct >= 0.10 else 0
        return (
            int(is_high_confidence),
            int(is_strong_winner),
            float(confidence_raw),
            float(self._position_priority_score(pos)),
            float(pnl_pct),
        )

    async def _maybe_run_trendline_fast_monitor(self, current_time: float) -> None:
        if not self._enable_trendline_strategy:
            return
        # When unified is enabled, main_loop owns maybe_tick — do not call it again.
        try:
            from modules.dte0_exit_monitor_config import resolve_exit_monitor_config

            if resolve_exit_monitor_config().unified_monitor_enabled:
                return
        except Exception:
            pass
        # Legacy scheduler body (only when unified disabled / import failure fallback).
        active_positions = self._trendline_unified_open_positions()
        if not active_positions:
            from modules.unified_0dte_monitor_registry import count_pending_monitor_for_strategy

            pending_n = count_pending_monitor_for_strategy(
                getattr(self, "_0dte_pending_monitor_registrations", None),
                strategy_substring="trendline",
            )
            if pending_n > 0:
                log.warning(
                    "TRENDLINE_PIPELINE | stage=fast_monitor_skip | reason=no_open_positions | pending_monitor=%d",
                    pending_n,
                )
            else:
                log.info("TRENDLINE_PIPELINE | stage=fast_monitor_skip | reason=no_open_positions")
            return

        from modules.unified_0dte_monitor_registry import (
            collect_stale_0dte_trade_ids,
            log_0dte_monitor_stale,
        )

        stale_sec = float(getattr(self, "_0dte_monitor_stale_force_sec", 45.0) or 45.0)
        stale_ids = collect_stale_0dte_trade_ids(
            active_ids=list(active_positions.keys()),
            lifecycle_by_id=getattr(self, "_trendline_lifecycle", {}) or {},
            first_seen=getattr(self, "_0dte_position_first_seen_ts", {}) or {},
            now_ts=float(current_time),
            stale_sec=stale_sec,
        )
        if stale_ids:
            log_0dte_monitor_stale(
                strategy_type="trendline_0dte",
                open_count=len(active_positions),
                stale_ids=stale_ids,
                stale_sec=stale_sec,
            )
            self._trendline_immediate_monitor_requested = True

        active_symbols = len(
            {
                str(getattr(p, "symbol", "") or "").strip().upper()
                for p in active_positions.values()
                if str(getattr(p, "symbol", "") or "").strip()
            }
        )
        interval_sec = self._compute_dynamic_options_monitor_interval(
            base_interval_sec=float(self._0dte_position_monitor_interval_sec()),
            active_symbols=active_symbols,
            dynamic_enabled=False,
        )
        interval_sec = max(
            1.0,
            float(interval_sec)
            + float(getattr(self, "_options_latency_backoff_extra_sec", 0.0) or 0.0)
            + float(getattr(self, "_options_api_hard_cap_extra_sec", 0.0) or 0.0),
        )
        immediate = bool(getattr(self, "_trendline_immediate_monitor_requested", False))
        if immediate:
            self._trendline_immediate_monitor_requested = False
        elif current_time - float(getattr(self, "_trendline_last_fast_monitor_ts", 0.0)) < interval_sec:
            return
        self._trendline_last_fast_monitor_ts = current_time

        open_positions = len(active_positions)
        _ftl_now = time.time()
        _ftl_sec = min(30.0, float(getattr(self, "_options_monitor_summary_sec", 180.0) or 180.0))
        if _ftl_now - float(getattr(self, "_tl_fast_monitor_tick_log_ts", 0.0) or 0.0) >= _ftl_sec:
            self._tl_fast_monitor_tick_log_ts = _ftl_now
            log.info(
                "OPTION_MONITOR_THROTTLE | strategy=trendline | active_symbols=%d | interval_used=%.1f",
                int(active_symbols),
                float(interval_sec),
            )
            log.info(
                "TRENDLINE_PIPELINE | stage=fast_monitor_tick | book=tl_only | open_positions=%d",
                open_positions,
            )
        from modules.unified_0dte_position_monitor import canonical_monitor_tick_id

        await self.monitor_0dte_options_positions(
            trigger_source="fast_loop_trendline",
            shared_chain_cache={},
            tick_id=canonical_monitor_tick_id(now=current_time),
        )
        self._maybe_log_options_monitor_summary(current_time)

    def _trendline_exec_alert_base_row(self, signal: Any, candidate: Any) -> Dict[str, Any]:
        """Shared Telegram row fields for Trendline execution success/failure alerts."""
        meta = signal.metadata if isinstance(getattr(signal, "metadata", None), dict) else {}
        eng = getattr(self, "trendline_signal_engine", None)
        trade_id = str(meta.get("trade_id") or "")
        if not trade_id and eng is not None:
            try:
                trade_id = str(eng._trade_id(candidate))
            except Exception:
                trade_id = f"{getattr(signal, 'symbol', 'UNKNOWN')}_unknown"
        direction = getattr(signal, "direction", None)
        if direction is not None and hasattr(direction, "value"):
            line_geom = str(direction.value).upper()
        else:
            line_geom = str(meta.get("line_geometry") or "n/a").upper()
        setup = getattr(candidate, "setup_payload", None) if candidate is not None else None
        if not isinstance(setup, dict):
            setup = {}
        nested = meta.get("setup_payload") if isinstance(meta.get("setup_payload"), dict) else {}
        slot_raw = (
            meta.get("trendline_slot")
            or nested.get("trendline_slot")
            or setup.get("trendline_slot")
            or "trendline1"
        )
        try:
            from easyTrendline.trendline_models import normalize_trendline_slot

            trendline_slot = normalize_trendline_slot(slot_raw)
        except Exception:
            trendline_slot = "trendline1"
        return {
            "symbol": str(getattr(signal, "symbol", "") or "UNKNOWN"),
            "setup_type": str(meta.get("setup_type") or "n/a"),
            "structure_display_label": str(meta.get("structure_display_label") or ""),
            "trigger_direction": str(meta.get("trigger_direction") or "n/a"),
            "line_geometry": line_geom,
            "option_side": str(getattr(signal, "option_side", "") or "").upper(),
            "trade_id": trade_id,
            "entry_mode": str(meta.get("entry_mode") or getattr(candidate, "entry_mode", "") or ""),
            "trendline_slot": trendline_slot,
        }

    @staticmethod
    def _trendline_order_payload_health(order_payload: Any) -> Dict[str, Any]:
        """Map executor order_payload fields into Trendline execution alert health context."""
        pl = order_payload if isinstance(order_payload, dict) else {}
        if not pl:
            return {}
        out: Dict[str, Any] = {}
        chain = pl.get("chain_source") or pl.get("chain_source_used")
        if chain:
            out["chain_source"] = str(chain)
        src = pl.get("source")
        if src:
            out["contract_source"] = str(src)
        rej = pl.get("reject_reason")
        if rej:
            out["reject_reason"] = str(rej)
        for key in (
            "estimated_contract_cost",
            "slot_capital_target",
            "entry_budget",
            "available_cash",
            "premium_per_share",
        ):
            if pl.get(key) is not None:
                out[key] = pl.get(key)
        er = pl.get("execution_risk")
        if isinstance(er, dict):
            out["execution_risk"] = er
        sel_delta = pl.get("selected_delta")
        if sel_delta is not None:
            try:
                out["selected_delta"] = float(sel_delta)
            except (TypeError, ValueError):
                pass
        for key in ("spread_pct", "open_interest", "volume", "bid_ask_spread_pct"):
            if pl.get(key) is not None:
                out[key if key != "bid_ask_spread_pct" else "spread_pct"] = pl.get(key)
        audit = pl.get("selector_audit")
        if isinstance(audit, dict):
            rr = audit.get("reject_reason")
            if rr and "reject_reason" not in out:
                out["reject_reason"] = str(rr)
        return out

    def _trendline_build_exec_failure_row(
        self,
        signal: Any,
        candidate: Any,
        *,
        stage: str,
        reason: str,
    ) -> Dict[str, Any]:
        row = self._trendline_exec_alert_base_row(signal, candidate)
        row["status"] = "failed"
        row["failure_stage"] = str(stage or "execution")
        reason_s = str(reason or "unknown")[:500]
        row["failure_reason"] = reason_s
        row["failure_reason_code"] = reason_s.split("|")[0].strip() or "unknown"
        if str(stage or "").strip() in _TRENDLINE_EXECUTION_REJECT_ALERT_STAGES:
            row["execution_attempted"] = True
        return row

    async def _send_trendline_emit_execution_alert(
        self,
        *,
        mode_label: str,
        executed_row: Optional[Dict[str, Any]] = None,
        failed_row: Optional[Dict[str, Any]] = None,
    ) -> None:
        """One Telegram when Trendline opens a position — filled or execution rejected."""
        if not self.alert_manager:
            log.warning(
                "TRENDLINE_PIPELINE | stage=execution_alert_dispatch | action=skip | reason=no_alert_manager",
            )
            return
        if failed_row and not _trendline_failed_row_may_send_execution_alert(failed_row):
            sym = str((failed_row or {}).get("symbol") or "?")
            log.info(
                "TRENDLINE_PIPELINE | stage=execution_alert_suppressed | symbol=%s | "
                "reason=execution_alert_gate | stage=%s | execution_attempted=%s",
                sym,
                str((failed_row or {}).get("failure_stage") or ""),
                str(bool((failed_row or {}).get("execution_attempted"))).lower(),
            )
            failed_row = None
        if not executed_row and not failed_row:
            return
        if executed_row:
            _fill_tid = self._execution_alert_trade_id(executed_row)
            if _fill_tid and self._fill_execution_telegram_already_sent(_fill_tid):
                log.info(
                    "TRENDLINE_PIPELINE | stage=execution_alert_dispatch | action=skip | "
                    "reason=already_sent | symbol=%s | filled=true",
                    str(executed_row.get("symbol") or "?"),
                )
                return
        try:
            sent = await self.alert_manager.send_trendline_options_execution_alert(
                executed_rows=[executed_row] if executed_row else [],
                failed_rows=[failed_row] if failed_row else [],
                mode=mode_label,
                single_emit=True,
            )
            if sent and executed_row:
                _fill_tid = self._execution_alert_trade_id(executed_row)
                if _fill_tid:
                    await self._on_fill_execution_telegram_sent(_fill_tid)
            if not sent:
                sym = str(
                    ((executed_row or failed_row) or {}).get("symbol") or "?"
                )
                log.warning(
                    "TRENDLINE_PIPELINE | stage=execution_alert_dispatch | action=failed | "
                    "symbol=%s | filled=%s | reason=telegram_send_false",
                    sym,
                    str(bool(executed_row)).lower(),
                )
        except Exception as trendline_exec_alert_err:
            log.warning(
                "TRENDLINE_PIPELINE | stage=execution_alert_dispatch | action=error | error=%s",
                trendline_exec_alert_err,
            )

    async def _flush_pending_trendline_quality_reject_alerts(self) -> int:
        """Queue hard quality / reclaim Reject Telegrams without blocking the watch loop."""
        pending = getattr(self, "_pending_trendline_quality_reject_alerts", None)
        if not isinstance(pending, list) or not pending:
            return 0
        self._pending_trendline_quality_reject_alerts = []
        from modules.runtime_mode import mode_label as runtime_mode_label

        mode_label = runtime_mode_label()
        rows = list(pending)
        n = len(rows)

        async def _bg_flush() -> None:
            sent_n = 0
            for row in rows:
                try:
                    await self._send_trendline_emit_execution_alert(
                        mode_label=mode_label,
                        failed_row=row,
                    )
                    sent_n += 1
                except Exception as flush_err:
                    log.debug(
                        "TRENDLINE_PIPELINE | stage=quality_reject_alert_flush | symbol=%s | error=%s",
                        (row or {}).get("symbol"),
                        flush_err,
                    )
            log.info(
                "TRENDLINE_PIPELINE | stage=quality_reject_alert_flush | action=done | "
                "queued=%d | attempted=%d",
                n,
                sent_n,
            )

        try:
            existing = getattr(self, "_tl_quality_reject_flush_task", None)
            if existing is not None and not existing.done():
                # Chain after in-flight flush so nothing is dropped.
                async def _chain() -> None:
                    try:
                        await existing
                    except Exception:
                        pass
                    await _bg_flush()

                self._tl_quality_reject_flush_task = asyncio.create_task(
                    _chain(), name="tl_quality_reject_tg_flush"
                )
            else:
                self._tl_quality_reject_flush_task = asyncio.create_task(
                    _bg_flush(), name="tl_quality_reject_tg_flush"
                )
        except Exception as schedule_err:
            log.debug(
                "TRENDLINE_PIPELINE | stage=quality_reject_alert_flush | action=schedule_failed | error=%s",
                schedule_err,
            )
            # Fallback: still attempt inline if task create fails.
            await _bg_flush()
        return n

    async def _send_trendline_single_execution_alert(self, row: Dict[str, Any], mode_label: str) -> None:
        """Send single Trendline execution through dedicated Telegram formatter."""
        await self._send_trendline_emit_execution_alert(
            mode_label=mode_label,
            executed_row=row,
        )

    async def _send_trendline_group_execution_alert(
        self,
        executed_rows: List[Dict[str, Any]],
        mode_label: str,
    ) -> None:
        """Send grouped Trendline execution through dedicated Telegram formatter."""
        if not self.alert_manager or not executed_rows:
            return
        await self.alert_manager.send_trendline_options_execution_alert(
            executed_rows=executed_rows,
            mode=mode_label,
        )

    def _trendline_mode_label_for_cap(self) -> str:
        from modules.runtime_mode import mode_label as runtime_mode_label

        return runtime_mode_label().lower()

    def _trendline_daily_cap_prefix(self) -> str:
        from zoneinfo import ZoneInfo

        today_pt = datetime.now(ZoneInfo("America/Los_Angeles")).date().isoformat()
        from modules.runtime_mode import gcs_namespaced_coord_prefix

        namespace = gcs_namespaced_coord_prefix(
            str(
                getattr(self, "_trendline_global_daily_cap_namespace", "trendline_daily_cap")
                or "trendline_daily_cap"
            )
        )
        return f"{namespace}/{today_pt}/{self._trendline_mode_label_for_cap()}"

    def _apply_trendline_open_caps_from_config(self) -> None:
        """Load slot/open caps from Account0DTE.env / Trendline0DTE.env.

        Freeze-skip and mid-session restarts must apply these — never a hardcoded 10.
        """
        try:
            from modules.config_loader import get_config_value
            from modules.unified_0dte_account import (
                trendline_0dte_max_positions,
                unified_0dte_slot_count,
                unified_trading_capital_pct,
            )

            slot_count = max(1, int(unified_0dte_slot_count(get_config_value)))
            max_open = max(1, int(trendline_0dte_max_positions(get_config_value)))
            alloc_pct = float(unified_trading_capital_pct(get_config_value))
            prev = int(getattr(self, "_trendline_max_open_positions", 0) or 0)
            self._trendline_slot_count = slot_count
            self._trendline_max_open_positions = max_open
            self._trendline_account_allocation_pct = max(0.0, min(100.0, alloc_pct))
            if prev and prev != max_open:
                log.warning(
                    "TRENDLINE_PIPELINE | stage=open_caps | action=applied_from_config | "
                    "was_max_open=%d | now_max_open=%d | slot_count=%d",
                    prev,
                    max_open,
                    slot_count,
                )
        except Exception as cap_err:
            log.warning(
                "TRENDLINE_PIPELINE | stage=open_caps | action=config_load_failed | error=%s",
                cap_err,
            )

    def _trendline_open_cap(self) -> int:
        """Live Trendline/GCS open cap from config — never a hardcoded 10."""
        n = int(getattr(self, "_trendline_max_open_positions", 0) or 0)
        if n <= 0:
            self._apply_trendline_open_caps_from_config()
            n = int(getattr(self, "_trendline_max_open_positions", 0) or 0)
        if n <= 0:
            from modules.unified_0dte_account import trendline_0dte_max_positions

            n = int(trendline_0dte_max_positions())
        return max(1, n)

    def _trendline_try_claim_global_daily_slot(
        self, signal_symbol: str, local_open: Optional[int] = None
    ) -> Tuple[bool, Optional[str]]:
        """
        Claim one global Trendline daily slot across Cloud Run instances.

        Uses create-if-absent semantics (`if_generation_match=0`) on per-slot objects.

        Fast path (TRENDLINE_GLOBAL_DAILY_CAP_FAST_PATH, default true): when the in-process
        Trendline open count (``local_open``, restored from the executor ledger on restart)
        already meets the cap, reject without any GCS call; otherwise probe slots starting at
        ``local_open + 1`` and wrap around, so every slot is still tried once. Markers in GCS
        remain the cross-instance / restart source of truth.
        """
        try:
            self._apply_trendline_open_caps_from_config()
            if not bool(getattr(self, "_trendline_global_daily_cap_enabled", True)):
                return True, None
            from modules.gcs_persistence import get_gcs_persistence

            gcs = get_gcs_persistence()
            bucket = getattr(gcs, "bucket", None)
            if not getattr(gcs, "enabled", False) or bucket is None:
                # Fail open: preserve existing single-instance behavior if GCS unavailable.
                return (True, None) if bool(getattr(self, "_trendline_global_daily_cap_fail_open", True)) else (False, None)

            cap = int(self._trendline_open_cap())
            prefix = self._trendline_daily_cap_prefix()
            payload = (
                f"{datetime.utcnow().isoformat()}|symbol={signal_symbol}|instance={os.getenv('K_REVISION', 'local')}"
            )
            slot_order = list(range(1, cap + 1))
            fast_path = str(os.getenv("TRENDLINE_GLOBAL_DAILY_CAP_FAST_PATH", "true")).strip().lower() in (
                "1", "true", "yes", "on"
            )
            if fast_path and local_open is not None:
                try:
                    lo = max(0, int(local_open))
                except (TypeError, ValueError):
                    lo = 0
                if cap > 0 and lo >= cap:
                    log.info(
                        "TRENDLINE_PIPELINE | stage=global_cap_fast_reject | symbol=%s | local_open=%d | cap=%d",
                        signal_symbol,
                        lo,
                        cap,
                    )
                    return False, None
                start = lo % cap if cap > 0 else 0
                slot_order = slot_order[start:] + slot_order[:start]
            for slot_num in slot_order:
                marker_path = f"{prefix}/slot_{slot_num:02d}.txt"
                blob = bucket.blob(marker_path)
                try:
                    blob.upload_from_string(payload, if_generation_match=0)
                    log.info(
                        "TRENDLINE_PIPELINE | stage=global_cap_slot_claimed | symbol=%s | slot=%d/%d | marker=%s",
                        signal_symbol,
                        slot_num,
                        cap,
                        marker_path,
                    )
                    return True, marker_path
                except Exception as slot_err:
                    # Precondition failed => slot already claimed by another instance.
                    if "conditionNotMet" in str(slot_err) or "412" in str(slot_err):
                        continue
                    log.warning(
                        "TRENDLINE_PIPELINE | stage=global_cap_claim_error | symbol=%s | slot=%d | error=%s",
                        signal_symbol,
                        slot_num,
                        slot_err,
                    )
                    return (True, None) if bool(getattr(self, "_trendline_global_daily_cap_fail_open", True)) else (False, None)
            return False, None
        except Exception as e:
            log.warning(
                "TRENDLINE_PIPELINE | stage=global_cap_claim_fallback | symbol=%s | error=%s",
                signal_symbol,
                e,
            )
            return (True, None) if bool(getattr(self, "_trendline_global_daily_cap_fail_open", True)) else (False, None)

    def _trendline_release_global_daily_slot(self, marker_path: str) -> None:
        """Release a previously claimed global slot if the trade did not execute."""
        if not marker_path:
            return
        try:
            from modules.gcs_persistence import get_gcs_persistence

            gcs = get_gcs_persistence()
            if getattr(gcs, "enabled", False):
                gcs.delete_file(marker_path)
                log.info(
                    "TRENDLINE_PIPELINE | stage=global_cap_slot_released | marker=%s",
                    marker_path,
                )
        except Exception as e:
            log.warning(
                "TRENDLINE_PIPELINE | stage=global_cap_release_error | marker=%s | error=%s",
                marker_path,
                e,
            )

    def _trendline_try_claim_global_monitor_alert_slot(
        self,
        mode_label: str,
        monitor_interval_sec: int,
    ) -> bool:
        """
        Allow only one Trendline monitor alert per interval across instances.

        Uses per-bucket create-if-absent marker objects in GCS.
        """
        try:
            if not bool(getattr(self, "_trendline_monitor_alert_global_dedup_enabled", True)):
                return True

            from modules.gcs_persistence import get_gcs_persistence
            from zoneinfo import ZoneInfo

            gcs = get_gcs_persistence()
            bucket = getattr(gcs, "bucket", None)
            if not getattr(gcs, "enabled", False) or bucket is None:
                return bool(getattr(self, "_trendline_monitor_alert_global_dedup_fail_open", True))

            now_pt = datetime.now(ZoneInfo("America/Los_Angeles"))
            date_pt = now_pt.date().isoformat()
            interval = max(1, int(monitor_interval_sec))
            bucket_id = int(time.time()) // interval
            from modules.runtime_mode import gcs_namespaced_coord_prefix

            ns = gcs_namespaced_coord_prefix(
                str(
                    getattr(
                        self,
                        "_trendline_monitor_alert_global_dedup_namespace",
                        "trendline_monitor_alerts",
                    )
                    or "trendline_monitor_alerts"
                )
            )
            marker_path = f"{ns}/{date_pt}/{str(mode_label).lower()}/bucket_{bucket_id}.txt"
            payload = f"{datetime.utcnow().isoformat()}|instance={os.getenv('K_REVISION', 'local')}"
            blob = bucket.blob(marker_path)
            blob.upload_from_string(payload, if_generation_match=0)
            return True
        except Exception as e:
            if "conditionNotMet" in str(e) or "412" in str(e):
                return False
            log.warning(
                "TRENDLINE_PIPELINE | stage=monitor_global_dedup_error | error=%s",
                e,
            )
            return bool(getattr(self, "_trendline_monitor_alert_global_dedup_fail_open", True))

    async def _orb_fetch_market_data(self, symbol: str) -> Dict[str, Any]:
        """Shared market-data adapter for ORB1 Breakout monitor loops.

        Cache-only. evaluate() must never initiate a broker equity get_quote.
        """
        from modules.option_api_accounting import record_monitor_lookup
        from modules.underlying_freshness import (
            note_observation_stat,
            resolve_underlying_observation,
        )

        obs = resolve_underlying_observation(self, symbol)
        record_monitor_lookup(self, cache_hit=obs.usable)
        note_observation_stat(self, obs)
        px = obs.price_or_zero
        return {
            "current_price": px,
            "current_value": 0.0,
            "vwap": None,
            "bid_ask_spread_pct": 0.01,
            "momentum": 0.0,
            "underlying_observation": obs,
        }

    async def _maybe_run_orb_0dte_fast_monitor(self, current_time: float) -> None:
        """Fast monitor loop for OPEN ORB1 Breakout options positions."""
        if not getattr(self, "dte0_manager", None) or not getattr(self.dte0_manager, "options_executor", None):
            return
        # When unified is enabled, main_loop owns maybe_tick — do not call it again.
        try:
            from modules.dte0_exit_monitor_config import resolve_exit_monitor_config

            if resolve_exit_monitor_config().unified_monitor_enabled:
                return
        except Exception:
            pass
        # Legacy scheduler body (only when unified disabled / import failure fallback).
        active_map = self._orb_unified_open_positions()
        if not active_map:
            return

        from modules.unified_0dte_monitor_registry import (
            collect_stale_0dte_trade_ids,
            log_0dte_monitor_stale,
        )

        stale_sec = float(getattr(self, "_0dte_monitor_stale_force_sec", 45.0) or 45.0)
        stale_ids = collect_stale_0dte_trade_ids(
            active_ids=list(active_map.keys()),
            lifecycle_by_id=getattr(self, "_orb_0dte_lifecycle", {}) or {},
            first_seen=getattr(self, "_0dte_position_first_seen_ts", {}) or {},
            now_ts=float(current_time),
            stale_sec=stale_sec,
        )
        if stale_ids:
            log_0dte_monitor_stale(
                strategy_type="orb_0dte",
                open_count=len(active_map),
                stale_ids=stale_ids,
                stale_sec=stale_sec,
            )
            # Force cycle by clearing last-ts gate below.
            self._orb_0dte_last_fast_monitor_ts = 0.0

        open_positions = list(active_map.values())
        active_symbols = len(
            {
                str(getattr(p, "symbol", "") or "").strip().upper()
                for p in open_positions
                if str(getattr(p, "symbol", "") or "").strip()
            }
        )
        interval_sec = self._compute_dynamic_options_monitor_interval(
            base_interval_sec=float(self._0dte_position_monitor_interval_sec()),
            active_symbols=active_symbols,
            dynamic_enabled=False,
        )
        interval_sec = max(
            1.0,
            float(interval_sec)
            + float(getattr(self, "_options_latency_backoff_extra_sec", 0.0) or 0.0)
            + float(getattr(self, "_options_api_hard_cap_extra_sec", 0.0) or 0.0),
        )
        if current_time - float(getattr(self, "_orb_0dte_last_fast_monitor_ts", 0.0)) < float(interval_sec):
            return
        last_completed = float(getattr(self, "_orb_0dte_last_monitor_cycle_completed_ts", 0.0) or 0.0)
        if last_completed > 0 and (current_time - last_completed) < (float(interval_sec) * 0.85):
            self._orb_log_monitor_latency_audit(
                expected_interval=float(interval_sec),
                actual_interval=float(current_time - last_completed),
                delay_reason="recent_cycle_dedup",
                active_position_count=len(open_positions),
                quote_requests_in_flight=int(getattr(self, "_orb_0dte_chain_requests_in_flight", 0) or 0),
                trigger_source="fast_loop_orb",
            )
            return
        actual_interval = (
            float(current_time - last_completed) if last_completed > 0 else float(interval_sec)
        )
        delay_reason = "on_schedule"
        if actual_interval > float(interval_sec) * 1.5:
            delay_reason = "scheduler_backlog"
        self._orb_log_monitor_latency_audit(
            expected_interval=float(interval_sec),
            actual_interval=actual_interval,
            delay_reason=delay_reason,
            active_position_count=len(open_positions),
            quote_requests_in_flight=int(getattr(self, "_orb_0dte_chain_requests_in_flight", 0) or 0),
            trigger_source="fast_loop_orb_start",
        )

        self._orb_0dte_fast_monitor_metrics["ticks"] = int(
            self._orb_0dte_fast_monitor_metrics.get("ticks", 0)
        ) + 1
        self._orb_0dte_fast_monitor_metrics["price_refresh_calls"] = int(
            self._orb_0dte_fast_monitor_metrics.get("price_refresh_calls", 0)
        ) + 1
        self._record_option_api_usage(
            chain_calls=int(active_symbols),
            quote_calls=0,
            symbols_active=int(active_symbols),
        )
        _fo_now = time.time()
        _fo_sec = min(30.0, float(getattr(self, "_options_monitor_summary_sec", 180.0) or 180.0))
        if _fo_now - float(getattr(self, "_orb_fast_monitor_tick_log_ts", 0.0) or 0.0) >= _fo_sec:
            self._orb_fast_monitor_tick_log_ts = _fo_now
            log.info(
                "OPTION_MONITOR_THROTTLE | strategy=orb | active_symbols=%d | interval_used=%.1f",
                int(active_symbols),
                float(interval_sec),
            )
            log.info(
                "OPTIONS_STEALTH | stage=orb_fast_monitor_tick | book=orb_only | "
                "interval_sec=%.1f | open_positions=%d",
                float(interval_sec),
                len(open_positions),
            )
        try:
            from modules.unified_0dte_position_monitor import canonical_monitor_tick_id

            shared_tick_id = canonical_monitor_tick_id(now=current_time)
            self._orb_0dte_fast_monitor_metrics["monitor_calls"] = int(
                self._orb_0dte_fast_monitor_metrics.get("monitor_calls", 0)
            ) + 1
            await self.monitor_0dte_options_positions(
                trigger_source="fast_loop_orb",
                shared_chain_cache={},
                tick_id=shared_tick_id,
            )
            self._orb_0dte_last_fast_monitor_ts = current_time
            cycle_end = time.time()
            self._orb_log_monitor_latency_audit(
                expected_interval=float(interval_sec),
                actual_interval=float(cycle_end - last_completed) if last_completed > 0 else float(interval_sec),
                delay_reason="cycle_complete",
                active_position_count=len(open_positions),
                quote_requests_in_flight=int(getattr(self, "_orb_0dte_chain_requests_in_flight", 0) or 0),
                trigger_source="fast_loop_orb_complete",
            )
        except Exception:
            self._orb_0dte_fast_monitor_metrics["errors"] = int(
                self._orb_0dte_fast_monitor_metrics.get("errors", 0)
            ) + 1
            raise
        if int(self._orb_0dte_fast_monitor_metrics.get("ticks", 0)) % 12 == 0:
            log.info(
                "OPTIONS_STEALTH | stage=orb_fast_monitor_metrics | ticks=%s | price_refresh_calls=%s | "
                "monitor_calls=%s | errors=%s",
                self._orb_0dte_fast_monitor_metrics.get("ticks", 0),
                self._orb_0dte_fast_monitor_metrics.get("price_refresh_calls", 0),
                self._orb_0dte_fast_monitor_metrics.get("monitor_calls", 0),
                self._orb_0dte_fast_monitor_metrics.get("errors", 0),
            )

    async def monitor_0dte_options_positions(
        self,
        trigger_source: str = "shared_loop",
        shared_chain_cache: Optional[Dict[Tuple[str, str, str], Dict[str, Any]]] = None,
        tick_id: Optional[str] = None,
        force_refresh_symbols: Optional[Set[str]] = None,
        exact_contract_quotes: Optional[Dict[str, Dict[str, Any]]] = None,
        sync_already_done: bool = False,
        ownership_gate_dispatch: bool = False,
    ) -> None:
        """Unified monitor for ORB1 Breakout + Trendline 0DTE options."""
        _hdr_now = time.time()
        _hdr_sec = min(30.0, float(getattr(self, "_options_monitor_summary_sec", 180.0) or 180.0))
        if _hdr_now - float(getattr(self, "_unified_monitor_header_log_ts", 0.0) or 0.0) >= _hdr_sec:
            self._unified_monitor_header_log_ts = _hdr_now
            log.info("OPTIONS_STEALTH_MONITOR | trigger=%s", trigger_source)
        cache: Dict[Tuple[str, str, str], Dict[str, Any]] = (
            shared_chain_cache if isinstance(shared_chain_cache, dict) else {}
        )
        from modules.unified_0dte_position_monitor import canonical_monitor_tick_id

        tick_key = canonical_monitor_tick_id(tick_id)
        dte0_manager = getattr(self, "dte0_manager", None)
        options_executor = getattr(dte0_manager, "options_executor", None) if dte0_manager else None
        if exact_contract_quotes:
            self._unified_0dte_exact_quotes = dict(exact_contract_quotes)
        self._unified_0dte_ownership_gate_dispatch = bool(ownership_gate_dispatch)

        # Live P0: broker sync BEFORE premium / exit evaluation — but do NOT skip evaluation
        # on transient sync failure (ownership gates dispatch only).
        if (
            options_executor is not None
            and not getattr(options_executor, "demo_mode", True)
            and not sync_already_done
        ):
            try:
                from modules.broker_position_synchronizer import (
                    get_or_create_synchronizer,
                    should_skip_normal_exits_for_stale_registry,
                )

                sync = get_or_create_synchronizer(self)
                sync_result = await sync.synchronize()
                log.info(
                    "BROKER_POSITION_SYNC | stage=pre_monitor | trigger=%s | pass=%s | repairs=%d | remaining=%d | stale=%s",
                    trigger_source,
                    str(bool(sync_result.pass_ok)).lower(),
                    len(sync_result.repairs),
                    len(sync_result.mismatches_remaining),
                    str(bool(sync_result.registry_stale or sync_result.sync_unavailable)).lower(),
                )
                if sync_result.sync_unavailable or should_skip_normal_exits_for_stale_registry(self):
                    self._unified_0dte_ownership_gate_dispatch = True
                    log.error(
                        "BROKER_POSITION_SYNC | stage=pre_monitor | ownership_gate_dispatch=true | "
                        "evaluate_exits=true | reason=%s | streak=%s",
                        sync_result.reason,
                        getattr(self, "_broker_sync_fail_streak", 0),
                    )
                    # Previously returned here — that erased breached exits. Now evaluate + latch.
                else:
                    self._unified_0dte_ownership_gate_dispatch = False
                    # Ownership restored — clear per-position gates so latched exits can dispatch.
                    try:
                        from modules.exit_latch import clear_ownership_gate

                        for _p in options_executor.get_open_positions() or []:
                            clear_ownership_gate(_p)
                    except Exception:
                        pass
                    # Previously returned here — that erased breached exits. Now evaluate + latch.
            except Exception as sync_err:
                log.warning("BROKER_POSITION_SYNC | stage=pre_monitor_failed | error=%s", sync_err)
                self._broker_registry_stale = True
                self._broker_sync_fail_streak = int(
                    getattr(self, "_broker_sync_fail_streak", 0) or 0
                ) + 1
                self._unified_0dte_ownership_gate_dispatch = True
                log.error(
                    "BROKER_POSITION_SYNC | stage=pre_monitor | ownership_gate_dispatch=true | reason=exception"
                )

        open_orb_positions = (
            options_executor.get_open_positions() or [] if options_executor is not None else []
        )
        # force_refresh_symbols semantics (see resolve_force_refresh_underlyings):
        #   None / empty set / non-empty set
        from modules.unified_0dte_position_monitor import resolve_force_refresh_underlyings

        open_syms = {
            str(getattr(p, "symbol", "") or "").upper()
            for p in (open_orb_positions or [])
            if str(getattr(p, "symbol", "") or "").strip()
        }
        force_set, exact_complete_no_bridge, full_chain_n = resolve_force_refresh_underlyings(
            force_refresh_symbols, open_syms
        )
        counts = getattr(self, "_unified_0dte_eval_counts", None)
        if not isinstance(counts, dict):
            counts = {}
            self._unified_0dte_eval_counts = counts
        counts["full_chain_requests"] = int(full_chain_n)
        if open_orb_positions and options_executor is not None:
            if hasattr(options_executor, "chain_latency_callback"):
                options_executor.chain_latency_callback = self._record_option_chain_latency
            if force_set:
                await self._orb_hydrate_chain_cache_for_monitor(
                    open_orb_positions,
                    cache,
                    tick_key,
                    force_refresh_symbols=force_set,
                )
                log.info(
                    "ORB_0DTE_MONITOR_CHAIN_HYDRATED | trigger=%s | book=executor_all | "
                    "open_positions=%d | "
                    "cache_symbols=%d | force_refresh=%d | exact_complete_no_bridge=%s",
                    trigger_source,
                    len(open_orb_positions),
                    len(cache),
                    len(force_set),
                    str(exact_complete_no_bridge).lower(),
                )
            else:
                log.info(
                    "ORB_0DTE_MONITOR_CHAIN_HYDRATE_SKIPPED | trigger=%s | book=executor_all | "
                    "open_positions=%d | "
                    "reason=%s | full_chain_requests=0",
                    trigger_source,
                    len(open_orb_positions),
                    "exact_quotes_complete" if exact_complete_no_bridge else "no_open_underlyings",
                )
            # Inject exact-contract quotes into position metadata before PE update
            exact_map = getattr(self, "_unified_0dte_exact_quotes", None) or {}
            if isinstance(exact_map, dict) and exact_map:
                for pos in open_orb_positions:
                    pid = str(getattr(pos, "position_id", "") or "")
                    oq = exact_map.get(pid)
                    if isinstance(oq, dict) and oq.get("bid") is not None:
                        meta = getattr(pos, "metadata", None)
                        if not isinstance(meta, dict):
                            try:
                                pos.metadata = {}
                                meta = pos.metadata
                            except Exception:
                                continue
                        meta["exact_quote"] = oq
                        meta["option_quote"] = oq
            await options_executor.update_positions_with_real_prices(
                shared_chain_cache=cache,
                tick_id=tick_key,
            )
        t_phase = time.monotonic()
        try:
            from modules.owned_eval_scheduler import run_fair_owned_eval_tick

            await run_fair_owned_eval_tick(
                self, tick_id=tick_key, trigger_source=str(trigger_source or "")
            )
        except Exception as fair_err:
            log.warning("OWNED_FAIR_EVAL_TICK_SKIP | tick_id=%s | err=%s", tick_key, fair_err)
        fair_ms = max(0.0, (time.monotonic() - t_phase) * 1000.0)
        t_phase = time.monotonic()
        await self._monitor_orb_0dte_positions_with_stealth(
            self._orb_fetch_market_data,
            trigger_source=trigger_source,
            shared_chain_cache=cache,
            tick_id=tick_key,
        )
        orb_ms = max(0.0, (time.monotonic() - t_phase) * 1000.0)
        t_phase = time.monotonic()
        await self._monitor_trendline_positions(
            trigger_source=trigger_source,
            shared_chain_cache=cache,
            tick_id=tick_key,
            force_refresh_symbols=force_refresh_symbols,
        )
        tl_ms = max(0.0, (time.monotonic() - t_phase) * 1000.0)
        log.info(
            "0DTE_MONITOR_PHASE_MS | tick_id=%s | fair_ms=%.1f | orb_ms=%.1f | tl_ms=%.1f",
            tick_key,
            fair_ms,
            orb_ms,
            tl_ms,
        )
        if options_executor is not None and not getattr(options_executor, "demo_mode", True):
            try:
                from modules.broker_position_synchronizer import get_or_create_synchronizer

                # Step 10: synchronize again after close attempts within this tick.
                sync = get_or_create_synchronizer(self)
                post = await sync.synchronize()
                log.info(
                    "BROKER_POSITION_SYNC | stage=post_monitor | trigger=%s | pass=%s | repairs=%d",
                    trigger_source,
                    str(bool(post.pass_ok)).lower(),
                    len(post.repairs),
                )
            except Exception as orphan_err:
                log.warning("BROKER_POSITION_SYNC | stage=post_monitor_failed | error=%s", orphan_err)
    async def _run_emergency_close_check(self, reason: str = "unknown") -> None:
        """Fallback-only emergency close check when stealth monitor fails."""
        log.error("OPTIONS_STEALTH_FAILSAFE | reason=%s", reason)
        if getattr(self, "dte0_manager", None) and getattr(self.dte0_manager, "options_executor", None):
            stale_signals = await self.dte0_manager.options_executor.monitor_positions(
                market_data_provider=None,
                orb_data_provider=None,
            )
            for sig in stale_signals:
                await self.dte0_manager.options_executor.execute_exit(sig, exit_reason_override=f"failsafe:{reason}")

    def _ensure_options_stealth_engine(self):
        """Lazy-init shared 0DTE options stealth (ORB + Trendline use one engine + config loader)."""
        eng = getattr(self, "orb_options_stealth", None) or getattr(self, "trendline_options_stealth", None)
        if eng is not None:
            self.orb_options_stealth = eng
            self.trendline_options_stealth = eng
            try:
                eng._system = self
            except Exception:
                pass
            return eng
        from modules.config_loader import get_config_value
        from .prime_options_stealth_trailing_tp import (
            TrendlineOptionsStealthEngine,
            load_option_stealth_config,
        )

        eng = TrendlineOptionsStealthEngine(load_option_stealth_config(get_config_value))
        try:
            eng._system = self
        except Exception:
            pass
        self.orb_options_stealth = eng
        self.trendline_options_stealth = eng
        try:
            from modules.exit_decision_dispatch import stealth_evaluate_api_enabled

            evaluate_api = bool(stealth_evaluate_api_enabled())
        except Exception:
            evaluate_api = True
        log.info(
            "0DTE_OPTIONS_STEALTH | initialized=true | stage=monitor_lazy | "
            "shared_instance=true | OPTION_STEALTH_USE_EVALUATE_API=%s | "
            "premium_engine=true",
            str(evaluate_api).lower(),
        )
        return eng

    def _ensure_trendline_options_stealth_engine(self):
        """Lazy-init Trendline options stealth (shared instance with ORB monitor)."""
        return self._ensure_options_stealth_engine()

    def _ensure_orb_options_stealth_engine(self):
        """Lazy-init ORB1 Breakout options stealth (shared instance with Trendline monitor)."""
        return self._ensure_options_stealth_engine()

    def _ensure_premium_snapshot_for_exit(
        self,
        pos: Any,
        *,
        option_quote: Optional[Dict[str, Any]] = None,
        now: Optional[Any] = None,
    ) -> Any:
        """Prefer registry premium_snapshot; else rebuild via Premium Engine + sync patch."""
        from modules.exit_decision_dispatch import load_premium_snapshot_from_position
        from modules.position_registry_contract import QuoteContext, PremiumEvaluationRequest
        from modules.premium_engine import evaluate as premium_evaluate
        from modules.broker_position_synchronizer import get_or_create_synchronizer
        from datetime import datetime, timezone

        snap = load_premium_snapshot_from_position(pos)
        if snap is not None and getattr(snap, "executable_exit_price", None) is not None:
            return snap

        oq = option_quote if isinstance(option_quote, dict) else {}
        md = getattr(pos, "metadata", None)
        if not isinstance(md, dict):
            md = {}
            try:
                pos.metadata = md
            except Exception:
                pass
        ptype = str(getattr(pos, "position_type", "") or "lotto").lower()
        strike = None
        otype = None
        lc = getattr(pos, "lotto_contract", None)
        if lc is not None:
            try:
                strike = float(getattr(lc, "strike", 0.0) or 0.0) or None
                otype = str(getattr(lc, "option_type", "") or "").lower() or None
            except Exception:
                pass
        evaluated_at = now if isinstance(now, datetime) else datetime.now(timezone.utc)
        if getattr(evaluated_at, "tzinfo", None) is None:
            evaluated_at = evaluated_at.replace(tzinfo=timezone.utc)
        ctx = QuoteContext(
            option_quote=oq,
            target_strike=strike,
            option_type=otype,
            position_type=ptype if ptype else "lotto",
        )
        try:
            snap, patch = premium_evaluate(
                PremiumEvaluationRequest(
                    position=pos,
                    quote_context=ctx,
                    evaluated_at=evaluated_at,
                )
            )
            sync = get_or_create_synchronizer(self)
            dte0 = getattr(self, "dte0_manager", None)
            executor = getattr(dte0, "options_executor", None) if dte0 else None
            if executor is not None:
                apply_result = sync.apply_premium_state_update(executor, snap, patch)
                if not getattr(apply_result, "applied", False):
                    log.error(
                        "PREMIUM_STATE_APPLY_FAILED | trade_id=%s | reason=%s",
                        getattr(pos, "position_id", ""),
                        getattr(apply_result, "reason", "unknown"),
                    )
                    # Do not fall back to a second economics path; return best snap
                    # for this tick only when PE computed it, but record the failure.
            return snap
        except Exception as err:
            log.warning(
                "PREMIUM_ENGINE | ensure_snapshot_failed | trade_id=%s | error=%s",
                getattr(pos, "position_id", ""),
                err,
            )
            return load_premium_snapshot_from_position(pos)

    def _schedule_po_snapshot_persist(
        self,
        pos: Any,
        position_metadata: Dict[str, Any],
        current_underlying: float,
        premium: Any = None,
    ) -> None:
        """Write 20p and lifecycle snapshots off the exit-check loop.

        The exit decision and the flight-recorder row stay on the monitor tick.
        A GCS snapshot for one name must not hold the next name's exit check.
        """
        import threading

        def _run() -> None:
            try:
                from modules.po_lifecycle_snapshots import maybe_persist_lifecycle_snapshots
                from modules.po_mfe20_snapshot import maybe_persist_po_20p_snapshot

                maybe_persist_po_20p_snapshot(
                    self, pos, position_metadata, current_underlying, premium
                )
                maybe_persist_lifecycle_snapshots(
                    self, pos, position_metadata, current_underlying, premium
                )
            except Exception as exc:
                log.debug(
                    "PO_SNAP_OFF_EVAL | trade_id=%s | err=%s",
                    getattr(pos, "position_id", ""),
                    exc,
                )

        threading.Thread(target=_run, name="po-snap-off-eval", daemon=False).start()

    def _0dte_run_stealth_exit_decision(
        self,
        *,
        stealth: Any,
        pos: Any,
        position_metadata: Dict[str, Any],
        current_underlying: float,
        now: Any,
        option_quote: Optional[Dict[str, Any]] = None,
        policy: Any = None,
        monitor_tick_id: str = "",
    ) -> Optional[Tuple[float, str, Dict[str, Any]]]:
        """Cutover: stealth.evaluate(premium) → dispatch; optional shadow compare."""
        from modules.exit_decision_dispatch import (
            compare_exit_decisions,
            dispatch_exit_decision,
            run_legacy_process_position_shadow,
            stealth_evaluate_api_enabled,
            stealth_evaluate_shadow_enabled,
        )

        pos_id = str(getattr(pos, "position_id", "") or "")
        symbol = str(getattr(pos, "symbol", "") or "")
        from modules.owned_tick_observe import (
            _unified_tick_id,
            count_path_v2_eval,
            reuse_owned_tick_eval,
        )

        tick = _unified_tick_id(self, monitor_tick_id)
        reused, cached_out = reuse_owned_tick_eval(
            position_metadata if isinstance(position_metadata, dict) else getattr(pos, "metadata", None),
            tick,
        )
        if reused:
            log.info(
                "PATH_V2_EVAL_DUP_BLOCKED | trade_id=%s | tick_id=%s | grep=PATH_V2_EVAL_DUP_BLOCKED",
                pos_id,
                tick,
            )
            return cached_out

        # Evaluate reads pos.metadata; keep monitor dict as the same object.
        if isinstance(position_metadata, dict):
            try:
                cur_md = getattr(pos, "metadata", None)
                if cur_md is not position_metadata:
                    if isinstance(cur_md, dict) and cur_md:
                        # Prefer monitor dict but retain any keys only on pos.
                        for _k, _v in cur_md.items():
                            position_metadata.setdefault(_k, _v)
                    pos.metadata = position_metadata
            except Exception:
                pass

        # Refresh cache-only session tech before PATH_V2 evaluates. This makes
        # 20% Save read a timestamped current-session PVE on its first eligible
        # bid tick; it does not perform an owned-loop quote or Yahoo request.
        try:
            osnap_pre = (
                position_metadata.get("option_stealth")
                if isinstance(position_metadata, dict)
                else None
            )
            if not isinstance(osnap_pre, dict):
                osnap_pre = {}
                if isinstance(position_metadata, dict):
                    position_metadata["option_stealth"] = osnap_pre
            self._maybe_sparse_refresh_path_session_tech(
                osnap=osnap_pre,
                symbol=str(symbol or ""),
                underlying_price=float(current_underlying or 0.0),
                position=pos,
                tick_id=str(
                    monitor_tick_id
                    or getattr(self, "_unified_0dte_monitor_tick_id", "")
                    or getattr(self, "_unified_0dte_tick_id", "")
                    or ""
                ),
                trade_id=pos_id,
            )
            cached = None
            if isinstance(position_metadata, dict) and isinstance(
                position_metadata.get("path_session_tech"), dict
            ):
                cached = position_metadata.get("path_session_tech")
            if not isinstance(cached, dict):
                by_sym = getattr(self, "_path_session_tech_by_symbol", None)
                if isinstance(by_sym, dict):
                    cached = by_sym.get(str(symbol or "").strip().upper())
            if isinstance(cached, dict):
                from profit_optimizer.path_chain_skew import overlay_live_session_tech

                overlay_live_session_tech(osnap_pre, cached)
            self._seed_osnap_path_chain_skew(
                osnap=osnap_pre,
                symbol=str(symbol or ""),
                option_side=str(
                    getattr(pos, "option_side", None)
                    or (position_metadata.get("option_side") if isinstance(position_metadata, dict) else "")
                    or ""
                ),
                position=pos,
            )
            self._freeze_contract_fade_entry_breadth(
                osnap=osnap_pre,
                position_metadata=position_metadata if isinstance(position_metadata, dict) else {},
                symbol=str(symbol or ""),
                option_side=str(
                    getattr(pos, "option_side", None)
                    or (position_metadata.get("option_side") if isinstance(position_metadata, dict) else "")
                    or ""
                ),
                trade_id=pos_id,
                position=pos,
            )
        except Exception as tech_pre_exc:
            log.debug(
                "STEALTH_PRE_EVAL_SESSION_TECH_SKIP | trade_id=%s | err=%s",
                pos_id,
                tech_pre_exc,
            )

        def _write_eval_row(out, decision=None):
            try:
                from modules.owned_tick_observe import record_path_v2_eval_row

                md = position_metadata if isinstance(position_metadata, dict) else {}
                osnap = md.get("option_stealth") if isinstance(md.get("option_stealth"), dict) else {}
                record_path_v2_eval_row(
                    self,
                    trade_id=pos_id,
                    position=pos,
                    option_quote=option_quote,
                    osnap=osnap,
                    monitor_tick_id=tick,
                    out=out,
                    eval_now=now,
                    decision=decision,
                )
            except Exception as rec_exc:
                log.debug("PATH_V2_EVAL_RECORD_SKIP | trade_id=%s | err=%s", pos_id, rec_exc)

        if not stealth_evaluate_api_enabled():
            legacy_decision = stealth.process_position(
                pos_id,
                position_symbol=symbol,
                position_metadata=position_metadata,
                current_underlying=current_underlying,
                now=now,
                option_quote=option_quote,
            )
            try:
                from modules.po_mfe20_snapshot import capture_po_20p_from_metadata

                capture_po_20p_from_metadata(self, pos, position_metadata, now_utc=now)
            except Exception as exc:
                log.warning("PATH_V2_POST_EVAL_20P_SKIP | trade_id=%s | err=%s", pos_id, exc)
            try:
                self._schedule_po_snapshot_persist(
                    pos, position_metadata, current_underlying
                )
            except Exception as exc:
                log.warning("PATH_V2_POST_EVAL_PERSIST_SKIP | trade_id=%s | err=%s", pos_id, exc)
            count_path_v2_eval(self, pos_id, tick_id=tick, eval_now=now)
            _write_eval_row(legacy_decision)
            return legacy_decision

        premium = self._ensure_premium_snapshot_for_exit(
            pos, option_quote=option_quote, now=now
        )
        if premium is None:
            log.warning(
                "STEALTH_EVALUATE | missing_premium_snapshot | trade_id=%s | falling_back_legacy",
                pos_id,
            )
            legacy_decision = stealth.process_position(
                pos_id,
                position_symbol=symbol,
                position_metadata=position_metadata,
                current_underlying=current_underlying,
                now=now,
                option_quote=option_quote,
            )
            try:
                from modules.po_mfe20_snapshot import capture_po_20p_from_metadata

                capture_po_20p_from_metadata(self, pos, position_metadata, now_utc=now)
            except Exception as exc:
                log.warning("PATH_V2_POST_EVAL_20P_SKIP | trade_id=%s | err=%s", pos_id, exc)
            try:
                self._schedule_po_snapshot_persist(
                    pos, position_metadata, current_underlying
                )
            except Exception as exc:
                log.warning("PATH_V2_POST_EVAL_PERSIST_SKIP | trade_id=%s | err=%s", pos_id, exc)
            count_path_v2_eval(self, pos_id, tick_id=tick, eval_now=now)
            _write_eval_row(legacy_decision)
            return legacy_decision

        decision = stealth.evaluate(
            position=pos,
            premium=premium,
            policy=policy,
            now=now,
            current_underlying=float(current_underlying or 0.0),
        )

        # Authoritative exit-evaluation cadence (evaluate completion, not scheduler wake).
        try:
            from modules.unified_0dte_position_monitor import get_unified_0dte_position_monitor

            mon = get_unified_0dte_position_monitor(self)
            tel = getattr(mon, "last_telemetry", None)
            mon.record_exit_evaluation(
                pos_id,
                quote_wait_ms=float(getattr(tel, "quote_refresh_wait_ms", 0.0) or 0.0) if tel else 0.0,
                monitor_runtime_ms=float(getattr(tel, "monitor_runtime_ms", 0.0) or 0.0) if tel else 0.0,
                decision_runtime_ms=0.0,
                total_cycle_ms=float(getattr(tel, "total_cycle_ms", 0.0) or 0.0) if tel else 0.0,
                meta=position_metadata if isinstance(position_metadata, dict) else None,
            )
        except Exception:
            pass

        if stealth_evaluate_shadow_enabled():
            try:
                legacy_out = run_legacy_process_position_shadow(
                    stealth,
                    position_id=pos_id,
                    position_symbol=symbol,
                    position_metadata=position_metadata,
                    current_underlying=current_underlying,
                    now=now,
                    option_quote=option_quote,
                )
                compare_exit_decisions(
                    trade_id=pos_id,
                    symbol=symbol,
                    decision=decision,
                    legacy_out=legacy_out,
                )
            except Exception as exc:
                log.warning("PATH_V2_POST_EVAL_SHADOW_SKIP | trade_id=%s | err=%s", pos_id, exc)

        try:
            from modules.po_mfe20_snapshot import capture_po_20p_from_metadata

            capture_po_20p_from_metadata(self, pos, position_metadata, now_utc=now)
        except Exception as exc:
            log.warning("PATH_V2_POST_EVAL_20P_SKIP | trade_id=%s | err=%s", pos_id, exc)
        try:
            self._schedule_po_snapshot_persist(
                pos, position_metadata, current_underlying, premium
            )
        except Exception as exc:
            log.warning("PATH_V2_POST_EVAL_PERSIST_SKIP | trade_id=%s | err=%s", pos_id, exc)
        try:
            dispatched = dispatch_exit_decision(decision)
        except Exception as exc:
            log.warning(
                "PATH_V2_POST_EVAL_DISPATCH_SKIP | trade_id=%s | err=%s",
                pos_id,
                exc,
            )
            dispatched = None
        tel = getattr(decision, "diagnostics", None) or getattr(decision, "telemetry", None)
        age_s = tel.get("age_seconds") if isinstance(tel, dict) else None
        count_path_v2_eval(self, pos_id, tick_id=tick, eval_now=now, eval_age_s=age_s)
        _write_eval_row(dispatched, decision=decision)
        return dispatched

    def _register_trendline_stealth_if_missing(
        self,
        stealth: Any,
        pos: Any,
        meta: Dict[str, Any],
        current_underlying: float,
    ) -> bool:
        """Register option_stealth on monitor tick when fill-time registration was skipped."""
        osnap_existing = meta.get("option_stealth")
        if isinstance(osnap_existing, dict) and osnap_existing:
            engine = osnap_existing.get("engine")
            if isinstance(engine, dict):
                from .prime_options_stealth_trailing_tp import (
                    OptionStealthState,
                    coerce_option_stealth_engine_state,
                )

                raw_state = engine.get("state")
                if isinstance(raw_state, OptionStealthState):
                    return True
                if coerce_option_stealth_engine_state(engine, osnap_existing) is not None:
                    return True
                # Corrupted engine.state — fall through to full re-register.
        from easy0DTE.modules.options_execution_normalize import validate_normalized_options_for_stealth

        pid = str(getattr(pos, "position_id", "") or "").strip()
        if not pid or stealth is None:
            return False
        norm_tl = meta.get("normalized_options") if isinstance(meta.get("normalized_options"), dict) else None
        snap = meta.get("signal_snapshot") if isinstance(meta.get("signal_snapshot"), dict) else {}
        pl = meta.get("execution_payload") if isinstance(meta.get("execution_payload"), dict) else {}
        sig_meta = snap if snap else {}
        norm_ok, norm_miss = (
            validate_normalized_options_for_stealth(norm_tl)
            if isinstance(norm_tl, dict)
            else (False, ["normalized_options_absent"])
        )
        trendline_d = pl.get("trendline_for_exit") if isinstance(pl.get("trendline_for_exit"), dict) else {}
        if not trendline_d:
            for bk in ("breakout_event", "break_event"):
                be = snap.get(bk) or pl.get(bk) or meta.get(bk)
                if isinstance(be, dict):
                    trendline_d = {"break_event": be}
                    break
        line_geometry = str(
            snap.get("line_geometry")
            or pl.get("line_geometry")
            or snap.get("direction")
            or getattr(pos, "line_geometry", "")
            or getattr(pos, "direction", "")
            or "unknown"
        )
        if norm_ok and isinstance(norm_tl, dict):
            legs_tl = [dict(x) for x in norm_tl["legs"] if isinstance(x, dict)]
            expiry_tl = str(norm_tl.get("expiration_ymd") or "")
            und_tl = str(norm_tl.get("underlying_symbol") or getattr(pos, "symbol", "") or "")
            setup_tl = str(norm_tl.get("setup_type") or sig_meta.get("setup_type") or pl.get("setup_type") or "")
            trig_tl = str(norm_tl.get("trigger_direction") or sig_meta.get("trigger_direction") or pl.get("trigger_direction") or "")
            src_tl = str(norm_tl.get("source_path") or "trendline_0dte")
            pos_type_tl = str(norm_tl.get("position_type") or "")
            if pos_type_tl not in ("single_leg_long_call", "single_leg_long_put"):
                pos_type_tl = (
                    "single_leg_long_put"
                    if str(getattr(pos, "option_side", "") or "").lower() == "put"
                    else "single_leg_long_call"
                )
            entry_val_tl = float(norm_tl.get("entry_value") or pl.get("estimated_contract_price") or 0.0)
            entry_debit_tl = float(norm_tl["entry_debit"]) if norm_tl.get("entry_debit") is not None else entry_val_tl
            entry_credit_tl = float(norm_tl["entry_credit"]) if norm_tl.get("entry_credit") is not None else None
            fl0 = legs_tl[0] if legs_tl else {}
            strike_tl = float(fl0.get("strike") or pl.get("strike") or 0.0)
            delta_tl = float(fl0.get("delta_at_entry") or norm_tl.get("delta_at_entry") or pl.get("delta_at_entry") or 0.25)
            option_side_tl = str(fl0.get("option_side") or getattr(pos, "option_side", "") or "call")
        else:
            if isinstance(norm_tl, dict):
                log.info(
                    "OPTIONS_STEALTH | stage=normalized_metadata_invalid | trade_id=%s | missing=%s",
                    pid,
                    ",".join(norm_miss) if norm_miss else "unknown",
                )
            log.info(
                "OPTIONS_STEALTH | stage=legacy_metadata_fallback | trade_id=%s | reason=%s",
                pid,
                "validation_failed" if isinstance(norm_tl, dict) else "normalized_options_absent_or_invalid",
            )
            expiry_tl = str(pl.get("expiry_ymd") or pl.get("expiration_ymd") or snap.get("expiry_ymd") or "")
            und_tl = str(pl.get("underlying_symbol") or snap.get("underlying_symbol") or getattr(pos, "symbol", "") or "")
            setup_tl = str(sig_meta.get("setup_type") or pl.get("setup_type") or "")
            trig_tl = str(sig_meta.get("trigger_direction") or pl.get("trigger_direction") or "")
            src_tl = "trendline_0dte"
            pos_type_tl = (
                "single_leg_long_put"
                if str(getattr(pos, "option_side", "") or "").lower() == "put"
                else "single_leg_long_call"
            )
            legs_tl = [
                {
                    "leg_id": f"{und_tl}_{expiry_tl}_{pl.get('strike')}_{getattr(pos, 'option_side', 'call')}",
                    "long_or_short": "long",
                    "option_side": str(getattr(pos, "option_side", "call")).lower(),
                    "strike": float(pl.get("strike", 0.0) or snap.get("strike", 0.0) or 0.0),
                    "quantity": int(max(1, int(pl.get("quantity", 1) or 1))),
                    "entry_price": float(pl.get("estimated_contract_price", 0.0) or snap.get("entry_premium", 0.0) or 0.0),
                    "delta_at_entry": float(pl.get("delta_at_entry", 0.0) or snap.get("delta_at_entry", 0.0) or 0.0),
                }
            ]
            entry_val_tl = float(
                getattr(pos, "entry_price", 0.0)
                or pl.get("estimated_contract_price", 0.0)
                or snap.get("entry_premium", 0.0)
                or 0.0
            )
            entry_debit_tl = entry_val_tl
            entry_credit_tl = None
            strike_tl = float(pl.get("strike", 0.0) or snap.get("strike", 0.0) or 0.0)
            delta_tl = float(pl.get("delta_at_entry", 0.25) or snap.get("delta_at_entry", 0.25) or 0.25)
            option_side_tl = str(getattr(pos, "option_side", "call") or "call")
        try:
            underlying_entry = float(
                pl.get("entry_underlying_price")
                or snap.get("entry_underlying_price")
                or current_underlying
                or 0.0
            )
        except (TypeError, ValueError):
            underlying_entry = float(current_underlying or 0.0)
        stealth.register_on_open(
            pid,
            entry_premium_per_contract=entry_val_tl,
            underlying_entry=underlying_entry,
            option_side=option_side_tl,
            line_geometry=line_geometry,
            strike=strike_tl,
            delta=delta_tl,
            trendline_dict=trendline_d,
            metadata_target=meta,
            underlying_symbol=und_tl,
            expiration_ymd=expiry_tl,
            setup_type=setup_tl,
            trigger_direction=trig_tl,
            trendline_mode=str(sig_meta.get("trendline_mode") or pl.get("trendline_mode") or "STANDARD"),
            impulse_mode=bool(sig_meta.get("impulse_mode") or pl.get("impulse_mode")),
            early_entry_mode=bool(sig_meta.get("early_entry_mode") or pl.get("early_entry_mode")),
            position_type=pos_type_tl,
            strategy_name=str(pl.get("strategy_name") or norm_tl.get("strategy_name") if isinstance(norm_tl, dict) else "easyTrendline_0dte"),
            strategy_type=str(pl.get("strategy_type") or (norm_tl.get("strategy_type") if isinstance(norm_tl, dict) else None) or "trendline_0dte"),
            entry_value=entry_val_tl,
            entry_debit=entry_debit_tl,
            entry_credit=entry_credit_tl,
            legs=legs_tl,
            structure_invalidation_enabled=True,
            source_path=src_tl,
            break_archetype=str(sig_meta.get("break_archetype") or pl.get("break_archetype") or ""),
        )
        log.info(
            "OPTIONS_STEALTH_REGISTER | symbol=%s | strategy=%s | trade_id=%s | stage=monitor_lazy",
            und_tl or getattr(pos, "symbol", ""),
            "trendline_0dte",
            pid,
        )
        return True

    async def _monitor_trendline_positions(
        self,
        trigger_source: str = "shared_loop",
        shared_chain_cache: Optional[Dict[Tuple[str, str, str], Dict[str, Any]]] = None,
        tick_id: Optional[str] = None,
        force_refresh_symbols: Optional[Set[str]] = None,
    ) -> None:
        """Premium-based stealth trailing for Trendline 0DTE (not ETF-style TP/SL)."""
        expected_interval = float(self._0dte_position_monitor_interval_sec())
        last_completed = float(getattr(self, "_trendline_last_monitor_cycle_completed_ts", 0.0) or 0.0)
        if self._trendline_position_monitor_running:
            log.info(
                "TRENDLINE_PIPELINE | stage=fast_monitor_reentrant_skip | trigger=%s",
                trigger_source,
            )
            return
        async with self._trendline_position_monitor_lock:
            if self._trendline_position_monitor_running:
                log.info(
                    "TRENDLINE_PIPELINE | stage=fast_monitor_reentrant_skip | trigger=%s",
                    trigger_source,
                )
                return
            skip_dup, skip_reason = self._should_skip_duplicate_monitor_cycle(
                strategy="trendline",
                trigger_source=trigger_source,
                tick_id=tick_id,
            )
            if skip_dup:
                counts = getattr(self, "_unified_0dte_eval_counts", None)
                if isinstance(counts, dict):
                    counts["duplicate_same_tick_suppressed"] = int(
                        counts.get("duplicate_same_tick_suppressed") or 0
                    ) + 1
                log.info(
                    "TRENDLINE_PIPELINE | stage=fast_monitor_%s | trigger=%s | tick_id=%s",
                    skip_reason,
                    trigger_source,
                    tick_id,
                )
                return
            self._trendline_position_monitor_running = True
            try:
                active_map = self._trendline_unified_open_positions()
                if not active_map:
                    from modules.unified_0dte_account import _open_positions_from_executor
                    from modules.unified_0dte_monitor_registry import (
                        count_executor_rows_for_strategy,
                        count_pending_monitor_for_strategy,
                        log_0dte_monitor_empty_open_set,
                    )

                    raw_executor_tl = count_executor_rows_for_strategy(
                        _open_positions_from_executor(self),
                        strategy_substring="trendline",
                    )
                    pending_n = count_pending_monitor_for_strategy(
                        getattr(self, "_0dte_pending_monitor_registrations", None),
                        strategy_substring="trendline",
                    )
                    if raw_executor_tl > 0 or pending_n:
                        log_0dte_monitor_empty_open_set(
                            strategy_type="trendline_0dte",
                            trigger_source=trigger_source,
                            executor_rows=raw_executor_tl,
                            pending_monitor=pending_n,
                        )
                    return
                unified_executor_tl = (
                    getattr(getattr(self, "dte0_manager", None), "options_executor", None)
                )
                if unified_executor_tl:
                    self._orb_0dte_purge_stale_demo_registry_entries(unified_executor_tl)
                    self._orb_0dte_maybe_clear_entry_kill_switch(unified_executor_tl)
                raw_positions = list(active_map.values())
                if unified_executor_tl:
                    raw_positions = self._orb_0dte_filter_demo_open_positions(
                        unified_executor_tl, raw_positions
                    )
                    try:
                        if str(trigger_source or "").startswith("unified"):
                            self._offload_ledger_closed_alert_flush(
                                executor=unified_executor_tl
                            )
                        else:
                            await self._flush_pending_ledger_closed_exit_alert_recovery(
                                executor=unified_executor_tl
                            )
                    except Exception as flush_err:
                        log.debug("TL ledger-closed alert flush skipped: %s", flush_err)
                if not raw_positions:
                    from modules.unified_0dte_monitor_registry import (
                        count_pending_monitor_for_strategy,
                        log_0dte_monitor_filtered_empty,
                    )

                    log_0dte_monitor_filtered_empty(
                        strategy_type="trendline_0dte",
                        trigger_source=trigger_source,
                        active_before_filter=len(active_map),
                        pending_monitor=count_pending_monitor_for_strategy(
                            getattr(self, "_0dte_pending_monitor_registrations", None),
                            strategy_substring="trendline",
                        ),
                    )
                    return
                total_symbols = len(
                    {
                        str(getattr(p, "symbol", "") or "").strip().upper()
                        for p in raw_positions
                        if str(getattr(p, "symbol", "") or "").strip()
                    }
                )
                symbol_cap = self._effective_symbol_monitor_cap(total_symbols)
                positions_for_monitor = raw_positions
                if symbol_cap < total_symbols:
                    positions_for_monitor = self._filter_positions_for_option_symbol_monitor_cap(
                        raw_positions,
                        symbol_cap,
                    )
                all_active_trade_ids = {
                    str(getattr(p, "position_id", "") or "").strip()
                    for p in raw_positions
                    if str(getattr(p, "position_id", "") or "").strip()
                }
                trendline_trade_ids = sorted(
                    [
                        str(pid)
                        for pid in (
                            [
                                getattr(p, "position_id", "")
                                for p in positions_for_monitor
                            ]
                        )
                        if str(pid).strip()
                    ]
                )
                log.info(
                    "OPTION_MONITOR_POSITION_LIST | trigger=%s | count=%d | trade_ids=%s",
                    trigger_source,
                    len(trendline_trade_ids),
                    ",".join(trendline_trade_ids) if trendline_trade_ids else "none",
                )
                from modules.unified_0dte_monitor_registry import (
                    resolve_enrollment_failed_sec,
                    sweep_0dte_pending_not_monitored,
                )

                sweep_0dte_pending_not_monitored(
                    pending=self._0dte_pending_monitor_registrations,
                    not_monitored_logged=self._0dte_not_monitored_logged,
                    active_trade_ids=all_active_trade_ids,
                    strategy_substring="trendline",
                    grace_sec=max(
                        5.0,
                        float(self._0dte_position_monitor_interval_sec()) * 1.2,
                    ),
                    failed_sec=resolve_enrollment_failed_sec(self),
                    roster_trade_ids={
                        str(getattr(p, "position_id", "") or "").strip()
                        for p in positions_for_monitor
                        if str(getattr(p, "position_id", "") or "").strip()
                    },
                )

                tick_metrics = {
                    "equity_batches": 0,
                    "chain_calls": 0,
                    "chain_cache_hits": 0,
                    "chain_cache_misses": 0,
                    "premium_sources": defaultdict(int),
                    "positions_processed": 0,
                    "positions_degraded": 0,
                    "positions_with_live_quotes": 0,
                }
                chain_cache: Dict[Tuple[str, str], Dict[str, Any]] = {}
                symbols = sorted({p.symbol for p in positions_for_monitor})
                shared_sc = shared_chain_cache if isinstance(shared_chain_cache, dict) else {}
                counts = getattr(self, "_unified_0dte_eval_counts", None)
                if not isinstance(counts, dict):
                    counts = {}
                    self._unified_0dte_eval_counts = counts
                counts["trendline_positions_collected"] = int(len(positions_for_monitor))
                # Honor unified force_refresh semantics (empty set = no chain hydrate)
                if positions_for_monitor:
                    if force_refresh_symbols is not None:
                        tl_force = {
                            str(s).upper()
                            for s in force_refresh_symbols
                            if str(s or "").strip()
                        }
                        if tl_force:
                            await self._orb_hydrate_chain_cache_for_monitor(
                                positions_for_monitor,
                                shared_sc,
                                str(tick_id or int(time.time())),
                                force_refresh_symbols=tl_force,
                            )
                        else:
                            log.info(
                                "TRENDLINE_PIPELINE | stage=monitor_chain_hydrate_skipped | "
                                "trigger=%s | tick_id=%s | reason=exact_quotes_complete",
                                trigger_source,
                                tick_id,
                            )
                    elif str(trigger_source or "").startswith("unified|"):
                        log.info(
                            "TRENDLINE_PIPELINE | stage=monitor_chain_hydrate_skipped | "
                            "trigger=%s | tick_id=%s | reason=unified_without_force_set",
                            trigger_source,
                            tick_id,
                        )
                    else:
                        await self._orb_hydrate_chain_cache_for_monitor(
                            positions_for_monitor,
                            shared_sc,
                            str(tick_id or int(time.time())),
                            force_refresh_symbols=set(symbols),
                        )
                self._mark_monitor_tick_processed(strategy="trendline", tick_id=tick_id)
                max_tl_option_symbols = int(
                    getattr(self, "_0dte_monitor_max_symbols", None)
                    or getattr(self, "_trendline_max_option_symbols", 10)
                    or 10
                )
                if len(symbols) > max_tl_option_symbols:
                    positions_for_monitor = self._filter_positions_for_option_symbol_monitor_cap(
                        positions_for_monitor,
                        max_tl_option_symbols,
                    )
                    symbols = sorted({p.symbol for p in positions_for_monitor})
                quotes: Dict[str, Any] = {}
                und_cache = getattr(self, "_orb_0dte_last_underlying_by_symbol", None) or {}
                if isinstance(und_cache, dict) and symbols:
                    for s in symbols:
                        key = str(s or "").strip().upper()
                        try:
                            px = float(und_cache.get(key, 0.0) or 0.0)
                        except (TypeError, ValueError):
                            px = 0.0
                        if px > 0:
                            quotes[s] = {"last": px, "price": px}
                tick_metrics["equity_batches"] = 0

                stealth = self._ensure_trendline_options_stealth_engine()
                now = datetime.now(timezone.utc)
                from easy0DTE.modules.options_execution_normalize import (
                    validate_normalized_options_for_stealth,
                )

                to_close: List[tuple[Any, float, float, str, Dict[str, Any]]] = []
                unified_executor_monitor = (
                    getattr(getattr(self, "dte0_manager", None), "options_executor", None)
                )
                mock_ledger_monitor = (
                    getattr(unified_executor_monitor, "mock_executor", None)
                    if unified_executor_monitor
                    else None
                )
                from modules.unified_0dte_monitor_registry import pending_first_positions

                positions_for_monitor = pending_first_positions(
                    positions_for_monitor,
                    getattr(self, "_0dte_pending_monitor_registrations", None),
                    extra_priority_ids=getattr(self, "_unified_0dte_eval_priority_ids", None),
                    system=self,
                )
                pending_ids_tl = {
                    str(tid).strip()
                    for tid in (getattr(self, "_0dte_pending_monitor_registrations", None) or {})
                    if str(tid or "").strip()
                }
                for pos in list(positions_for_monitor):
                    pos_id_tl = str(getattr(pos, "position_id", "") or "").strip()
                    sym_tl = str(getattr(pos, "symbol", "") or "").strip()
                    if (
                        pos_id_tl
                        and mock_ledger_monitor is not None
                        and hasattr(mock_ledger_monitor, "is_position_closed")
                        and mock_ledger_monitor.is_position_closed(pos_id_tl)
                    ):
                        self._clear_0dte_lifecycle_pending_state(
                            pos_id_tl, reason="ledger_closed_trendline_monitor"
                        )
                        unified_executor_recover = (
                            getattr(getattr(self, "dte0_manager", None), "options_executor", None)
                        )
                        if unified_executor_recover:
                            try:
                                await self._trendline_recover_exit_from_ledger(
                                    pos_id=pos_id_tl,
                                    symbol=sym_tl,
                                    executor=unified_executor_recover,
                                    lifecycle_rec=self._trendline_lifecycle.get(pos_id_tl, {}),
                                    pos=pos,
                                )
                            except Exception as recover_err:
                                log.warning(
                                    "TRENDLINE_PIPELINE | stage=monitor | exit_alert_recovery_failed | "
                                    "trade_id=%s | symbol=%s | error=%s",
                                    pos_id_tl,
                                    sym_tl,
                                    recover_err,
                                )
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=monitor | skip_ledger_closed | trade_id=%s | symbol=%s",
                            pos_id_tl,
                            sym_tl,
                        )
                        continue
                    if pos_id_tl:
                        lifecycle_skip_tl = self._trendline_lifecycle.get(pos_id_tl, {})
                        if bool(lifecycle_skip_tl.get("close_confirmed")):
                            self._clear_0dte_lifecycle_pending_state(
                                pos_id_tl, reason="lifecycle_close_confirmed_trendline_monitor"
                            )
                            # Close confirmed without alert — still attempt Telegram recovery.
                            if pos_id_tl not in getattr(self, "_trendline_exit_alerts_sent", set()):
                                unified_executor_recover = (
                                    getattr(getattr(self, "dte0_manager", None), "options_executor", None)
                                )
                                if unified_executor_recover:
                                    try:
                                        await self._trendline_recover_exit_from_ledger(
                                            pos_id=pos_id_tl,
                                            symbol=sym_tl,
                                            executor=unified_executor_recover,
                                            lifecycle_rec=lifecycle_skip_tl,
                                            pos=pos,
                                        )
                                    except Exception as recover_err:
                                        log.warning(
                                            "TRENDLINE_PIPELINE | stage=monitor | "
                                            "lifecycle_closed_alert_recovery_failed | trade_id=%s | error=%s",
                                            pos_id_tl,
                                            recover_err,
                                        )
                            log.warning(
                                "OPTIONS_STEALTH | stage=trendline_monitor | skip_lifecycle_closed | trade_id=%s | symbol=%s",
                                pos_id_tl,
                                sym_tl,
                            )
                            continue
                        if pos_id_tl in self._trendline_exit_alerts_sent:
                            log.warning(
                                "OPTIONS_STEALTH | stage=trendline_monitor | skip_exit_alert_sent | trade_id=%s | symbol=%s",
                                pos_id_tl,
                                sym_tl,
                            )
                            continue
                        if self._orb_0dte_is_quarantined_ghost(pos_id_tl):
                            # Quarantined after close — recover alert if never sent.
                            if (
                                pos_id_tl not in getattr(self, "_trendline_exit_alerts_sent", set())
                                and pos_id_tl
                                not in getattr(self, "_orb_0dte_exit_alerts_sent", set())
                            ):
                                unified_executor_recover = (
                                    getattr(getattr(self, "dte0_manager", None), "options_executor", None)
                                )
                                if unified_executor_recover:
                                    try:
                                        await self._trendline_recover_exit_from_ledger(
                                            pos_id=pos_id_tl,
                                            symbol=sym_tl,
                                            executor=unified_executor_recover,
                                            lifecycle_rec=self._trendline_lifecycle.get(pos_id_tl, {}),
                                            pos=pos,
                                        )
                                    except Exception:
                                        pass
                            continue
                    md_tl = getattr(pos, "metadata", None)
                    md_tl = md_tl if isinstance(md_tl, dict) else {}
                    norm_mon_pre = md_tl.get("normalized_options") if isinstance(md_tl.get("normalized_options"), dict) else {}
                    exec_mon_pre = md_tl.get("execution_payload") if isinstance(md_tl.get("execution_payload"), dict) else {}
                    strategy_type_tl = str(
                        (norm_mon_pre.get("strategy_type") if isinstance(norm_mon_pre, dict) else None)
                        or (exec_mon_pre.get("strategy_type") if isinstance(exec_mon_pre, dict) else None)
                        or "trendline_0dte"
                    ).strip().lower()
                    # Enroll when the monitor has the name. An eval skip is not
                    # "not monitored" — that skip used to hold the pending clock
                    # until ENROLLMENT_FAILED on the tick that finally evaluated.
                    if pos_id_tl and pos_id_tl not in self._0dte_position_first_seen_ts:
                        from modules.unified_0dte_monitor_registry import stamp_0dte_first_seen_on_monitor_tick

                        stamp_0dte_first_seen_on_monitor_tick(
                            first_seen=self._0dte_position_first_seen_ts,
                            pending=self._0dte_pending_monitor_registrations,
                            not_monitored_logged=self._0dte_not_monitored_logged,
                            trade_id=pos_id_tl,
                        )
                        self._trendline_lifecycle_record(
                            trade_id=pos_id_tl,
                            symbol=sym_tl,
                            strategy_type=strategy_type_tl,
                            structural_position_type=str(getattr(pos, "option_side", "") or "unknown"),
                            quote_source="monitor_start",
                            degraded_mode=False,
                            state="monitoring_active",
                            state_log_token="TRENDLINE_MONITORING_ACTIVE",
                        )
                        log.info(
                            "OPTION_POSITION_MONITOR_START | strategy=%s | trigger=%s | trade_id=%s | symbol=%s",
                            strategy_type_tl,
                            trigger_source,
                            pos_id_tl,
                            sym_tl,
                        )
                    from modules.owned_tick_observe import owned_tick_eval

                    tick_eval_tl = owned_tick_eval(md_tl, str(tick_id or ""))
                    if isinstance(tick_eval_tl, dict) and not tick_eval_tl.get("evaluated"):
                        continue
                    if pos_id_tl and pos_id_tl not in self.positions:
                        log.error(
                            "OPTION_POSITION_MISSING_FROM_REGISTRY | stage=trendline_monitor_discovery | trade_id=%s | symbol=%s",
                            pos_id_tl,
                            sym_tl,
                        )
                        self._rebuild_0dte_system_position_registry()
                        if sym_tl:
                            self._trendline_signals_executed_today.add(sym_tl)
                        log.info(
                            "OPTION_POSITION_REGISTERED | strategy=%s | trade_id=%s | symbol=%s | option_side=%s | entry_premium=%.6f",
                            strategy_type_tl,
                            pos_id_tl,
                            sym_tl,
                            str(getattr(pos, "option_side", "") or "").strip().lower() or "unknown",
                            float(
                                (norm_mon_pre.get("entry_value") if isinstance(norm_mon_pre, dict) else None)
                                or (exec_mon_pre.get("estimated_contract_price") if isinstance(exec_mon_pre, dict) else None)
                                or 0.0
                            ),
                        )
                    q = quotes.get(pos.symbol, {}) if isinstance(quotes, dict) else {}
                    px = q.get("last", 0.0) or q.get("close", 0.0) or q.get("price", 0.0)
                    try:
                        current_underlying = float(px)
                    except (TypeError, ValueError):
                        current_underlying = 0.0
                    try:
                        from modules.underlying_freshness import (
                            resolve_underlying_observation,
                            stamp_underlying_provenance,
                        )

                        obs_tl = resolve_underlying_observation(self, sym_tl)
                        osnap_u = (
                            md_tl.get("option_stealth")
                            if isinstance(md_tl.get("option_stealth"), dict)
                            else None
                        )
                        if osnap_u is None:
                            osnap_u = {}
                            md_tl["option_stealth"] = osnap_u
                        stamp_underlying_provenance(osnap_u, obs_tl)
                        current_underlying = float(obs_tl.price_or_zero or 0.0)
                    except Exception:
                        pass
                    if current_underlying <= 0:
                        log.warning(
                            "OPTION_MONITOR_POSITION_TICK | trade_id=%s | symbol=%s | "
                            "underlying_source=unavailable | evaluate_premium_only=true | strategy=trendline_0dte",
                            pos_id_tl,
                            sym_tl,
                        )
                    elif sym_tl:
                        self._orb_0dte_last_underlying_by_symbol[str(sym_tl).upper()] = float(
                            current_underlying
                        )
                        self._trendline_last_price_by_symbol[sym_tl] = current_underlying

                    lifecycle_rec_tl = self._trendline_lifecycle.setdefault(pos_id_tl, {})
                    lifecycle_rec_tl["last_monitor_tick_ts"] = time.time()

                    oq = None
                    try:
                        oq = await self._trendline_fetch_option_quote(
                            pos,
                            chain_cache=chain_cache,
                            tick_metrics=tick_metrics,
                            shared_chain_cache=shared_sc,
                            tick_id=tick_id,
                        )
                    except Exception as tl_oq_err:
                        log.debug("TRENDLINE_PIPELINE | stage=monitor | option_quote_skip=%s", tl_oq_err)

                    if not isinstance(md_tl, dict):
                        md_tl = {}
                        if isinstance(getattr(pos, "metadata", None), dict):
                            pos.metadata = md_tl
                    self._register_trendline_stealth_if_missing(stealth, pos, md_tl, current_underlying)
                    await self._orb_post_fill_hydration_burst(
                        pos,
                        pos_id_tl,
                        sym_tl,
                        shared_sc,
                        tick_id,
                    )
                    osnap_pre = md_tl.get("option_stealth")
                    if not isinstance(osnap_pre, dict) or not osnap_pre:
                        log.error(
                            "OPTIONS_STEALTH_FAILSAFE | reason=trendline_stealth_not_registered | trade_id=%s | symbol=%s",
                            pos_id_tl,
                            sym_tl,
                        )
                        continue
                    norm_mon = md_tl.get("normalized_options")
                    oq_final: Dict[str, Any] = {}
                    if isinstance(oq, dict):
                        oq_final.update(oq)
                    if isinstance(norm_mon, dict):
                        nmon_ok, _ = validate_normalized_options_for_stealth(norm_mon)
                        if nmon_ok:
                            pt_mon = str(norm_mon.get("position_type") or "")
                            if pt_mon in ("single_leg_long_call", "single_leg_long_put"):
                                cv_mon = float(norm_mon.get("current_value") or 0.0)
                                if cv_mon > 0:
                                    oq_final.setdefault("current_position_value", cv_mon)
                    exit_sig_ts_tl = float(lifecycle_rec_tl.get("exit_signalled_ts", 0.0) or 0.0)
                    close_pending_tl = exit_sig_ts_tl > 0 and not bool(lifecycle_rec_tl.get("close_confirmed"))
                    if (
                        not close_pending_tl
                        and not oq_final
                        and unified_executor_monitor
                        and pos_id_tl
                    ):
                        if self._demo_0dte_handle_persistent_quote_ghost(
                            unified_executor_monitor,
                            pos_id_tl,
                            reason="no_option_quote",
                        ):
                            continue
                    if close_pending_tl:
                        pending_reason_tl = str(
                            lifecycle_rec_tl.get("pending_exit_reason")
                            or (lifecycle_rec_tl.get("close_confirmation") or {}).get("close_reason")
                            or "pending_close_retry"
                        )
                        pending_prem_tl = float(
                            lifecycle_rec_tl.get("pending_exit_premium")
                            or (osnap_pre.get("current_effective_premium") if isinstance(osnap_pre, dict) else 0.0)
                            or 0.0
                        )
                        if isinstance(oq_final, dict):
                            try:
                                live_bid_tl = float(oq_final.get("bid") or 0.0)
                            except (TypeError, ValueError):
                                live_bid_tl = 0.0
                            if live_bid_tl > 0:
                                pending_prem_tl = live_bid_tl
                        if pending_prem_tl <= 0 and isinstance(oq_final, dict):
                            pending_prem_tl = float(oq_final.get("current_position_value") or 0.0)
                        if pending_prem_tl <= 0:
                            pending_prem_tl = float(getattr(pos, "entry_cost", 0.0) or 0.0) / max(
                                1, int(getattr(pos, "quantity", 1) or 1)
                            ) / 100.0
                        log.info(
                            "OPTIONS_PENDING_CLOSE_RETRY | strategy=trendline_0dte | trade_id=%s | symbol=%s | reason=%s | exit_premium=%.6f",
                            pos_id_tl,
                            sym_tl,
                            pending_reason_tl,
                            pending_prem_tl,
                        )
                        self._trendline_lifecycle_record(
                            trade_id=pos_id_tl,
                            symbol=sym_tl,
                            strategy_type=strategy_type_tl,
                            structural_position_type=str(getattr(pos, "option_side", "") or "unknown"),
                            quote_source=str(
                                (osnap_pre.get("last_premium_source") if isinstance(osnap_pre, dict) else None)
                                or "unknown"
                            ),
                            degraded_mode=False,
                            state="pending_close_retry",
                            state_log_token="TRENDLINE_PENDING_CLOSE_RETRY",
                            extras={"reason": pending_reason_tl},
                        )
                        out = (
                            pending_prem_tl,
                            pending_reason_tl,
                            {"source": "pending_close_fast_path", "stealth_exit_reason": pending_reason_tl},
                        )
                    else:
                        from modules.owned_tick_observe import reuse_owned_tick_eval

                        reused_tl, tick_eval_tl_out = reuse_owned_tick_eval(
                            md_tl if isinstance(md_tl, dict) else {}, str(tick_id or "")
                        )
                        if reused_tl:
                            out = tick_eval_tl_out
                        else:
                            out = self._0dte_run_stealth_exit_decision(
                                stealth=stealth,
                                pos=pos,
                                position_metadata=md_tl,
                                current_underlying=current_underlying,
                                now=now,
                                option_quote=oq_final if oq_final else None,
                                monitor_tick_id=str(tick_id or ""),
                            )
                    self._bump_unified_eval_count("trendline_positions_evaluated", 1)
                    osnap = (md_tl or {}).get("option_stealth") if isinstance(md_tl, dict) else {}
                    if isinstance(osnap, dict):
                        tick_metrics["positions_processed"] += 1
                        source = str(osnap.get("last_premium_source") or "other")
                        oq_tl = oq_final if isinstance(oq_final, dict) else {}
                        trusted_quote_hold = False
                        try:
                            from .prime_options_stealth_trailing_tp import orb_trusted_exit_grade_hold_active

                            trusted_quote_hold = bool(orb_trusted_exit_grade_hold_active(osnap))
                        except Exception:
                            trusted_quote_hold = bool(osnap.get("orb_trusted_exit_grade_hold"))
                        from .unified_0dte_premium_bucket import classify_0dte_monitor_premium_bucket

                        prem_bucket = classify_0dte_monitor_premium_bucket(
                            source=source,
                            osnap=osnap,
                            oq_orb=oq_tl,
                            durability={},
                            trusted_quote_hold=trusted_quote_hold,
                        )
                        tick_metrics["premium_sources"][prem_bucket] = (
                            int(tick_metrics["premium_sources"].get(prem_bucket, 0) or 0) + 1
                        )
                        if prem_bucket in ("mark_or_mid", "last"):
                            tick_metrics["positions_with_live_quotes"] += 1
                        elif prem_bucket in (
                            "modeled_proxy",
                            "current_position_value_fallback",
                            "missing_or_invalid",
                        ):
                            tick_metrics["positions_degraded"] += 1
                        # Feed shared 0DTE quote-health counters (same as ORB monitor)
                        ps_all = self._orb_0dte_monitor_metrics.setdefault("premium_sources", {})
                        ps_all[prem_bucket] = int(ps_all.get(prem_bucket, 0) or 0) + 1
                        self._orb_0dte_monitor_metrics["processed_positions"] = int(
                            self._orb_0dte_monitor_metrics.get("processed_positions", 0) or 0
                        ) + 1
                        self._update_trendline_execution_dataset_snapshot(
                            trade_id=str(pos.position_id),
                            execution_ts=None,
                            held_minutes=(
                                float(osnap.get("held_minutes"))
                                if isinstance(osnap.get("held_minutes"), (int, float))
                                else None
                            ),
                            pnl_pct=(
                                float(osnap.get("current_pnl_pct_per_contract"))
                                if isinstance(osnap.get("current_pnl_pct_per_contract"), (int, float))
                                else None
                            ),
                        )
                    current_premium_tick = float(osnap.get("current_effective_premium", 0.0) or 0.0) if isinstance(osnap, dict) else 0.0
                    entry_premium_tick = float(osnap.get("entry_premium", 0.0) or 0.0) if isinstance(osnap, dict) else 0.0
                    current_pnl_tick = float(osnap.get("current_pnl_pct_per_contract", 0.0) or 0.0) if isinstance(osnap, dict) else 0.0
                    max_pnl_tick = float(osnap.get("max_pnl_pct", 0.0) or 0.0) if isinstance(osnap, dict) else 0.0
                    had_opp_tick = bool(osnap.get("had_opportunity", False)) if isinstance(osnap, dict) else False
                    behavior_tick = str(osnap.get("trade_behavior", "unknown") or "unknown") if isinstance(osnap, dict) else "unknown"
                    stealth_mode_tick = str(osnap.get("trailing_mode", "inactive") or "inactive") if isinstance(osnap, dict) else "inactive"
                    log.info(
                        "OPTION_POSITION_MONITOR_TICK | trigger=%s | trade_id=%s | symbol=%s | strategy_type=%s | "
                        "current_premium=%.6f | entry_premium=%.6f | current_pnl_pct=%.4f | max_pnl_pct=%.4f | "
                        "had_opportunity=%s | trade_behavior=%s | stealth_mode=%s | status=%s",
                        trigger_source,
                        pos_id_tl,
                        sym_tl,
                        strategy_type_tl,
                        current_premium_tick,
                        entry_premium_tick,
                        current_pnl_tick,
                        max_pnl_tick,
                        str(had_opp_tick).lower(),
                        behavior_tick,
                        stealth_mode_tick,
                        "exit_signaled" if bool(out) else "hold",
                    )
                    from modules.unified_0dte_monitor_registry import (
                        emit_0dte_mfe_heartbeat,
                        should_emit_0dte_mfe_heartbeat,
                    )

                    if should_emit_0dte_mfe_heartbeat(
                        getattr(self, "_0dte_monitor_tick_hb_ts", {}),
                        trade_id=pos_id_tl,
                    ):
                        emit_0dte_mfe_heartbeat(
                            strategy_type=strategy_type_tl or "trendline_0dte",
                            trade_id=pos_id_tl,
                            symbol=sym_tl,
                            current_pnl_pct=current_pnl_tick,
                            max_pnl_pct=max_pnl_tick,
                            had_opportunity=had_opp_tick,
                            stealth_mode=stealth_mode_tick,
                            trigger_source=trigger_source,
                        )
                    self._emit_option_lifecycle_tick_unified(
                        trade_id=pos_id_tl,
                        symbol=sym_tl,
                        strategy_type=strategy_type_tl,
                        monitor_loop="trendline_0dte",
                        trigger_source=str(trigger_source or ""),
                        osnap=osnap if isinstance(osnap, dict) else {},
                        lifecycle_rec=lifecycle_rec_tl,
                        quote_source=str(osnap.get("last_premium_source") or "unknown")
                        if isinstance(osnap, dict)
                        else "unknown",
                        out=out,
                        seconds_since_last_tick=0.0,
                        position_meta=md_tl if isinstance(md_tl, dict) else None,
                    )
                    if isinstance(osnap, dict) and pos_id_tl:
                        tl_source = str(osnap.get("last_premium_source") or "")
                        tl_quote_grade = self._orb_0dte_quote_grade_from_snap(osnap, tl_source)
                        try:
                            _side_tl = str(
                                getattr(pos, "option_side", None)
                                or (md_tl.get("option_side") if isinstance(md_tl, dict) else "")
                                or ""
                            )
                            self._maybe_sparse_refresh_path_chain_skew(
                                osnap=osnap,
                                symbol=str(sym_tl or ""),
                                option_side=_side_tl,
                                underlying_price=float(current_underlying or 0.0),
                                position=pos,
                                tick_id=str(tick_id or ""),
                                trade_id=str(pos_id_tl or ""),
                            )
                            self._maybe_sparse_refresh_path_session_tech(
                                osnap=osnap,
                                symbol=str(sym_tl or ""),
                                underlying_price=float(current_underlying or 0.0),
                                position=pos,
                                tick_id=str(tick_id or ""),
                                trade_id=str(pos_id_tl or ""),
                            )
                            self._seed_osnap_path_chain_skew(
                                osnap=osnap,
                                symbol=str(sym_tl or ""),
                                option_side=_side_tl,
                                position=pos,
                            )
                        except Exception:
                            pass
                        # Recorder write lives in _0dte_run_stealth_exit_decision.
                        try:
                            await self._apply_exit_grade_durability_tick(
                                pos=pos,
                                trade_id=pos_id_tl,
                                symbol=sym_tl,
                                strategy_type=str(strategy_type_tl or "trendline_0dte"),
                                osnap=osnap,
                                quote_source=tl_source,
                            )
                        except Exception as _eg_tl_err:
                            log.warning(
                                "TRENDLINE_EXIT_GRADE_EVAL_FAIL | trade_id=%s | symbol=%s | error=%s",
                                pos_id_tl,
                                sym_tl,
                                _eg_tl_err,
                            )
                    if not out:
                        _exit_sig_ts_tl = float(lifecycle_rec_tl.get("exit_signalled_ts", 0.0) or 0.0)
                        if _exit_sig_ts_tl > 0 and not bool(lifecycle_rec_tl.get("close_confirmed", False)):
                            _since_sig_tl = max(0.0, time.time() - _exit_sig_ts_tl)
                            if _since_sig_tl > float(
                                getattr(self, "_trendline_exit_confirmation_timeout_seconds", 15.0)
                            ):
                                self._trendline_lifecycle_session_stats["positions_missing_confirmation"] = int(
                                    self._trendline_lifecycle_session_stats.get("positions_missing_confirmation", 0)
                                ) + 1
                                log.warning(
                                    "TRENDLINE_EXIT_CONFIRMATION_MISSING | trade_id=%s | symbol=%s | seconds_since_signal=%.1f | current_state=%s",
                                    pos_id_tl,
                                    sym_tl,
                                    float(_since_sig_tl),
                                    str(lifecycle_rec_tl.get("state", "unknown")),
                                )
                    if out:
                        exit_prem, reason, telem = out
                        md_tl_adj = md_tl if isinstance(md_tl, dict) else {}
                        osnap_adj = osnap if isinstance(osnap, dict) else {}
                        ed_adj = (
                            telem.get("exit_diagnostics")
                            if isinstance(telem, dict) and isinstance(telem.get("exit_diagnostics"), dict)
                            else {}
                        )
                        if not ed_adj.get("exit_premium_adjusted"):
                            from .prime_options_stealth_trailing_tp import (
                                finalize_tline_true_to_live_exit_premium,
                                _hydrate_exit_prem_detail,
                            )

                            entry_prem_adj = float(
                                getattr(pos, "entry_price", 0.0)
                                or md_tl_adj.get("entry_fill_price")
                                or (
                                    (md_tl_adj.get("premium_snapshot") or {}).get("entry_fill_price")
                                    if isinstance(md_tl_adj.get("premium_snapshot"), dict)
                                    else 0.0
                                )
                                or 0.0
                            )
                            if entry_prem_adj <= 0:
                                # Fallback only — entry_cost may include fees (BE wash).
                                entry_prem_adj = float(getattr(pos, "entry_cost", 0.0) or 0.0)
                                entry_prem_adj = (
                                    entry_prem_adj
                                    / max(1, int(getattr(pos, "quantity", 1) or 1))
                                    / 100.0
                                )
                            prem_detail_adj = ed_adj
                            if isinstance(telem, dict) and isinstance(telem.get("premium_detail"), dict):
                                prem_detail_adj = telem.get("premium_detail")
                            prem_detail_adj = _hydrate_exit_prem_detail(
                                prem_detail_adj if isinstance(prem_detail_adj, dict) else {},
                                osnap=osnap_adj if isinstance(osnap_adj, dict) else None,
                                exit_premium=float(exit_prem or 0.0),
                            )
                            stealth_cfg = getattr(
                                getattr(self, "trendline_options_stealth", None), "config", None
                            )
                            max_sp = float(
                                getattr(stealth_cfg, "tline_exit_grade_max_spread_pct", 0.30) or 0.30
                            )
                            exit_prem_adj, adjusted_adj, adj_reason = finalize_tline_true_to_live_exit_premium(
                                strategy_type="trendline_0dte",
                                option_side=str(getattr(pos, "option_side", "") or ""),
                                entry_chain_source=str(
                                    md_tl_adj.get("entry_chain_source")
                                    or osnap_adj.get("entry_chain_source")
                                    or (md_tl_adj.get("execution_payload") or {}).get("chain_source")
                                    or ""
                                ),
                                entry_premium=entry_prem_adj,
                                exit_premium=float(exit_prem or 0.0),
                                prem_detail=prem_detail_adj if isinstance(prem_detail_adj, dict) else None,
                                mark_is_exit_grade=bool(osnap_adj.get("mark_is_exit_grade")),
                                premium_jump_detected=bool(osnap_adj.get("premium_jump_detected")),
                                use_bid_for_long_exit=bool(
                                    getattr(stealth_cfg, "dte_use_bid_for_long_exit", True)
                                ),
                                max_spread_pct=max_sp,
                                true_to_live_enabled=bool(
                                    getattr(stealth_cfg, "dte_true_to_live_executable_marks", True)
                                ),
                            )
                            if adjusted_adj:
                                exit_prem = exit_prem_adj
                                if isinstance(osnap_adj, dict):
                                    osnap_adj["exit_premium_adjusted"] = True
                                    osnap_adj["exit_premium_adjustment_reason"] = adj_reason
                                    osnap_adj["exit_premium_raw_live"] = float(
                                        telem.get("exit_diagnostics", {}).get("exit_price")
                                        if isinstance(telem, dict)
                                        else exit_prem_adj
                                    )
                        now_tl_exit = time.time()
                        lifecycle_rec_tl["exit_signalled_ts"] = now_tl_exit
                        lifecycle_rec_tl["pending_exit_reason"] = str(reason or "")
                        lifecycle_rec_tl["pending_exit_premium"] = float(exit_prem or 0.0)
                        try:
                            from modules.exit_grade_durability import (
                                EVT_CLOSE_SUBMIT,
                                EVT_EXIT_SIGNAL,
                                stamp_session_event,
                            )

                            _md_exit = md_tl if isinstance(md_tl, dict) else getattr(pos, "metadata", None)
                            if isinstance(_md_exit, dict):
                                stamp_session_event(_md_exit, EVT_EXIT_SIGNAL, now_ts=now_tl_exit)
                                stamp_session_event(_md_exit, EVT_CLOSE_SUBMIT, now_ts=now_tl_exit)
                        except Exception:
                            pass
                        self._trendline_lifecycle_record(
                            trade_id=pos_id_tl,
                            symbol=sym_tl,
                            strategy_type=strategy_type_tl,
                            structural_position_type=str(getattr(pos, "option_side", "") or "unknown"),
                            quote_source=str(
                                (osnap.get("last_premium_source") if isinstance(osnap, dict) else None) or "unknown"
                            ),
                            degraded_mode=bool(
                                isinstance(osnap, dict) and bool(osnap.get("degraded_data_active"))
                            ),
                            state="exit_signalled",
                            state_log_token="TRENDLINE_EXIT_SIGNALLED",
                            extras={"reason": reason},
                        )
                        try:
                            from modules.exit_latch import latch_exit_decision, mark_dispatch_ownership_gated
                            from modules.dte0_exit_monitor_config import resolve_exit_monitor_config

                            if resolve_exit_monitor_config().exit_latch_enabled:
                                latch_exit_decision(
                                    pos,
                                    reason=str(reason or ""),
                                    bid=float(exit_prem or 0.0) or None,
                                    premium=float(exit_prem or 0.0) or None,
                                )
                                if bool(getattr(self, "_unified_0dte_ownership_gate_dispatch", False)):
                                    try:
                                        from modules.ownership_urgent_sync import (
                                            mark_ownership_blocked,
                                            request_urgent_ownership_sync,
                                        )

                                        mark_ownership_blocked(
                                            pos,
                                            last_confirmed_quantity=int(getattr(pos, "quantity", 0) or 0),
                                            strategy="trendline_0dte",
                                        )
                                        await request_urgent_ownership_sync(
                                            self, pos, strategy="trendline_0dte"
                                        )
                                    except Exception:
                                        from modules.exit_latch import mark_dispatch_ownership_gated

                                        mark_dispatch_ownership_gated(
                                            pos,
                                            last_confirmed_quantity=int(getattr(pos, "quantity", 0) or 0),
                                        )
                                    log.warning(
                                        "EXIT_LATCHED_BUT_SYNC_BLOCKED | strategy=trendline | trade_id=%s | "
                                        "defer_submit=true | reason=%s",
                                        pos_id_tl,
                                        reason,
                                    )
                                    continue
                                try:
                                    from modules.exit_latch import (
                                        should_defer_broker_dispatch,
                                        clear_ownership_gate,
                                    )

                                    clear_ownership_gate(pos)
                                    if should_defer_broker_dispatch(pos, ownership_gate_active=False):
                                        log.info(
                                            "EXIT_DISPATCH_DEFER | strategy=trendline | trade_id=%s | "
                                            "reason=inflight_or_pending",
                                            pos_id_tl,
                                        )
                                        continue
                                except Exception:
                                    pass
                        except Exception as tl_latch_err:
                            log.warning(
                                "EXIT_LATCH | trendline_failed | trade_id=%s | error=%s",
                                pos_id_tl,
                                tl_latch_err,
                            )
                        log_option_exit_diagnosis(
                            stage="exit_signal",
                            strategy="trendline_0dte",
                            trade_id=pos_id_tl,
                            symbol=sym_tl,
                            reason=str(reason or ""),
                            exit_premium=float(exit_prem or 0.0),
                            underlying=float(current_underlying),
                            trigger=str(trigger_source or ""),
                        )
                        log.info(
                            "OPTION_LIFECYCLE_EXIT_SIGNAL | trigger=%s | symbol=%s | trade_id=%s | norm_trade_id=%s | "
                            "reason=%s | exit_premium=%.6f",
                            trigger_source,
                            sym_tl,
                            pos_id_tl,
                            pos_id_tl,
                            reason,
                            float(exit_prem or 0.0),
                        )
                        contracts = max(1, int(pos.quantity))
                        exit_value = exit_prem * 100.0 * contracts
                        pnl_pct = (exit_value - pos.entry_cost) / pos.entry_cost if pos.entry_cost > 0 else 0.0
                        if isinstance(osnap, dict):
                            osnap["exit_reason"] = reason
                            osnap["exit_premium"] = exit_prem
                            osnap["exit_telemetry"] = telem
                            ed = telem.get("exit_diagnostics")
                            if isinstance(ed, dict):
                                osnap["exit_diagnostics"] = ed
                        try:
                            from modules.underlying_freshness import resolve_exit_underlying_price

                            exit_und_alert = resolve_exit_underlying_price(
                                live_underlying=current_underlying,
                                osnap=osnap if isinstance(osnap, dict) else None,
                                position=pos,
                                metadata=md_tl if isinstance(md_tl, dict) else None,
                                symbol_cache=getattr(
                                    self, "_orb_0dte_last_underlying_by_symbol", None
                                ),
                                symbol=sym_tl,
                            )
                        except Exception:
                            exit_und_alert = float(current_underlying or 0.0)
                        to_close.append(
                            (
                                pos,
                                exit_value,
                                pnl_pct,
                                reason,
                                telem,
                                float(exit_prem or 0.0),
                                float(exit_und_alert or 0.0),
                            )
                        )

                had_monitor_closes = False
                for pos, est_value, pnl_pct, reason, telem, exit_prem_alert, exit_underlying_alert in to_close:
                    pos_id_tl = str(getattr(pos, "position_id", "") or "").strip()
                    sym_tl = str(getattr(pos, "symbol", "") or "").strip()
                    _tl_post_alert_quarantine = False
                    # Always refresh metadata from THIS position — do not reuse the
                    # last monitor-loop md_tl (multi-close batch bug).
                    md_tl = getattr(pos, "metadata", None)
                    md_tl = md_tl if isinstance(md_tl, dict) else {}
                    from modules.prime_alert_manager import _position_dict_is_breakout_0dte

                    _close_probe = {
                        "strategy_type": str(getattr(pos, "strategy_type", "") or ""),
                        "metadata": md_tl,
                    }
                    close_strategy_type = (
                        "breakout_0dte"
                        if _position_dict_is_breakout_0dte(_close_probe)
                        else "trendline_0dte"
                    )
                    if (
                        pos_id_tl
                        and mock_ledger_monitor is not None
                        and hasattr(mock_ledger_monitor, "is_position_closed")
                        and mock_ledger_monitor.is_position_closed(pos_id_tl)
                    ):
                        unified_executor_recover = (
                            getattr(getattr(self, "dte0_manager", None), "options_executor", None)
                        )
                        self._clear_0dte_lifecycle_pending_state(
                            pos_id_tl, reason="ledger_closed_trendline_exit"
                        )
                        if unified_executor_recover:
                            await self._trendline_recover_exit_from_ledger(
                                pos_id=pos_id_tl,
                                symbol=sym_tl,
                                executor=unified_executor_recover,
                                lifecycle_rec=self._trendline_lifecycle.get(pos_id_tl, {}),
                                pos=pos,
                            )
                        self._rebuild_0dte_system_position_registry()
                        try:
                            from modules.unified_0dte_monitor_registry import clear_0dte_monitor_identity

                            clear_0dte_monitor_identity(
                                first_seen=self._0dte_position_first_seen_ts,
                                pending=self._0dte_pending_monitor_registrations,
                                not_monitored_logged=self._0dte_not_monitored_logged,
                                trade_id=pos_id_tl,
                                heartbeat_ts=getattr(self, "_0dte_monitor_tick_hb_ts", None),
                            )
                        except Exception:
                            pass
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=exit | skip_ledger_closed | trade_id=%s | symbol=%s",
                            pos_id_tl,
                            sym_tl,
                        )
                        continue
                    if not pos_id_tl or pos_id_tl not in self.positions:
                        log.error(
                            "OPTION_EXIT_WITHOUT_POSITION | trigger=%s | trade_id=%s | symbol=%s | reason=%s | "
                            "action=continue_close_without_registry",
                            trigger_source,
                            pos_id_tl,
                            sym_tl,
                            reason,
                        )
                        # Soft-fail: never assert-crash the monitor loop mid-exit batch.
                        # Proceed to close via unified executor using the monitor position object.
                        if not pos_id_tl:
                            continue
                    unified_executor = (
                        getattr(getattr(self, "dte0_manager", None), "options_executor", None)
                    )
                    if not unified_executor:
                        log.error(
                            "OPTIONS_STEALTH_FAILSAFE | reason=missing_unified_executor | trade_id=%s",
                            pos.position_id,
                        )
                        continue
                    log.info(
                        "OPTIONS_STEALTH_CLOSE_ROUTED | trade_id=%s | path=unified_executor_close | strategy=%s",
                        pos.position_id,
                        close_strategy_type,
                    )
                    log_option_exit_diagnosis(
                        stage="close_attempt",
                        strategy=close_strategy_type,
                        trade_id=pos_id_tl,
                        symbol=sym_tl,
                        reason=str(reason or ""),
                        pnl_pct=float(pnl_pct),
                        trigger=str(trigger_source or ""),
                    )
                    close_result = await unified_executor.close_position_with_data(
                        position_id=pos.position_id,
                        exit_price=(float(est_value) / max(1, int(pos.quantity)) / 100.0),
                        exit_reason=_safe_canonical_exit_reason(str(reason)),
                        exit_time=datetime.now(timezone.utc),
                        details={
                            "source": "trendline_options_stealth",
                            "stealth_reason": str(reason or ""),
                            "telemetry": telem if isinstance(telem, dict) else {},
                        },
                        external_position_data=self._build_0dte_external_close_payload(
                            pos,
                            strategy_type=close_strategy_type,
                            meta=md_tl if isinstance(md_tl, dict) else None,
                        ),
                        suppress_exit_alert=True,
                    )
                    if not close_result:
                        lifecycle_rec_tl = self._trendline_lifecycle.setdefault(pos_id_tl, {})
                        lifecycle_rec_tl["close_confirmed"] = False
                        self._trendline_lifecycle_session_stats["close_failures"] = int(
                            self._trendline_lifecycle_session_stats.get("close_failures", 0)
                        ) + 1
                        self._trendline_lifecycle_record(
                            trade_id=pos_id_tl,
                            symbol=sym_tl,
                            strategy_type="trendline_0dte",
                            structural_position_type=str(getattr(pos, "option_side", "") or "unknown"),
                            quote_source="close_failed",
                            degraded_mode=True,
                            state="close_failed",
                            state_log_token="TRENDLINE_CLOSE_FAILED",
                            extras={"reason": reason},
                        )
                        log_option_exit_diagnosis(
                            stage="close_failed",
                            strategy="trendline_0dte",
                            trade_id=pos_id_tl,
                            symbol=sym_tl,
                            reason=str(reason or ""),
                            trigger=str(trigger_source or ""),
                            close_ok=False,
                            extra={"failure": "unified_executor_returned_none"},
                        )
                        continue
                    closed = None
                    if close_result:
                        from modules.unified_0dte_account import trendline_position_entry_cost
                        from types import SimpleNamespace

                        entry_cost = trendline_position_entry_cost(pos)
                        realized = float(est_value) - entry_cost
                        if isinstance(close_result, dict) and close_result.get("realized_pnl") is not None:
                            try:
                                realized = float(close_result.get("realized_pnl"))
                            except (TypeError, ValueError):
                                pass
                        closed = SimpleNamespace(
                            position_id=pos_id_tl,
                            symbol=sym_tl,
                            realized_pnl=realized,
                            entry_cost=entry_cost,
                            metadata=md_tl if isinstance(md_tl, dict) and md_tl else None,
                        )
                    if not closed:
                        lifecycle_rec_tl = self._trendline_lifecycle.setdefault(pos_id_tl, {})
                        lifecycle_rec_tl["close_confirmed"] = False
                        self._trendline_lifecycle_session_stats["close_failures"] = int(
                            self._trendline_lifecycle_session_stats.get("close_failures", 0)
                        ) + 1
                        self._trendline_lifecycle_record(
                            trade_id=pos_id_tl,
                            symbol=sym_tl,
                            strategy_type="trendline_0dte",
                            structural_position_type=str(getattr(pos, "option_side", "") or "unknown"),
                            quote_source="finalize_failed",
                            degraded_mode=True,
                            state="close_failed",
                            state_log_token="TRENDLINE_CLOSE_FAILED",
                            extras={"reason": reason, "failure": "finalize_close_from_unified_result"},
                        )
                        log_option_exit_diagnosis(
                            stage="close_failed",
                            strategy="trendline_0dte",
                            trade_id=pos_id_tl,
                            symbol=sym_tl,
                            reason=str(reason or ""),
                            trigger=str(trigger_source or ""),
                            close_ok=False,
                            extra={"failure": "finalize_close_from_unified_result"},
                        )
                        continue
                    lifecycle_rec_tl = self._trendline_lifecycle.setdefault(pos_id_tl, {})
                    lifecycle_rec_tl["close_confirmed"] = True
                    lifecycle_rec_tl["pending_exit_reason"] = ""
                    lifecycle_rec_tl["pending_exit_premium"] = 0.0
                    lifecycle_rec_tl["close_confirmation"] = {
                        "close_confirmed": True,
                        "close_reason": _safe_canonical_exit_reason(str(reason)),
                    }
                    try:
                        from modules.exit_grade_durability import EVT_CLOSE_CONFIRM, stamp_session_event

                        _md_close = getattr(pos, "metadata", None)
                        if isinstance(_md_close, dict):
                            stamp_session_event(_md_close, EVT_CLOSE_CONFIRM)
                    except Exception:
                        pass
                    self._trendline_lifecycle_session_stats["exits_confirmed"] = int(
                        self._trendline_lifecycle_session_stats.get("exits_confirmed", 0)
                    ) + 1
                    self._trendline_lifecycle_record(
                        trade_id=pos_id_tl,
                        symbol=sym_tl,
                        strategy_type="trendline_0dte",
                        structural_position_type=str(getattr(pos, "option_side", "") or "unknown"),
                        quote_source="close_confirmed",
                        degraded_mode=False,
                        state="exit_execution_confirmed",
                        state_log_token="TRENDLINE_EXIT_EXECUTION_CONFIRMED",
                        extras={"reason": reason},
                    )
                    log_option_exit_diagnosis(
                        stage="close_confirmed",
                        strategy="trendline_0dte",
                        trade_id=pos_id_tl,
                        symbol=sym_tl,
                        reason=str(reason or ""),
                        pnl_pct=float(pnl_pct),
                        pnl_dollar=float(getattr(closed, "realized_pnl", 0.0) or 0.0),
                        trigger=str(trigger_source or ""),
                        close_ok=True,
                    )
                    self._profit_optimizer_observe_0dte_exit(
                        trade_id=pos_id_tl,
                        exit_premium=float(exit_prem_alert or 0.0),
                        exit_underlying=float(exit_underlying_alert or 0.0),
                        exit_reason=str(reason or ""),
                        realized_pnl_pct=float(pnl_pct),
                        strategy="trendline_0dte",
                        symbol=str(getattr(pos, "symbol", "") or ""),
                        position=pos,
                        _skip_po_exit_snapshot=True,
                    )
                    try:
                        self._save_trendline_exit_priority_snapshot(
                            symbol=str(getattr(pos, "symbol", "") or ""),
                            trade_id=str(pos_id_tl or getattr(pos, "position_id", "") or ""),
                            option_side=str(getattr(pos, "option_side", "") or "") or None,
                            exit_reason=str(reason or ""),
                            exit_premium=float(exit_prem_alert or 0.0) or None,
                            entry_premium=float(getattr(pos, "entry_price", 0.0) or 0.0) or None,
                            realized_pnl=float(getattr(closed, "realized_pnl", 0.0) or 0.0),
                            realized_pnl_pct=float(pnl_pct or 0.0),
                            exit_underlying=float(exit_underlying_alert or 0.0) or None,
                            position=pos,
                        )
                    except Exception as _tl_exit_snap_exc:
                        log.debug("Trendline exit snapshot skipped: %s", _tl_exit_snap_exc)
                    try:
                        self._rebuild_0dte_system_position_registry()
                        try:
                            from modules.unified_0dte_monitor_registry import clear_0dte_monitor_identity

                            clear_0dte_monitor_identity(
                                first_seen=self._0dte_position_first_seen_ts,
                                pending=self._0dte_pending_monitor_registrations,
                                not_monitored_logged=self._0dte_not_monitored_logged,
                                trade_id=pos_id_tl,
                                heartbeat_ts=getattr(self, "_0dte_monitor_tick_hb_ts", None),
                            )
                        except Exception:
                            self._0dte_pending_monitor_registrations.pop(pos_id_tl, None)
                            self._0dte_not_monitored_logged.discard(pos_id_tl)
                            self._0dte_position_first_seen_ts.pop(pos_id_tl, None)
                        # Defer ghost quarantine until AFTER Telegram exit alert
                        # (parity with ORB path) so cleanup cannot suppress alerts.
                        _tl_post_alert_quarantine = bool(unified_executor and pos_id_tl)
                        had_monitor_closes = True
                        slot_marker = None
                        try:
                            if isinstance(getattr(pos, "metadata", None), dict):
                                slot_marker = pos.metadata.get("trendline_open_slot_marker")
                        except Exception:
                            slot_marker = None
                        if slot_marker:
                            self._trendline_release_global_daily_slot(str(slot_marker))
                        self._refresh_trendline_slot_capital()
                    except Exception as post_close_cleanup_err:
                        had_monitor_closes = True
                        _tl_post_alert_quarantine = bool(unified_executor and pos_id_tl)
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=post_close_cleanup | trade_id=%s | symbol=%s | error=%s | "
                            "action=continue_exit_alert",
                            pos_id_tl,
                            sym_tl,
                            post_close_cleanup_err,
                        )
                    log.info(
                        "TRENDLINE_PIPELINE | stage=option_exit | symbol=%s | trade_id=%s | reason=%s | pnl_pct=%.4f",
                        pos.symbol,
                        pos.position_id,
                        reason,
                        pnl_pct,
                    )
                    log.info(
                        "OPTION_POSITION_EXIT | strategy=trendline_0dte | trigger=%s | trade_id=%s | symbol=%s | reason=%s | pnl_pct=%.4f",
                        trigger_source,
                        pos_id_tl,
                        sym_tl,
                        _safe_canonical_exit_reason(str(reason)),
                        float(pnl_pct),
                    )
                    try:
                        from modules.exit_observation_telemetry import (
                            log_mfe_decision,
                            mfe_decision_fields,
                        )

                        _os = (
                            (getattr(pos, "metadata", None) or {}).get("option_stealth")
                            if isinstance(getattr(pos, "metadata", None), dict)
                            else {}
                        )
                        _os = _os if isinstance(_os, dict) else {}
                        _diag = _os.get("exit_diagnostics") if isinstance(_os.get("exit_diagnostics"), dict) else {}
                        log_mfe_decision(
                            "EXIT_FILLED",
                            mfe_decision_fields(
                                trade_id=str(pos_id_tl or ""),
                                current_bid=float(exit_premium or 0.0) or None,
                                entry_premium=float(getattr(pos, "entry_price", 0.0) or 0.0) or None,
                                hwm_bid=_os.get("premium_hwm") or _diag.get("premium_high_water_mark"),
                                hwm_pnl_pct=_os.get("max_pnl_pct"),
                                quote_source=str(_os.get("last_premium_source") or ""),
                                confirmation_count=_os.get("mfe_giveback_gap_confirm_count"),
                            ),
                        )
                    except Exception:
                        pass
                    log.info(
                        "OPTIONS_STEALTH_EXIT | symbol=%s | strategy=trendline_0dte | trade_id=%s | reason=%s | pnl=%.4f",
                        pos.symbol,
                        pos.position_id,
                        reason,
                        pnl_pct,
                    )
                    log.info(
                        "OPTIONS_STEALTH_EXIT | reason=%s | pnl=%.4f | position_id=%s",
                        reason,
                        pnl_pct,
                        pos.position_id,
                    )
                    self._log_trendline_feature_events(
                        [c for c in self._pending_trendline_candidates if getattr(c, "executed_trade_id", None) == pos.position_id],
                        stage="option_exit",
                        closed_position=closed,
                        exit_telemetry=telem if isinstance(telem, dict) else None,
                    )
                    if self.alert_manager:
                        try:
                            if pos_id_tl in self._trendline_exit_alerts_sent:
                                log.info(
                                    "TRENDLINE_OPTION_EXIT_ALERT_DEDUPED | trade_id=%s | symbol=%s | reason=session_already_sent",
                                    pos_id_tl,
                                    sym_tl,
                                )
                            else:
                                from modules.runtime_mode import mode_label as runtime_mode_label

                                mode_label = runtime_mode_label()
                                account_balance_alert = float(
                                    self._orb_0dte_resolve_account_balance_for_alerts()
                                )
                                qty = int(max(1, int(getattr(pos, "quantity", 1) or 1)))
                                option_side = str(getattr(pos, "option_side", "") or "").upper()
                                entry_underlying = float(
                                    getattr(pos, "entry_underlying", 0.0)
                                    or (((getattr(pos, "metadata", None) or {}).get("signal_snapshot") or {}).get("entry_underlying_price") or 0.0)
                                )
                                try:
                                    from modules.underlying_freshness import resolve_exit_underlying_price

                                    exit_underlying_alert = resolve_exit_underlying_price(
                                        live_underlying=exit_underlying_alert,
                                        osnap=(
                                            (getattr(pos, "metadata", None) or {}).get("option_stealth")
                                            if isinstance(getattr(pos, "metadata", None), dict)
                                            else None
                                        ),
                                        position=pos,
                                        metadata=(
                                            getattr(pos, "metadata", None)
                                            if isinstance(getattr(pos, "metadata", None), dict)
                                            else None
                                        ),
                                        entry_underlying=entry_underlying,
                                        symbol_cache=getattr(
                                            self, "_orb_0dte_last_underlying_by_symbol", None
                                        ),
                                        symbol=sym_tl,
                                    )
                                except Exception:
                                    pass
                                estimated_total_cost = float(getattr(pos, "entry_cost", 0.0) or 0.0)
                                meta = getattr(pos, "metadata", None) if isinstance(getattr(pos, "metadata", None), dict) else {}
                                signal_snapshot = meta.get("signal_snapshot") if isinstance(meta.get("signal_snapshot"), dict) else {}
                                execution_payload = meta.get("execution_payload") if isinstance(meta.get("execution_payload"), dict) else {}
                                delta_entry_raw = (
                                    execution_payload.get("delta_at_entry")
                                    or signal_snapshot.get("delta_at_entry")
                                    or execution_payload.get("delta")
                                    or signal_snapshot.get("delta")
                                    or 0.0
                                )
                                delta_entry = float(delta_entry_raw or 0.0)
                                delta_exit = delta_entry
                                try:
                                    if isinstance(telem, dict):
                                        dq = telem.get("position_diagnostics") if isinstance(telem.get("position_diagnostics"), dict) else {}
                                        delta_exit = float(
                                            dq.get("effective_delta_estimate")
                                            or dq.get("delta_estimate")
                                            or delta_entry
                                        )
                                except Exception:
                                    delta_exit = delta_entry
                                strike_alert = float(getattr(pos, "strike", 0.0) or 0.0)
                                if strike_alert <= 0.0:
                                    norm_tl = meta.get("normalized_options") if isinstance(meta.get("normalized_options"), dict) else {}
                                    legs_tl = norm_tl.get("legs") if isinstance(norm_tl.get("legs"), list) else []
                                    if legs_tl and isinstance(legs_tl[0], dict):
                                        strike_alert = float(legs_tl[0].get("strike") or 0.0)
                                if strike_alert <= 0.0:
                                    strike_alert = entry_underlying
                                entry_premium_alert = float(
                                    signal_snapshot.get("entry_premium_per_contract")
                                    or signal_snapshot.get("entry_value")
                                    or 0.0
                                )
                                if entry_premium_alert <= 0.0 and float(getattr(pos, "entry_cost", 0.0) or 0.0) > 0:
                                    entry_premium_alert = float(pos.entry_cost) / max(1, qty) / 100.0
                                exit_premium_alert = float(exit_prem_alert or 0.0)
                                if exit_premium_alert <= 0.0 and float(est_value or 0.0) > 0:
                                    exit_premium_alert = float(est_value) / max(1, qty) / 100.0
                                exit_diag_alert = (
                                    telem.get("exit_diagnostics")
                                    if isinstance(telem, dict) and isinstance(telem.get("exit_diagnostics"), dict)
                                    else {}
                                )
                                osnap_alert = (
                                    meta.get("option_stealth")
                                    if isinstance(meta.get("option_stealth"), dict)
                                    else {}
                                )
                                entry_chain_alert = str(
                                    meta.get("entry_chain_source")
                                    or (meta.get("execution_payload") or {}).get("chain_source")
                                    or exit_diag_alert.get("entry_chain_source")
                                    or ""
                                )
                                mark_exit_grade_alert = exit_diag_alert.get("mark_is_exit_grade_at_exit")
                                if mark_exit_grade_alert is None:
                                    mark_exit_grade_alert = exit_diag_alert.get("mark_is_exit_grade")
                                if mark_exit_grade_alert is None and isinstance(
                                    getattr(pos, "metadata", None), dict
                                ):
                                    if isinstance(osnap_alert, dict):
                                        mark_exit_grade_alert = osnap_alert.get("mark_is_exit_grade")
                                dq_alert = (
                                    exit_diag_alert.get("data_quality")
                                    if isinstance(exit_diag_alert.get("data_quality"), dict)
                                    else {}
                                )
                                max_pnl_alert = float(
                                    exit_diag_alert.get("max_pnl_pct")
                                    or osnap_alert.get("max_pnl_pct")
                                    or 0.0
                                )
                                # Prefer liquidatable exit P&L (fraction). Snapshot/profit_retention
                                # may store percent points (e.g. 5.47). |v|>1.5 alone 100×'s
                                # +1.28%/+1.37% HWM (1.28/1.37 points) into +128%/+137%.
                                from modules.profit_retention_telemetry import (
                                    display_max_bid_pnl_fraction as _max_bid,
                                    first_present_number as _first_num,
                                    liquidatable_pnl_to_fraction as _liq_frac,
                                    premium_hwm_from_exit_metadata as _hwm_meta,
                                    reconcile_exit_liq_fraction as _exit_liq,
                                )

                                ps_alert = (
                                    meta.get("premium_snapshot")
                                    if isinstance(meta.get("premium_snapshot"), dict)
                                    else {}
                                )
                                pr_alert = (
                                    meta.get("profit_retention")
                                    if isinstance(meta.get("profit_retention"), dict)
                                    else {}
                                )
                                econ_summary_alert = (
                                    meta.get("economic_summary")
                                    if isinstance(meta.get("economic_summary"), dict)
                                    else {}
                                )
                                econ_alert = (
                                    econ_summary_alert.get("profit_retention")
                                    if isinstance(econ_summary_alert.get("profit_retention"), dict)
                                    else {}
                                )
                                econ_nums_alert = (
                                    econ_summary_alert.get("economics")
                                    if isinstance(econ_summary_alert.get("economics"), dict)
                                    else {}
                                )
                                # Jul 31 GOOGL: osnap still held decision-bid MFE (+34.375% at $0.43)
                                # while fill was $0.40 (+25%). Prefer fill-time retention / fill
                                # premium for Exit PnL (liq); keep Max from retention HWM.
                                max_from_ret = _liq_frac(
                                    pr_alert.get("max_liquidatable_pnl_pct")
                                    or econ_alert.get("max_liquidatable_pnl_pct"),
                                    engine_fraction=max_pnl_alert,
                                )
                                if max_from_ret is not None and abs(float(max_from_ret)) >= 1e-9:
                                    max_pnl_alert = float(max_from_ret)
                                hwm_alert = _hwm_meta(meta)
                                if hwm_alert is None:
                                    try:
                                        hwm_alert = float(osnap_alert.get("premium_hwm") or 0.0) or None
                                    except (TypeError, ValueError):
                                        hwm_alert = None
                                max_pnl_alert = float(
                                    _max_bid(
                                        max_pnl_alert,
                                        engine_fraction=max_pnl_alert,
                                        entry_premium=entry_premium_alert,
                                        premium_hwm=hwm_alert,
                                    )
                                )

                                fill_frac_alert = None
                                if entry_premium_alert > 0 and exit_premium_alert > 0:
                                    fill_frac_alert = (
                                        float(exit_premium_alert) - float(entry_premium_alert)
                                    ) / float(entry_premium_alert)
                                raw_exit_liq = _first_num(
                                    pr_alert.get("exit_liquidatable_pnl_pct"),
                                    econ_alert.get("exit_liquidatable_pnl_pct"),
                                    exit_diag_alert.get("current_pnl_pct_liquidation"),
                                    ps_alert.get("liquidatable_pnl_pct"),
                                    osnap_alert.get("current_pnl_pct_liquidation"),
                                )
                                exit_pnl_liq_alert = _exit_liq(
                                    raw_exit_liq,
                                    entry_premium=entry_premium_alert,
                                    exit_premium=exit_premium_alert,
                                    engine_fraction=fill_frac_alert,
                                )
                                # Header P&L: prefer fee-net economics when stamped; else ledger
                                # realized; only fall back to gross premium $ when net is missing.
                                alert_pnl_pct = float(pnl_pct)
                                alert_realized = float(closed.realized_pnl)
                                if econ_nums_alert.get("net_pnl") is not None:
                                    try:
                                        alert_realized = float(econ_nums_alert.get("net_pnl"))
                                    except (TypeError, ValueError):
                                        pass
                                if econ_nums_alert.get("net_pnl_pct") is not None:
                                    try:
                                        # Economics net_pnl_pct is already net/cost fraction
                                        # (MSFT 2026-08-19: 5.622842 = +562.28%). Do not run
                                        # liquidatable_pnl_to_fraction — |v|>1.5 treats moons
                                        # as percent-points and prints +5.62% with no Moon.
                                        alert_pnl_pct = float(econ_nums_alert.get("net_pnl_pct"))
                                    except (TypeError, ValueError):
                                        pass
                                diag_pnl = _liq_frac(exit_diag_alert.get("realized_pnl_pct"))
                                if diag_pnl is None:
                                    diag_pnl = _liq_frac(exit_diag_alert.get("pnl_pct"))
                                if entry_premium_alert > 0 and exit_premium_alert > 0:
                                    prem_pnl_pct = (
                                        float(exit_premium_alert) - float(entry_premium_alert)
                                    ) / float(entry_premium_alert)
                                    prem_realized = (
                                        float(exit_premium_alert) - float(entry_premium_alert)
                                    ) * 100.0 * float(qty)
                                    if abs(alert_pnl_pct) < 1e-9 and abs(prem_pnl_pct) >= 1e-9:
                                        alert_pnl_pct = prem_pnl_pct
                                    if abs(alert_realized) < 1e-9 and abs(prem_realized) >= 1e-9:
                                        alert_realized = prem_realized
                                if abs(alert_pnl_pct) < 1e-9 and diag_pnl is not None and abs(diag_pnl) >= 1e-9:
                                    alert_pnl_pct = float(diag_pnl)
                                    if abs(alert_realized) < 1e-9 and entry_premium_alert > 0:
                                        alert_realized = (
                                            float(alert_pnl_pct) * float(entry_premium_alert) * 100.0 * float(qty)
                                        )
                                # Exit PnL (liq): treat explicit ~0 as missing when premium/diag PnL is live.
                                if exit_pnl_liq_alert is None or (
                                    abs(float(exit_pnl_liq_alert)) < 1e-9
                                    and abs(float(alert_pnl_pct)) >= 1e-9
                                ):
                                    if entry_premium_alert > 0 and exit_premium_alert > 0:
                                        exit_pnl_liq_alert = (
                                            float(exit_premium_alert) - float(entry_premium_alert)
                                        ) / float(entry_premium_alert)
                                    else:
                                        exit_pnl_liq_alert = float(alert_pnl_pct)
                                quote_source_alert = str(
                                    exit_diag_alert.get("premium_source_at_exit")
                                    or exit_diag_alert.get("exit_source")
                                    or osnap_alert.get("last_premium_source")
                                    or "unknown"
                                )
                                quote_age_alert = float(
                                    dq_alert.get("quote_age_seconds")
                                    or exit_diag_alert.get("quote_age_seconds")
                                    or osnap_alert.get("quote_age_seconds")
                                    or 0.0
                                )
                                mark_quality_alert = str(
                                    exit_diag_alert.get("mark_quality_at_exit")
                                    or exit_diag_alert.get("mark_quality")
                                    or osnap_alert.get("mark_quality")
                                    or "unknown"
                                )
                                account_equity_at_entry = None
                                raw_equity = meta.get("account_equity_at_entry")
                                if raw_equity is not None:
                                    try:
                                        account_equity_at_entry = float(raw_equity)
                                    except (TypeError, ValueError):
                                        account_equity_at_entry = None
                                # Breakout fills ride this monitor path (shared TL executor).
                                # Route to Breakout Telegram — never silent-skip as trendline-owned.
                                from modules.prime_alert_manager import _position_dict_is_breakout_0dte

                                _exit_probe = {
                                    "strategy_type": str(
                                        getattr(pos, "strategy_type", "")
                                        or getattr(closed, "strategy_type", "")
                                        or ""
                                    ),
                                    "metadata": meta if isinstance(meta, dict) else {},
                                }
                                if _position_dict_is_breakout_0dte(_exit_probe):
                                    await self.alert_manager.send_breakout_position_exit_alert(
                                        symbol=pos.symbol,
                                        trade_id=pos.position_id,
                                        reason=_safe_canonical_exit_reason(str(reason)),
                                        realized_pnl=float(alert_realized),
                                        pnl_pct=float(alert_pnl_pct),
                                        account_balance=account_balance_alert,
                                        quantity=qty,
                                        option_side=option_side,
                                        strike_price=strike_alert,
                                        entry_underlying=entry_underlying,
                                        estimated_total_cost=estimated_total_cost,
                                        delta_at_entry=delta_entry,
                                        delta_at_exit=delta_exit,
                                        entry_premium=entry_premium_alert,
                                        exit_premium=exit_premium_alert,
                                        exit_underlying=float(exit_underlying_alert or 0.0),
                                        mode=mode_label,
                                        account_equity_at_entry=account_equity_at_entry,
                                        entry_chain_source=entry_chain_alert or None,
                                        mark_is_exit_grade=(
                                            bool(mark_exit_grade_alert)
                                            if mark_exit_grade_alert is not None
                                            else None
                                        ),
                                        exit_premium_adjusted=bool(
                                            exit_diag_alert.get("exit_premium_adjusted")
                                        ),
                                        exit_premium_adjustment_reason=str(
                                            exit_diag_alert.get("exit_premium_adjustment_reason")
                                            or ""
                                        )
                                        or None,
                                        modeled_premium_at_exit=exit_diag_alert.get(
                                            "modeled_premium_at_exit"
                                        ),
                                        max_pnl_pct=max_pnl_alert,
                                        current_pnl_pct_liquidation=float(exit_pnl_liq_alert),
                                        quote_source=quote_source_alert,
                                        quote_age_seconds=quote_age_alert,
                                        mark_quality=mark_quality_alert,
                                        metadata=meta if isinstance(meta, dict) else None,
                                    )
                                    try:
                                        from modules.breakout_watch import (
                                            arm_breakout_side_cooldown_after_exit,
                                        )

                                        # Arm once: 1h exited-side cooldown + re-arm opposite edge.
                                        # Do not also call maybe_release (now an alias) or the 1h window slides.
                                        arm_breakout_side_cooldown_after_exit(
                                            self,
                                            symbol=str(pos.symbol or ""),
                                            option_side=str(option_side or "") or None,
                                            reason="post_exit",
                                        )
                                    except Exception as bo_reentry_err:
                                        log.debug(
                                            "BREAKOUT_PIPELINE | stage=profit_reentry | "
                                            "action=skip | error=%s",
                                            bo_reentry_err,
                                        )
                                    if pos_id_tl:
                                        bo_sent = getattr(
                                            self.alert_manager, "_breakout_exit_alert_trade_ids", None
                                        )
                                        if isinstance(bo_sent, set):
                                            bo_sent.add(pos_id_tl)
                                else:
                                    await self.alert_manager.send_trendline_position_exit_alert(
                                        symbol=pos.symbol,
                                        trade_id=pos.position_id,
                                        reason=_safe_canonical_exit_reason(str(reason)),
                                        realized_pnl=float(alert_realized),
                                        pnl_pct=float(alert_pnl_pct),
                                        account_balance=account_balance_alert,
                                        quantity=qty,
                                        option_side=option_side,
                                        strike_price=strike_alert,
                                        entry_underlying=entry_underlying,
                                        estimated_total_cost=estimated_total_cost,
                                        delta_at_entry=delta_entry,
                                        delta_at_exit=delta_exit,
                                        entry_premium=entry_premium_alert,
                                        exit_premium=exit_premium_alert,
                                        exit_underlying=float(exit_underlying_alert or 0.0),
                                        mode=mode_label,
                                        account_equity_at_entry=account_equity_at_entry,
                                        entry_chain_source=entry_chain_alert or None,
                                        mark_is_exit_grade=(
                                            bool(mark_exit_grade_alert)
                                            if mark_exit_grade_alert is not None
                                            else None
                                        ),
                                        exit_premium_adjusted=bool(
                                            exit_diag_alert.get("exit_premium_adjusted")
                                        ),
                                        exit_premium_adjustment_reason=str(
                                            exit_diag_alert.get("exit_premium_adjustment_reason")
                                            or ""
                                        )
                                        or None,
                                        modeled_premium_at_exit=exit_diag_alert.get(
                                            "modeled_premium_at_exit"
                                        ),
                                        max_pnl_pct=max_pnl_alert,
                                        current_pnl_pct_liquidation=float(exit_pnl_liq_alert),
                                        quote_source=quote_source_alert,
                                        quote_age_seconds=quote_age_alert,
                                        mark_quality=mark_quality_alert,
                                        metadata=meta if isinstance(meta, dict) else None,
                                    )
                                    if pos_id_tl:
                                        self._trendline_exit_alerts_sent.add(pos_id_tl)
                        except Exception as trendline_exit_alert_err:
                            log.warning(
                                "TRENDLINE_PIPELINE | stage=exit | alert_error=%s",
                                trendline_exit_alert_err,
                            )
                    if _tl_post_alert_quarantine:
                        try:
                            self._orb_0dte_quarantine_ghost(pos_id_tl, "post_close_ledger")
                            self._orb_0dte_remove_demo_position_everywhere(
                                unified_executor, pos_id_tl
                            )
                        except Exception as quarantine_err:
                            log.warning(
                                "TRENDLINE_PIPELINE | stage=post_alert_quarantine | trade_id=%s | error=%s",
                                pos_id_tl,
                                quarantine_err,
                            )
                    self._update_trendline_execution_dataset_final(
                        trade_id=str(pos.position_id),
                        execution_ts=None,
                        final_pnl_pct=float(pnl_pct),
                    )

                now_ts = time.time()
                monitor_interval = int(get_config_value("TRENDLINE_MONITOR_ALERT_INTERVAL_SEC", 300))
                if (
                    self.alert_manager
                    and bool(getattr(self, "_trendline_monitor_alert_enabled", False))
                    and (now_ts - float(getattr(self, "_trendline_last_monitor_alert_ts", 0.0))) >= monitor_interval
                ):
                    try:
                        from modules.prime_alert_manager import _alert_mode_header_line
                        from modules.runtime_mode import mode_label as runtime_mode_label
                        from modules.unified_0dte_account import sync_unified_account_balance

                        mode_label = runtime_mode_label()
                        tl_open_ct = self._trendline_option_positions_count()
                        tl_closed_ct = int(
                            (getattr(self, "_trendline_lifecycle_session_stats", None) or {}).get(
                                "exits_confirmed", 0
                            )
                        )
                        monitor_state = (
                            int(tl_open_ct),
                            int(tl_closed_ct),
                            round(float(sync_unified_account_balance(self)), 2),
                            mode_label,
                        )
                        if bool(getattr(self, "_trendline_monitor_alert_only_on_change", True)) and monitor_state == getattr(self, "_trendline_last_monitor_alert_state", None):
                            self._trendline_last_monitor_alert_ts = now_ts
                        else:
                            global_monitor_slot_ok = self._trendline_try_claim_global_monitor_alert_slot(
                                mode_label=mode_label,
                                monitor_interval_sec=monitor_interval,
                            )
                            if not global_monitor_slot_ok:
                                self._trendline_last_monitor_alert_ts = now_ts
                            else:
                                await self.alert_manager.send_system_alert(
                                    title=(
                                        f"🔮 {ALERT_LABEL_EASY_TRENDLINE_0DTE} — Monitor\n"
                                        f"{_alert_mode_header_line(None)}"
                                    ),
                                    message=(
                                        f"Strategy: {ALERT_LABEL_EASY_TRENDLINE_0DTE} (options)\n"
                                        f"Open Positions: {tl_open_ct}\n"
                                        f"Closed Today: {tl_closed_ct}\n"
                                        f"Account Balance: ${sync_unified_account_balance(self):.2f}\n"
                                        "Ledger: unified 0DTE demo account (ORB + Trendline)"
                                    ),
                                )
                                self._trendline_last_monitor_alert_state = monitor_state
                                self._trendline_last_monitor_alert_ts = now_ts
                    except Exception as trendline_monitor_alert_err:
                        log.warning(
                            "TRENDLINE_PIPELINE | stage=monitor | alert_error=%s",
                            trendline_monitor_alert_err,
                        )

                if stealth and had_monitor_closes and not self._trendline_unified_open_positions():
                    stealth.log_options_exit_summary()

                unified_executor_tl = (
                    getattr(getattr(self, "dte0_manager", None), "options_executor", None)
                )
                try:
                    await self._trendline_guardrail_unclosable_survey(unified_executor_tl)
                except Exception as _tl_ug_err:
                    log.debug("TRENDLINE_UNCLOSABLE_SURVEY_SKIP | err=%s", _tl_ug_err)

                _tl_sum_now = time.time()
                _tl_sum_last = float(getattr(self, "_tl_stealth_monitor_summary_ts", 0.0) or 0.0)
                _tl_sum_sec = float(getattr(self, "_options_monitor_summary_sec", 180.0) or 180.0)
                _tl_sum_force = (
                    len(to_close) > 0
                    or int(tick_metrics.get("positions_degraded", 0) or 0) > 0
                )
                if _tl_sum_force or (_tl_sum_now - _tl_sum_last) >= _tl_sum_sec:
                    self._tl_stealth_monitor_summary_ts = _tl_sum_now
                    log.info(
                        "OPTIONS_STEALTH_MONITOR_SUMMARY | trigger=%s | book=tl_only | "
                        "open_positions=%d | processed=%d | exits=%d | degraded=%d | "
                        "live_quote_positions=%d | premium_sources=%s",
                        trigger_source,
                        self._trendline_option_positions_count(),
                        int(tick_metrics["positions_processed"]),
                        len(to_close),
                        int(tick_metrics["positions_degraded"]),
                        int(tick_metrics["positions_with_live_quotes"]),
                        dict(tick_metrics["premium_sources"]),
                    )

                if trigger_source == "fast_loop":
                    m = self._trendline_fast_monitor_metrics
                    m["ticks"] = int(m.get("ticks", 0)) + 1
                    m["equity_batches"] = int(m.get("equity_batches", 0)) + int(tick_metrics["equity_batches"])
                    m["chain_calls"] = int(m.get("chain_calls", 0)) + int(tick_metrics["chain_calls"])
                    m["chain_cache_hits"] = int(m.get("chain_cache_hits", 0)) + int(tick_metrics["chain_cache_hits"])
                    m["chain_cache_misses"] = int(m.get("chain_cache_misses", 0)) + int(tick_metrics["chain_cache_misses"])
                    ps = m.setdefault("premium_sources", {})
                    for k in ("option_mark_or_mid", "option_last", "modeled_proxy", "other"):
                        ps[k] = int(ps.get(k, 0)) + int(tick_metrics["premium_sources"].get(k, 0))
                    if int(m["ticks"]) % 12 == 0:
                        self._log_trendline_fast_monitor_metrics()
            finally:
                self._trendline_position_monitor_running = False
                self._trendline_last_monitor_cycle_completed_ts = time.time()

    def _log_orb_options_monitor_heartbeat(self) -> None:
        """Periodic ORB1 Breakout options monitor heartbeat and premium-source summary."""
        m = getattr(self, "_orb_0dte_monitor_metrics", None) or {}
        ps = m.get("premium_sources", {}) if isinstance(m.get("premium_sources"), dict) else {}
        processed = int(m.get("processed_positions", 0) or 0)
        degraded = (
            int(ps.get("modeled_proxy", 0) or 0)
            + int(ps.get("current_position_value_fallback", 0) or 0)
            + int(ps.get("missing_or_invalid", 0) or 0)
        )
        degraded_ratio = (float(degraded) / float(processed)) if processed > 0 else 0.0
        exits_signaled = int(m.get("exits_signaled", 0) or 0)
        exits_executed = int(m.get("exits_executed", 0) or 0)
        exit_conversion = (float(exits_executed) / float(exits_signaled)) if exits_signaled > 0 else 1.0
        log.info(
            "OPTIONS_STEALTH | stage=orb_monitor_heartbeat | open_positions=%s | processed=%s | exits_signaled=%s | "
            "exits_executed=%s | exit_execute_failures=%s | fast_loop_calls=%s | shared_loop_calls=%s | "
            "skipped_no_price=%s | quote_failures=%s | "
            "fallback_monitor_used=%s | ticks=%s",
            m.get("open_positions", 0),
            m.get("processed_positions", 0),
            m.get("exits_signaled", 0),
            m.get("exits_executed", 0),
            m.get("exit_execute_failures", 0),
            m.get("fast_loop_calls", 0),
            m.get("shared_loop_calls", 0),
            m.get("skipped_no_price", 0),
            m.get("quote_failures", 0),
            m.get("fallback_monitor_used", 0),
            m.get("ticks", 0),
        )
        log.info(
            "OPTIONS_STEALTH | stage=orb_monitor_health | open=%s | processed=%d | degraded=%d | "
            "degraded_ratio=%.2f | exits=%d/%d | exit_conversion=%.2f",
            m.get("open_positions", 0),
            processed,
            degraded,
            degraded_ratio,
            exits_executed,
            exits_signaled,
            exit_conversion,
        )
        if processed > 0 and degraded_ratio >= float(getattr(self, "_orb_0dte_degraded_warn_ratio", 0.60)):
            self._orb_0dte_degraded_ratio_consecutive = int(
                getattr(self, "_orb_0dte_degraded_ratio_consecutive", 0)
            ) + 1
        else:
            self._orb_0dte_degraded_ratio_consecutive = 0
            self._orb_0dte_last_degraded_warn_streak = 0
        streak = int(getattr(self, "_orb_0dte_degraded_ratio_consecutive", 0))
        threshold_hits = int(getattr(self, "_orb_0dte_degraded_warn_consecutive", 3))
        if streak >= threshold_hits and streak != int(getattr(self, "_orb_0dte_last_degraded_warn_streak", 0)):
            log.warning(
                "OPTIONS_STEALTH | stage=orb_monitor_health_warning | reason=degraded_quote_ratio_persistent | "
                "degraded_ratio=%.2f | threshold=%.2f | consecutive=%d | required=%d | open=%s | processed=%d",
                degraded_ratio,
                float(getattr(self, "_orb_0dte_degraded_warn_ratio", 0.60)),
                streak,
                threshold_hits,
                m.get("open_positions", 0),
                processed,
            )
            self._orb_0dte_last_degraded_warn_streak = streak
        if (
            bool(getattr(self, "_orb_0dte_degraded_entry_kill_switch_enabled", True))
            and not bool(
                getattr(self, "_0dte_entry_kill_switch_active", False)
                or getattr(self, "_orb_0dte_entry_kill_switch_active", False)
            )
            and streak >= int(getattr(self, "_orb_0dte_degraded_entry_kill_switch_consecutive", 3))
            and degraded_ratio >= float(getattr(self, "_orb_0dte_degraded_entry_kill_switch_ratio", 0.60))
        ):
            self._orb_0dte_entry_kill_switch_active = True
            self._0dte_entry_kill_switch_active = True
            log.warning(
                "0DTE_ENTRY_KILL_SWITCH_ACTIVATED | degraded_ratio=%.2f | ratio_threshold=%.2f | consecutive=%d | required=%d",
                float(degraded_ratio),
                float(getattr(self, "_orb_0dte_degraded_entry_kill_switch_ratio", 0.60)),
                int(streak),
                int(getattr(self, "_orb_0dte_degraded_entry_kill_switch_consecutive", 3)),
            )
        log.info(
            "OPTIONS_STEALTH | stage=orb_premium_source_summary | mark_or_mid=%s | last=%s | modeled=%s | "
            "position_value_fallback=%s | missing=%s",
            ps.get("mark_or_mid", 0),
            ps.get("last", 0),
            ps.get("modeled_proxy", 0),
            ps.get("current_position_value_fallback", 0),
            ps.get("missing_or_invalid", 0),
        )

    def _orb_0dte_maybe_log_position_lifecycle_snapshot(
        self,
        *,
        pos_id: str,
        symbol: str,
        lifecycle_rec: Dict[str, Any],
        osnap: Dict[str, Any],
        oq_orb: Dict[str, Any],
        quote_grade: str,
        quote_src: str,
        mark_exit: bool,
        good_ticks: int,
        min_exit_ticks: int,
        structural_type_lc: str,
        pos: Any,
        trigger_source: str,
    ) -> None:
        """Throttled consolidated ORB1 Breakout position lifecycle row for ops / replay (does not change exits)."""
        if not pos_id:
            return
        min_interval = float(getattr(self, "_orb_0dte_lifecycle_snapshot_log_sec", 30.0) or 30.0)
        now_ts = time.time()
        last = float(self._orb_0dte_last_lifecycle_snapshot_ts.get(pos_id, 0.0) or 0.0)
        if min_interval > 0 and (now_ts - last) < min_interval:
            return
        self._orb_0dte_last_lifecycle_snapshot_ts[pos_id] = now_ts
        meta = getattr(pos, "metadata", None) if pos is not None else None
        dur: Dict[str, Any] = {}
        if isinstance(meta, dict):
            d0 = meta.get("orb_0dte_durability")
            if isinstance(d0, dict):
                dur = d0
        exec_ok = bool(dur.get("execution_durable_confirmed"))
        exit_ok = bool(dur.get("exit_grade_durable_confirmed"))
        if not exec_ok:
            durable_stage = "pre_execution_durable"
        elif not exit_ok:
            durable_stage = "stage_a_execution_durable"
        else:
            durable_stage = "stage_b_exit_grade_durable"
        st_mark = bool(osnap.get("mark_is_exit_grade", mark_exit))
        timeout_frozen = bool(osnap.get("timeout_clock_frozen"))
        max_mfe = float(osnap.get("max_pnl_pct") or 0.0)
        mfe_active = bool(max_mfe > 0.0 or bool(osnap.get("had_opportunity")))
        be_armed = bool(osnap.get("breakeven_active"))
        trail_active = bool(osnap.get("trailing_active"))
        micro_lock_active = bool(osnap.get("micro_lock_active"))
        mq = str(osnap.get("mark_quality") or "").strip().lower()
        degraded_hold = mq in {"partial_leg", "stale_last_valid", "cached_recent"} and (not st_mark)
        if str(quote_grade or "").strip().lower() == "degraded":
            degraded_hold = True
        is_spread = "spread" in str(structural_type_lc or "").lower()
        wdog_gap = float(osnap.get("watchdog_gap_seconds") or 0.0)
        wdog_seen = bool(osnap.get("watchdog_gap_seen"))
        wd_thr = float(getattr(self, "_orb_0dte_monitor_watchdog_seconds", 20.0) or 20.0)
        monitor_stale_flag = bool(wdog_seen or wdog_gap >= max(1.0, wd_thr * 2.0))
        policy_exit_grade_hold = bool(
            exec_ok
            and (
                (not st_mark)
                or (int(good_ticks) < int(min_exit_ticks))
                or timeout_frozen
            )
        )
        if monitor_stale_flag:
            op_class = "monitor_stale_or_gap"
        elif policy_exit_grade_hold and (not st_mark):
            op_class = "intentional_exit_grade_policy_hold"
        else:
            op_class = "active_monitored_ok"
        px_telem = str(osnap.get("option_price_source_telemetry") or osnap.get("price_source_telemetry") or "")
        single_cached_recent_audit = "n/a"
        if (not is_spread) and mq == "cached_recent":
            single_cached_recent_audit = (
                f"be={str(be_armed).lower()}|mfe_pct={max_mfe:.4f}|trail={str(trail_active).lower()}|"
                f"micro_lock={str(micro_lock_active).lower()}|px_telem={px_telem}"
            )
        spread_relief_audit = "n/a"
        if is_spread:
            spread_relief_audit = (
                f"relief_active={str(bool(osnap.get('orb_spread_relief_active'))).lower()}|"
                f"tier={osnap.get('orb_spread_relief_tier') or 'none'}|"
                f"deferrals={int(osnap.get('orb_exit_defer_total') or 0)}|quote_grade={quote_grade}"
            )
        cpv = float(oq_orb.get("current_position_value") or 0.0)
        entry_px = float(getattr(pos, "entry_price", 0.0) or 0.0)
        pnl_pct_snap = 0.0
        ptype_lc = str(getattr(pos, "position_type", "") or "").lower()
        try:
            if entry_px > 0 and cpv > 0:
                if ptype_lc == "credit_spread":
                    pnl_pct_snap = ((entry_px - cpv) / entry_px) * 100.0
                else:
                    pnl_pct_snap = ((cpv - entry_px) / entry_px) * 100.0
        except Exception:
            pnl_pct_snap = 0.0
        trail_mode = str(osnap.get("trailing_mode") or "unknown")
        log.info(
            "ORB_0DTE_POSITION_LIFECYCLE_SNAPSHOT | trigger=%s | trade_id=%s | symbol=%s | is_open=true | durable_stage=%s | "
            "exit_grade_ready=%s | quote_grade=%s | quote_src=%s | mark_is_exit_grade=%s | timeout_clock_frozen=%s | "
            "MFE_active=%s | BE_armed=%s | trailing_active=%s | micro_lock_active=%s | degraded_hold_active=%s | "
            "operational_class=%s | current_premium=%.6f | current_pnl_pct=%.2f | max_pnl_pct=%.4f | trailing_mode=%s | "
            "single_leg_cached_recent_audit=%s | spread_degraded_relief_audit=%s",
            trigger_source,
            pos_id,
            symbol or "",
            durable_stage,
            str(bool(exit_ok)).lower(),
            quote_grade or "",
            quote_src or "",
            str(st_mark).lower(),
            str(timeout_frozen).lower(),
            str(mfe_active).lower(),
            str(be_armed).lower(),
            str(trail_active).lower(),
            str(micro_lock_active).lower(),
            str(degraded_hold).lower(),
            op_class,
            cpv,
            pnl_pct_snap,
            max_mfe,
            trail_mode,
            single_cached_recent_audit,
            spread_relief_audit,
        )
        # Single-line audit for ORB vs Trendline grep parity (Trendline uses OPTION_STEALTH_STATE; ORB uses this token).
        last_tick_ts = float(lifecycle_rec.get("last_monitor_tick_ts", 0.0) or 0.0)
        last_tick_age = max(0.0, now_ts - last_tick_ts) if last_tick_ts > 0 else -1.0
        registry_present = bool(pos_id in self.positions)
        monitor_present = bool(dur.get("monitor_attached")) or bool(isinstance(meta, dict) and isinstance(meta.get("option_stealth"), dict))
        hydrated = bool(dur.get("first_quote_hydrated"))
        exit_sig_ts = float(lifecycle_rec.get("exit_signalled_ts", 0.0) or 0.0)
        close_conf = bool(lifecycle_rec.get("close_confirmed"))
        close_pending = bool(exit_sig_ts > 0.0 and not close_conf)
        stealth_state = str(osnap.get("mode") or osnap.get("trailing_mode") or osnap.get("stealth_phase") or "").strip() or "unknown"
        last_eval = str(osnap.get("_last_eval_ts") or "").strip()
        exit_eval_running = bool(last_eval)
        executor_open = False
        try:
            ex = getattr(self, "dte0_manager", None) and getattr(self.dte0_manager, "options_executor", None)
            if ex:
                executor_open = any(
                    str(getattr(p, "position_id", "") or "").strip() == pos_id for p in (ex.get_open_positions() or [])
                )
        except Exception:
            executor_open = False
        eod_eligible = bool(executor_open)
        broadcast_pending = "n/a"
        if close_conf:
            broadcast_pending = "unknown_post_close"
        elif exit_sig_ts > 0.0:
            broadcast_pending = "true_if_close_succeeds"
        pnl_frac_stealth = float(pnl_pct_snap) / 100.0
        drawdown_from_mfe = max(0.0, float(max_mfe) - pnl_frac_stealth)
        timeout_clock_state = (
            "frozen"
            if timeout_frozen
            else ("degraded_running" if bool(osnap.get("orb_spread_degraded_running")) else "running")
        )
        monitor_alive = bool(last_tick_age < 0.0 or (last_tick_age >= 0.0 and last_tick_age < max(90.0, wd_thr * 4.0)))
        close_blocked_reason = str(osnap.get("orb_last_exit_hold_reason") or "none")
        close_candidate_reason = str(op_class)
        had_uo = bool(osnap.get("had_underlying_opportunity"))
        trusted_deg = bool(osnap.get("trusted_degraded_spread_mark"))
        degraded_run = bool(osnap.get("orb_spread_degraded_running"))
        alert_pending = bool(close_pending)
        log.info(
            "ORB_0DTE_LIFECYCLE_AUDIT | trigger=%s | trade_id=%s | symbol=%s | monitor_alive=%s | last_tick_age_sec=%.2f | "
            "timeout_clock_state=%s | degraded_running=%s | trusted_degraded=%s | quote_grade=%s | mark_quality=%s | "
            "exit_grade_ready=%s | had_underlying_opportunity=%s | be_armed=%s | trail_armed=%s | max_pnl_pct=%.4f | "
            "drawdown_from_mfe=%.4f | close_candidate_reason=%s | close_blocked_reason=%s | registry_present=%s | "
            "monitor_present=%s | hydrated=%s | exit_eval_seen=%s | executor_position_open=%s | stealth_state=%s | "
            "timeout_clock_frozen=%s | eod_eligible=%s | close_pending=%s | broadcast_pending=%s | alert_pending=%s | "
            "durable_exec=%s | durable_exit_grade=%s",
            trigger_source,
            pos_id,
            symbol or "",
            str(monitor_alive).lower(),
            float(last_tick_age),
            timeout_clock_state,
            str(degraded_run).lower(),
            str(trusted_deg).lower(),
            quote_grade or "",
            mq,
            str(st_mark).lower(),
            str(had_uo).lower(),
            str(be_armed).lower(),
            str(trail_active).lower(),
            float(max_mfe),
            float(drawdown_from_mfe),
            close_candidate_reason,
            close_blocked_reason,
            str(registry_present).lower(),
            str(monitor_present).lower(),
            str(hydrated).lower(),
            str(exit_eval_running).lower(),
            str(executor_open).lower(),
            stealth_state or "unknown",
            str(timeout_frozen).lower(),
            str(eod_eligible).lower(),
            str(close_pending).lower(),
            broadcast_pending,
            str(alert_pending).lower(),
            str(exec_ok).lower(),
            str(exit_ok).lower(),
        )
        try:
            stealth_eng = getattr(self, "orb_options_stealth", None)
            if stealth_eng is not None and getattr(stealth_eng, "config", None):
                from .prime_options_stealth_trailing_tp import _emit_option_stealth_state_if_due

                _emit_option_stealth_state_if_due(
                    cfg=stealth_eng.config,
                    trade_id=str(pos_id or "-"),
                    symbol=str(symbol or "-"),
                    message=(
                        f"ORB_0DTE_STEALTH_STATE | path=orb_monitor_audit | trade_id={pos_id} | symbol={symbol} | "
                        f"timeout_clock_state={timeout_clock_state} | degraded_running={str(degraded_run).lower()} | "
                        f"trusted_degraded={str(trusted_deg).lower()} | mark_quality={mq} | exit_grade_ready={str(st_mark).lower()} | "
                        f"relief={str(bool(osnap.get('orb_spread_relief_active'))).lower()}"
                    ),
                )
        except Exception:
            pass

    async def _orb_0dte_emit_position_status_heartbeat(self, wall_ts: float) -> None:
        """Per-position status lines on the ORB monitor heartbeat; optional system Telegram."""
        if not getattr(self, "dte0_manager", None) or not getattr(self.dte0_manager, "options_executor", None):
            return
        ex = self.dte0_manager.options_executor
        rows: List[str] = []
        open_positions = ex.get_open_positions() or []
        for p in open_positions:
            pid = str(getattr(p, "position_id", "") or "").strip()
            sym = str(getattr(p, "symbol", "") or "").strip()
            if not pid:
                continue
            meta = getattr(p, "metadata", None)
            osn: Dict[str, Any] = {}
            if isinstance(meta, dict) and isinstance(meta.get("option_stealth"), dict):
                osn = meta.get("option_stealth") or {}
            dur: Dict[str, Any] = {}
            if isinstance(meta, dict) and isinstance(meta.get("orb_0dte_durability"), dict):
                dur = meta.get("orb_0dte_durability") or {}
            cpv = float(getattr(p, "current_value", 0.0) or 0.0)
            ep = float(getattr(p, "entry_price", 0.0) or 0.0)
            pnl_pct = 0.0
            ptl = str(getattr(p, "position_type", "") or "").lower()
            try:
                if ep > 0 and cpv > 0:
                    pnl_pct = ((ep - cpv) / ep) * 100.0 if ptl == "credit_spread" else ((cpv - ep) / ep) * 100.0
            except Exception:
                pnl_pct = 0.0
            eg_ready = str(bool(dur.get("exit_grade_durable_confirmed"))).lower()
            mx = float(osn.get("max_pnl_pct") or 0.0)
            tf = str(bool(osn.get("timeout_clock_frozen"))).lower()
            tmode = str(osn.get("trailing_mode") or "-")
            log.info(
                "ORB_0DTE_POSITION_STATUS_HEARTBEAT | trade_id=%s | symbol=%s | state=OPEN | monitoring=active | "
                "exit_grade_ready=%s | timeout_clock_frozen=%s | current_premium=%.6f | current_pnl_pct=%.2f | MFE_pct=%.4f | "
                "trailing_active=%s | trailing_mode=%s",
                pid,
                sym,
                eg_ready,
                tf,
                cpv,
                pnl_pct,
                mx,
                str(bool(osn.get("trailing_active"))).lower(),
                tmode,
            )
            rows.append(
                f"{sym} | {pid} | pnl={pnl_pct:.1f}% | prem={cpv:.4f} | exit_gr={eg_ready} | frz={tf} | mfe={mx:.4f} | trail={tmode}"
            )
        if (
            rows
            and bool(getattr(self, "_orb_0dte_position_status_heartbeat_alert", False))
            and getattr(self, "alert_manager", None)
        ):
            try:
                body = "ORB1 Breakout position status heartbeat\n" + "\n".join(rows[:20])
                if len(body) > 3500:
                    body = body[:3490] + "…(truncated)"
                await self.alert_manager.send_system_alert("ORB1 Breakout Position Status Heartbeat", body)
            except Exception as e:
                log.warning("ORB_0DTE_POSITION_STATUS_HEARTBEAT_ALERT_FAIL | error=%s", e)

    @staticmethod
    def _orb_0dte_quote_grade_from_snap(osnap_post: Dict[str, Any], source: str) -> str:
        if bool(osnap_post.get("mark_is_exit_grade")):
            return "exit_grade"
        mq = str(osnap_post.get("mark_quality") or "").strip().lower()
        if mq == "cached_recent":
            return "cached_recent"
        if mq == "synthetic" or "synthetic" in str(source).lower():
            return "synthetic"
        if mq in {"live_two_leg_spread", "live_single_leg"}:
            return "exit_grade"
        return "degraded"

    def _orb_0dte_resolve_strategy_route_label(
        self,
        *,
        norm_meta: Optional[Dict[str, Any]],
        position: Any,
        signal: Any = None,
    ) -> str:
        nm = norm_meta if isinstance(norm_meta, dict) else {}
        raw = str(nm.get("orb_strategy_type") or "").strip()
        if raw:
            return raw
        pt = str(getattr(position, "strategy_type", "") or "").strip()
        if pt:
            return pt
        if signal is not None:
            st = str(getattr(signal, "strategy_type", "") or "").strip()
            if st:
                return st
        legs = nm.get("legs")
        if isinstance(legs, list) and len(legs) >= 2:
            return "debit_spread"
        if isinstance(legs, list) and len(legs) == 1:
            osid = str((legs[0] or {}).get("option_side") or "").lower()
            if osid == "put":
                return "single_leg_long_put"
            if osid == "call":
                return "single_leg_long_call"
        lp = str(getattr(position, "position_type", "") or "").lower()
        if lp == "debit_spread":
            return "debit_spread"
        if lp == "lotto":
            lc = getattr(position, "lotto_contract", None)
            if lc is not None:
                ot = str(getattr(lc, "option_type", "") or "").lower()
                return "single_leg_long_put" if ot == "put" else "single_leg_long_call"
        struct = str(nm.get("position_type") or "").strip().lower()
        if "spread" in struct and "debit" in struct:
            return "debit_spread"
        try:
            if getattr(position, "debit_spread", None) is not None:
                return "debit_spread"
            if getattr(position, "credit_spread", None) is not None:
                return "credit_spread"
            lc = getattr(position, "lotto_contract", None)
            if lc is not None:
                ot = str(getattr(lc, "option_type", "") or "").lower()
                return "single_leg_long_put" if ot == "put" else "single_leg_long_call"
        except Exception:
            pass
        return "unknown"


    def _options_lifecycle_record(
        self,
        lifecycle: Dict[str, Dict[str, Any]],
        *,
        trade_id: str,
        symbol: str,
        strategy_type: str,
        structural_position_type: str,
        quote_source: str,
        degraded_mode: bool,
        state: str,
        state_log_token: str,
        extras: Optional[Dict[str, Any]] = None,
    ) -> None:
        if not trade_id:
            return
        rec = lifecycle.setdefault(
            trade_id,
            {
                "trade_id": trade_id,
                "symbol": symbol,
                "strategy_type": strategy_type or "unknown",
                "structural_position_type": structural_position_type or "unknown",
                "state": "created",
                "state_history": set(),
                "last_monitor_tick_ts": 0.0,
                "exit_signalled_ts": 0.0,
                "close_confirmed": False,
                "pending_exit_reason": "",
                "pending_exit_premium": 0.0,
                "close_confirmation": {},
                "quality": {
                    "valid_quote_ticks": 0,
                    "degraded_quote_ticks": 0,
                    "stale_quote_ticks": 0,
                    "modeled_proxy_ticks": 0,
                    "missing_bid_ticks": 0,
                    "missing_ask_ticks": 0,
                    "spread_quote_failures": 0,
                    "quote_source_transitions": 0,
                    "max_quote_age_seconds": 0.0,
                    "monitor_tick_count": 0,
                },
                "last_quote_source": "",
            },
        )
        rec["symbol"] = symbol or rec.get("symbol", "unknown")
        rec["strategy_type"] = strategy_type or rec.get("strategy_type", "unknown")
        rec["structural_position_type"] = structural_position_type or rec.get("structural_position_type", "unknown")
        rec["state"] = state
        ts_iso = datetime.now(timezone.utc).isoformat()
        history = rec.setdefault("state_history", set())
        if state not in history:
            history.add(state)
            msg = (
                f"{state_log_token} | trade_id={trade_id} | symbol={rec['symbol']} | "
                f"strategy_type={rec['strategy_type']} | structural_position_type={rec['structural_position_type']} | "
                f"quote_source={quote_source or 'unknown'} | degraded_mode={str(bool(degraded_mode)).lower()} | "
                f"timestamp={ts_iso}"
            )
            if isinstance(extras, dict) and extras:
                extras_txt = " | ".join(f"{k}={v}" for k, v in extras.items())
                msg = f"{msg} | {extras_txt}"
            log.info(msg)

    def _orb_0dte_lifecycle_record(
        self,
        *,
        trade_id: str,
        symbol: str,
        strategy_type: str,
        structural_position_type: str,
        quote_source: str,
        degraded_mode: bool,
        state: str,
        state_log_token: str,
        extras: Optional[Dict[str, Any]] = None,
    ) -> None:
        self._options_lifecycle_record(
            self._orb_0dte_lifecycle,
            trade_id=trade_id,
            symbol=symbol,
            strategy_type=strategy_type,
            structural_position_type=structural_position_type,
            quote_source=quote_source,
            degraded_mode=degraded_mode,
            state=state,
            state_log_token=state_log_token,
            extras=extras,
        )

    async def _orb_0dte_ensure_exit_alert_sent(
        self,
        *,
        pos_id: str,
        symbol: str,
        exit_premium: float,
        reason: str,
        pos: Any,
        closed: Optional[Any],
        executor: Any,
        pnl_dollar: Optional[float] = None,
        pnl_pct: Optional[float] = None,
    ) -> bool:
        """Emit ORB1 Breakout exit Telegram when not already sent this session."""
        pid = str(pos_id or "").strip()
        if not pid or not self.alert_manager:
            return False
        if pid in self._orb_0dte_exit_alerts_sent:
            return True
        entry_price = float(getattr(pos, "entry_price", 0.0) or 0.0)
        qty = int(max(1, int(getattr(pos, "quantity", 1) or 1)))
        ex = float(exit_premium or 0.0)
        if pnl_pct is None or pnl_dollar is None:
            if entry_price > 0:
                pnl_pct = (ex - entry_price) / entry_price
                pnl_dollar = (ex - entry_price) * qty * 100.0
            else:
                pnl_pct = 0.0
                pnl_dollar = float(getattr(closed, "realized_pnl", 0.0) or 0.0) if closed else 0.0
        position_dict: Dict[str, Any]
        if closed is not None and hasattr(closed, "to_dict"):
            position_dict = closed.to_dict()
        elif hasattr(pos, "to_dict"):
            position_dict = pos.to_dict()
        else:
            position_dict = {
                "position_id": pid,
                "symbol": str(symbol or ""),
                "entry_price": entry_price,
                "quantity": qty,
            }
        position_dict["current_value"] = ex
        mode = "DEMO" if bool(getattr(executor, "demo_mode", False)) else "LIVE"
        account_balance = None
        if hasattr(executor, "_snapshot_alert_account_balance"):
            try:
                account_balance = executor._snapshot_alert_account_balance()
            except Exception:
                account_balance = None
        sent = await self.alert_manager.send_options_position_exit_alert(
            position=position_dict,
            exit_price=ex,
            exit_reason=_safe_canonical_exit_reason(str(reason or "")),
            holding_time_minutes=0,
            mode=mode,
            realized_pnl_override=float(pnl_dollar),
            pnl_pct_fraction_override=float(pnl_pct),
            account_balance_override=account_balance,
        )
        if sent:
            self._orb_0dte_exit_alerts_sent.add(pid)
            self._orb_0dte_lifecycle_session_stats["alerts_sent"] = int(
                self._orb_0dte_lifecycle_session_stats.get("alerts_sent", 0)
            ) + 1
        else:
            self._orb_0dte_lifecycle_session_stats["alerts_missing"] = int(
                self._orb_0dte_lifecycle_session_stats.get("alerts_missing", 0)
            ) + 1
        return bool(sent)

    def _offload_ledger_closed_alert_flush(self, *, executor: Any = None) -> None:
        """Telegram recovery must not sit on the owned evaluate spine."""
        from modules.ledger_alert_flush import offload_flush_task

        offload_flush_task(
            self,
            lambda: self._flush_pending_ledger_closed_exit_alert_recovery(executor=executor),
        )

    async def _flush_pending_ledger_closed_exit_alert_recovery(self, *, executor: Any = None) -> int:
        """Drain demo-filter queue: Telegram retries only. Ledger/fills stay put."""
        from modules.ledger_alert_flush import (
            flush_notification_batch,
            requeue_failed,
            take_flush_batch,
        )

        pending = getattr(self, "_pending_ledger_closed_alert_recovery", None)
        rows = take_flush_batch(pending)
        if not rows:
            return 0
        if not isinstance(pending, list):
            pending = []
            self._pending_ledger_closed_alert_recovery = pending
        ex = executor or getattr(getattr(self, "dte0_manager", None), "options_executor", None)
        if not ex:
            requeue_failed(pending, rows)
            return 0

        async def _send(item: Dict[str, Any]) -> bool:
            return await self._send_ledger_closed_exit_notification(item, executor=ex)

        return await flush_notification_batch(self, rows, pending=pending, send=_send)

    async def _send_ledger_closed_exit_notification(
        self,
        item: Dict[str, Any],
        *,
        executor: Any,
    ) -> bool:
        pid = str(item.get("pos_id") or "").strip()
        if not pid:
            return False
        already = (
            pid in getattr(self, "_orb_0dte_exit_alerts_sent", set())
            or pid in getattr(self, "_trendline_exit_alerts_sent", set())
            or pid
            in (getattr(getattr(self, "alert_manager", None), "_breakout_exit_alert_trade_ids", None) or set())
        )
        if already:
            return True
        sym = str(item.get("symbol") or "")
        pos = item.get("pos")
        from modules.prime_alert_manager import _position_dict_is_breakout_0dte
        from modules.unified_0dte_account import _position_strategy_type

        probe = {
            "strategy_type": str(getattr(pos, "strategy_type", "") or ""),
            "metadata": getattr(pos, "metadata", None)
            if isinstance(getattr(pos, "metadata", None), dict)
            else {},
        }
        st = _position_strategy_type(pos) if pos is not None else ""
        if "trendline" in st and "breakout" not in st and not _position_dict_is_breakout_0dte(probe):
            return bool(
                await self._trendline_recover_exit_from_ledger(
                    pos_id=pid,
                    symbol=sym,
                    executor=executor,
                    lifecycle_rec=self._trendline_lifecycle.get(pid, {}),
                    pos=pos,
                )
            )
        return bool(
            await self._orb_0dte_recover_exit_alert_from_ledger(
                pos_id=pid,
                symbol=sym,
                executor=executor,
                lifecycle_rec=self._orb_0dte_lifecycle.get(pid, {}),
                pos=pos,
            )
        )

    async def _orb_0dte_recover_exit_alert_from_ledger(
        self,
        *,
        pos_id: str,
        symbol: str,
        executor: Any,
        lifecycle_rec: Optional[Dict[str, Any]] = None,
        pos: Any = None,
    ) -> bool:
        """Recover exit Telegram when ledger shows closed but alert was never sent."""
        pid = str(pos_id or "").strip()
        if not pid:
            return False
        mock = getattr(executor, "mock_executor", None)
        row = None
        if mock is not None:
            for cand in getattr(mock, "closed_positions", []) or []:
                if str(getattr(cand, "position_id", "")) == pid:
                    row = cand
                    break
        row_source = "closed_ledger"
        if row is None:
            if pos is None:
                log.error(
                    "ORB_0DTE_EXIT_ALERT_RECOVERY_MISS | trade_id=%s | symbol=%s | reason=closed_row_not_found",
                    pid,
                    symbol,
                )
                return False
            row = pos
            row_source = "open_position_snapshot"
            log.warning(
                "ORB_0DTE_EXIT_ALERT_RECOVERY_FALLBACK | trade_id=%s | symbol=%s | source=%s",
                pid,
                symbol,
                row_source,
            )
        meta = getattr(row, "metadata", None) or {}
        if not isinstance(meta, dict):
            meta = {}
        econ_exit = (meta.get("economic_summary") or {}).get("exit") or {}
        lifecycle = lifecycle_rec if isinstance(lifecycle_rec, dict) else {}
        close_conf = lifecycle.get("close_confirmation") or {}
        if not isinstance(close_conf, dict):
            close_conf = {}
        exit_premium = float(
            econ_exit.get("fill")
            or getattr(row, "current_value", 0.0)
            or close_conf.get("filled_exit_price")
            or close_conf.get("requested_exit_price")
            or lifecycle.get("pending_exit_premium", 0.0)
            or getattr(row, "entry_price", 0.0)
            or 0.0
        )
        reason = str(
            meta.get("exit_reason")
            or close_conf.get("close_reason")
            or lifecycle.get("pending_exit_reason")
            or "closed"
        )
        entry_price = float(getattr(row, "entry_price", 0.0) or 0.0)
        qty = int(max(1, int(getattr(row, "quantity", 1) or 1)))
        raw_pnl = getattr(row, "realized_pnl", None)
        if raw_pnl is None:
            pnl_dollar = (float(exit_premium or 0.0) - entry_price) * qty * 100.0
        else:
            pnl_dollar = float(raw_pnl or 0.0)
        pnl_pct = (pnl_dollar / (entry_price * qty * 100.0)) if entry_price > 0 else 0.0
        sym = str(symbol or getattr(row, "symbol", "") or "").strip()
        exit_underlying = float(self._orb_0dte_last_underlying_by_symbol.get(sym.upper(), 0.0) or 0.0)
        self._profit_optimizer_observe_0dte_exit(
            trade_id=pid,
            symbol=sym,
            position=row,
            exit_premium=float(exit_premium or 0.0),
            exit_underlying=exit_underlying,
            exit_reason=reason,
            entry_premium=float(entry_price or 0.0) or None,
            realized_pnl=float(pnl_dollar or 0.0),
            realized_pnl_pct=float(pnl_pct),
            option_side=str(getattr(row, "option_side", "") or "") or None,
        )
        if pid in self._orb_0dte_exit_alerts_sent:
            log.info(
                "ORB_0DTE_EXIT_ALERT_RECOVERY_STATUS | trade_id=%s | symbol=%s | sent=true | deduped=true | source=%s",
                pid,
                sym,
                row_source,
            )
            return True
        sent = await self._orb_0dte_ensure_exit_alert_sent(
            pos_id=pid,
            symbol=sym,
            exit_premium=exit_premium,
            reason=reason,
            pos=row,
            closed=row if row_source == "closed_ledger" else None,
            executor=executor,
            pnl_dollar=pnl_dollar,
            pnl_pct=pnl_pct,
        )
        log.info(
            "ORB_0DTE_EXIT_ALERT_RECOVERY_STATUS | trade_id=%s | symbol=%s | sent=%s | deduped=false | source=%s",
            pid,
            sym,
            bool(sent),
            row_source,
        )
        return bool(sent)

    async def _trendline_recover_exit_from_ledger(
        self,
        *,
        pos_id: str,
        symbol: str,
        executor: Any,
        lifecycle_rec: Optional[Dict[str, Any]] = None,
        pos: Any = None,
    ) -> bool:
        """Recover Trendline exit Telegram + PO observe when ledger closed before monitor side effects."""
        pid = str(pos_id or "").strip()
        if not pid:
            return False
        mock = getattr(executor, "mock_executor", None)
        row = pos
        if mock is not None:
            for cand in getattr(mock, "closed_positions", []) or []:
                if str(getattr(cand, "position_id", "")) == pid:
                    row = cand
                    break
        if row is None:
            return False
        meta = getattr(row, "metadata", None) or {}
        if not isinstance(meta, dict):
            meta = {}
        econ_exit = (meta.get("economic_summary") or {}).get("exit") or {}
        exit_premium = float(
            econ_exit.get("fill")
            or getattr(row, "current_value", 0.0)
            or (lifecycle_rec.get("pending_exit_premium", 0.0) if isinstance(lifecycle_rec, dict) else 0.0)
        )
        reason = str(
            meta.get("exit_reason")
            or (lifecycle_rec or {}).get("pending_exit_reason")
            or "closed"
        )
        pnl_dollar = float(getattr(row, "realized_pnl", 0.0) or 0.0)
        entry_price = float(getattr(row, "entry_price", 0.0) or 0.0)
        qty = int(max(1, int(getattr(row, "quantity", 1) or 1)))
        pnl_pct = (pnl_dollar / (entry_price * qty * 100.0)) if entry_price > 0 else 0.0
        sym = str(symbol or getattr(row, "symbol", "") or "").strip()
        exit_underlying = float(
            self._trendline_last_price_by_symbol.get(sym.upper(), 0.0)
            or self._orb_0dte_last_underlying_by_symbol.get(sym.upper(), 0.0)
            or 0.0
        )
        self._profit_optimizer_observe_0dte_exit(
            trade_id=pid,
            symbol=sym,
            position=row,
            exit_premium=float(exit_premium or 0.0),
            exit_underlying=exit_underlying,
            exit_reason=reason,
            entry_premium=float(entry_price or 0.0) or None,
            realized_pnl=float(pnl_dollar or 0.0),
            realized_pnl_pct=float(pnl_pct),
            strategy="trendline_0dte",
            option_side=str(getattr(row, "option_side", "") or "") or None,
            _skip_po_exit_snapshot=True,
        )
        try:
            self._save_trendline_exit_priority_snapshot(
                symbol=sym,
                trade_id=pid,
                option_side=str(getattr(row, "option_side", "") or "") or None,
                exit_reason=reason,
                exit_premium=float(exit_premium or 0.0) or None,
                entry_premium=float(entry_price or 0.0) or None,
                realized_pnl=float(pnl_dollar or 0.0),
                realized_pnl_pct=float(pnl_pct or 0.0),
                exit_underlying=float(exit_underlying or 0.0) or None,
                position=row,
                extra={"via": "trendline_recover_exit_from_ledger"},
            )
        except Exception as _tl_rec_snap_exc:
            log.debug("Trendline ledger-recovery exit snapshot skipped: %s", _tl_rec_snap_exc)
        if not self.alert_manager:
            return False
        # Already alerted via Breakout or Trendline session sets — treat as recovered.
        bo_sent = getattr(self.alert_manager, "_breakout_exit_alert_trade_ids", None) or set()
        if pid in getattr(self, "_trendline_exit_alerts_sent", set()) or pid in bo_sent:
            return True
        if pid in getattr(self, "_orb_0dte_exit_alerts_sent", set()):
            return True
        try:
            from modules.prime_alert_manager import _position_dict_is_breakout_0dte
            from modules.runtime_mode import mode_label as runtime_mode_label

            mode_label = runtime_mode_label()
            account_balance = float(self._orb_0dte_resolve_account_balance_for_alerts())
            probe = {
                "strategy_type": str(getattr(row, "strategy_type", "") or ""),
                "metadata": meta if isinstance(meta, dict) else {},
            }
            strike = float(getattr(row, "strike", 0.0) or 0.0)
            if strike <= 0.0 and isinstance(meta, dict):
                norm = meta.get("normalized_options") if isinstance(meta.get("normalized_options"), dict) else {}
                legs = norm.get("legs") if isinstance(norm.get("legs"), list) else []
                if legs and isinstance(legs[0], dict):
                    strike = float(legs[0].get("strike") or 0.0)
            common_kwargs = dict(
                symbol=sym,
                trade_id=pid,
                reason=_safe_canonical_exit_reason(reason),
                realized_pnl=float(pnl_dollar),
                pnl_pct=float(pnl_pct),
                account_balance=account_balance,
                quantity=qty,
                option_side=str(getattr(row, "option_side", "") or "").upper(),
                strike_price=strike,
                entry_underlying=exit_underlying,
                estimated_total_cost=float(entry_price * qty * 100.0),
                delta_at_entry=0.0,
                delta_at_exit=0.0,
                entry_premium=float(entry_price),
                exit_premium=float(exit_premium or 0.0),
                exit_underlying=exit_underlying,
                mode=mode_label,
            )
            if _position_dict_is_breakout_0dte(probe):
                sent = await self.alert_manager.send_breakout_position_exit_alert(
                    **common_kwargs,
                    metadata=meta if isinstance(meta, dict) else None,
                )
                if sent:
                    if isinstance(bo_sent, set):
                        bo_sent.add(pid)
                    self._orb_0dte_exit_alerts_sent.add(pid)
                log.info(
                    "TRENDLINE_EXIT_RECOVER_STATUS | trade_id=%s | symbol=%s | sent=%s | route=breakout",
                    pid,
                    sym,
                    bool(sent),
                )
                return bool(sent)
            sent = await self.alert_manager.send_trendline_position_exit_alert(
                **common_kwargs,
                metadata=meta if isinstance(meta, dict) else None,
            )
            if sent:
                self._trendline_exit_alerts_sent.add(pid)
            log.info(
                "TRENDLINE_EXIT_RECOVER_STATUS | trade_id=%s | symbol=%s | sent=%s | route=trendline",
                pid,
                sym,
                bool(sent),
            )
            return bool(sent)
        except Exception as exc:
            log.warning(
                "TRENDLINE_EXIT_RECOVER_FAILED | trade_id=%s | symbol=%s | err=%s",
                pid,
                sym,
                exc,
            )
            return False

    def _trendline_lifecycle_record(
        self,
        *,
        trade_id: str,
        symbol: str,
        strategy_type: str,
        structural_position_type: str,
        quote_source: str,
        degraded_mode: bool,
        state: str,
        state_log_token: str,
        extras: Optional[Dict[str, Any]] = None,
    ) -> None:
        self._options_lifecycle_record(
            self._trendline_lifecycle,
            trade_id=trade_id,
            symbol=symbol,
            strategy_type=strategy_type,
            structural_position_type=structural_position_type,
            quote_source=quote_source,
            degraded_mode=degraded_mode,
            state=state,
            state_log_token=state_log_token,
            extras=extras,
        )

    def _orb_0dte_update_durability_state(
        self,
        *,
        trade_id: str,
        symbol: str,
        option_side: str,
        strategy_type: str,
        position_type: str,
        source_path: str,
        state: str,
        registry_present: bool,
        monitor_attached: bool,
        quote_source: str,
        quote_age_ms: float,
        leg_quote_completeness: str,
        alert_eligible: bool,
        failure_reason: str = "",
    ) -> None:
        if not trade_id:
            return
        rec = self._orb_0dte_durability_registry.setdefault(trade_id, {})
        prior_state = str(rec.get("state") or "")
        try:
            from modules.orb_0dte_durability_latch import stage_a_latch_blocks
        except Exception:
            stage_a_latch_blocks = None  # type: ignore
        if stage_a_latch_blocks is not None and stage_a_latch_blocks(prior_state, state):
            rec["monitor_attached"] = bool(rec.get("monitor_attached") or monitor_attached)
            rec["registry_present"] = bool(registry_present or rec.get("registry_present"))
            rec["updated_at"] = datetime.now(timezone.utc).isoformat()
            log.info(
                "ORB_0DTE_DURABILITY_LATCH | trade_id=%s | symbol=%s | keep=%s | skip=%s | reason=no_regress_stage_a",
                trade_id,
                symbol,
                prior_state,
                state,
            )
            return
        rec.update(
            {
                "trade_id": trade_id,
                "symbol": symbol,
                "option_side": option_side or rec.get("option_side", "unknown"),
                "strategy_type": strategy_type or rec.get("strategy_type", "unknown"),
                "position_type": position_type or rec.get("position_type", "unknown"),
                "source_path": source_path or rec.get("source_path", "unknown"),
                "state": state,
                "registry_present": bool(registry_present),
                "monitor_attached": bool(monitor_attached),
                "quote_source": quote_source or "unknown",
                "quote_age_ms": float(max(0.0, quote_age_ms)),
                "leg_quote_completeness": leg_quote_completeness or "unknown",
                "alert_eligible": bool(alert_eligible),
                "failure_reason": failure_reason or "",
                "updated_at": datetime.now(timezone.utc).isoformat(),
            }
        )
        if prior_state != state:
            log.info(
                "ORB_0DTE_DURABILITY_STATE_TRANSITION | trade_id=%s | symbol=%s | from=%s | to=%s | alert_eligible=%s",
                trade_id,
                symbol,
                prior_state or "none",
                state,
                str(bool(alert_eligible)).lower(),
            )
        if state == "durability_failed":
            self._orb_0dte_durability_failures[trade_id] = dict(rec)
            self._orb_0dte_submitted_not_durable.pop(trade_id, None)
        elif state != "durable_position_confirmed" and not bool(alert_eligible):
            self._orb_0dte_submitted_not_durable[trade_id] = dict(rec)
        else:
            self._orb_0dte_submitted_not_durable.pop(trade_id, None)
            self._orb_0dte_durability_failures.pop(trade_id, None)
        log.info(
            "ORB_0DTE_DURABILITY_STATE | trade_id=%s | symbol=%s | state=%s | option_side=%s | strategy_type=%s | "
            "position_type=%s | source_path=%s | registry_present=%s | monitor_attached=%s | quote_source=%s | "
            "quote_age_ms=%.1f | leg_quote_completeness=%s | alert_eligible=%s | failure_reason=%s",
            trade_id,
            symbol,
            state,
            option_side or "unknown",
            strategy_type or "unknown",
            position_type or "unknown",
            source_path or "unknown",
            str(bool(registry_present)).lower(),
            str(bool(monitor_attached)).lower(),
            quote_source or "unknown",
            float(max(0.0, quote_age_ms)),
            leg_quote_completeness or "unknown",
            str(bool(alert_eligible)).lower(),
            failure_reason or "",
        )

    async def _orb_0dte_reconcile_pending_durability(
        self,
        *,
        pending_rows: List[Dict[str, Any]],
        run_id: str,
        wait_seconds: float,
    ) -> Dict[str, List[Dict[str, Any]]]:
        """Recheck pending submissions so durability lag is not reported as hard failure."""
        wait_s = float(max(0.0, wait_seconds))
        log.info(
            "ORB_0DTE_DURABILITY_RECONCILE_START | run_id=%s | pending_count=%d | wait_seconds=%.1f",
            run_id,
            len(pending_rows),
            wait_s,
        )
        try:
            await self.monitor_0dte_options_positions(
                trigger_source="durability_reconcile_pre",
                tick_id=f"{run_id}_pre",
            )
            log.info("ORB_0DTE_DURABILITY_RECONCILE_PUMP | run_id=%s | phase=pre | status=ok", run_id)
        except Exception as _pump_pre:
            log.warning(
                "ORB_0DTE_DURABILITY_RECONCILE_PUMP | run_id=%s | phase=pre | status=fail | error=%s",
                run_id,
                _pump_pre,
            )
        if wait_s > 0:
            await asyncio.sleep(wait_s)
        try:
            await self.monitor_0dte_options_positions(
                trigger_source="durability_reconcile_post",
                tick_id=f"{run_id}_post",
            )
            log.info("ORB_0DTE_DURABILITY_RECONCILE_PUMP | run_id=%s | phase=post | status=ok", run_id)
        except Exception as _pump_post:
            log.warning(
                "ORB_0DTE_DURABILITY_RECONCILE_PUMP | run_id=%s | phase=post | status=fail | error=%s",
                run_id,
                _pump_post,
            )

        reconciled = {
            "durable_executed": [],
            "monitoring_active_not_yet_durable": [],
            "submitted_pending_confirmation": [],
            "durability_failed": [],
        }

        for row in pending_rows:
            symbol = str(row.get("symbol", "UNKNOWN") or "UNKNOWN")
            trade_id = str(row.get("position_id", "") or "").strip()
            order_id = str(row.get("order_id", "") or "")
            prior_state = str(row.get("prior_state", "submitted_not_durable") or "submitted_not_durable")

            dur = self._orb_0dte_durability_registry.get(trade_id, {}) if trade_id else {}
            if trade_id and trade_id in self.positions:
                pm = getattr(self.positions[trade_id], "metadata", None)
                if isinstance(pm, dict):
                    od = pm.get("orb_0dte_durability")
                    if isinstance(od, dict):
                        merged = dict(dur)
                        merged.update(od)
                        dur = merged
            lifecycle = self._orb_0dte_lifecycle.get(trade_id, {}) if trade_id else {}
            position_obj = self.positions.get(trade_id) if trade_id else None

            monitor_state = str(
                dur.get("state")
                or lifecycle.get("state")
                or ("position_registered" if position_obj is not None else "unknown")
            )
            durable_position_confirmed = bool(dur.get("alert_eligible")) or bool(
                monitor_state == "durable_position_confirmed"
            ) or bool(monitor_state == "execution_durable_confirmed") or bool(dur.get("execution_durable_confirmed"))
            failure_reason = str(dur.get("failure_reason", "") or "")
            monitor_attached = bool(dur.get("monitor_attached")) or bool(monitor_state == "monitoring_active")
            registry_present = bool(dur.get("registry_present")) or bool(position_obj is not None)

            if failure_reason or monitor_state == "durability_failed":
                reconciled_state = "durability_failed"
                counted_as = "durability_failed"
                reconciled["durability_failed"].append(row)
            elif (
                trade_id in getattr(self, "_orb_0dte_exit_alerts_sent", set())
                or str(lifecycle.get("state") or "") == "closed"
            ):
                reconciled_state = "already_closed"
                counted_as = "durable_executed"
                row["reason"] = "Already closed before durability reconcile finished"
                row["reason_code"] = "already_closed"
                reconciled["durable_executed"].append(row)
            elif durable_position_confirmed:
                reconciled_state = "durable_position_confirmed"
                counted_as = "durable_executed"
                row["reason"] = "Durable position confirmed"
                row["reason_code"] = "durable_confirmed"
                reconciled["durable_executed"].append(row)
            elif monitor_attached or registry_present:
                reconciled_state = monitor_state if monitor_state != "unknown" else "monitoring_active"
                counted_as = "monitoring_active_not_yet_durable"
                row["reason"] = "Submitted, monitoring active (durability pending)"
                row["reason_code"] = "monitoring_active_not_yet_durable"
                reconciled["monitoring_active_not_yet_durable"].append(row)
            else:
                reconciled_state = "submitted_pending_confirmation"
                counted_as = "submitted_pending_confirmation"
                row["reason"] = "Submitted, pending durable confirmation"
                row["reason_code"] = "submitted_pending_confirmation"
                reconciled["submitted_pending_confirmation"].append(row)

            row["monitor_state"] = monitor_state
            log.info(
                "ORB_0DTE_DURABILITY_RECONCILE_RESULT | run_id=%s | symbol=%s | trade_id=%s | order_id=%s | "
                "prior_state=%s | reconciled_state=%s | durable_position_confirmed=%s | monitor_state=%s | counted_as=%s",
                run_id,
                symbol,
                trade_id or "unknown",
                order_id or "unknown",
                prior_state,
                reconciled_state,
                str(bool(durable_position_confirmed)).lower(),
                monitor_state,
                counted_as,
            )

        return reconciled

    def _orb_0dte_resolve_account_balance_for_alerts(self) -> float:
        """Best-effort account balance for 0DTE Telegram formatting (matches execution alert sourcing)."""
        bal = 5000.0
        try:
            dte0_manager = getattr(self, "dte0_manager", None)
            options_executor = getattr(dte0_manager, "options_executor", None) if dte0_manager else None
            if not options_executor:
                return bal
            if getattr(options_executor, "demo_mode", False) and getattr(options_executor, "mock_executor", None):
                bal = float(getattr(options_executor.mock_executor, "account_balance", bal) or bal)
                return bal
            snap_fn = getattr(options_executor, "_snapshot_alert_account_balance", None)
            if callable(snap_fn):
                snap = snap_fn()
                if snap is not None:
                    return float(snap)
            api = getattr(options_executor, "etrade_options_api", None)
            if api and getattr(api, "is_available", lambda: False)() and getattr(api, "etrade", None):
                account_balance_obj = api.etrade.get_account_balance()
                if account_balance_obj:
                    bal = (
                        float(account_balance_obj.cash_available_for_investment or 0.0)
                        or float(account_balance_obj.account_value or 0.0)
                        or bal
                    )
        except Exception:
            pass
        return bal

    def _orb_0dte_telegram_mode(self, position: Any = None) -> str:
        """DEMO/LIVE header for 0DTE Telegram — runtime MODE (demo|live), not Cloud Run service."""
        try:
            from .runtime_mode import mode_label

            return mode_label()
        except Exception:
            pass
        if position is not None:
            pid = str(getattr(position, "position_id", "") or "")
            if pid.upper().startswith("DEMO_"):
                return "DEMO"
            if bool(getattr(position, "is_demo", False)):
                return "DEMO"
        dte0_manager = getattr(self, "dte0_manager", None)
        options_executor = getattr(dte0_manager, "options_executor", None) if dte0_manager else None
        if options_executor is not None:
            return "DEMO" if bool(getattr(options_executor, "demo_mode", False)) else "LIVE"
        return "DEMO"

    def _orb_0dte_merge_buffered_durable_metadata_into_positions(
        self,
        executed_positions_dict: List[Dict[str, Any]],
    ) -> None:
        """Copy Stage-A quote telemetry from deferred durability rows into execution-alert dicts."""
        rows = getattr(self, "_orb_0dte_pending_durable_telegram_rows", None) or []
        if not rows:
            return
        by_id: Dict[str, Dict[str, Any]] = {}
        for r in rows:
            if not isinstance(r, dict):
                continue
            pid = str(r.get("position_id") or "").strip()
            if pid:
                by_id[pid] = r
        for pos in executed_positions_dict or []:
            if not isinstance(pos, dict):
                continue
            tid = str(pos.get("position_id") or "").strip()
            row = by_id.get(tid)
            if not row:
                continue
            pos["execution_durable_quote_grade"] = str(row.get("quote_grade") or "degraded")
            pos["execution_durable_quote_source"] = str(row.get("quote_source") or "unknown")
            pos["execution_durable_exit_grade_ready"] = bool(row.get("exit_grade_ready", False))
            pos["execution_durable_good_mark_ticks"] = int(row.get("good_mark_ticks") or 0)

    async def _orb_0dte_maybe_send_durability_followup_alert(
        self,
        *,
        trade_id: str,
        symbol: str,
        position: Any,
        source_quote: str,
        quote_grade: str = "degraded",
        exit_grade_ready: bool = False,
        good_mark_ticks: int = 0,
    ) -> None:
        tid = str(trade_id or "").strip()
        if not tid or tid in self._orb_0dte_durability_followup_alerted:
            return
        if not self.alert_manager:
            return
        pos_meta = getattr(position, "metadata", None)
        option_side = "unknown"
        if isinstance(pos_meta, dict):
            option_side = str(
                ((pos_meta.get("option_stealth") or {}) if isinstance(pos_meta.get("option_stealth"), dict) else {}).get("option_side")
                or option_side
            )

        row: Dict[str, Any]
        try:
            if hasattr(position, "to_dict"):
                raw = position.to_dict()
                row = raw if isinstance(raw, dict) else {}
            else:
                row = {}
            row.setdefault("position_id", tid)
            row.setdefault("symbol", str(symbol or "UNKNOWN"))
            row.setdefault("entry_price", float(getattr(position, "entry_price", 0.0) or 0.0))
            row.setdefault("quantity", int(getattr(position, "quantity", 0) or 0))
            row.setdefault("position_type", str(getattr(position, "position_type", "") or "unknown"))

            enrich: Dict[str, Any] = {}
            if isinstance(pos_meta, dict):
                ed = pos_meta.get("orb_0dte_alert_enrichment")
                if isinstance(ed, dict):
                    enrich = ed
            for key in (
                "priority_rank",
                "priority_score",
                "capital_allocated",
                "confidence",
                "momentum_score",
                "underlying_price",
            ):
                if key in enrich and enrich.get(key) is not None:
                    row[key] = enrich[key]

            acct_snap = enrich.get("account_balance_snapshot")
            if acct_snap is not None and float(acct_snap or 0) > 0:
                row["account_balance"] = float(acct_snap)
            else:
                row["account_balance"] = float(self._orb_0dte_resolve_account_balance_for_alerts())

            if not float(row.get("capital_allocated") or 0):
                ep = float(row.get("entry_price") or 0.0)
                q = int(row.get("quantity") or 0)
                row["capital_allocated"] = ep * max(1, q) * 100.0

            row["quote_source"] = str(source_quote or "unknown")
            row["quote_grade"] = str(quote_grade or "degraded")
            row["exit_grade_ready"] = bool(exit_grade_ready)
            row["good_mark_ticks"] = int(good_mark_ticks or 0)
        except Exception:
            row = {
                "symbol": str(symbol or "UNKNOWN"),
                "position_id": tid,
                "option_type": option_side,
                "strategy_type": str(
                    self._orb_0dte_resolve_strategy_route_label(
                        norm_meta=(pos_meta.get("normalized_options") if isinstance(pos_meta, dict) else None),
                        position=position,
                        signal=None,
                    )
                    or getattr(position, "strategy_type", "")
                    or "unknown"
                ),
                "position_type": str(getattr(position, "position_type", "") or "unknown"),
                "entry_price": float(getattr(position, "entry_price", 0.0) or 0.0),
                "quantity": int(getattr(position, "quantity", 0) or 0),
                "quote_source": str(source_quote or "unknown"),
                "quote_grade": str(quote_grade or "degraded"),
                "exit_grade_ready": bool(exit_grade_ready),
                "good_mark_ticks": int(good_mark_ticks or 0),
            }

        defer_telegram = bool(getattr(self, "_orb_0dte_active_execution_run_id", None)) and not bool(
            getattr(self, "_orb_0dte_execution_alert_telegram_sent", False)
        )
        if defer_telegram:
            buf = self._orb_0dte_pending_durable_telegram_rows
            replaced = False
            for idx, existing in enumerate(buf):
                if str(existing.get("position_id") or "").strip() == tid:
                    buf[idx] = row
                    replaced = True
                    break
            if not replaced:
                buf.append(row)
            log.info(
                "ORB_0DTE_DURABLE_TELEGRAM_DEFERRED | run_id=%s | trade_id=%s | symbol=%s | quote_grade=%s",
                getattr(self, "_orb_0dte_active_execution_run_id", ""),
                tid,
                row.get("symbol"),
                row.get("quote_grade"),
            )
            return

        mode = self._orb_0dte_telegram_mode(position)
        sent = await self.alert_manager.send_options_durability_update_alert(
            durable_positions=[row],
            mode=mode,
        )
        if sent:
            self._orb_0dte_durability_followup_alerted.add(tid)
            log.info(
                "ORB_0DTE_DURABLE_CONFIRMED | trade_id=%s | symbol=%s | option_type=%s | qty=%d | entry=%.4f | quote_source=%s | quote_grade=%s | exit_grade_ready=%s | strategy=%s | mode=%s",
                tid,
                row.get("symbol"),
                option_side,
                int(row.get("quantity") or 0),
                float(row.get("entry_price") or 0.0),
                row.get("quote_source"),
                row.get("quote_grade"),
                str(bool(exit_grade_ready)).lower(),
                row.get("strategy_type"),
                mode,
            )

    def _orb_0dte_maybe_emit_session_lifecycle_summary(self) -> None:
        if self._orb_0dte_lifecycle_summary_sent:
            return
        if not self._orb_0dte_lifecycle:
            return
        if self._orb_option_positions_count() > 0:
            return
        stats = self._orb_0dte_lifecycle_session_stats
        entries = int(stats.get("entries", 0))
        if entries <= 0:
            return
        degraded_ratios = []
        bad_quality = 0
        for rec in self._orb_0dte_lifecycle.values():
            q = rec.get("quality", {}) if isinstance(rec.get("quality"), dict) else {}
            ticks = int(q.get("monitor_tick_count", 0) or 0)
            dq = int(q.get("degraded_quote_ticks", 0) or 0)
            ratio = (float(dq) / float(ticks)) if ticks > 0 else 0.0
            degraded_ratios.append(ratio)
            if ratio >= 0.5:
                bad_quality += 1
            if rec.get("exit_signalled_ts", 0.0) and not rec.get("close_confirmed", False):
                stats["positions_missing_confirmation"] = int(stats.get("positions_missing_confirmation", 0)) + 1
        avg_deg = (sum(degraded_ratios) / len(degraded_ratios)) if degraded_ratios else 0.0
        log.info(
            "ORB_0DTE_SESSION_LIFECYCLE_SUMMARY | entries=%d | exits_confirmed=%d | close_failures=%d | "
            "alerts_sent=%d | alerts_missing=%d | watchdog_failures=%d | avg_degraded_ratio=%.3f | "
            "positions_with_bad_data_quality=%d | positions_missing_confirmation=%d",
            entries,
            int(stats.get("exits_confirmed", 0)),
            int(stats.get("close_failures", 0)),
            int(stats.get("alerts_sent", 0)),
            int(stats.get("alerts_missing", 0)),
            int(stats.get("watchdog_failures", 0)),
            float(avg_deg),
            int(bad_quality),
            int(stats.get("positions_missing_confirmation", 0)),
        )
        self._orb_0dte_lifecycle_summary_sent = True

    def _orb_unified_open_positions(self) -> Dict[str, Any]:
        from modules.unified_0dte_account import list_orb_open_positions

        out: Dict[str, Any] = {}
        for pos in list_orb_open_positions(self):
            pid = str(getattr(pos, "position_id", "") or "").strip()
            if pid:
                out[pid] = pos
        return out

    def _orb_option_positions_count(self) -> int:
        """Count open ORB1 Breakout rows using the same filter as the stealth monitor."""
        return int(len(self._orb_unified_open_positions()))

    def _trendline_executed_today_symbols(self) -> Set[str]:
        """Telemetry set of symbols that filled Trendline today (not an entry block)."""
        raw = getattr(self, "_trendline_signals_executed_today", None)
        if isinstance(raw, set):
            return raw
        if isinstance(raw, (list, tuple, frozenset)):
            rebuilt = {str(x) for x in raw if x}
            self._trendline_signals_executed_today = rebuilt
            return rebuilt
        if raw is not None:
            log.warning(
                "TRENDLINE_PIPELINE | stage=watch | action=reset_executed_today | "
                "reason=invalid_type | was=%s",
                type(raw).__name__,
            )
        fresh: Set[str] = set()
        self._trendline_signals_executed_today = fresh
        return fresh

    def _trendline_candidate_option_side(self, candidate: Any) -> str:
        """Normalize CALL/PUT for a watch/exec candidate."""
        pl = getattr(candidate, "setup_payload", None) or {}
        if isinstance(pl, dict):
            for key in ("expected_option_side", "option_side"):
                raw = str(pl.get(key) or "").strip().lower()
                if raw in ("call", "put"):
                    return raw
        try:
            from easyTrendline.trendline_models import TrendlineDirection

            direction = getattr(candidate, "direction", None)
            if direction == TrendlineDirection.BEAR:
                return "call"
            if direction == TrendlineDirection.BULL:
                return "put"
        except Exception:
            pass
        side = str(getattr(candidate, "option_side", "") or "").strip().lower()
        return side if side in ("call", "put") else ""

    def _trendline_has_open_same_side(self, symbol: str, option_side: str) -> bool:
        """True when an open Trendline position exists for same symbol + CALL/PUT."""
        sym = str(symbol or "").strip().upper()
        side = str(option_side or "").strip().lower()
        if not sym or side not in ("call", "put"):
            return False
        try:
            from modules.unified_0dte_account import (
                list_trendline_open_positions,
                normalize_trendline_position_attrs,
                trendline_position_option_side,
            )

            for pos in list_trendline_open_positions(self):
                pos = normalize_trendline_position_attrs(pos)
                pos_sym = str(getattr(pos, "symbol", "") or "").strip().upper()
                if pos_sym != sym:
                    continue
                pos_side = str(trendline_position_option_side(pos) or "").strip().lower()
                if pos_side == side:
                    return True
        except Exception as exc:
            log.warning(
                "TRENDLINE_PIPELINE | stage=dedupe_guard | action=open_side_check_failed | "
                "symbol=%s | side=%s | error=%s",
                sym,
                side,
                exc,
            )
        return False

    def _trendline_option_positions_count(self) -> int:
        """Count open Trendline rows using the same filter as the stealth monitor."""
        return int(len(self._trendline_unified_open_positions()))

    def _total_option_positions_count(self) -> int:
        from modules.unified_0dte_account import count_unified_open_positions

        return int(count_unified_open_positions(self))

    def _unified_0dte_risk_enabled(self) -> bool:
        try:
            from modules.unified_0dte_portfolio_risk_manager import Unified0DTERiskConfig

            return bool(Unified0DTERiskConfig.from_env().enabled)
        except ImportError:
            return False

    def _option_entry_cooldown_remaining_sec(self) -> float:
        until = float(getattr(self, "_option_entry_cooldown_until_ts", 0.0) or 0.0)
        return max(0.0, until - time.time())

    def _arm_option_entry_cooldown_global_cap(self) -> None:
        now_ts = time.time()
        last_arm = float(getattr(self, "_option_entry_cooldown_last_arm_ts", 0.0) or 0.0)
        if now_ts - last_arm < 3.0 and self._option_entry_cooldown_remaining_sec() > 0.5:
            return
        self._option_entry_cooldown_last_arm_ts = now_ts
        duration_sec = float(random.randint(30, 60))
        self._option_entry_cooldown_until_ts = now_ts + duration_sec
        log.warning(
            "OPTION_ENTRY_COOLDOWN | duration_sec=%.0f | reason=global_cap",
            duration_sec,
        )

    def _maybe_log_option_entry_cooldown_blocking(self, *, blocked_for_symbol: Optional[str] = None) -> None:
        rem = self._option_entry_cooldown_remaining_sec()
        if rem <= 0:
            return
        now_ts = time.time()
        if now_ts - float(getattr(self, "_option_entry_cooldown_last_block_log_ts", 0.0) or 0.0) < 60.0:
            return
        self._option_entry_cooldown_last_block_log_ts = now_ts
        sym_tail = f" | blocked_for_symbol={blocked_for_symbol}" if blocked_for_symbol else ""
        log.warning(
            "OPTION_ENTRY_COOLDOWN | stage=blocking | remaining_sec=%.0f | reason=global_cap%s",
            rem,
            sym_tail,
        )

    @staticmethod
    def _position_datetime_to_epoch_seconds(dt: Any) -> Optional[float]:
        if dt is None:
            return None
        try:
            if isinstance(dt, datetime):
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                return float(dt.timestamp())
        except Exception:
            return None
        return None

    def _option_position_seconds_since_entry(self, pos: Any) -> float:
        """Monotonic age since best-effort entry instant; inf if unknown."""
        now_ts = time.time()
        entry_epochs: List[float] = []
        for attr in ("entry_time", "opened_at"):
            t = self._position_datetime_to_epoch_seconds(getattr(pos, attr, None))
            if t is not None:
                entry_epochs.append(t)
        md = getattr(pos, "metadata", None)
        if isinstance(md, dict):
            raw_ts = md.get("entry_timestamp") or md.get("entry_ts")
            if isinstance(raw_ts, (int, float)):
                entry_epochs.append(float(raw_ts))
            elif isinstance(raw_ts, str):
                try:
                    parsed = datetime.fromisoformat(raw_ts.replace("Z", "+00:00"))
                    t2 = self._position_datetime_to_epoch_seconds(parsed)
                    if t2 is not None:
                        entry_epochs.append(t2)
                except Exception:
                    pass
        pid = str(getattr(pos, "position_id", "") or "").strip()
        if pid:
            fs = (getattr(self, "_orb_0dte_position_first_seen_ts", None) or {}).get(pid)
            if isinstance(fs, (int, float)):
                entry_epochs.append(float(fs))
        if not entry_epochs:
            return float("inf")
        return max(0.0, now_ts - min(entry_epochs))

    def _option_position_protected_from_backoff(self, pos: Any) -> bool:
        """True for the first 60s after entry; syncs metadata flag when a dict is available."""
        sec = self._option_position_seconds_since_entry(pos)
        prot = bool(sec < 60.0)
        md = getattr(pos, "metadata", None)
        if md is None and prot:
            try:
                setattr(pos, "metadata", {})
                md = getattr(pos, "metadata", None)
            except Exception:
                md = None
        if isinstance(md, dict):
            md["protected_from_backoff"] = prot
        return prot

    def _option_symbols_protected_from_backoff(self, positions: List[Any]) -> Set[str]:
        protected: Set[str] = set()
        for p in positions:
            if not self._option_position_protected_from_backoff(p):
                continue
            sym = str(getattr(p, "symbol", "") or "").strip().upper()
            if sym:
                protected.add(sym)
        return protected

    def _max_protected_symbols_soft_cap(self) -> int:
        """Soft cap on distinct protected symbols (first ~60s post-entry) to limit API fan-out."""
        try:
            v = int(float(get_config_value("MAX_PROTECTED_SYMBOLS", 5)))
            return max(1, min(32, v))
        except Exception:
            return 5

    def _filter_positions_for_option_symbol_monitor_cap(
        self,
        positions: List[Any],
        symbol_cap: int,
    ) -> List[Any]:
        """
        Under latency/API symbol caps, keep highest-ranked symbols per _position_backoff_sort_tuple,
        but never drop symbols that still have a position in the post-entry survival window.

        Protected symbols (first 60s) are always honored up to MAX_PROTECTED_SYMBOLS; beyond that,
        only the top-ranked protected symbols are kept as first-class monitor rows. Remaining
        protected symbols are still appended for exit-only ticks (synthetic / last-valid path),
        flagged on metadata with _orb_synthetic_only_monitor_tick.
        """
        if not positions or symbol_cap <= 0:
            return list(positions)
        unique_symbols = {
            str(getattr(p, "symbol", "") or "").strip().upper()
            for p in positions
            if str(getattr(p, "symbol", "") or "").strip()
        }
        total_symbols = len(unique_symbols)
        if symbol_cap >= total_symbols:
            return list(positions)
        symbol_scores: Dict[str, Tuple[int, int, float, float, float]] = {}
        for p in positions:
            sym = str(getattr(p, "symbol", "") or "").strip().upper()
            if not sym:
                continue
            score = self._position_backoff_sort_tuple(p)
            prev = symbol_scores.get(sym)
            if prev is None or score > prev:
                symbol_scores[sym] = score
        protected_syms_all = self._option_symbols_protected_from_backoff(positions)
        max_prot = self._max_protected_symbols_soft_cap()
        protected_kept_syms = set(protected_syms_all)
        dropped_prot_syms: Set[str] = set()
        if len(protected_syms_all) > max_prot:
            prot_ranked: List[Tuple[str, Tuple[int, int, float, float, float]]] = []
            for sym in protected_syms_all:
                best: Optional[Tuple[int, int, float, float, float]] = None
                for p in positions:
                    ps = str(getattr(p, "symbol", "") or "").strip().upper()
                    if ps != sym:
                        continue
                    sc = self._position_backoff_sort_tuple(p)
                    if best is None or sc > best:
                        best = sc
                if best is not None:
                    prot_ranked.append((sym, best))
            prot_ranked.sort(key=lambda kv: kv[1], reverse=True)
            if prot_ranked:
                protected_kept_syms = {sym for sym, _ in prot_ranked[:max_prot]}
            else:
                protected_kept_syms = set(sorted(protected_syms_all)[:max_prot])
            dropped_prot_syms = set(protected_syms_all) - protected_kept_syms
            log.warning(
                "OPTION_PROTECTED_CAP | protected_symbols=%s | kept=%s | dropped=%s",
                ",".join(sorted(protected_syms_all)) if protected_syms_all else "none",
                ",".join(sorted(protected_kept_syms)) if protected_kept_syms else "none",
                ",".join(sorted(dropped_prot_syms)) if dropped_prot_syms else "none",
            )

        protected_syms = protected_kept_syms
        ranked_symbols = sorted(symbol_scores.items(), key=lambda kv: kv[1], reverse=True)
        ranked_order = [sym for sym, _ in ranked_symbols]
        if len(protected_syms) >= symbol_cap:
            keep_syms = set(protected_syms)
        else:
            budget = symbol_cap - len(protected_syms)
            extra = [s for s in ranked_order if s not in protected_syms][: max(0, budget)]
            keep_syms = set(protected_syms) | set(extra)
        pending = getattr(self, "_0dte_pending_monitor_registrations", None) or {}
        if isinstance(pending, dict) and pending:
            pending_syms = {
                str((info or {}).get("symbol") or "").strip().upper()
                for info in pending.values()
                if isinstance(info, dict) and str((info or {}).get("symbol") or "").strip()
            }
            if pending_syms:
                keep_syms |= pending_syms
        kept_ordered = [s for s in ranked_order if s in keep_syms]
        dropped_ordered = [s for s in ranked_order if s not in keep_syms]
        log.info(
            "OPTION_BACKOFF_SELECTION | kept_symbols=%s | dropped_symbols=%s",
            ",".join(kept_ordered) if kept_ordered else "none",
            ",".join(dropped_ordered) if dropped_ordered else "none",
        )
        main_list = [
            p
            for p in positions
            if str(getattr(p, "symbol", "") or "").strip().upper() in keep_syms
        ]
        if not dropped_prot_syms:
            return main_list
        kept_ids = {
            str(getattr(p, "position_id", "") or "").strip()
            for p in main_list
            if str(getattr(p, "position_id", "") or "").strip()
        }
        extras: List[Any] = []
        for p in positions:
            sym = str(getattr(p, "symbol", "") or "").strip().upper()
            if sym not in dropped_prot_syms or sym in keep_syms:
                continue
            if not self._option_position_protected_from_backoff(p):
                continue
            pid = str(getattr(p, "position_id", "") or "").strip()
            if pid and pid in kept_ids:
                continue
            md = getattr(p, "metadata", None)
            if not isinstance(md, dict):
                try:
                    setattr(p, "metadata", {})
                    md = getattr(p, "metadata", {})
                except Exception:
                    md = {}
            if isinstance(md, dict):
                md["_orb_synthetic_only_monitor_tick"] = True
            extras.append(p)
        return main_list + extras

    def _log_option_position_summary(self) -> None:
        orb_open = self._orb_option_positions_count()
        trendline_open = self._trendline_option_positions_count()
        log.info(
            "OPTION_POSITION_SUMMARY | orb_positions=%d | trendline_positions=%d | total_positions=%d",
            int(orb_open),
            int(trendline_open),
            int(orb_open + trendline_open),
        )

    def _maybe_log_options_monitor_summary(self, now_ts: Optional[float] = None) -> None:
        """Unified options monitor summary across ORB1 Breakout and Trendline."""
        ts = float(now_ts if now_ts is not None else time.time())
        if ts - float(getattr(self, "_options_monitor_last_summary_ts", 0.0)) < float(
            getattr(self, "_options_monitor_summary_sec", 180.0)
        ):
            return
        self._options_monitor_last_summary_ts = ts

        orb_open = self._orb_option_positions_count()
        trendline_open = self._trendline_option_positions_count()
        self._log_option_position_summary()

        orb_m = getattr(self, "_orb_0dte_monitor_metrics", {}) or {}
        tl_m = getattr(self, "_trendline_fast_monitor_metrics", {}) or {}
        orb_ps = orb_m.get("premium_sources", {}) if isinstance(orb_m.get("premium_sources"), dict) else {}
        orb_open_pnl_pct = 0.0
        tl_open_pnl_pct = 0.0
        orb_open_pnl_count = 0
        tl_open_pnl_count = 0
        try:
            if getattr(self, "dte0_manager", None) and getattr(self.dte0_manager, "options_executor", None):
                for p in (self.dte0_manager.options_executor.get_open_positions() or []):
                    md = getattr(p, "metadata", None)
                    if not isinstance(md, dict):
                        continue
                    osnap = md.get("option_stealth")
                    if not isinstance(osnap, dict):
                        continue
                    pnl = osnap.get("current_pnl_pct_per_contract")
                    if isinstance(pnl, (int, float)):
                        orb_open_pnl_pct += float(pnl)
                        orb_open_pnl_count += 1
        except Exception:
            pass
        try:
            for pos in list(self._trendline_unified_open_positions().values()):
                md = getattr(pos, "metadata", None)
                if not isinstance(md, dict):
                    continue
                osnap = md.get("option_stealth")
                if not isinstance(osnap, dict):
                    continue
                pnl = osnap.get("current_pnl_pct_per_contract")
                if isinstance(pnl, (int, float)):
                    tl_open_pnl_pct += float(pnl)
                    tl_open_pnl_count += 1
        except Exception:
            pass
        log.info(
            "OPTIONS_MONITOR | stage=summary | orb_open=%s | trendline_open=%s | orb_ticks=%s | "
            "orb_fast_calls=%s | orb_shared_calls=%s | orb_exits=%s/%s | orb_fallback=%s | "
            "orb_degraded_quotes=%s | trendline_ticks=%s | trendline_chain_calls=%s | "
            "orb_open_pnl_avg_pct=%s | trendline_open_pnl_avg_pct=%s",
            orb_open,
            trendline_open,
            orb_m.get("ticks", 0),
            orb_m.get("fast_loop_calls", 0),
            orb_m.get("shared_loop_calls", 0),
            orb_m.get("exits_executed", 0),
            orb_m.get("exits_signaled", 0),
            orb_m.get("fallback_monitor_used", 0),
            int(orb_ps.get("modeled_proxy", 0))
            + int(orb_ps.get("current_position_value_fallback", 0))
            + int(orb_ps.get("missing_or_invalid", 0)),
            tl_m.get("ticks", 0),
            tl_m.get("chain_calls", 0),
            (f"{(orb_open_pnl_pct / orb_open_pnl_count):.4f}" if orb_open_pnl_count > 0 else "n/a"),
            (f"{(tl_open_pnl_pct / tl_open_pnl_count):.4f}" if tl_open_pnl_count > 0 else "n/a"),
        )

    def _emit_option_lifecycle_tick_unified(
        self,
        *,
        trade_id: str,
        symbol: str,
        strategy_type: str,
        monitor_loop: str,
        trigger_source: str,
        osnap: Dict[str, Any],
        lifecycle_rec: Dict[str, Any],
        quote_source: str,
        out: Optional[Tuple[Any, Any, Any]],
        seconds_since_last_tick: float,
        position_meta: Optional[Dict[str, Any]] = None,
    ) -> None:
        if not trade_id:
            return
        try:
            min_iv = float(get_config_value("OPTION_LIFECYCLE_TICK_LOG_SEC", 7.0) or 0.0)
        except Exception:
            min_iv = 7.0
        if min_iv > 0:
            cache = getattr(self, "_option_lifecycle_tick_last", None)
            if not isinstance(cache, dict):
                cache = {}
                self._option_lifecycle_tick_last = cache
            now_m = time.monotonic()
            key = f"{monitor_loop}|{trade_id}"
            if now_m - float(cache.get(key, -1e30)) < min_iv:
                return
            cache[key] = now_m
        eng = osnap.get("engine") if isinstance(osnap, dict) else None
        st_obj = (eng or {}).get("state") if isinstance(eng, dict) else None
        good_ticks = 0
        if st_obj is not None:
            good_ticks = int(getattr(st_obj, "good_mark_tick_count", 0) or 0)
        else:
            good_ticks = int(osnap.get("good_mark_tick_count") or 0)
        mark_exit = bool(osnap.get("mark_is_exit_grade"))
        max_pnl = float(osnap.get("max_pnl_pct") or 0.0)
        prem_pnl = float(osnap.get("current_pnl_pct_per_contract") or 0.0)
        t_frozen = bool(osnap.get("timeout_clock_frozen"))
        es_ts = float(lifecycle_rec.get("exit_signalled_ts", 0.0) or 0.0)
        close_pending = bool(es_ts > 0 and not lifecycle_rec.get("close_confirmed"))
        close_conf = bool(lifecycle_rec.get("close_confirmed"))
        exit_candidate = str(osnap.get("orb_last_exit_hold_reason") or "")
        log.info(
            "OPTION_LIFECYCLE_TICK | trade_id=%s | strategy_type=%s | monitor_active=true | "
            "seconds_since_last_tick=%.2f | monitor_loop=%s | quote_source=%s | mark_is_exit_grade=%s | "
            "good_mark_tick_count=%d | premium_pnl_pct=%.4f | max_pnl_pct=%.4f | timeout_clock_frozen=%s | "
            "close_pending=%s | close_confirmed=%s | exit_reason_candidate=%s | trigger=%s | symbol=%s",
            trade_id,
            str(strategy_type or "unknown"),
            float(seconds_since_last_tick),
            monitor_loop,
            str(quote_source or ""),
            str(mark_exit).lower(),
            good_ticks,
            prem_pnl,
            max_pnl,
            str(t_frozen).lower(),
            str(close_pending).lower(),
            str(close_conf).lower(),
            exit_candidate[:160] if exit_candidate else "none",
            trigger_source,
            symbol,
        )
        if str(strategy_type or "").lower() == "orb_0dte":
            dur_ok = False
            mon_ok = False
            first_q = False
            if isinstance(position_meta, dict):
                d0 = position_meta.get("orb_0dte_durability")
                if isinstance(d0, dict):
                    dur_ok = bool(d0.get("durable_position_confirmed") or d0.get("execution_durable_confirmed"))
                    mon_ok = bool(d0.get("monitor_attached"))
                    first_q = bool(d0.get("first_quote_hydrated"))
            log.info(
                "ORB_0DTE_LIFECYCLE_AUDIT | trade_id=%s | symbol=%s | strategy_type=%s | "
                "durable_position_confirmed=%s | monitor_attached=%s | first_quote_hydrated=%s | "
                "quote_source=%s | mark_is_exit_grade=%s | good_mark_tick_count=%d | premium_pnl_pct=%.4f | "
                "max_pnl_pct=%.4f | exit_reason_candidate=%s | exit_triggered=%s | close_pending=%s | "
                "close_confirmed=%s | timeout_clock_frozen=%s | eod_close_eligible=n/a | forced_close_eligible=n/a | "
                "position_removed=n/a",
                trade_id,
                symbol,
                str(strategy_type or "orb_0dte"),
                str(dur_ok).lower(),
                str(mon_ok).lower(),
                str(first_q).lower(),
                str(quote_source or ""),
                str(mark_exit).lower(),
                good_ticks,
                prem_pnl,
                max_pnl,
                exit_candidate[:120] if exit_candidate else "none",
                str(bool(out)).lower(),
                str(close_pending).lower(),
                str(close_conf).lower(),
                str(t_frozen).lower(),
            )

    def _register_orb_0dte_stealth_after_execution(self, position: Any, *, current_underlying: float) -> None:
        """Eager ORB stealth registration at fill (mirrors Trendline); avoids monitor-only lazy registration."""
        from easy0DTE.modules.options_execution_normalize import validate_normalized_options_for_stealth
        from .prime_options_stealth_trailing_tp import TrendlineOptionsStealthEngine

        ts_iso = datetime.now(timezone.utc).isoformat()
        trade_id = str(getattr(position, "position_id", "") or "").strip()
        sym_u = str(getattr(position, "symbol", "") or "").strip()
        monitor_owner = "execution_handoff"
        meta = getattr(position, "metadata", None)
        if not isinstance(meta, dict):
            meta = {}
            try:
                position.metadata = meta
            except Exception:
                log.info(
                    "ORB_0DTE_POSITION_REGISTERED_FOR_STEALTH | trade_id=%s | symbol=%s | registered_ok=false | "
                    "monitor_owner=%s | timestamp=%s | reason=no_metadata",
                    trade_id,
                    sym_u,
                    monitor_owner,
                    ts_iso,
                )
                return
        ox = meta.get("option_stealth")
        if isinstance(ox, dict) and isinstance(ox.get("engine"), dict):
            blk = ox.get("engine") or {}
            st0 = blk.get("state")
            pt0 = str(getattr(st0, "position_type", "") or "") if st0 is not None else ""
            is_spread = "spread" in pt0.lower()
            legs_count = len(getattr(st0, "legs", None) or []) or (2 if is_spread else 1)
            stn = str(getattr(st0, "strategy_type", "orb_0dte") or "orb_0dte")
            ep = float(getattr(st0, "entry_premium", 0.0) or 0.0)
            log.info(
                "ORB_0DTE_POSITION_REGISTERED_FOR_STEALTH | trade_id=%s | symbol=%s | strategy_type=%s | "
                "is_spread=%s | legs_count=%d | entry_premium=%.6f | registered_ok=true | monitor_owner=%s | "
                "timestamp=%s | note=already_stealth_engine",
                trade_id,
                sym_u,
                stn,
                str(is_spread).lower(),
                int(legs_count),
                ep,
                monitor_owner,
                ts_iso,
            )
            # Align durability with eager-registration contract (no second register_on_open).
            try:
                dur_sync = meta.setdefault("orb_0dte_durability", {})
                dur_sync["fill_confirmed"] = True
                dur_sync["position_registered"] = True
                dur_sync["stealth_registered"] = True
                dur_sync["monitor_attached"] = True
                try:
                    from modules.exit_grade_durability import (
                        EVT_FILL,
                        EVT_REGISTRY,
                        stamp_session_event,
                    )

                    stamp_session_event(meta, EVT_FILL)
                    stamp_session_event(meta, EVT_REGISTRY)
                except Exception:
                    pass
                opt_side_sync = str(
                    getattr(st0, "option_side", "") or (ox.get("option_side") if isinstance(ox, dict) else "") or "unknown"
                ).lower()
                src_sync = str(ox.get("source_path") or dur_sync.get("source_path") or "easy0DTE")
                qsrc_sync = str(ox.get("last_quote_source") or dur_sync.get("quote_source") or "pending_first_quote")
                self._orb_0dte_update_durability_state(
                    trade_id=trade_id,
                    symbol=sym_u,
                    option_side=opt_side_sync or "unknown",
                    strategy_type=stn,
                    position_type=pt0 or "unknown",
                    source_path=src_sync,
                    state="stealth_registered_execution",
                    registry_present=True,
                    monitor_attached=True,
                    quote_source=qsrc_sync,
                    quote_age_ms=float(dur_sync.get("quote_age_ms") or 0.0),
                    leg_quote_completeness=str(dur_sync.get("leg_quote_completeness") or "unknown"),
                    alert_eligible=bool(dur_sync.get("alert_eligible", False)),
                )
            except Exception:
                pass
            try:
                from modules.unified_0dte_monitor_registry import enqueue_0dte_pending_monitor

                enqueue_0dte_pending_monitor(
                    self._0dte_pending_monitor_registrations,
                    trade_id=str(trade_id),
                    symbol=sym_u,
                    strategy_type=stn or "orb_0dte",
                )
                self._0dte_not_monitored_logged.discard(str(trade_id))
                self._orb_0dte_last_fast_monitor_ts = 0.0
                self._request_immediate_0dte_monitor(reason="orb_fill")
            except Exception:
                pass
            return
        if not getattr(self, "orb_options_stealth", None):
            self._ensure_orb_options_stealth_engine()
            log.info("ORB_OPTIONS_STEALTH | initialized=true | stage=execution_eager")
        stealth = self.orb_options_stealth
        norm_orb = meta.get("normalized_options")
        if not isinstance(norm_orb, dict):
            log.info(
                "ORB_0DTE_POSITION_REGISTERED_FOR_STEALTH | trade_id=%s | symbol=%s | strategy_type=unknown | "
                "is_spread=unknown | legs_count=0 | entry_premium=0.000000 | registered_ok=false | monitor_owner=%s | "
                "timestamp=%s | reason=normalized_options_absent",
                trade_id,
                sym_u,
                monitor_owner,
                ts_iso,
            )
            return
        norm_ok, norm_missing = validate_normalized_options_for_stealth(norm_orb)
        if not norm_ok:
            log.info(
                "ORB_0DTE_POSITION_REGISTERED_FOR_STEALTH | trade_id=%s | symbol=%s | strategy_type=unknown | "
                "is_spread=unknown | legs_count=0 | entry_premium=0.000000 | registered_ok=false | monitor_owner=%s | "
                "timestamp=%s | reason=normalized_invalid | missing=%s",
                trade_id,
                sym_u,
                monitor_owner,
                ts_iso,
                ",".join(norm_missing) if norm_missing else "unknown",
            )
            return
        pid_orb = str(getattr(position, "position_id", "") or "")
        legs_meta = [dict(x) for x in norm_orb["legs"] if isinstance(x, dict)]
        position_type_norm = str(norm_orb["position_type"])
        is_spread = "spread" in position_type_norm.lower()
        legs_count = len(legs_meta)
        exp_ymd = str(norm_orb.get("expiration_ymd") or "")
        und_sym = str(norm_orb.get("underlying_symbol") or getattr(position, "symbol", "") or "")
        strategy_name_n = str(norm_orb.get("strategy_name") or "Easy ORB1 Breakout")
        strategy_type_n = str(
            norm_orb.get("orb_strategy_type") or norm_orb.get("strategy_type") or "orb_0dte"
        )
        setup_type_n = str(norm_orb.get("setup_type") or "orb_0dte")
        trigger_direction_n = str(norm_orb.get("trigger_direction") or "")
        source_path_n = str(norm_orb.get("source_path") or "easy0DTE")
        ev_raw = norm_orb.get("entry_value")
        entry_val_n = float(getattr(position, "entry_price", 0.0) or 0.0)
        if entry_val_n <= 0:
            entry_val_n = float(ev_raw if ev_raw is not None else 0.0)
        entry_debit_n = norm_orb.get("entry_debit")
        entry_credit_n = norm_orb.get("entry_credit")
        if entry_debit_n is not None and float(getattr(position, "entry_price", 0.0) or 0.0) > 0:
            entry_debit_n = float(getattr(position, "entry_price", 0.0))
        elif entry_debit_n is not None:
            entry_debit_n = float(entry_debit_n)
        if entry_credit_n is not None:
            entry_credit_n = float(entry_credit_n)
        fl = legs_meta[0]
        option_side = str(fl.get("option_side") or "call").lower()
        strike = float(fl.get("strike") or 0.0)
        delta = abs(float(fl.get("delta_at_entry") or norm_orb.get("delta_at_entry") or 0.30))
        if not trigger_direction_n:
            trigger_direction_n = f"red_day_{option_side}"
        line_geometry = "bull" if option_side == "put" else "bear"
        u_entry = float(current_underlying or 0.0)
        if u_entry <= 0:
            try:
                u_entry = float(norm_orb.get("entry_underlying_price") or 0.0)
            except (TypeError, ValueError):
                u_entry = 0.0
        try:
            stealth.register_on_open(
                pid_orb,
                entry_premium_per_contract=entry_val_n,
                underlying_entry=u_entry,
                option_side=option_side,
                line_geometry=line_geometry,
                strike=strike,
                delta=delta,
                trendline_dict={},
                metadata_target=meta,
                underlying_symbol=und_sym,
                expiration_ymd=exp_ymd,
                setup_type=setup_type_n,
                trigger_direction=trigger_direction_n,
                position_type=position_type_norm,
                strategy_name=strategy_name_n,
                strategy_type=strategy_type_n,
                entry_value=entry_val_n,
                entry_debit=entry_debit_n,
                entry_credit=entry_credit_n,
                legs=legs_meta,
                structure_invalidation_enabled=False,
                source_path=source_path_n,
            )
        except Exception as _reg_open_err:
            log.info(
                "ORB_0DTE_POSITION_REGISTERED_FOR_STEALTH | trade_id=%s | symbol=%s | strategy_type=%s | "
                "is_spread=%s | legs_count=%d | entry_premium=%.6f | registered_ok=false | monitor_owner=%s | "
                "timestamp=%s | reason=register_on_open_failed | error=%s",
                trade_id,
                sym_u,
                strategy_type_n,
                str(is_spread).lower(),
                int(legs_count),
                float(entry_val_n),
                monitor_owner,
                ts_iso,
                str(_reg_open_err)[:200],
            )
            return
        dur = meta.setdefault("orb_0dte_durability", {})
        dur["fill_confirmed"] = True
        dur["position_registered"] = True
        dur["stealth_registered"] = True
        dur["monitor_attached"] = True
        try:
            from modules.exit_grade_durability import (
                EVT_FILL,
                EVT_REGISTRY,
                stamp_session_event,
            )

            stamp_session_event(meta, EVT_FILL)
            stamp_session_event(meta, EVT_REGISTRY)
        except Exception:
            pass
        try:
            self._orb_0dte_update_durability_state(
                trade_id=trade_id,
                symbol=sym_u,
                option_side=str(option_side or "unknown"),
                strategy_type=strategy_type_n,
                position_type=position_type_norm,
                source_path=source_path_n,
                state="stealth_registered_execution",
                registry_present=True,
                monitor_attached=True,
                quote_source="pending_first_quote",
                quote_age_ms=0.0,
                leg_quote_completeness="unknown",
                alert_eligible=False,
            )
        except Exception:
            pass
        log.info(
            "OPTIONS_STEALTH_REGISTER | symbol=%s | strategy=%s | trade_id=%s",
            und_sym or sym_u,
            strategy_type_n,
            pid_orb,
        )
        log.info(
            "ORB_0DTE_POSITION_REGISTERED_FOR_STEALTH | trade_id=%s | symbol=%s | strategy_type=%s | "
            "is_spread=%s | legs_count=%d | entry_premium=%.6f | registered_ok=true | monitor_owner=%s | timestamp=%s",
            trade_id,
            sym_u,
            strategy_type_n,
            str(is_spread).lower(),
            int(legs_count),
            float(entry_val_n),
            monitor_owner,
            ts_iso,
        )
        try:
            from modules.unified_0dte_monitor_registry import enqueue_0dte_pending_monitor

            enqueue_0dte_pending_monitor(
                self._0dte_pending_monitor_registrations,
                trade_id=str(pid_orb or trade_id),
                symbol=und_sym or sym_u,
                strategy_type=strategy_type_n or "orb_0dte",
            )
            self._0dte_not_monitored_logged.discard(str(pid_orb or trade_id))
            # Force next ORB fast-monitor cycle (same goal as Trendline immediate request).
            self._orb_0dte_last_fast_monitor_ts = 0.0
            self._request_immediate_0dte_monitor(reason="orb_fill")
        except Exception:
            pass

    async def _orb_0dte_guardrail_unclosable_survey(self, executor: Any) -> None:
        try:
            open_positions = executor.get_open_positions() or []
        except Exception:
            return
        now_ts = time.time()
        alerted = getattr(self, "_orb_0dte_unclosable_alerted", None)
        if not isinstance(alerted, set):
            alerted = set()
            self._orb_0dte_unclosable_alerted = alerted
        try:
            min_age = float(get_config_value("ORB_0DTE_UNCLOSABLE_ALERT_AFTER_SEC", 120.0))
        except Exception:
            min_age = 120.0
        for p in open_positions:
            pid = str(getattr(p, "position_id", "") or "").strip()
            if not pid:
                continue
            rec = (self._orb_0dte_lifecycle or {}).get(pid, {})
            es = float(rec.get("exit_signalled_ts", 0.0) or 0.0)
            if es <= 0 or bool(rec.get("close_confirmed")):
                continue
            pm = getattr(p, "metadata", None)
            dur0 = pm.get("orb_0dte_durability") if isinstance(pm, dict) else None
            if not isinstance(dur0, dict):
                dur0 = {}
            durable_ok = bool(dur0.get("durable_position_confirmed") or dur0.get("execution_durable_confirmed"))
            if not durable_ok:
                continue
            age = max(0.0, now_ts - es)
            if age < min_age:
                continue
            if pid in alerted:
                continue
            alerted.add(pid)
            sym = str(getattr(p, "symbol", "") or "")
            defer = 0
            tier = ""
            meta = getattr(p, "metadata", None)
            if isinstance(meta, dict):
                osnp = meta.get("option_stealth")
                if isinstance(osnp, dict):
                    defer = int(osnp.get("orb_exit_defer_total") or 0)
                    tier = str(osnp.get("orb_spread_relief_tier") or "")
            log.error(
                "ORB_0DTE_DURABLE_POSITION_UNCLOSABLE | trade_id=%s | symbol=%s | seconds_since_exit_signal=%.1f | "
                "deferrals=%d | relief_tier=%s | durable_confirmed=true | hint=verify_close_submission_and_telegram_pipeline",
                pid,
                sym,
                age,
                defer,
                tier or "none",
            )
            am = getattr(self, "alert_manager", None)
            if am:
                try:
                    await am.send_system_alert(
                        "ORB1 Breakout durable position unclosable",
                        f"trade_id={pid} symbol={sym} age_sec={age:.0f} deferrals={defer} tier={tier or 'none'}",
                    )
                except Exception as exc:
                    log.warning("ORB_0DTE_UNCLOSABLE_ALERT_FAIL | trade_id=%s | error=%s", pid, exc)

    async def _trendline_guardrail_unclosable_survey(self, executor: Any) -> None:
        now_ts = time.time()
        alerted = getattr(self, "_trendline_unclosable_alerted", None)
        if not isinstance(alerted, set):
            alerted = set()
            self._trendline_unclosable_alerted = alerted
        try:
            min_age = float(get_config_value("TRENDLINE_UNCLOSABLE_ALERT_AFTER_SEC", 120.0))
        except Exception:
            min_age = 120.0
        open_ids: Set[str] = set()
        if executor is not None:
            try:
                open_ids = {
                    str(getattr(p, "position_id", "") or "").strip()
                    for p in (executor.get_open_positions() or [])
                    if str(getattr(p, "position_id", "") or "").strip()
                }
            except Exception:
                open_ids = set()
        for pid, rec in (self._trendline_lifecycle or {}).items():
            if not isinstance(rec, dict):
                continue
            if pid not in open_ids:
                continue
            es = float(rec.get("exit_signalled_ts", 0.0) or 0.0)
            if es <= 0 or bool(rec.get("close_confirmed")):
                continue
            age = max(0.0, now_ts - es)
            if age < min_age:
                continue
            if pid in alerted:
                continue
            alerted.add(pid)
            sym = str(rec.get("symbol") or "")
            log.error(
                "TRENDLINE_DURABLE_POSITION_UNCLOSABLE | trade_id=%s | symbol=%s | seconds_since_exit_signal=%.1f | "
                "hint=verify_close_submission_and_broker_fill",
                pid,
                sym,
                age,
            )
            am = getattr(self, "alert_manager", None)
            if am:
                try:
                    await am.send_system_alert(
                        "Trendline 0DTE position unclosable",
                        f"trade_id={pid} symbol={sym} age_sec={age:.0f}",
                    )
                except Exception as exc:
                    log.warning("TRENDLINE_UNCLOSABLE_ALERT_FAIL | trade_id=%s | error=%s", pid, exc)

